--

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;


--
-- Name: EXTENSION pg_trgm; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION pg_trgm IS 'text similarity measurement and index searching based on trigrams';


--
-- Name: pgcrypto; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;


--
-- Name: EXTENSION pgcrypto; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION pgcrypto IS 'cryptographic functions';


--
-- Name: accept_sourced_work_request_outcome_feedback(text, integer, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.accept_sourced_work_request_outcome_feedback(p_work_request text, p_base_version integer, p_feedback_hash text, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, state text, version integer, feedback_id uuid, feedback_ref text, feedback_hash text, plan_ref text, plan_hash text, outcome text, criterion_results jsonb, evidence_refs jsonb, blocker_code text, result_summary text, observed_minutes integer, interaction_surface text, heavy_session_used boolean, manual_context_transfers integer, accepted_by_actor_slug text, accepted_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  actor_slug text; a public.actor%rowtype; w ops.work_request%rowtype;
  p ops.sourced_work_request_plan%rowtype;
  ar ops.sourced_work_request_plan_acceptance_receipt%rowtype;
  f ops.sourced_work_request_outcome_feedback%rowtype;
  fr ops.sourced_work_request_outcome_feedback_acceptance_receipt%rowtype;
  canonical_preimage jsonb; canonical_hash text;
begin
  if coalesce(btrim(p_work_request),'') !~ '^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version < 1
     or coalesce(p_feedback_hash,'') !~ '^sha256:[0-9a-f]{64}$'
     or p_idempotency_key is null then
    raise exception 'independent outcome-feedback acceptance requires exact ready Work Request/version, feedback hash, and UUID idempotency key';
  end if;
  actor_slug := ops.authority_actor_slug();
  select x.* into a from public.actor x where x.slug=actor_slug and x.active and x.kind='human' for share;
  if not found then raise exception 'authority session user is not an active human actor'; end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-outcome-feedback-acceptance:' || p_idempotency_key,0));
  select x.* into fr from ops.sourced_work_request_outcome_feedback_acceptance_receipt x
   where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into f from ops.sourced_work_request_outcome_feedback x where x.id=fr.feedback_id for share;
    select x.* into w from ops.work_request x where x.id=fr.work_request_id for share;
    select x.* into p from ops.sourced_work_request_plan x where x.id=f.plan_id for share;
    if not found or w.ref is distinct from p_work_request
       or fr.base_version is distinct from p_base_version
       or fr.result_version is distinct from p_base_version or f.feedback_hash is distinct from p_feedback_hash
       or fr.feedback_hash is distinct from p_feedback_hash or fr.accepted_by_actor_id is distinct from a.id then
      raise exception 'idempotency key already names different sourced outcome feedback acceptance';
    end if;
    return query select w.id,w.ref,'ready'::text,fr.result_version,f.id,f.feedback_ref,f.feedback_hash,
      p.plan_ref,p.plan_hash,f.outcome,f.criterion_results,f.evidence_refs,f.blocker_code,f.result_summary,
      f.observed_minutes,f.interaction_surface,f.heavy_session_used,f.manual_context_transfers,
      a.slug,fr.accepted_at,true;
    return;
  end if;

  select x.* into w from ops.work_request x where x.ref=p_work_request for update;
  if not found then raise exception 'exact sourced Work Request not found'; end if;
  select x.* into f from ops.sourced_work_request_outcome_feedback x
   where x.work_request_id=w.id and x.feedback_hash=p_feedback_hash for share;
  if not found then raise exception 'exact sourced outcome feedback proposal not found'; end if;
  select x.* into p from ops.sourced_work_request_plan x where x.id=f.plan_id for share;
  select x.* into ar from ops.sourced_work_request_plan_acceptance_receipt x
   where x.id=f.plan_acceptance_receipt_id for share;
  if not found or w.capture_idempotency_key is null
     or w.organization_tenant_id is distinct from 'carr-internal'
     or w.state is distinct from 'ready' or w.version is distinct from p_base_version
     or f.work_request_version is distinct from p_base_version
     or ar.work_request_id is distinct from w.id or ar.plan_id is distinct from p.id
     or ar.result_version is distinct from w.version or ar.plan_hash is distinct from p.plan_hash
     or ar.accepted_by_actor_id is null
     or w.shape_fixed_surface_ref is distinct from ar.shape_fixed_surface_ref then
    raise exception 'only an exact current ready sourced plan may receive human outcome-feedback acceptance';
  end if;
  canonical_preimage := ops.sourced_work_request_outcome_feedback_preimage(
    w.id,p.id,ar.id,f.criterion_results,f.evidence_refs,f.outcome,f.blocker_code,
    f.result_summary,f.observed_minutes,f.interaction_surface,f.heavy_session_used,
    f.manual_context_transfers);
  canonical_hash := ops.sourced_work_request_outcome_feedback_digest(canonical_preimage);
  if canonical_preimage is distinct from f.preimage
     or canonical_hash is distinct from f.feedback_hash
     or canonical_hash is distinct from p_feedback_hash then
    raise exception 'sourced outcome-feedback preimage is stale or does not match its exact hash';
  end if;
  if exists (select 1 from ops.sourced_work_request_outcome_feedback_acceptance_receipt x where x.feedback_id=f.id) then
    raise exception 'the sourced outcome-feedback proposal already has an immutable acceptance receipt';
  end if;
  insert into ops.sourced_work_request_outcome_feedback_acceptance_receipt
    (work_request_id,feedback_id,idempotency_key,base_version,feedback_hash,
     accepted_by_actor_id,result_version)
  values (w.id,f.id,p_idempotency_key,p_base_version,p_feedback_hash,a.id,w.version)
  returning * into fr;
  -- No Work Request UPDATE: this accepts a measurement, not an execution result.
  return query select w.id,w.ref,w.state,w.version,f.id,f.feedback_ref,f.feedback_hash,
    p.plan_ref,p.plan_hash,f.outcome,f.criterion_results,f.evidence_refs,f.blocker_code,f.result_summary,
    f.observed_minutes,f.interaction_surface,f.heavy_session_used,f.manual_context_transfers,
    a.slug,fr.accepted_at,false;
end;
$_$;


--
-- Name: accept_sourced_work_request_plan(text, integer, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.accept_sourced_work_request_plan(p_work_request text, p_base_version integer, p_plan_hash text, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, state text, version integer, plan_id uuid, plan_ref text, plan_hash text, accepted_by_actor_slug text, accepted_at timestamp with time zone, shape_disposition text, shape_fixed_surface_ref text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  actor_slug text; a public.actor%rowtype; w ops.work_request%rowtype;
  p ops.sourced_work_request_plan%rowtype;
  ar ops.sourced_work_request_plan_acceptance_receipt%rowtype;
  canonical_preimage jsonb; canonical_hash text; fixed_surface text; rationale text;
  preserve_shape boolean := false;
  applied_disposition text; applied_fixed_surface text; applied_rationale text;
  applied_actor_id uuid; applied_at timestamptz;
begin
  if p_idempotency_key is null or p_base_version is null or p_base_version < 1
     or coalesce(p_plan_hash,'') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'exact sourced plan acceptance inputs required';
  end if;
  actor_slug := ops.authority_actor_slug();
  select x.* into a from public.actor x
   where x.slug = actor_slug and x.active and x.kind = 'human' for share;
  if not found then raise exception 'authority session user is not an active human actor'; end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-plan-acceptance:' || p_idempotency_key, 0));
  select x.* into ar from ops.sourced_work_request_plan_acceptance_receipt x
   where x.idempotency_key = p_idempotency_key for share;
  if found then
    select x.* into p from ops.sourced_work_request_plan x where x.id = ar.plan_id for share;
    select x.* into w from ops.work_request x where x.id = ar.work_request_id for share;
    if not found or w.ref is distinct from p_work_request
       or ar.base_version is distinct from p_base_version or ar.plan_hash is distinct from p_plan_hash
       or ar.accepted_by_actor_id is distinct from a.id or p.id is distinct from ar.plan_id
       or p.plan_hash is distinct from ar.plan_hash or w.state is distinct from 'ready'
       or w.version is distinct from ar.result_version
       or not exists (
         select 1 from ops.sourced_work_request_plan_shape_binding_receipt b
          where b.plan_acceptance_receipt_id = ar.id and b.work_request_id = w.id
            and (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
                is not distinct from (b.disposition,b.fixed_surface_ref,b.rationale,b.decided_by_actor_id,b.decided_at)
         union all
         select 1 where not exists (select 1 from ops.sourced_work_request_plan_shape_binding_receipt b where b.plan_acceptance_receipt_id = ar.id)
           and w.shape_disposition = 'not_required' and w.shape_fixed_surface_ref is not distinct from ar.shape_fixed_surface_ref
       ) then
      raise exception 'idempotency key already names a different sourced plan acceptance';
    end if;
    return query select w.id,w.ref,w.state,w.version,p.id,p.plan_ref,p.plan_hash,
      a.slug,ar.accepted_at,w.shape_disposition,w.shape_fixed_surface_ref,true;
    return;
  end if;

  select x.* into w from ops.work_request x where x.ref = p_work_request for update;
  if not found then raise exception 'exact sourced Work Request not found'; end if;
  select x.* into p from ops.sourced_work_request_plan x
   where x.work_request_id = w.id and x.plan_hash = p_plan_hash for share;
  if not found or w.state is distinct from 'triaged' or w.version is distinct from p_base_version
     or p.work_request_version is distinct from p_base_version or w.capture_idempotency_key is null then
    raise exception 'exact current triaged sourced plan/version required';
  end if;

  if (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
       is not distinct from (null::text,null::text,null::text,null::uuid,null::timestamptz)
     and not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id = w.id) then
    preserve_shape := false;
  elsif w.shape_disposition = 'required' and w.shape_fixed_surface_ref is null
     and w.shape_rationale is not null and btrim(w.shape_rationale) <> ''
     and w.shape_decided_by_actor_id is not null and w.shape_decided_at is not null
     and exists (select 1 from ops.sourced_work_request_shape_disposition_receipt r
                  where r.work_request_id=w.id and r.result_version=w.version
                    and (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
                        is not distinct from (r.disposition,r.fixed_surface_ref,r.rationale,r.decided_by_actor_id,r.decided_at))
     and (select sr.work_request_version from ops.work_shape_revision sr
            where sr.work_request_id = w.id order by sr.version desc limit 1) = w.version then
    preserve_shape := true;
  elsif w.shape_disposition = 'not_required' and w.shape_fixed_surface_ref is not null
     and btrim(w.shape_fixed_surface_ref) <> '' and w.shape_rationale is not null
     and btrim(w.shape_rationale) <> '' and w.shape_decided_by_actor_id is not null
     and w.shape_decided_at is not null
     and exists (select 1 from ops.sourced_work_request_shape_disposition_receipt r
                  where r.work_request_id=w.id and r.result_version=w.version
                    and (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
                        is not distinct from (r.disposition,r.fixed_surface_ref,r.rationale,r.decided_by_actor_id,r.decided_at))
     and not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id = w.id) then
    preserve_shape := true;
  else
    raise exception 'sourced ready-plan requires either an exact unshaped request or one current receipt-backed shape disposition';
  end if;

  perform 1 from public.doctrine_document d join public.doctrine_section s on s.document_id = d.id
    join public.doctrine_revision r on r.id = s.current_revision_id and r.section_id = s.id
   where d.slug = 'runbook' and d.visibility = 'shared' and s.status = 'active'
     and s.id = p.runbook_section_id and r.id = p.runbook_revision_id and r.content_hash = p.runbook_content_hash
     and ('doctrine:' || d.slug || '#' || s.section_key) = p.runbook_ref
     and encode(public.digest(r.plain_text,'sha256'),'hex') = r.content_hash and r.body = jsonb_build_object('text',r.plain_text)
   for share of d,s,r;
  if not found then raise exception 'accepted sourced plan runbook is no longer current'; end if;
  perform 1 from public.doctrine_document source_document join public.doctrine_section source_section on source_section.document_id = source_document.id
    join public.doctrine_revision source_revision on source_revision.id = source_section.current_revision_id and source_revision.section_id = source_section.id
   where source_document.visibility = 'shared' and source_section.status = 'active'
     and source_section.id = w.doctrine_section_id and source_revision.id = w.doctrine_revision_id
     and source_revision.content_hash ~ '^[0-9a-f]{64}$'
     and encode(public.digest(source_revision.plain_text,'sha256'),'hex') = source_revision.content_hash
     and source_revision.body = jsonb_build_object('text',source_revision.plain_text)
   for share of source_document,source_section,source_revision;
  if not found then raise exception 'accepted sourced plan source evidence is no longer current'; end if;

  canonical_preimage := ops.sourced_work_request_plan_preimage(w.id,p.scope_summary,p.runbook_ref,p.runbook_section_id,p.runbook_revision_id,p.runbook_content_hash,p.dependency_refs,p.recovery_ref,p.observability_ref,p.caps);
  canonical_hash := ops.sourced_work_request_plan_digest(canonical_preimage);
  if canonical_preimage is distinct from p.preimage or canonical_hash is distinct from p.plan_hash or canonical_hash is distinct from p_plan_hash then
    raise exception 'sourced plan preimage is stale or does not match its exact hash';
  end if;

  fixed_surface := 'sourced-plan:' || p.plan_ref || '#' || p.plan_hash;
  rationale := 'Accepted immutable plan ' || p.plan_ref || ' for ' || p.runbook_ref || ' at sha256:' || p.runbook_content_hash;
  insert into ops.sourced_work_request_plan_acceptance_receipt
    (work_request_id,plan_id,idempotency_key,base_version,plan_hash,accepted_by_actor_id,result_version,shape_fixed_surface_ref,shape_rationale)
  values (w.id,p.id,p_idempotency_key,p_base_version,p_plan_hash,a.id,w.version + 1,fixed_surface,rationale)
  returning * into ar;

  if preserve_shape then
    insert into ops.sourced_work_request_plan_shape_binding_receipt
      (plan_acceptance_receipt_id,work_request_id,disposition,fixed_surface_ref,rationale,decided_by_actor_id,decided_at)
    values (ar.id,w.id,w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at);
    applied_disposition := w.shape_disposition; applied_fixed_surface := w.shape_fixed_surface_ref;
    applied_rationale := w.shape_rationale; applied_actor_id := w.shape_decided_by_actor_id; applied_at := w.shape_decided_at;
  else
    applied_disposition := 'not_required'; applied_fixed_surface := ar.shape_fixed_surface_ref;
    applied_rationale := ar.shape_rationale; applied_actor_id := a.id; applied_at := ar.accepted_at;
  end if;

  update ops.work_request x set state='ready',version=ar.result_version,updated_at=now(),
    shape_disposition=applied_disposition,shape_fixed_surface_ref=applied_fixed_surface,
    shape_rationale=applied_rationale,shape_decided_by_actor_id=applied_actor_id,shape_decided_at=applied_at
   where x.id=w.id;
  select x.* into w from ops.work_request x where x.id=w.id;
  return query select w.id,w.ref,w.state,w.version,p.id,p.plan_ref,p.plan_hash,
    a.slug,ar.accepted_at,w.shape_disposition,w.shape_fixed_surface_ref,false;
end;
$_$;


--
-- Name: activate_calendar_prebrief_joe_live(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.activate_calendar_prebrief_joe_live(p_evidence_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare a ops.calendar_prebrief_allowed_calendar%rowtype; rid uuid; v_definition_count integer;
begin
 if session_user<>'carr_authority_joe' or p_evidence_digest !~ '^[0-9a-f]{64}$' then raise exception 'Joe activation authority or evidence refused'; end if;
 select * into a from ops.calendar_prebrief_allowed_calendar where sponsor='joe' for update;
 if not found or a.active_revision_id is null or not exists(select 1 from ops.calendar_prebrief_allowlist_receipt where id=a.active_revision_id and sponsor='joe' and configuration_digest=a.configuration_digest) then raise exception 'Joe activation requires current allowlist receipt'; end if;
 insert into ops.calendar_prebrief_runtime_activation_receipt(sponsor,app_evidence_digest,allowlist_revision_id,activated_by) values('joe',p_evidence_digest,a.active_revision_id,'joe') returning id into rid;
 update ops.job_definition set enabled=true,updated_at=now()
  where key='calendar-prebrief-projection-joe-daily' and version=1
    and owner_actor='joe';
 get diagnostics v_definition_count = row_count;
 if v_definition_count<>1 then
   raise exception 'Joe activation requires exactly one Joe live definition';
 end if;
 return rid;
end $_$;


--
-- Name: activate_context_bundle(text, text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.activate_context_bundle(p_work_request text, p_plan_ref text, p_bundle jsonb, p_idempotency_key uuid) RETURNS TABLE(binding_id text, bundle_digest text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  tenant text := current_setting('carr.organization_tenant_id', true);
  work ops.work_request%rowtype;
  plan ops.sourced_work_request_plan%rowtype;
  existing ops.context_activation_binding%rowtype;
  new_id text;
  digest_text text;
  item jsonb;
  ordinal integer := 0;
begin
  if coalesce(tenant,'') = '' then raise exception 'activation requires authenticated tenant context'; end if;
  select * into work from ops.work_request where ref=p_work_request and organization_tenant_id=tenant for share;
  if not found then raise exception 'activation work request is not visible to tenant'; end if;
  select p.* into plan from ops.sourced_work_request_plan p
   join ops.sourced_work_request_plan_acceptance_receipt a on a.plan_id=p.id and a.plan_hash=p.plan_hash
   where p.work_request_id=work.id and p.plan_ref=p_plan_ref and a.result_version=work.version for share;
  if not found then raise exception 'activation requires the exact accepted current plan'; end if;
  select * into existing from ops.context_activation_binding where organization_tenant_id=tenant and idempotency_key=p_idempotency_key for share;
  if found then
    if existing.work_request_id<>work.id or existing.plan_hash<>plan.plan_hash or existing.bundle_digest<>coalesce(p_bundle->>'bundle_digest','') then raise exception 'activation idempotency key conflicts with prior binding'; end if;
    return query select existing.binding_id, existing.bundle_digest, true; return;
  end if;
  if jsonb_typeof(p_bundle)<>'object' or p_bundle->>'schema_version' <> 'context-bundle.v1' or jsonb_typeof(p_bundle->'header')<>'object' or jsonb_typeof(p_bundle->'items')<>'array' then raise exception 'activation bundle shape is invalid'; end if;
  if jsonb_array_length(p_bundle->'items') < 1 or jsonb_array_length(p_bundle->'items') > 64 then raise exception 'activation bundle exceeds bounded item count'; end if;
  if p_bundle->'header'->>'work_request_id' <> work.ref or p_bundle->'header'->>'accepted_plan_digest' <> coalesce(plan.preimage->'context_activation'->>'base_plan_digest',plan.plan_hash) then raise exception 'activation bundle is not bound to accepted Work Request and plan'; end if;
  if p_bundle->'header'->>'tenant_id' <> tenant then raise exception 'activation bundle tenant mismatch'; end if;
  if plan.preimage->'context_activation'->>'bundle_digest' is null
     or plan.preimage->'context_activation'->>'bundle_digest' <> p_bundle->>'bundle_digest' then
    raise exception 'activation bundle digest is not in the accepted plan preimage';
  end if;
  if plan.preimage->'context_activation'->'item_refs' is null
     or (select count(*) from jsonb_array_elements_text(plan.preimage->'context_activation'->'item_refs')) <> jsonb_array_length(p_bundle->'items') then
    raise exception 'activation bundle item set is not in the accepted plan preimage';
  end if;
  digest_text := ops.context_activation_bundle_digest(p_bundle);
  if p_bundle->>'bundle_digest' <> digest_text then raise exception 'activation bundle digest does not reproduce canonical body'; end if;
  new_id := 'ctx-' || encode(gen_random_bytes(8),'hex');
  insert into ops.context_activation_binding(idempotency_key,organization_tenant_id,work_request_id,work_request_version,plan_id,plan_hash,binding_id,bundle_digest,retrieval_policy,mode,issued_at,expires_at,compiler_ref,query_basis_digest,grounding_plan)
  values(p_idempotency_key,tenant,work.id,work.version,plan.id,plan.plan_hash,new_id,p_bundle->>'bundle_digest',jsonb_build_object('ref',coalesce(p_bundle->'header'->>'retrieval_policy','policy:unknown')),coalesce(p_bundle->'header'->>'mode','shadow'),now(),coalesce((p_bundle->'header'->>'expires_at')::timestamptz,now()+interval '1 hour'),coalesce(p_bundle->'header'->>'compiler_id','compiler:unknown'),coalesce(p_bundle->'header'->>'query_basis_digest','sha256:'||repeat('0',64)),jsonb_build_object('source_coverage',jsonb_build_object('doctrine','retrieved','standing_rules','retrieved','accepted_decisions','dependency_selected','promoted_memory','dependency_selected','skills',jsonb_build_object('state','not_available','reason','no canonical skills store'), 'architecture_constraints',jsonb_build_object('state','covered_by_doctrine_and_active_rules','reason','canonical architecture constraints are represented by the selected doctrine/rule revisions'), 'prior_failures',jsonb_build_object('state','dependency_selected','reason','selected canonical defect refs are frozen body-free in the bundle'))));
  for item in select * from jsonb_array_elements(p_bundle->'items') loop
    ordinal := ordinal + 1;
    insert into ops.context_activation_item(binding_id,ordinal,artifact_kind,canonical_ref,revision,content_digest,scope_redaction,required,trigger_ref,consumer_ref,delivery_mode,representation_kind,freshness,selection_reason,selection_rank)
    values((select b.id from ops.context_activation_binding b where b.binding_id=new_id),ordinal,coalesce(item->>'artifact_kind',item->>'kind'),item->>'canonical_ref',item->>'revision',item->>'digest',coalesce(item->>'scope_redaction',item->>'redaction_class'),'true' = lower(coalesce(item->>'required','false')),coalesce(item->>'trigger_ref',item->>'trigger'),coalesce(item->>'consumer_ref',item->>'consumer'),coalesce(item->>'delivery_mode','reference_only'),coalesce(item->>'representation_kind',item->>'kind'),jsonb_build_object('state',coalesce(item->>'freshness','unknown')),coalesce(item->>'selection_reason','bounded-retrieval'),coalesce((item->>'selection_rank')::integer,ordinal));
  end loop;
  return query select new_id, p_bundle->>'bundle_digest', false;
end $$;


--
-- Name: activate_guidance_registry(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.activate_guidance_registry(p_registry_id uuid, p_manifest_digest text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_batch_id uuid;
  authority_slug text;
  authority_actor uuid;
  registry_owner uuid;
  receipt_id uuid;
  event_id uuid;
  constitution_count integer;
  coverage_count integer;
  existing record;
begin
  authority_slug := ops.authority_actor_slug();
  select id into authority_actor from actor
   where slug=authority_slug and kind='human' and active;
  if authority_actor is null then
    raise exception 'guidance registry activation requires an admitted human authority actor';
  end if;
  if p_manifest_digest !~ '^[0-9a-f]{64}$' or coalesce(btrim(p_idempotency_key),'')=''
     or coalesce(btrim(p_reason),'')='' then
    raise exception 'activation requires a sha256 manifest digest, idempotency key and reason';
  end if;
  select created_by into registry_owner from ops.guidance_registry where id=p_registry_id;
  if registry_owner is null then
    raise exception 'unknown guidance registry %',p_registry_id;
  end if;
  if registry_owner <> authority_actor then
    raise exception 'guidance registry activation requires its accountable human authority actor';
  end if;
  select b.id into v_batch_id from ops.guidance_import_batch b
   where b.manifest_digest=p_manifest_digest
     and exists (select 1 from ops.guidance_import_apply_event a where a.batch_id=b.id)
     and exists (select 1 from ops.guidance_import_decision_event d
                  where d.batch_id=b.id and d.manifest_digest=p_manifest_digest and d.state='active');
  if v_batch_id is null then
    raise exception 'registry activation requires an applied, human-approved exact guidance import manifest';
  end if;
  perform ops.assert_guidance_import_inventory(v_batch_id);
  perform ops.assert_guidance_import_materialization(v_batch_id);
  perform pg_advisory_xact_lock(
    hashtextextended('guidance-registry-activation:' || p_idempotency_key,0));
  select ar.id,ar.kind,ar.subject_type,ar.subject_id,ar.actor_id,ar.decision,
         ar.contract_hash,ge.id as event_id,ge.manifest_digest,ge.reason
    into existing
    from ops.authority_receipt ar
    left join ops.guidance_registry_event ge on ge.authority_receipt_id=ar.id
   where ar.idempotency_key=p_idempotency_key;
  if existing.id is not null then
    if existing.kind<>'activation' or existing.subject_type<>'guidance'
       or existing.subject_id<>p_registry_id or existing.actor_id<>authority_actor
       or existing.decision<>'approved' or existing.contract_hash<>p_manifest_digest
       or existing.event_id is null or existing.manifest_digest<>p_manifest_digest
       or existing.reason<>p_reason then
      raise exception 'idempotency key already names a different or incomplete guidance registry activation';
    end if;
    return existing.event_id;
  end if;
  select count(*) into constitution_count
    from ops.v_guidance_materialized_current where is_constitution;
  if constitution_count not between 5 and 10 then
    raise exception 'guidance constitution must contain between 5 and 10 active items';
  end if;
  select count(*) into coverage_count from ops.assert_guidance_registry_coverage();
  if coverage_count <> 0 then
    raise exception 'guidance registry has % coverage failure(s)',coverage_count;
  end if;
  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,
     contract_hash,evidence_refs)
  values
    (p_idempotency_key,'activation','guidance',p_registry_id,authority_actor,
     'approved',p_manifest_digest,array[p_registry_id::text])
  returning id into receipt_id;
  insert into ops.guidance_registry_event
    (registry_id,state,authority_receipt_id,manifest_digest,reason)
  values (p_registry_id,'active',receipt_id,p_manifest_digest,p_reason)
  returning id into event_id;
  return event_id;
end $_$;


--
-- Name: activate_guidance_situation_mapping(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.activate_guidance_situation_mapping(p_proposed_mapping_id uuid, p_authority_binding_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  authority_slug text;
  authority_actor uuid;
  mapping_id uuid;
  proposal ops.guidance_situation_mapping%rowtype;
begin
  authority_slug := ops.authority_actor_slug();
  select id into authority_actor from actor
   where slug=authority_slug and kind='human';
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'situation mapping activation requires a reason';
  end if;
  select * into proposal from ops.guidance_situation_mapping
   where id=p_proposed_mapping_id and state='proposed';
  if proposal.id is null then
    raise exception 'unknown proposed situation mapping %',p_proposed_mapping_id;
  end if;
  if not exists (
    select 1
      from ops.guidance_authority_binding b
      join ops.authority_receipt ar on ar.id=b.authority_receipt_id
     where b.id=p_authority_binding_id
       and b.guidance_revision_id=proposal.guidance_revision_id
       and ar.actor_id=authority_actor
       and ar.decision='approved') then
    raise exception 'mapping activation requires this authority session approval for the exact doctrine revision';
  end if;
  if not exists (
    select 1 from doctrine_concept_mapping
     where concept_id=proposal.concept_id
       and section_id=proposal.doctrine_section_id
       and status='approved') then
    raise exception 'mapping activation requires an approved WR-AI-006 doctrine bridge';
  end if;
  insert into ops.guidance_situation_mapping
    (guidance_revision_id,concept_id,doctrine_section_id,state,
     authority_binding_id,supersedes_mapping_id,reason)
  values
    (proposal.guidance_revision_id,proposal.concept_id,proposal.doctrine_section_id,
     'active',p_authority_binding_id,proposal.id,p_reason)
  returning id into mapping_id;
  return mapping_id;
end $$;


--
-- Name: admit_job_cost(uuid, uuid, text, numeric); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.admit_job_cost(p_job_id uuid, p_lease_token uuid, p_route_key text, p_estimated_cost_usd numeric) RETURNS TABLE(admitted boolean, reservation_id uuid, refusal_id uuid, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; route ops.provider_route%rowtype;
        spent numeric; reserved numeric; rid uuid; refusal ops.cost_refusal%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select * into route from ops.provider_route where route_key=p_route_key and enabled;
  if not found then raise exception 'provider route % is not enabled',p_route_key; end if;
  if p_estimated_cost_usd<0 then raise exception 'estimated cost must be non-negative'; end if;
  select coalesce(sum(a.cost_usd),0) into spent from ops.job_attempt a
   where a.provider_route=p_route_key and a.started_at>=date_trunc('month',now());
  select coalesce(sum(r.estimated_cost_usd),0) into reserved from ops.cost_reservation r
   where r.route_key=p_route_key and r.state='reserved'
     and r.created_at>=date_trunc('month',now());
  if route.monthly_budget_usd is not null
     and spent+reserved+p_estimated_cost_usd>route.monthly_budget_usd then
    insert into ops.cost_refusal
      (job_id,attempt,route_key,estimated_cost_usd,monthly_budget_usd,spent_usd,reserved_usd,reason)
    values
      (j.id,j.attempt,p_route_key,p_estimated_cost_usd,route.monthly_budget_usd,spent,reserved,
       'monthly_budget_exceeded')
    on conflict (job_id,attempt,route_key) do nothing
    returning * into refusal;
    if refusal.id is null then
      select * into refusal from ops.cost_refusal
       where job_id=j.id and attempt=j.attempt and route_key=p_route_key;
    end if;
    return query select false,null::uuid,refusal.id,refusal.reason;
    return;
  end if;
  insert into ops.cost_reservation(job_id,attempt,route_key,estimated_cost_usd)
    values(j.id,j.attempt,p_route_key,p_estimated_cost_usd)
  returning id into rid;
  return query select true,rid,null::uuid,null::text;
end $$;


--
-- Name: applicable_rules(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.applicable_rules(p_workflow text DEFAULT NULL::text, p_surface text DEFAULT NULL::text, p_tier text DEFAULT NULL::text) RETURNS TABLE(rule_id uuid, statement text, enforcement_class text, binding_moment text, applicability jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select r.id,r.statement,a.enforcement_class,a.binding_moment,a.applicability
    from rule r
    join ops.rule_admission a on a.rule_id=r.id
    join ops.rule_approval_receipt ar
      on ar.rule_id=r.id and ar.actor_id=r.activated_by
     and (ar.rule_version=r.version or exists (
       select 1 from ops.rule_approval_lifecycle_anchor legacy
        where legacy.approval_receipt_id=ar.id and legacy.rule_id=r.id
          and legacy.rule_version_after=r.version
          and legacy.statement_hash=ar.statement_hash))
     and ar.statement_hash=encode(digest(r.statement,'sha256'),'hex')
     and ar.policy_kind=a.enforcement_class
     and ar.enforcement_status=a.enforcement_status
     and ar.normalized_contract->>'binding_moment'=a.binding_moment
     and ar.normalized_contract->'applicability'=a.applicability
     and ar.normalized_contract->'projection'=a.projection
     and ar.normalized_contract->'reachability'=a.reachability
     and ar.normalized_contract->'input_contract'=a.input_contract
     and ar.evidence_refs=a.fixture_refs
   where r.status='active' and a.state='admitted' and a.admitted_by=ar.actor_id
     and exists (
       select 1 from ops.authority_receipt auth
        where auth.idempotency_key='approval:'||ar.idempotency_key
          and auth.kind='activation' and auth.subject_type='rule'
          and auth.subject_id=r.id and auth.actor_id=ar.actor_id
          and auth.contract_hash=ar.contract_hash)
     and not exists (
       select 1 from unnest(ar.requested_control_keys) requested(control_key)
        where not exists (
          select 1 from ops.rule_enforcement_point ep
          join ops.enforcement_control_catalog c using (control_key)
          join ops.rule_control_binding b
            on b.rule_id=ep.rule_id and b.control_key=ep.control_key
         where ep.rule_id=r.id and ep.control_key=requested.control_key
           and ep.installed and c.installed and c.verified_at is not null
           and b.statement_hash=ar.statement_hash
           and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')))
     and (p_workflow is null or not (a.applicability ? 'workflows')
          or a.applicability->'workflows' ? '*'
          or a.applicability->'workflows' ? p_workflow)
     and (p_surface is null or not (a.applicability ? 'surfaces')
          or a.applicability->'surfaces' ? '*'
          or a.applicability->'surfaces' ? p_surface)
     and (p_tier is null or not (a.applicability ? 'tiers')
          or a.applicability->'tiers' ? '*'
          or a.applicability->'tiers' ? p_tier)
   order by r.created_at,r.id
$$;


--
-- Name: FUNCTION applicable_rules(p_workflow text, p_surface text, p_tier text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.applicable_rules(p_workflow text, p_surface text, p_tier text) IS 'Compiles the active admitted rule set for a workflow/surface/tier. SECURITY DEFINER with a pinned search_path (0188): the caller is the worker''s carr_reader role, which is views-only by design and cannot read public.rule or ops.rule_admission directly. Read-only, no dynamic SQL.';


--
-- Name: apply_guidance_import_batch(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.apply_guidance_import_batch(p_batch_id uuid, p_manifest_digest text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_batch ops.guidance_import_batch%rowtype;
  v_existing record;
  v_entry ops.guidance_import_entry%rowtype;
  v_item_id uuid;
  v_revision_id uuid;
  v_mapping jsonb;
  v_mapping_ordinal integer;
  v_proposed_mapping_id uuid;
  v_apply_event_id uuid;
begin
  if p_manifest_digest !~ '^[0-9a-f]{64}$'
     or coalesce(btrim(p_idempotency_key),'')=''
     or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance import apply requires digest, idempotency key and reason';
  end if;
  select * into v_batch from ops.guidance_import_batch where id=p_batch_id;
  if v_batch.id is null or v_batch.manifest_digest<>p_manifest_digest then
    raise exception 'unknown guidance import batch or mismatched manifest digest';
  end if;
  select * into v_existing from ops.guidance_import_apply_event where idempotency_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.batch_id<>p_batch_id or v_existing.manifest_digest<>p_manifest_digest
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different guidance import apply';
    end if;
    return v_existing.id;
  end if;
  if exists (select 1 from ops.guidance_import_apply_event where batch_id=p_batch_id) then
    raise exception 'guidance import batch is already applied under another idempotency key';
  end if;
  perform ops.assert_guidance_import_inventory(p_batch_id);
  for v_entry in select * from ops.guidance_import_entry where batch_id=p_batch_id order by ordinal loop
    select id into v_item_id from ops.guidance_item
      where source_rule_id=v_entry.source_rule_id and source_clause=v_entry.source_clause;
    if v_item_id is null then
      insert into ops.guidance_item
        (source_rule_id,source_clause,is_primary,split_group_id,created_by)
      values (v_entry.source_rule_id,v_entry.source_clause,v_entry.is_primary,
              ops.guidance_import_split_group_id(v_entry.split_group_key),v_batch.classifier_actor_id)
      returning id into v_item_id;
    elsif not exists (
      select 1 from ops.guidance_item where id=v_item_id
        and is_primary=v_entry.is_primary
        and split_group_id is not distinct from ops.guidance_import_split_group_id(v_entry.split_group_key)) then
      raise exception 'existing guidance item conflicts with import entry %',v_entry.guidance_id;
    end if;
    select id into v_revision_id from ops.guidance_revision
      where guidance_item_id=v_item_id and version=1;
    if v_revision_id is null then
      if exists (select 1 from ops.guidance_revision where guidance_item_id=v_item_id) then
        raise exception 'existing guidance item has a non-import revision history for entry %',v_entry.guidance_id;
      end if;
      insert into ops.guidance_revision
        (guidance_item_id,version,guidance_type,scope,activation,consumer,verification,
         provenance,delivery,is_constitution,classified_by,reason)
      values (v_item_id,1,v_entry.guidance_type,v_entry.scope,v_entry.activation,v_entry.consumer,
              v_entry.verification,v_entry.provenance,v_entry.delivery,v_entry.is_constitution,
              v_batch.classifier_actor_id,v_entry.revision_reason)
      returning id into v_revision_id;
    elsif not exists (
      select 1 from ops.guidance_revision where id=v_revision_id
        and guidance_type=v_entry.guidance_type and scope=v_entry.scope
        and activation=v_entry.activation and consumer=v_entry.consumer
        and verification=v_entry.verification and provenance=v_entry.provenance
        and delivery=v_entry.delivery and is_constitution=v_entry.is_constitution
        and reason=v_entry.revision_reason and classified_by=v_batch.classifier_actor_id) then
      raise exception 'existing guidance revision conflicts with import entry %',v_entry.guidance_id;
    end if;
    v_mapping_ordinal := 0;
    for v_mapping in select value from jsonb_array_elements(v_entry.situation_mappings) loop
      v_mapping_ordinal := v_mapping_ordinal + 1;
      select proposed_mapping_id into v_proposed_mapping_id
        from ops.guidance_import_mapping_execution
       where batch_id=p_batch_id and entry_id=v_entry.id and ordinal=v_mapping_ordinal;
      if v_proposed_mapping_id is null then
        v_proposed_mapping_id := ops.propose_guidance_situation_mapping(
          v_revision_id,(v_mapping->>'concept_id')::uuid,
          (v_mapping->>'doctrine_section_id')::uuid,v_mapping->>'reason');
        insert into ops.guidance_import_mapping_execution
          (batch_id,entry_id,ordinal,concept_id,doctrine_section_id,proposed_mapping_id)
        values (p_batch_id,v_entry.id,v_mapping_ordinal,(v_mapping->>'concept_id')::uuid,
                (v_mapping->>'doctrine_section_id')::uuid,v_proposed_mapping_id);
      end if;
    end loop;
  end loop;
  insert into ops.guidance_import_apply_event
    (batch_id,manifest_digest,idempotency_key,applied_by,reason)
  values (p_batch_id,p_manifest_digest,p_idempotency_key,v_batch.classifier_actor_id,p_reason)
  returning id into v_apply_event_id;
  return v_apply_event_id;
end $_$;


--
-- Name: approve_program5_release(text, text, uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_program5_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid, p_expires_hours integer) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
  select ops.approve_program5_release($1,$2,$3,$4,null,null)
$_$;


--
-- Name: approve_program5_release(text, text, uuid, integer, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_program5_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid, p_expires_hours integer, p_verifier_actor text, p_verifier_evidence_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare actor_slug text; rel ops.release%rowtype; existing ops.release_approval_receipt%rowtype;
  rehearsal_run ops.run%rowtype; approval_uuid uuid; approved_time timestamptz;
  expiry_time timestamptz; projection jsonb; approval_hash text; approval_ref text;
  supplied_verifier_actor text; supplied_verifier_evidence text;
  candidate_verifier_actor text; candidate_verifier_evidence text;
  verifier_actor_value text; verifier_evidence_value text;
begin
  actor_slug:=ops.authority_actor_slug();
  if actor_slug<>'joe' then raise exception 'Program 5 Production approval requires Joe authority'; end if;
  if p_idempotency_key is null or coalesce(p_release_key,'')='' or coalesce(p_plan_hash,'')=''
     or coalesce(p_expires_hours,0) not between 1 and 24 then
    raise exception 'invalid Program 5 approval input';
  end if;
  if (p_verifier_actor is null) <> (p_verifier_evidence_ref is null)
     or (p_verifier_actor is not null
         and (btrim(p_verifier_actor)='' or btrim(p_verifier_evidence_ref)='')) then
    raise exception 'supplied verifier actor and evidence must be an atomic nonblank pair';
  end if;
  supplied_verifier_actor:=case when p_verifier_actor is null then null else lower(btrim(p_verifier_actor)) end;
  supplied_verifier_evidence:=case when p_verifier_evidence_ref is null then null else btrim(p_verifier_evidence_ref) end;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into existing from ops.release_approval_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.plan_hash<>p_plan_hash
       or existing.approval_expires_at-existing.approved_at
          <> make_interval(hours=>p_expires_hours)
       or not exists (
      select 1 from ops.release where id=existing.release_id and release_key=p_release_key
        and plan_hash=existing.plan_hash and approval_receipt_id=existing.id
        and state in ('approved','deploying','verifying','complete')
        and approved_at=existing.approved_at
        and approval_expires_at=existing.approval_expires_at
        and (supplied_verifier_actor is null or existing.verifier_actor=supplied_verifier_actor)
        and (supplied_verifier_evidence is null or existing.verifier_evidence_ref=supplied_verifier_evidence)) then
      raise exception 'Program 5 approval idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('approval_receipt_id',existing.id,
      'approval_ref',existing.evidence_ref,'approval_expires_at',existing.approval_expires_at,
      'replayed',true);
  end if;
  select * into rel from ops.release where release_key=p_release_key for update;
  if not found or rel.environment<>'production' or rel.state<>'candidate'
     or rel.plan_hash is distinct from p_plan_hash then
    raise exception 'release is not the exact Production candidate plan requested';
  end if;
  if (rel.verifier_actor is null) <> (rel.verifier_evidence_ref is null)
     or (rel.verifier_actor is not null
         and (btrim(rel.verifier_actor)='' or btrim(rel.verifier_evidence_ref)='')) then
    raise exception 'candidate verifier actor and evidence must be an atomic nonblank pair';
  end if;
  candidate_verifier_actor:=case when rel.verifier_actor is null then null else lower(btrim(rel.verifier_actor)) end;
  candidate_verifier_evidence:=case when rel.verifier_evidence_ref is null then null else btrim(rel.verifier_evidence_ref) end;
  verifier_actor_value:=coalesce(supplied_verifier_actor,candidate_verifier_actor);
  verifier_evidence_value:=coalesce(supplied_verifier_evidence,candidate_verifier_evidence);
  if verifier_actor_value is null or verifier_evidence_value is null then
    raise exception 'release cannot be approved without an INDEPENDENT VERIFIER and verification evidence';
  end if;
  if rel.maker_actor is not null
     and verifier_actor_value=lower(btrim(rel.maker_actor)) then
    raise exception 'maker cannot independently verify their own release';
  end if;
  select r.* into rehearsal_run from ops.run r
   join ops.staging_recovery_rehearsal_bundle b on b.id=r.recovery_rehearsal_bundle_id
   where r.release_id=rel.id and r.service_id=rel.service_id
     and r.environment='staging' and r.run_key='recovery.rehearsal.worker'
     and r.state='succeeded' and r.evidence_ref=b.evidence_ref
     and b.current_release_id=rel.id and b.service_id=rel.service_id
     and b.recovery_strategy=rel.recovery_strategy
     and b.recovery_plan_ref=rel.rollback_plan_ref and b.plan_hash=rel.plan_hash
     and b.declared_migration_set_sha256=ops.program5_migration_set_sha256(rel.migration_set)
     and b.declared_migration_count=cardinality(rel.migration_set)
     and b.declared_schema_highest_migration=rel.schema_highest_migration
     and b.declared_schema_applied_count=rel.schema_applied_count
     and b.declared_schema_ledger_sha256=rel.schema_ledger_sha256
     and b.completed_at between clock_timestamp()-interval '24 hours' and clock_timestamp()
   order by r.ended_at desc limit 1;
  if not found then raise exception 'release has no exact typed recovery rehearsal'; end if;
  approved_time:=clock_timestamp(); expiry_time:=approved_time+make_interval(hours=>p_expires_hours);
  projection:=jsonb_build_object('release_id',rel.id,'plan_hash',rel.plan_hash,
    'recovery_run_id',rehearsal_run.id,'recovery_bundle_id',rehearsal_run.recovery_rehearsal_bundle_id,
    'approved_by_actor',actor_slug,'approved_at',approved_time,'approval_expires_at',expiry_time,
    'verifier_actor',verifier_actor_value,'verifier_evidence_ref',verifier_evidence_value);
  approval_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  approval_ref:='ops.program5-release-approval:'||approval_hash;
  insert into ops.release_approval_receipt(idempotency_key,release_id,recovery_run_id,
    recovery_bundle_id,plan_hash,approved_by_actor,approved_at,approval_expires_at,
    verifier_actor,verifier_evidence_ref,
    approval_sha256,evidence_ref)
  values(p_idempotency_key,rel.id,rehearsal_run.id,rehearsal_run.recovery_rehearsal_bundle_id,
    rel.plan_hash,actor_slug,approved_time,expiry_time,verifier_actor_value,verifier_evidence_value,
    approval_hash,approval_ref)
  returning id into approval_uuid;
  update ops.release set verifier_actor=verifier_actor_value,
    verifier_evidence_ref=verifier_evidence_value,state='approved',approved_by_actor=actor_slug,
    approved_at=approved_time,approval_expires_at=expiry_time,
    approval_receipt_id=approval_uuid where id=rel.id;
  return jsonb_build_object('approval_receipt_id',approval_uuid,'approval_ref',approval_ref,
    'approval_expires_at',expiry_time,'replayed',false);
end $$;


--
-- Name: approve_rule(uuid, text, text[], text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_rule(p_rule_id uuid, p_policy_kind text, p_control_keys text[], p_idempotency_key text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_actor_slug text;
  v_actor_id uuid;
  v_rule rule%rowtype;
  v_intake_id uuid;
  v_requested text[];
  v_installed text[];
  v_missing text[];
  v_evidence text[];
  v_status text;
  v_contract jsonb;
  v_contract_hash text;
  v_receipt ops.rule_approval_receipt%rowtype;
  v_prior ops.rule_approval_receipt%rowtype;
begin
  v_actor_slug := ops.authority_actor_slug();
  if v_actor_slug <> 'joe' then
    raise exception 'system rule approval requires Joe authority; % may teach and participate but cannot replace Joe approval',
      v_actor_slug;
  end if;
  select id into v_actor_id from actor
   where slug=v_actor_slug and kind='human' and active;
  if v_actor_id is null then
    raise exception 'authority actor % is not an active human',v_actor_slug;
  end if;
  if p_policy_kind='judgment_advisory' then
    raise exception 'advisory guidance is not an unbreakable rule; build a mechanical control before approval';
  end if;
  if p_policy_kind not in ('machine_enforceable','human_only') then
    raise exception 'unsupported policy kind %',p_policy_kind;
  end if;
  if btrim(coalesce(p_idempotency_key,''))='' or btrim(coalesce(p_reason,''))='' then
    raise exception 'idempotency key and approval reason are required';
  end if;

  v_requested := array(
    select distinct btrim(u.control_key)
      from unnest(coalesce(p_control_keys,'{}'::text[])) as u(control_key)
     where btrim(u.control_key)<>'' order by btrim(u.control_key));
  if p_policy_kind='human_only'
     and not ('human_authority_runtime'=any(v_requested)) then
    v_requested := array_append(v_requested,'human_authority_runtime');
    select array_agg(u.control_key order by u.control_key) into v_requested
      from unnest(v_requested) as u(control_key);
  end if;
  if cardinality(v_requested)=0 then
    raise exception 'exact registered controls must be implemented before approval';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('rule-approval:'||p_idempotency_key,0));
  select * into v_prior from ops.rule_approval_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if v_prior.rule_id is distinct from p_rule_id
       or v_prior.policy_kind is distinct from p_policy_kind
       or v_prior.requested_control_keys is distinct from v_requested
       or v_prior.reason is distinct from btrim(p_reason) then
      raise exception 'rule approval idempotency key was reused with different input';
    end if;
    select * into v_rule from rule where id=p_rule_id for update;
    if not found
       or v_rule.status is distinct from 'active'
       or not (v_rule.version=v_prior.rule_version or exists (
         select 1 from ops.rule_approval_lifecycle_anchor legacy
          where legacy.approval_receipt_id=v_prior.id and legacy.rule_id=v_rule.id
            and legacy.rule_version_after=v_rule.version
            and legacy.statement_hash=v_prior.statement_hash))
       or encode(digest(v_rule.statement,'sha256'),'hex') is distinct from v_prior.statement_hash
       or v_rule.activated_by is distinct from v_prior.actor_id then
      raise exception 'rule approval replay refused: current active rule no longer matches the immutable approval';
    end if;
    if not exists (
      select 1 from ops.rule_admission a
       where a.rule_id=v_rule.id and a.state='admitted'
         and a.enforcement_status=v_prior.enforcement_status
         and a.enforcement_class=v_prior.policy_kind
         and a.admitted_by=v_prior.actor_id
         and a.binding_moment=v_prior.normalized_contract->>'binding_moment'
         and a.applicability=v_prior.normalized_contract->'applicability'
         and a.projection=v_prior.normalized_contract->'projection'
         and a.reachability=v_prior.normalized_contract->'reachability'
         and a.input_contract=v_prior.normalized_contract->'input_contract'
         and a.fixture_refs=v_prior.evidence_refs
    ) or exists (
      select 1 from unnest(v_prior.requested_control_keys) requested(control_key)
       where not exists (
         select 1
           from ops.rule_enforcement_point ep
           join ops.enforcement_control_catalog c using (control_key)
           join ops.rule_control_binding b
             on b.rule_id=ep.rule_id and b.control_key=ep.control_key
          where ep.rule_id=v_rule.id
            and ep.control_key=requested.control_key
            and ep.installed and c.installed and c.verified_at is not null
            and b.statement_hash=v_prior.statement_hash
            and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')
       )
    ) or not exists (
      select 1 from ops.authority_receipt ar
       where ar.idempotency_key='approval:'||v_prior.idempotency_key
         and ar.kind='activation' and ar.subject_type='rule'
         and ar.subject_id=v_rule.id and ar.actor_id=v_prior.actor_id
         and ar.contract_hash=v_prior.contract_hash
    ) then
      raise exception 'rule approval replay refused: exact installed enforcement or authority evidence is stale';
    end if;
    return jsonb_build_object(
      'ok',true,'replayed',true,'rule_id',v_prior.rule_id,
      'policy_status','active','enforcement_status',v_prior.enforcement_status,
      'installed_controls',v_prior.installed_control_keys,
      'pending_controls','{}'::text[],'approval_receipt_id',v_prior.id);
  end if;

  select * into v_rule from rule where id=p_rule_id for update;
  if not found then raise exception 'rule % not found',p_rule_id; end if;
  if v_rule.status<>'proposed' then
    raise exception 'rule % is %, only a proposed rule can be approved',p_rule_id,v_rule.status;
  end if;

  select coalesce(array_agg(c.control_key order by c.control_key),'{}'::text[]),
         coalesce(array_agg(c.test_ref order by c.control_key),'{}'::text[])
    into v_installed,v_evidence
    from ops.enforcement_control_catalog c
    join ops.rule_control_binding b using (control_key)
   where c.installed and c.verified_at is not null
     and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')
     and b.rule_id=p_rule_id
     and b.statement_hash=encode(digest(v_rule.statement,'sha256'),'hex')
     and c.control_key=any(v_requested);
  v_missing := array(
    select requested.control_key from unnest(v_requested) as requested(control_key)
     where not (requested.control_key=any(v_installed)) order by requested.control_key);
  if cardinality(v_missing)>0 or cardinality(v_installed)<>cardinality(v_requested) then
    raise exception 'rule approval refused: exact enforcement is not installed; missing %',v_missing;
  end if;
  v_status := case when p_policy_kind='human_only'
                   then 'authority_enforced' else 'hard_enforced' end;

  v_contract := jsonb_build_object(
    'rule_id',p_rule_id,
    'rule_version',v_rule.version,
    'statement_hash',encode(digest(v_rule.statement,'sha256'),'hex'),
    'enforcement_class',p_policy_kind,
    'enforcement_status',v_status,
    'binding_moment','when the approved rule applies',
    'applicability',case when v_rule.scope='{}'::jsonb
      then '{"workflows":["*"],"surfaces":["*"],"tiers":["*"]}'::jsonb
      else v_rule.scope end,
    'projection',jsonb_build_object('targets',jsonb_build_array(
      'standing-context','applicable-rules','rule-enforcement-status')),
    'reachability',jsonb_build_object('paths',jsonb_build_array(
      'record-layer','session-boot','registered-controls')),
    'input_contract','{"type":"object","required":["workflow","surface","tier"]}'::jsonb,
    'requested_controls',v_requested);
  v_contract_hash := encode(digest(v_contract::text,'sha256'),'hex');

  select id into v_intake_id from ops.guidance_intake
   where lane='rule' and source_ref='rule:'||p_rule_id::text
   order by captured_at limit 1;
  if v_intake_id is null then
    insert into ops.guidance_intake
      (lane,source_kind,source_ref,statement,state,normalized_contract,captured_by)
    values ('rule','human','rule:'||p_rule_id::text,v_rule.statement,'admitted',
            v_contract,v_actor_id) returning id into v_intake_id;
  else
    update ops.guidance_intake
       set state='admitted',normalized_contract=v_contract,updated_at=now(),version=version+1
     where id=v_intake_id;
  end if;

  insert into ops.rule_admission
    (rule_id,guidance_intake_id,enforcement_class,enforcement_status,binding_moment,
     applicability,projection,reachability,input_contract,fixture_refs,state,
     admitted_by,admitted_at,reason,coverage_detail)
  values
    (p_rule_id,v_intake_id,p_policy_kind,v_status,'when the approved rule applies',
     v_contract->'applicability',v_contract->'projection',v_contract->'reachability',
     v_contract->'input_contract',v_evidence,'admitted',v_actor_id,now(),btrim(p_reason),
     jsonb_build_object('requested',v_requested,'installed',v_installed,'missing','{}'::text[]))
  on conflict (rule_id) do update set
    guidance_intake_id=excluded.guidance_intake_id,
    enforcement_class=excluded.enforcement_class,
    enforcement_status=excluded.enforcement_status,
    binding_moment=excluded.binding_moment,
    applicability=excluded.applicability,
    projection=excluded.projection,
    reachability=excluded.reachability,
    input_contract=excluded.input_contract,
    fixture_refs=excluded.fixture_refs,
    state='admitted',admitted_by=excluded.admitted_by,admitted_at=excluded.admitted_at,
    reason=excluded.reason,coverage_detail=excluded.coverage_detail,
    version=ops.rule_admission.version+1,updated_at=now();

  update ops.rule_enforcement_point set installed=false,verified_at=null
   where rule_id=p_rule_id and not (control_key=any(v_installed));
  insert into ops.rule_enforcement_point
    (rule_id,control_key,implementation_ref,test_ref,enforcement_class,installed,verified_at)
  select p_rule_id,control_key,implementation_ref,test_ref,enforcement_class,true,verified_at
    from ops.enforcement_control_catalog
   where control_key=any(v_installed)
  on conflict (rule_id,control_key) do update set
    implementation_ref=excluded.implementation_ref,test_ref=excluded.test_ref,
    enforcement_class=excluded.enforcement_class,installed=true,
    verified_at=excluded.verified_at;

  insert into ops.rule_approval_receipt
    (idempotency_key,rule_id,rule_version,statement_hash,actor_id,policy_kind,
     enforcement_status,requested_control_keys,installed_control_keys,reason,
     normalized_contract,contract_hash,evidence_refs)
  -- The activation UPDATE below is the one permitted active transition and
  -- trg_touch_row increments the rule version in that same statement. Store
  -- the post-activation version so replay can prove no later mutation occurred.
  values (p_idempotency_key,p_rule_id,v_rule.version+1,
          encode(digest(v_rule.statement,'sha256'),'hex'),v_actor_id,p_policy_kind,v_status,
          v_requested,v_installed,btrim(p_reason),v_contract,v_contract_hash,v_evidence)
  returning * into v_receipt;

  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,contract_hash,evidence_refs)
  values ('approval:'||p_idempotency_key,'activation','rule',p_rule_id,v_actor_id,
          'approved, enforced and activated atomically',v_contract_hash,v_evidence);

  update rule
     set status='active',activated_by=v_actor_id,activated_at=now(),
         enforcement=case when v_status='hard_enforced' then 'gate' else 'constraint' end
   where id=p_rule_id and status='proposed';
  if not found then raise exception 'rule % did not activate',p_rule_id; end if;

  return jsonb_build_object(
    'ok',true,'replayed',false,'rule_id',p_rule_id,'policy_status','active',
    'enforcement_status',v_status,'installed_controls',v_installed,
    'pending_controls','{}'::text[],'approval_receipt_id',v_receipt.id);
end $$;


--
-- Name: approve_staging_release(text, text, uuid, integer, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_staging_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid, p_expires_hours integer, p_verifier_actor text, p_verifier_evidence_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  actor_slug text; rel ops.release%rowtype; existing ops.staging_release_approval_receipt%rowtype;
  approved_time timestamptz; expiry_time timestamptz; projection jsonb; approval_hash text;
  approval_ref text; approval_uuid uuid; verifier_actor_value text; verifier_evidence_value text;
begin
  actor_slug:=ops.authority_actor_slug();
  if session_user<>'carr_authority_joe' or actor_slug<>'joe' then
    raise exception 'staging approval requires Joe authority';
  end if;
  if p_idempotency_key is null or coalesce(p_release_key,'')='' or coalesce(p_plan_hash,'')=''
     or coalesce(p_expires_hours,0) not between 1 and 24
     or coalesce(btrim(p_verifier_actor),'')='' or coalesce(btrim(p_verifier_evidence_ref),'')='' then
    raise exception 'invalid typed staging approval input';
  end if;
  verifier_actor_value:=lower(btrim(p_verifier_actor));
  verifier_evidence_value:=btrim(p_verifier_evidence_ref);
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,219));
  select * into existing from ops.staging_release_approval_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.plan_hash<>p_plan_hash
       or existing.approval_expires_at-existing.approved_at<>make_interval(hours=>p_expires_hours)
       or existing.verifier_actor<>verifier_actor_value or existing.verifier_evidence_ref<>verifier_evidence_value
       or not exists (select 1 from ops.release where id=existing.release_id and release_key=p_release_key
                        and environment='staging' and plan_hash=existing.plan_hash
                        and state in ('approved','deploying','verifying','complete')
                        and approved_by_actor='joe' and approved_at=existing.approved_at
                        and approval_expires_at=existing.approval_expires_at
                        and staging_approval_receipt_id=existing.id
                        and verifier_actor=existing.verifier_actor
                        and verifier_evidence_ref=existing.verifier_evidence_ref) then
      raise exception 'staging approval idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('approval_receipt_id',existing.id,'approval_ref',existing.evidence_ref,
      'approval_expires_at',existing.approval_expires_at,'replayed',true);
  end if;
  select * into rel from ops.release where release_key=p_release_key for update;
  if not found or rel.environment<>'staging' or rel.state<>'candidate'
     or rel.plan_hash is distinct from p_plan_hash or rel.rollback_ready is not true
     or coalesce(btrim(rel.rollback_plan_ref),'')='' then
    raise exception 'release is not the exact rollback-ready staging candidate plan requested';
  end if;
  if rel.maker_actor is not null and verifier_actor_value=lower(btrim(rel.maker_actor)) then
    raise exception 'maker cannot independently verify their own staging release';
  end if;
  approved_time:=clock_timestamp(); expiry_time:=approved_time+make_interval(hours=>p_expires_hours);
  projection:=jsonb_build_object('release_id',rel.id,'environment','staging','plan_hash',rel.plan_hash,'approved_by_actor',actor_slug,
    'approved_at',approved_time,'approval_expires_at',expiry_time,'verifier_actor',verifier_actor_value,
    'verifier_evidence_ref',verifier_evidence_value);
  approval_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  approval_ref:='ops.staging-release-approval:'||approval_hash;
  insert into ops.staging_release_approval_receipt(idempotency_key,release_id,plan_hash,approved_by_actor,
    approved_at,approval_expires_at,verifier_actor,verifier_evidence_ref,approval_sha256,evidence_ref)
  values(p_idempotency_key,rel.id,rel.plan_hash,actor_slug,approved_time,expiry_time,verifier_actor_value,
    verifier_evidence_value,approval_hash,approval_ref) returning id into approval_uuid;
  update ops.release set state='approved',approved_by_actor=actor_slug,approved_at=approved_time,
    approval_expires_at=expiry_time,verifier_actor=verifier_actor_value,
    verifier_evidence_ref=verifier_evidence_value,staging_approval_receipt_id=approval_uuid where id=rel.id;
  return jsonb_build_object('approval_receipt_id',approval_uuid,'approval_ref',approval_ref,
    'approval_expires_at',expiry_time,'replayed',false);
end $$;


--
-- Name: assert_guidance_import_inventory(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assert_guidance_import_inventory(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from ops.guidance_import_batch where id=p_batch_id) then
    raise exception 'unknown guidance import batch %',p_batch_id;
  end if;
  if exists (
    (select id from rule
      where status='active' and coalesce(scope->>'kind','') <> 'intro_politics')
    except
    (select distinct source_rule_id from ops.guidance_import_entry where batch_id=p_batch_id)
  ) or exists (
    (select distinct source_rule_id from ops.guidance_import_entry where batch_id=p_batch_id)
    except
    (select id from rule
      where status='active' and coalesce(scope->>'kind','') <> 'intro_politics')
  ) then
    raise exception 'guidance import batch source inventory no longer exactly matches standing-context active rules';
  end if;
end $$;


--
-- Name: assert_guidance_import_materialization(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assert_guidance_import_materialization(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from ops.guidance_import_apply_event where batch_id=p_batch_id)
     or not exists (select 1 from ops.guidance_import_decision_event
                     where batch_id=p_batch_id and state='active') then
    raise exception 'guidance import batch is not applied and human-approved';
  end if;
  if (select count(*) from ops.guidance_import_entry where batch_id=p_batch_id)
     <> (select count(*) from ops.guidance_import_entry e
          join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
          join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
          where e.batch_id=p_batch_id) then
    raise exception 'guidance import batch lacks an exact materialized revision for one or more entries';
  end if;
  if exists (
    (select g.guidance_revision_id from ops.v_guidance_materialized_current g)
    except
    (select r.id from ops.guidance_import_entry e
      join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
      join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
     where e.batch_id=p_batch_id)
  ) or exists (
    (select r.id from ops.guidance_import_entry e
      join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
      join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
     where e.batch_id=p_batch_id)
    except
    (select g.guidance_revision_id from ops.v_guidance_materialized_current g)
  ) then
    raise exception 'active guidance revisions do not exactly match the approved import batch';
  end if;
  if exists (
    (select m.guidance_revision_id,m.concept_id,m.doctrine_section_id
       from ops.v_guidance_materialized_situation_mapping_current m
       join ops.v_guidance_materialized_current g on g.guidance_revision_id=m.guidance_revision_id
      where m.state='active' and g.guidance_type='doctrine')
    except
    (select r.id,x.concept_id,x.doctrine_section_id
       from ops.guidance_import_mapping_execution x
       join ops.guidance_import_entry e on e.id=x.entry_id
       join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
       join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
      where x.batch_id=p_batch_id)
  ) or exists (
    (select r.id,x.concept_id,x.doctrine_section_id
       from ops.guidance_import_mapping_execution x
       join ops.guidance_import_entry e on e.id=x.entry_id
       join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
       join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
      where x.batch_id=p_batch_id)
    except
    (select m.guidance_revision_id,m.concept_id,m.doctrine_section_id
       from ops.v_guidance_materialized_situation_mapping_current m
       join ops.v_guidance_materialized_current g on g.guidance_revision_id=m.guidance_revision_id
      where m.state='active' and g.guidance_type='doctrine')
  ) then
    raise exception 'active doctrine mappings do not exactly match the approved import batch';
  end if;
end $$;


--
-- Name: assert_guidance_registry_coverage(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assert_guidance_registry_coverage() RETURNS TABLE(source_rule_id uuid, issue text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  with active_rules as (
    select id from rule
     where status='active' and coalesce(scope->>'kind','') <> 'intro_politics'
  ), primary_counts as (
    select ar.id,
           count(g.*) filter (where g.is_primary) as primary_count
      from active_rules ar
      left join ops.v_guidance_materialized_current g on g.source_rule_id=ar.id
     group by ar.id
  )
  select id,
         case when primary_count=0 then 'missing active primary guidance'
              else 'multiple active primary guidance records' end
    from primary_counts where primary_count <> 1
  union all
  select g.source_rule_id,'constraint lacks admitted installed enforcement projection'
    from ops.v_guidance_materialized_current g
   where g.is_primary and g.guidance_type='constraint'
     and not exists (
       select 1
         from ops.rule_admission a
         join ops.rule_enforcement_point ep
           on ep.rule_id=a.rule_id and ep.installed
        where a.rule_id=g.source_rule_id and a.state='admitted')
  union all
  select g.source_rule_id,'doctrine lacks active WR-AI-006 situation bridge'
    from ops.v_guidance_materialized_current g
   where g.is_primary and g.guidance_type='doctrine'
     and not exists (
       select 1
         from ops.v_guidance_materialized_situation_mapping_current m
         join retrieval_concept c on c.id=m.concept_id and c.status='approved'
         join doctrine_section s on s.id=m.doctrine_section_id and s.status='active'
         join doctrine_concept_mapping dcm
           on dcm.concept_id=m.concept_id
          and dcm.section_id=m.doctrine_section_id
          and dcm.status='approved'
        where m.guidance_revision_id=g.guidance_revision_id and m.state='active')
$$;


--
-- Name: assign_execution_profile(text, text, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assign_execution_profile(p_work_request text, p_profile_key text, p_environment text, p_policy_ref text, p_policy_digest text, p_idempotency_key uuid) RETURNS TABLE(assignment_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare tenant text := current_setting('carr.organization_tenant_id', true); work ops.work_request%rowtype;
  profile agent_profile%rowtype; sponsor actor%rowtype; existing ops.work_request_execution_assignment%rowtype;
begin
  if session_user !~ '^carr_authority_' then raise exception 'execution profile assignment requires the authoritative policy gateway'; end if;
  select * into work from ops.work_request where ref=p_work_request and organization_tenant_id=tenant for share;
  if not found then raise exception 'execution profile assignment work request is not visible'; end if;
  select * into profile from agent_profile where profile_key=p_profile_key and status='active' and current_model is not null and current_desk is not null for share;
  if not found or p_environment not in ('local','rehearsal','staging','production') or p_policy_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or p_policy_digest !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'execution profile assignment requires active profile and exact policy binding';
  end if;
  select * into sponsor from actor where slug=regexp_replace(session_user,'^carr_authority_','') and kind='human' and active;
  if not found then raise exception 'execution profile assignment cannot derive sponsoring human'; end if;
  select * into existing from ops.work_request_execution_assignment where work_request_id=work.id;
  if found then
    if existing.profile_id<>profile.id or existing.sponsoring_human_id<>sponsor.id or existing.environment<>p_environment or existing.policy_ref<>p_policy_ref or existing.policy_digest<>p_policy_digest then raise exception 'execution profile assignment conflicts with immutable existing lane'; end if;
    return query select existing.id,true; return;
  end if;
  insert into ops.work_request_execution_assignment(work_request_id,profile_id,sponsoring_human_id,environment,policy_ref,policy_digest,idempotency_key)
  values(work.id,profile.id,sponsor.id,p_environment,p_policy_ref,p_policy_digest,p_idempotency_key) returning id into assignment_id;
  return query select assignment_id,false;
end $_$;


--
-- Name: attempt_receipt_binding_valid(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attempt_receipt_binding_valid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare binding ops.context_activation_binding%rowtype; envelope_row ops.execution_envelope_v1%rowtype; expected_unresolved jsonb; expected_closure_state text;
  disposition jsonb; reliability jsonb; expected_reliability_state text; expected_reliability_reasons jsonb; required_evaluator_kinds text[]; held_out_count integer;
begin
  select * into binding from ops.context_activation_binding where id=new.activation_binding_id;
  select * into envelope_row from ops.execution_envelope_v1 where id=new.execution_envelope_id;
  if not found or binding.organization_tenant_id is distinct from new.organization_tenant_id
     or binding.work_request_id is distinct from new.work_request_id
     or binding.plan_hash is distinct from new.plan_hash
     or binding.expires_at < now()
     or exists (select 1 from ops.work_request current_work where current_work.id=binding.work_request_id and (current_work.version<>binding.work_request_version or current_work.organization_tenant_id<>binding.organization_tenant_id))
     or envelope_row.organization_tenant_id is distinct from new.organization_tenant_id
     or envelope_row.work_request_id is distinct from new.work_request_id
     or envelope_row.plan_hash is distinct from new.plan_hash
     or envelope_row.activation_binding_id is distinct from binding.id
     or envelope_row.envelope_digest is distinct from new.envelope_digest
     or envelope_row.expires_at < now()
     or jsonb_typeof(new.receipt) is distinct from 'object'::text
     or new.receipt->>'schema_version' <> 'attempt-receipt.v1'
     or new.receipt->>'envelope_digest' is distinct from new.envelope_digest
     or new.receipt->>'attempt_id' is distinct from new.attempt_id
     or not (new.receipt ?& array['schema_version','attempt_id','envelope_digest','attempt_ordinal','adapter','lifecycle','result','attestation','negative_knowledge','telemetry','tool_event_summaries','observation','interventions','handoff_proposal','visual_artifacts','evaluation_binding'])
     or exists (select 1 from jsonb_object_keys(new.receipt) key where key <> all(array['schema_version','attempt_id','envelope_digest','attempt_ordinal','adapter','lifecycle','result','attestation','negative_knowledge','telemetry','tool_event_summaries','observation','interventions','handoff_proposal','visual_artifacts','evaluation_binding','knowledge_activation','reliability']))
     or ops.attempt_receipt_contains_raw_content(new.receipt)
     or not (new.receipt ?& array['knowledge_activation','reliability'])
     or coalesce(new.receipt->'knowledge_activation'->'closure'->>'derived_by','') <> 'server' then
    raise exception 'attempt receipt is cross-bound, malformed, or contains raw content';
  end if;
  -- A `derived_by: server` label is not proof.  Recompute the required-item
  -- closure from the immutable activation rows and reject any forged or stale
  -- nested receipt before it is admitted.
  if jsonb_typeof(new.receipt->'knowledge_activation') <> 'object'
     or not (new.receipt->'knowledge_activation' ?& array['bundle_digest','item_dispositions','closure','mode','canonical_binding'])
     or exists (select 1 from jsonb_object_keys(new.receipt->'knowledge_activation') key where key <> all(array['bundle_digest','item_dispositions','closure','mode','canonical_binding']))
     or jsonb_typeof(new.receipt->'knowledge_activation'->'canonical_binding') <> 'object'
     or not (new.receipt->'knowledge_activation'->'canonical_binding' ?& array['work_request_id','work_request_version','accepted_plan_digest','envelope_digest','activation_binding_ref'])
     or exists (select 1 from jsonb_object_keys(new.receipt->'knowledge_activation'->'canonical_binding') key where key <> all(array['work_request_id','work_request_version','accepted_plan_digest','envelope_digest','activation_binding_ref']))
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'work_request_id' <> (select ref from ops.work_request where id=binding.work_request_id)
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'work_request_version' <> binding.work_request_version::text
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'accepted_plan_digest' <> binding.plan_hash
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'envelope_digest' <> new.envelope_digest
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'activation_binding_ref' <> binding.binding_id
     or new.receipt->'knowledge_activation'->>'bundle_digest' <> binding.bundle_digest
     or jsonb_typeof(new.receipt->'knowledge_activation'->'item_dispositions') <> 'array'
     or (select count(*) from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions'))
          <> (select count(*) from ops.context_activation_item where binding_id=binding.id)
     or exists (
       select 1 from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions') d
        where jsonb_typeof(d) <> 'object'
           or not (d ?& array['item_ref','disposition','evidence_refs','reason_ref'])
           or exists (select 1 from jsonb_object_keys(d) key where key <> all(array['item_ref','disposition','evidence_refs','reason_ref','stage_ref','tool_ref']))
           or d->>'disposition' not in ('applied','not_applicable','conflicted','stale','missing')
           or jsonb_typeof(d->'evidence_refs') <> 'array'
           or coalesce(d->>'reason_ref','') !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
           or (d->>'disposition'='applied' and (jsonb_array_length(d->'evidence_refs')=0 or not (d ?| array['stage_ref','tool_ref'])))
     )
     or exists (
       select 1 from ops.context_activation_item i
       left join lateral (
         select d from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions') d
          where d->>'item_ref'=i.canonical_ref limit 1
       ) supplied on true
       where i.binding_id=binding.id and supplied.d is null
          or (i.binding_id=binding.id and i.required and coalesce(supplied.d->>'disposition','missing') <> 'applied'
              and (jsonb_typeof(supplied.d->'evidence_refs') <> 'array' or jsonb_array_length(supplied.d->'evidence_refs')=0))
     ) then
    raise exception 'attempt receipt knowledge activation is not exactly bound';
  end if;
  select coalesce(jsonb_agg(i.canonical_ref order by i.canonical_ref),'[]'::jsonb)
    into expected_unresolved
    from ops.context_activation_item i
    left join lateral (
      select d from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions') d
       where d->>'item_ref'=i.canonical_ref limit 1
    ) disposition on true
   where i.binding_id=binding.id and i.required
     and coalesce(disposition.d->>'disposition','missing') <> 'applied';
  expected_closure_state := case when binding.mode='shadow' then 'not_activated'
    when expected_unresolved='[]'::jsonb then 'closed' else 'blocked' end;
  if new.receipt->'knowledge_activation'->'closure'->'unresolved_required_item_refs' is distinct from expected_unresolved
     or new.receipt->'knowledge_activation'->'closure'->>'state' is distinct from expected_closure_state then
    raise exception 'attempt receipt knowledge closure was not server-derived';
  end if;
  reliability := new.receipt->'reliability';
  if jsonb_typeof(reliability) <> 'object'
     or not (reliability ?& array['route_digest','topology_digest','evaluation_plan_digest','grounding_sufficiency','deterministic_checks','model_judgement','human_acceptance','trajectory','evaluator_results','corrections','defects','incidents','downstream_outcome','outcome_horizon','process_metrics','eval_candidates','shadow_comparisons','learning_disposition','telemetry','closure'])
     or exists (select 1 from jsonb_object_keys(reliability) key where key <> all(array['route_digest','topology_digest','evaluation_plan_digest','grounding_sufficiency','deterministic_checks','model_judgement','human_acceptance','trajectory','evaluator_results','corrections','defects','incidents','downstream_outcome','outcome_horizon','process_metrics','eval_candidates','shadow_comparisons','learning_disposition','telemetry','closure']))
     or jsonb_typeof(reliability->'deterministic_checks') <> 'array'
     or exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where jsonb_typeof(check_row) <> 'object' or not (check_row ?& array['check_id','state','critical','evidence_refs']) or check_row->>'check_id' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or check_row->>'state' not in ('passed','failed','unknown','not_run') or jsonb_typeof(check_row->'critical')<>'boolean' or jsonb_typeof(check_row->'evidence_refs')<>'array')
     or jsonb_typeof(reliability->'trajectory') <> 'array'
     or exists (select 1 from jsonb_array_elements(reliability->'trajectory') trace_row where jsonb_typeof(trace_row) <> 'object' or not (trace_row ?& array['sequence','stage_ref','parent_event_ref','decision_class','tool_class','result_state','fallback_state','guardrail_state','latency_ms','evidence_refs']) or exists (select 1 from jsonb_object_keys(trace_row) key where key <> all(array['sequence','stage_ref','parent_event_ref','decision_class','tool_class','result_state','fallback_state','guardrail_state','latency_ms','evidence_refs'])))
     or jsonb_typeof(reliability->'evaluator_results') <> 'array' or jsonb_array_length(reliability->'evaluator_results')=0
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where jsonb_typeof(evaluator) <> 'object' or not (evaluator ?& array['kind','evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','status','confidence','critical','independence_state','held_out_case_count','check_refs','dimension_refs','evidence_refs','judge_provenance','calibration_evidence_refs']) or exists (select 1 from jsonb_object_keys(evaluator) key where key <> all(array['kind','evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','status','confidence','critical','independence_state','held_out_case_count','check_refs','dimension_refs','evidence_refs','judge_provenance','calibration_evidence_refs'])) or evaluator->>'kind' not in ('deterministic','judge','human_acceptance') or evaluator->>'status' not in ('passed','failed','blocked','unknown','not_run') or evaluator->>'independence_state' not in ('not_independent','unknown') or jsonb_typeof(evaluator->'held_out_case_count')<>'number' or (evaluator->>'held_out_case_count')::integer<0 or jsonb_typeof(evaluator->'check_refs')<>'array' or jsonb_typeof(evaluator->'dimension_refs')<>'array')
     or jsonb_typeof(reliability->'grounding_sufficiency') <> 'object' or not (reliability->'grounding_sufficiency' ?& array['state','evidence_refs','required_supplied','required_used','required_missing','advisory_supplied','advisory_used','freshness_failures','retrieval_failures'])
     -- Learning facts are canonical, redacted metadata.  The executor cannot
     -- smuggle a candidate, free-text case body, or a fact into the wrong lane.
     or jsonb_typeof(reliability->'eval_candidates') <> 'array' or jsonb_array_length(reliability->'eval_candidates') <> 0
     -- Executor receipts cannot carry a shadow route or its side-effect
     -- claims. Governed shadows are admitted only by Policy Learning.
     or jsonb_typeof(reliability->'shadow_comparisons') <> 'array' or jsonb_array_length(reliability->'shadow_comparisons') <> 0
     or exists (select 1 from jsonb_array_elements(reliability->'corrections') event_row where jsonb_typeof(event_row)<>'object' or not (event_row ?& array['event_ref','kind','evidence_refs','summary']) or exists(select 1 from jsonb_object_keys(event_row) key where key<>all(array['event_ref','kind','evidence_refs','summary'])) or event_row->>'kind'<>'correction' or event_row->>'event_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or event_row->>'summary' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or jsonb_typeof(event_row->'evidence_refs')<>'array' or jsonb_array_length(event_row->'evidence_refs')=0)
     or exists (select 1 from jsonb_array_elements(reliability->'defects') event_row where jsonb_typeof(event_row)<>'object' or not (event_row ?& array['event_ref','kind','evidence_refs','summary']) or exists(select 1 from jsonb_object_keys(event_row) key where key<>all(array['event_ref','kind','evidence_refs','summary'])) or event_row->>'kind'<>'defect' or event_row->>'event_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or event_row->>'summary' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or jsonb_typeof(event_row->'evidence_refs')<>'array' or jsonb_array_length(event_row->'evidence_refs')=0)
     or exists (select 1 from jsonb_array_elements(reliability->'incidents') event_row where jsonb_typeof(event_row)<>'object' or not (event_row ?& array['event_ref','kind','evidence_refs','summary']) or exists(select 1 from jsonb_object_keys(event_row) key where key<>all(array['event_ref','kind','evidence_refs','summary'])) or event_row->>'kind'<>'incident' or event_row->>'event_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or event_row->>'summary' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or jsonb_typeof(event_row->'evidence_refs')<>'array' or jsonb_array_length(event_row->'evidence_refs')=0)
     or jsonb_typeof(reliability->'human_acceptance')<>'object' or not (reliability->'human_acceptance' ?& array['state','actor_ref','evidence_refs','outcome_feedback_ref','outcome_feedback_hash'])
     or reliability->'human_acceptance'->>'state' not in ('accepted','rejected','absent','unknown')
     or (reliability->'human_acceptance'->>'state'='accepted' and (reliability->'human_acceptance'->>'outcome_feedback_ref' is null or reliability->'human_acceptance'->>'outcome_feedback_hash' !~ '^sha256:[0-9a-f]{64}$'))
     or (reliability->'human_acceptance'->>'state'<>'accepted' and ((reliability->'human_acceptance'->'outcome_feedback_ref')<>'null'::jsonb or (reliability->'human_acceptance'->'outcome_feedback_hash')<>'null'::jsonb))
     or jsonb_typeof(reliability->'downstream_outcome')<>'object' or not (reliability->'downstream_outcome' ?& array['state','brokerage_ref','evidence_refs','outcome_feedback_ref','outcome_feedback_hash'])
     or reliability->'downstream_outcome'->>'state' not in ('observed','not_observed','unknown')
     or (reliability->'downstream_outcome'->>'state'='observed' and (reliability->'downstream_outcome'->>'outcome_feedback_ref' is null or reliability->'downstream_outcome'->>'outcome_feedback_hash' !~ '^sha256:[0-9a-f]{64}$'))
     or (reliability->'downstream_outcome'->>'state'<>'observed' and ((reliability->'downstream_outcome'->'outcome_feedback_ref')<>'null'::jsonb or (reliability->'downstream_outcome'->'outcome_feedback_hash')<>'null'::jsonb))
     or jsonb_typeof(reliability->'outcome_horizon') <> 'object' or not (reliability->'outcome_horizon' ?& array['state','ends_at','as_of','evidence_refs'])
     or jsonb_typeof(reliability->'process_metrics') <> 'object' or not (reliability->'process_metrics' ?& array['latency_ms','cost_usd','input_tokens','output_tokens','cached_input_tokens','retry_count','recovery_count','context_reconstruction_ms','human_intervention_count','security_event_refs'])
     or jsonb_typeof(reliability->'closure') <> 'object' or not (reliability->'closure' ?& array['state','reasons','derived_by']) or reliability->'closure'->>'derived_by'<>'server'
     or jsonb_typeof(reliability->'telemetry') <> 'array' or jsonb_array_length(reliability->'telemetry') <> 0 then
    raise exception 'attempt receipt reliability extension is malformed';
  end if;
  if reliability ? 'route_digest' and reliability->>'route_digest' <> envelope_row.runtime_profile->>'digest'
     or reliability ? 'topology_digest' and reliability->>'topology_digest' <> envelope_row.execution_topology->>'digest'
     or reliability ? 'evaluation_plan_digest' and reliability->>'evaluation_plan_digest' <> envelope_row.evaluation_plan->>'digest' then
    raise exception 'attempt receipt route/topology/evaluation digests do not bind the server-issued envelope';
  end if;
  if (select coalesce(jsonb_agg(check_row->>'check_id' order by check_row->>'check_id'),'[]'::jsonb) from jsonb_array_elements(reliability->'deterministic_checks') check_row)
       is distinct from (select coalesce(jsonb_agg(value order by value),'[]'::jsonb) from jsonb_array_elements_text(envelope_row.evaluation_plan->'required_deterministic_check_refs') value)
     or exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where (check_row->>'critical')::boolean is not true)
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'kind'='deterministic' and (jsonb_array_length(evaluator->'check_refs')<>1 or evaluator->'dimension_refs' is distinct from envelope_row.evaluation_plan->'critical_dimensions'))
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'kind'<>'deterministic' and (jsonb_array_length(evaluator->'check_refs')<>0 or evaluator->'dimension_refs' is distinct from envelope_row.evaluation_plan->'critical_dimensions')) then
    raise exception 'evaluation evidence does not exactly bind server-required checks and critical dimensions';
  end if;
  -- Executor-submitted actor/status labels are never acceptance evidence.  A
  -- claimed human acceptance/outcome must resolve to the existing immutable,
  -- human-authority Program 6 feedback receipt for this exact Work Request and
  -- accepted plan; absent/unknown feedback remains visibly unavailable.
  if reliability->'human_acceptance'->>'state'='accepted' and not exists (
    select 1 from ops.sourced_work_request_outcome_feedback f
      join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
      join public.actor a on a.id=fr.accepted_by_actor_id
     where f.work_request_id=new.work_request_id and f.plan_id=binding.plan_id
       and f.feedback_ref=reliability->'human_acceptance'->>'outcome_feedback_ref'
       and f.feedback_hash=reliability->'human_acceptance'->>'outcome_feedback_hash'
       and ('actor:'||a.slug)=reliability->'human_acceptance'->>'actor_ref'
  ) then raise exception 'attempt receipt human acceptance is not bound to accepted Work Request outcome feedback'; end if;
  if reliability->'downstream_outcome'->>'state'='observed' and (
    reliability->'downstream_outcome'->>'outcome_feedback_ref' is distinct from reliability->'human_acceptance'->>'outcome_feedback_ref'
    or reliability->'downstream_outcome'->>'outcome_feedback_hash' is distinct from reliability->'human_acceptance'->>'outcome_feedback_hash'
    or not exists (
      select 1 from ops.sourced_work_request_outcome_feedback f
        join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
       where f.work_request_id=new.work_request_id and f.plan_id=binding.plan_id
         and f.feedback_ref=reliability->'downstream_outcome'->>'outcome_feedback_ref'
         and f.feedback_hash=reliability->'downstream_outcome'->>'outcome_feedback_hash'
    )
  ) then raise exception 'attempt receipt observed outcome is not bound to accepted Work Request feedback'; end if;
  select coalesce(array_agg(value),array[]::text[]) into required_evaluator_kinds from jsonb_array_elements_text(envelope_row.evaluation_plan->'requirements'->'required_evaluator_kinds');
  select coalesce(sum((evaluator->>'held_out_case_count')::integer),0) into held_out_count from jsonb_array_elements(reliability->'evaluator_results') evaluator;
  if exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where (check_row->>'critical')::boolean and check_row->>'state'='failed')
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where (evaluator->>'critical')::boolean and evaluator->>'status' in ('failed','blocked')) then
    expected_reliability_state := 'blocked';
  elsif reliability->'grounding_sufficiency'->>'state'<>'sufficient'
     or coalesce((envelope_row.evaluation_plan->'requirements'->>'outcome_horizon_required')::boolean,false) and reliability->'outcome_horizon'->>'state'<>'mature'
     or reliability->'model_judgement'->>'state'<>'pass'
     or exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where (check_row->>'critical')::boolean and check_row->>'state' in ('unknown','not_run'))
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where (evaluator->>'critical')::boolean and evaluator->>'status' in ('unknown','not_run'))
     or exists (select 1 from unnest(required_evaluator_kinds) kind where not exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'kind'=kind))
     or held_out_count < coalesce((envelope_row.evaluation_plan->'requirements'->>'minimum_held_out_case_count')::integer,0)
     or coalesce((envelope_row.evaluation_plan->'requirements'->>'independent_review_required')::boolean,false) and not exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'independence_state'='independent')
     or coalesce((envelope_row.evaluation_plan->'requirements'->>'human_acceptance_required')::boolean,false) and reliability->'human_acceptance'->>'state'<>'accepted' then
    expected_reliability_state := 'insufficient_evidence';
  -- AttemptReceipt is executor evidence, never the authoritative evaluator
  -- event.  It cannot promote its own judge/held-out/calibration claims.
  else expected_reliability_state := 'insufficient_evidence';
  end if;
  if reliability->'closure'->>'state' is distinct from expected_reliability_state then
    raise exception 'attempt receipt reliability closure was not server-derived for attempt %, expected %, got %',new.attempt_id,expected_reliability_state,reliability->'closure'->>'state';
  end if;
  expected_reliability_reasons := case when expected_reliability_state='blocked' then
    jsonb_build_array('reason:authority_evaluation_evidence_missing','reason:critical_deterministic_or_evaluator_failure')
  else jsonb_build_array('reason:authority_evaluation_evidence_missing') end;
  if reliability->'closure'->'reasons' is distinct from expected_reliability_reasons then
    raise exception 'attempt receipt reliability closure reasons were not server-derived';
  end if;
  return new;
end $_$;


--
-- Name: attempt_receipt_contains_raw_content(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attempt_receipt_contains_raw_content(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare entry record;
begin
  if jsonb_typeof(p_value) = 'object' then
    -- Held-out expected outputs are evaluator material, not executor or
    -- Passport material.  Refuse them at the same recursive persistence
    -- boundary as prompts and tool bodies.
    if p_value ?| array['raw_prompt','raw_transcript','tool_payload','raw_output','prompt','transcript','expected_output','expected_answer','held_out_expected_output','held_out_answer'] then
      return true;
    end if;
    for entry in select value from jsonb_each(p_value) loop
      if ops.attempt_receipt_contains_raw_content(entry.value) then return true; end if;
    end loop;
  elsif jsonb_typeof(p_value) = 'array' then
    for entry in select value from jsonb_array_elements(p_value) loop
      if ops.attempt_receipt_contains_raw_content(entry.value) then return true; end if;
    end loop;
  elsif jsonb_typeof(p_value) = 'string' then
    -- This projection is an identifier/enumeration/timestamp/digest contract,
    -- never a prose transport.  A sentence cannot be made safe merely by
    -- changing its field name.
    if char_length(p_value #>> '{}') > 127 or (p_value #>> '{}') ~ '[[:space:]]' then return true; end if;
  end if;
  return false;
end $$;


--
-- Name: attest_attempt_receipt_evaluation(text, text, text, jsonb, text, boolean, jsonb, jsonb, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attest_attempt_receipt_evaluation(p_attempt_id text, p_evaluator_kind text, p_check_ref text, p_dimension_refs jsonb, p_status text, p_independent boolean, p_evidence_refs jsonb, p_evaluation_metadata jsonb, p_outcome_feedback_ref text, p_outcome_feedback_hash text, p_idempotency_key uuid) RETURNS TABLE(attestation_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare tenant text := current_setting('carr.organization_tenant_id',true); receipt_row ops.attempt_receipt%rowtype;
  envelope_row ops.execution_envelope_v1%rowtype; authority_actor actor%rowtype; existing ops.attempt_receipt_evaluation_attestation%rowtype;
  derived_horizon text; accepted_feedback boolean;
begin
  if session_user !~ '^carr_authority_' then raise exception 'evaluation attestation requires human authority'; end if;
  select * into authority_actor from actor where slug=regexp_replace(session_user,'^carr_authority_','') and kind='human' and active;
  select * into receipt_row from ops.attempt_receipt where organization_tenant_id=tenant and attempt_id=p_attempt_id for share;
  select * into envelope_row from ops.execution_envelope_v1 where id=receipt_row.execution_envelope_id and organization_tenant_id=tenant for share;
  if authority_actor.id is null or receipt_row.id is null or envelope_row.id is null
     or jsonb_typeof(p_dimension_refs)<>'array' or jsonb_array_length(p_dimension_refs)=0
     or jsonb_typeof(p_evidence_refs)<>'array' or jsonb_array_length(p_evidence_refs)=0
     or jsonb_typeof(p_evaluation_metadata)<>'object'
     or not (p_evaluation_metadata ?& array['evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','confidence','held_out_case_count','calibration_refs','lower_bound_ref'])
     or exists (select 1 from jsonb_object_keys(p_evaluation_metadata) k where k <> all(array['evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','confidence','held_out_case_count','calibration_refs','lower_bound_ref']))
     or p_evaluation_metadata->>'evaluator_ref' <> envelope_row.evaluation_plan->>'evaluator_ref'
     or p_evaluation_metadata->>'rubric_ref' <> envelope_row.evaluation_plan->>'rubric_ref'
     or p_evaluation_metadata->>'evaluator_version' <> envelope_row.evaluation_plan->>'evaluator_version'
     or p_evaluation_metadata->>'evaluator_digest' <> envelope_row.evaluation_plan->>'evaluator_digest'
     or p_evaluation_metadata->>'confidence' not in ('high','medium','low','unknown')
     or jsonb_typeof(p_evaluation_metadata->'held_out_case_count') <> 'number' or (p_evaluation_metadata->>'held_out_case_count')::integer < 0
     or jsonb_typeof(p_evaluation_metadata->'calibration_refs') <> 'array'
     or ops.attempt_receipt_contains_raw_content(p_evidence_refs) or ops.attempt_receipt_contains_raw_content(p_evaluation_metadata)
     or p_evaluator_kind not in ('deterministic','judge','human_acceptance','outcome_horizon')
     or p_status not in ('passed','failed','blocked','unknown','not_run','mature','immature')
     or p_dimension_refs is distinct from envelope_row.evaluation_plan->'critical_dimensions' then
    raise exception 'evaluation attestation lacks exact canonical binding';
  end if;
  if (p_evaluator_kind='deterministic' and (p_check_ref='' or not ((envelope_row.evaluation_plan->'required_deterministic_check_refs') ? p_check_ref) or p_status not in ('passed','failed','blocked','unknown','not_run')))
     or (p_evaluator_kind<>'deterministic' and p_check_ref<>'')
     or (p_evaluator_kind='judge' and p_status not in ('passed','failed','blocked','unknown','not_run'))
     or (p_evaluator_kind='human_acceptance' and p_status not in ('passed','failed','blocked','unknown','not_run'))
     or (p_evaluator_kind='outcome_horizon' and p_status not in ('mature','immature'))
     or (p_evaluator_kind='judge' and not p_independent)
     or (p_evaluator_kind<>'judge' and p_independent) then
    raise exception 'evaluation attestation kind/check/status/independence is invalid';
  end if;
  select exists (
    select 1 from ops.sourced_work_request_outcome_feedback f join ops.sourced_work_request_outcome_feedback_acceptance_receipt accepted on accepted.feedback_id=f.id
      where f.work_request_id=receipt_row.work_request_id and f.plan_id=(select plan_id from ops.context_activation_binding where id=receipt_row.activation_binding_id)
        and f.feedback_ref=p_outcome_feedback_ref and f.feedback_hash=p_outcome_feedback_hash
  ) into accepted_feedback;
  if p_evaluator_kind in ('human_acceptance','outcome_horizon') and (not accepted_feedback or p_outcome_feedback_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or p_outcome_feedback_hash !~ '^sha256:[0-9a-f]{64}$') then
    raise exception 'authority attestation requires exact accepted Program 6 outcome feedback';
  elsif p_evaluator_kind not in ('human_acceptance','outcome_horizon') and (p_outcome_feedback_ref is not null or p_outcome_feedback_hash is not null) then
    raise exception 'only outcome-bound authority facts may name Program 6 feedback';
  end if;
  derived_horizon := case when clock_timestamp() >= (envelope_row.evaluation_plan->>'outcome_horizon_not_before')::timestamptz then 'mature' else 'immature' end;
  if p_evaluator_kind='outcome_horizon' and p_status <> derived_horizon then
    raise exception 'outcome horizon is derived from the issued policy and database clock';
  end if;
  select * into existing from ops.attempt_receipt_evaluation_attestation where idempotency_key=p_idempotency_key for share;
  if found then
    if existing.attempt_receipt_id<>receipt_row.id or existing.evaluator_kind<>p_evaluator_kind or existing.check_ref<>p_check_ref or existing.dimension_refs is distinct from p_dimension_refs or existing.status<>p_status or existing.independent<>p_independent or existing.evidence_refs is distinct from p_evidence_refs or existing.evaluator_ref<>p_evaluation_metadata->>'evaluator_ref' or existing.rubric_ref<>p_evaluation_metadata->>'rubric_ref' or existing.evaluator_version<>p_evaluation_metadata->>'evaluator_version' or existing.evaluator_digest<>p_evaluation_metadata->>'evaluator_digest' or existing.confidence<>p_evaluation_metadata->>'confidence' or existing.held_out_case_count<>(p_evaluation_metadata->>'held_out_case_count')::integer or existing.calibration_refs is distinct from p_evaluation_metadata->'calibration_refs' or existing.lower_bound_ref is distinct from nullif(p_evaluation_metadata->>'lower_bound_ref','') or existing.outcome_feedback_ref is distinct from p_outcome_feedback_ref or existing.outcome_feedback_hash is distinct from p_outcome_feedback_hash then raise exception 'evaluation attestation idempotency conflict'; end if;
    return query select existing.id,true; return;
  end if;
  insert into ops.attempt_receipt_evaluation_attestation(organization_tenant_id,attempt_receipt_id,evaluator_kind,check_ref,dimension_refs,evaluator_policy_digest,evaluator_ref,rubric_ref,evaluator_version,evaluator_digest,confidence,held_out_case_count,calibration_refs,lower_bound_ref,outcome_feedback_ref,outcome_feedback_hash,status,independent,evidence_refs,attested_by_actor_id,idempotency_key)
  values(tenant,receipt_row.id,p_evaluator_kind,p_check_ref,p_dimension_refs,envelope_row.evaluation_plan->>'evaluator_policy_digest',p_evaluation_metadata->>'evaluator_ref',p_evaluation_metadata->>'rubric_ref',p_evaluation_metadata->>'evaluator_version',p_evaluation_metadata->>'evaluator_digest',p_evaluation_metadata->>'confidence',(p_evaluation_metadata->>'held_out_case_count')::integer,p_evaluation_metadata->'calibration_refs',nullif(p_evaluation_metadata->>'lower_bound_ref',''),p_outcome_feedback_ref,p_outcome_feedback_hash,p_status,p_independent,p_evidence_refs,authority_actor.id,p_idempotency_key)
  returning id into attestation_id;
  return query select attestation_id,false;
end $_$;


--
-- Name: authority_actor_slug(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.authority_actor_slug() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  case session_user
    when 'carr_authority_joe' then return 'joe';
    when 'carr_authority_dell' then return 'dell';
    else raise exception 'authority session user % is not an admitted human authority principal', session_user;
  end case;
end $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: job; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.job (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    definition_key text CONSTRAINT job_definition_key_not_null1 NOT NULL,
    definition_version integer CONSTRAINT job_definition_version_not_null1 NOT NULL,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    scheduled_for timestamp with time zone NOT NULL,
    mode text DEFAULT 'live'::text NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    max_attempts integer NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_owner text,
    lease_token uuid,
    leased_until timestamp with time zone,
    timeout_seconds integer NOT NULL,
    last_failure_class text,
    last_failure_detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_attempt_check CHECK ((attempt >= 0)),
    CONSTRAINT job_max_attempts_check CHECK ((max_attempts > 0)),
    CONSTRAINT job_mode_check CHECK ((mode = ANY (ARRAY['shadow'::text, 'canary'::text, 'live'::text, 'replay'::text]))),
    CONSTRAINT job_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'retry_wait'::text, 'waiting_approval'::text, 'succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'dead_lettered'::text]))),
    CONSTRAINT job_timeout_seconds_check CHECK ((timeout_seconds > 0)),
    CONSTRAINT running_job_has_a_lease CHECK (((state <> 'running'::text) OR ((lease_owner IS NOT NULL) AND (lease_token IS NOT NULL) AND (leased_until IS NOT NULL)))),
    CONSTRAINT terminal_job_has_ended CHECK (((state <> ALL (ARRAY['succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'dead_lettered'::text])) OR (ended_at IS NOT NULL)))
);


--
-- Name: calendar_canary_live_job(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_canary_live_job(p_job_id uuid, p_lease uuid) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; k text;
begin
 if session_user<>'carr_jobs' then raise exception using errcode='42501',message='calendar canary requires carr_jobs identity'; end if;
 select * into j from ops.job where id=p_job_id for update;
 select execution_kind into k from ops.job_definition where key=j.definition_key and version=j.definition_version;
 if not found or j.state<>'running' or j.lease_token<>p_lease or j.leased_until<now() then raise exception using errcode='55000',message='calendar canary requires current live job lease'; end if;
 if j.definition_key<>'calendar-fetch-daily' or j.definition_version<>5 or j.mode<>'canary' or k<>'deterministic' then raise exception using errcode='22023',message='job is not calendar-fetch-daily v5 deterministic canary'; end if;
 return j;
end $$;


--
-- Name: calendar_prebrief_attestor_sponsor(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_attestor_sponsor() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not pg_has_role(session_user,'carr_calendar_prebrief_attestors','member') then
    raise exception using errcode='42501',message='calendar prebrief attestor identity lacks its capability bundle';
  end if;
  case session_user
    when 'carr_calendar_prebrief_attestor_joe' then return 'joe';
    when 'carr_calendar_prebrief_attestor_dell' then return 'dell';
    else raise exception using errcode='42501',message='calendar prebrief requires its exact sponsor-bound verifier identity';
  end case;
end $$;


--
-- Name: calendar_prebrief_canonical_event_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_canonical_event_digest(p_events jsonb) RETURNS TABLE(event_count integer, canonical_event_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v_events jsonb;
begin
  if p_events is null or pg_column_size(p_events)>262144 or jsonb_typeof(p_events)<>'array' then
    raise exception using errcode='22023',message='calendar prebrief verified envelope requires a bounded event array';
  end if;
  if jsonb_array_length(p_events)>128 or exists(
      select 1 from jsonb_array_elements(p_events) e(value)
       where pg_column_size(e.value)>4096 or jsonb_typeof(e.value)<>'object'
          or jsonb_typeof(e.value->'participant_refs')<>'array') then
    raise exception using errcode='22023',message='calendar prebrief verified envelope has invalid bounded events';
  end if;
  select coalesce(jsonb_agg(event order by event->>'occurrence_key'),'[]'::jsonb) into v_events
    from (select jsonb_set(e.value,'{participant_refs}',coalesce((select jsonb_agg(ref order by ref)
             from jsonb_array_elements_text(e.value->'participant_refs') refs(ref)),'[]'::jsonb)) event
            from jsonb_array_elements(p_events) e(value)) normalized;
  event_count:=jsonb_array_length(p_events);
  canonical_event_digest:=encode(digest(convert_to(v_events::text,'UTF8'),'sha256'),'hex');
  return next;
end $$;


--
-- Name: calendar_prebrief_joe_live_due_at(timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_joe_live_due_at(p_now timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare local_now timestamp; local_due timestamp; due timestamptz;
begin
  if p_now is null then
    raise exception 'Joe calendar scheduler requires an observed instant';
  end if;
  local_now := p_now at time zone 'America/Chicago';
  if extract(isodow from local_now) not between 1 and 5
     or local_now::time < time '06:30'
     or local_now::time >= time '06:45' then
    return null;
  end if;
  local_due := local_now::date + time '06:30';
  due := local_due at time zone 'America/Chicago';
  return due;
end $$;


--
-- Name: calendar_prebrief_resolver_sponsor(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_resolver_sponsor() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not pg_has_role(session_user,'carr_calendar_prebrief_email_resolver','member') then
    raise exception using errcode='42501',message='calendar prebrief resolver identity lacks its capability bundle';
  end if;
  case session_user
    when 'carr_calendar_prebrief_resolver_joe' then return 'joe';
    when 'carr_calendar_prebrief_resolver_dell' then return 'dell';
    else raise exception using errcode='42501',message='calendar prebrief requires its exact sponsor-bound resolver identity';
  end case;
end $$;


--
-- Name: capability_agent_session_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_agent_session_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.state <> 'claimed' or new.candidate_evidence is not null
       or new.candidate_kind is not null or new.candidate_fingerprint is not null then
      raise exception 'capability session must be created claimed with no candidate';
    end if;
  else
    if old.state in ('completed','cancelled') then
      if new is distinct from old then
        raise exception 'terminal capability session is immutable';
      end if;
      return old;
    end if;
    if new.work_request_id is distinct from old.work_request_id
       or new.executor_actor_id is distinct from old.executor_actor_id
       or new.created_by_actor_id is distinct from old.created_by_actor_id
       or new.source_commit_sha is distinct from old.source_commit_sha
       or new.worktree_ref is distinct from old.worktree_ref
       or new.scope_ref is distinct from old.scope_ref then
      raise exception 'capability session identity is immutable';
    end if;
    if old.candidate_kind is not null
       and new.candidate_kind is distinct from old.candidate_kind then
      raise exception 'prepared capability candidate kind is immutable';
    end if;
    if old.candidate_evidence is not null
       and new.candidate_evidence is distinct from old.candidate_evidence then
      raise exception 'prepared capability candidate is immutable';
    end if;
    if old.candidate_fingerprint is not null
       and new.candidate_fingerprint is distinct from old.candidate_fingerprint then
      raise exception 'prepared capability fingerprint is immutable';
    end if;
    if old.state = 'claimed' and new.state not in ('in_progress','cancelled') then
      raise exception 'capability session claimed may only move to in_progress or cancelled';
    elsif old.state = 'in_progress' and new.state not in ('verification','cancelled') then
      raise exception 'capability session in_progress may only move to verification or cancelled';
    elsif old.state = 'verification' and new.state not in ('completed','cancelled') then
      raise exception 'capability session verification may only move to completed or cancelled';
    end if;
  end if;

  if new.candidate_evidence is not null then
    new.candidate_fingerprint := md5(new.candidate_evidence::text);
  elsif new.candidate_fingerprint is not null then
    raise exception 'candidate fingerprint requires candidate evidence';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: capability_attestation_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_attestation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare s ops.capability_agent_session%rowtype;
begin
  select * into s from ops.capability_agent_session where id = new.build_session_id for key share;
  if not found then raise exception 'capability build session does not exist'; end if;
  if s.work_request_id <> new.work_request_id then
    raise exception 'attestation work request does not match build session';
  end if;
  if s.state <> 'verification' then
    raise exception 'attestation requires a session in verification';
  end if;
  if new.verifier_actor_id = s.executor_actor_id then
    raise exception 'capability executor may not attest its own candidate';
  end if;
  if new.candidate_fingerprint <> s.candidate_fingerprint then
    raise exception 'attestation candidate does not match the prepared candidate';
  end if;
  return new;
end;
$$;


--
-- Name: capability_program_close_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_program_close_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare s ops.capability_agent_session%rowtype; pass_id uuid;
begin
  if new.program_key is distinct from 'carr-ai-engineering-suite-v1'
     or new.state <> 'confirmed_closed' or old.state = 'confirmed_closed' then
    return new;
  end if;
  select * into s from ops.capability_agent_session
   where work_request_id=new.id and state='verification'
   order by prepared_at desc limit 1 for key share;
  if not found or s.candidate_kind <> new.completion_kind
     or (new.completion_evidence -> 'candidate') is distinct from s.candidate_evidence then
    raise exception 'capability programme close requires its frozen prepared candidate';
  end if;
  begin
    pass_id := new.verification_evidence_ref::uuid;
  exception when invalid_text_representation then
    raise exception 'capability programme close requires a stored pass attestation id';
  end;
  if not exists (
    select 1 from ops.capability_verification a
     where a.id=pass_id and a.build_session_id=s.id and a.work_request_id=new.id
       and a.outcome='pass' and a.candidate_fingerprint=s.candidate_fingerprint
       and a.verifier_actor_id <> s.executor_actor_id
  ) then
    raise exception 'capability programme close requires an independent stored pass';
  end if;
  return new;
end;
$$;


--
-- Name: capability_program_closed_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_program_closed_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.program_key = 'carr-ai-engineering-suite-v1'
     and old.state = 'confirmed_closed'
     and new is distinct from old then
    raise exception 'closed capability programme evidence is immutable';
  end if;
  return new;
end;
$$;


--
-- Name: capability_program_identity_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_program_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.program_key = 'carr-ai-engineering-suite-v1'
     and (new.program_key is distinct from old.program_key
          or new.program_ordinal is distinct from old.program_ordinal) then
    raise exception 'capability programme identity is immutable';
  end if;
  return new;
end;
$$;


--
-- Name: capability_verification_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_verification_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'capability verification records are immutable';
end;
$$;


--
-- Name: capture_sourced_work_request(text, text, text, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capture_sourced_work_request(p_origin_ref text, p_title text, p_desired_outcome text, p_acceptance_criteria jsonb, p_doctrine_section_id uuid, p_doctrine_revision_id uuid, p_idempotency_key uuid) RETURNS TABLE(id uuid, ref text, state text, version integer, organization_tenant_id text, doctrine_section_id uuid, doctrine_revision_id uuid, doctrine_source_label text, source_current boolean, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  v_section public.doctrine_section%rowtype;
  v_document public.doctrine_document%rowtype;
  v_existing ops.work_request%rowtype;
  v_sequence bigint;
  v_ref text;
  v_label text;
begin
  if p_idempotency_key is null
     or coalesce(btrim(p_origin_ref), '') !~ '^doctrine:[a-z0-9][a-z0-9-]*#[a-z0-9][a-z0-9-]*$'
     or char_length(p_origin_ref) > 300
     or coalesce(btrim(p_title), '') = '' or char_length(p_title) > 240
     or coalesce(btrim(p_desired_outcome), '') = '' or char_length(p_desired_outcome) > 4000
     or jsonb_typeof(p_acceptance_criteria) <> 'array'
     or jsonb_array_length(p_acceptance_criteria) not between 1 and 12
     or exists (select 1 from jsonb_array_elements(p_acceptance_criteria) x
                 where jsonb_typeof(x) <> 'object' or x ?| array['id','text'] is false
                    or (select array_agg(k order by k) from jsonb_object_keys(x) k) <> array['id','text']
                    or coalesce(x->>'id','') !~ '^[A-Z][A-Z0-9-]{1,63}$'
                    or coalesce(btrim(x->>'text'),'') = '' or char_length(x->>'text') > 500) then
    raise exception 'sourced capture requires bounded exact acceptance criteria plus a doctrine origin, title, outcome, and UUID idempotency key';
  end if;
  if exists (select x->>'id' from jsonb_array_elements(p_acceptance_criteria) x
               group by x->>'id' having count(*) > 1) then
    raise exception 'sourced capture acceptance criterion IDs must be unique';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-sourced-capture:' || p_idempotency_key, 0));
  select w.* into v_existing from ops.work_request w
   where w.capture_idempotency_key=p_idempotency_key;
  if found then
    if v_existing.organization_tenant_id is distinct from 'carr-internal'
       or v_existing.origin_ref is distinct from p_origin_ref
       or v_existing.title is distinct from p_title
       or v_existing.desired_outcome is distinct from p_desired_outcome
       or v_existing.acceptance_criteria is distinct from p_acceptance_criteria
       or v_existing.doctrine_section_id is distinct from p_doctrine_section_id
       or v_existing.doctrine_revision_id is distinct from p_doctrine_revision_id then
      raise exception 'idempotency key already names a different sourced capture';
    end if;
    select coalesce(s.title, s.section_key) into v_label from public.doctrine_section s where s.id=v_existing.doctrine_section_id;
    return query select v_existing.id, v_existing.ref, v_existing.state, v_existing.version,
      v_existing.organization_tenant_id, v_existing.doctrine_section_id,
      v_existing.doctrine_revision_id, v_label,
      exists (select 1 from public.doctrine_section s where s.id=v_existing.doctrine_section_id
                and s.status='active' and s.current_revision_id=v_existing.doctrine_revision_id), true;
    return;
  end if;

  select s.* into v_section from public.doctrine_section s
   where s.id=p_doctrine_section_id
   for update;
  if not found then
    raise exception 'sourced capture requires an exact current active shared doctrine revision';
  end if;
  select d.* into v_document from public.doctrine_document d where d.id=v_section.document_id for share;
  perform 1 from public.doctrine_revision r
   where r.id=p_doctrine_revision_id and r.section_id=p_doctrine_section_id for share;
  if not found or v_section.current_revision_id is distinct from p_doctrine_revision_id
     or v_section.status <> 'active'
     or v_document.visibility <> 'shared' then
    raise exception 'sourced capture requires an exact current active shared doctrine revision';
  end if;
  if p_origin_ref is distinct from ('doctrine:' || v_document.slug || '#' || v_section.section_key) then
    raise exception 'sourced capture origin reference does not name its exact doctrine evidence';
  end if;
  if not exists (select 1 from public.doctrine_revision r where r.id=p_doctrine_revision_id and r.section_id=p_doctrine_section_id) then
    raise exception 'sourced capture doctrine evidence is invented';
  end if;

  select nextval('ops.work_request_ref_seq') into v_sequence;
  v_ref := 'WR-' || lpad(v_sequence::text, 6, '0');
  v_label := coalesce(v_section.title, v_section.section_key);
  insert into ops.work_request
    (ref,state,title,desired_outcome,acceptance_criteria,origin_ref,requester_actor,
     organization_tenant_id,doctrine_section_id,doctrine_revision_id,
     capture_idempotency_key,sourced_capture_sequence)
  values
    (v_ref,'captured',p_title,p_desired_outcome,p_acceptance_criteria,p_origin_ref,'mcp-authenticated',
     'carr-internal',p_doctrine_section_id,p_doctrine_revision_id,p_idempotency_key,v_sequence)
  returning * into v_existing;
  return query select v_existing.id, v_existing.ref, v_existing.state, v_existing.version,
    v_existing.organization_tenant_id, v_existing.doctrine_section_id,
    v_existing.doctrine_revision_id, v_label, true, false;
end;
$_$;


--
-- Name: FUNCTION capture_sourced_work_request(p_origin_ref text, p_title text, p_desired_outcome text, p_acceptance_criteria jsonb, p_doctrine_section_id uuid, p_doctrine_revision_id uuid, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.capture_sourced_work_request(p_origin_ref text, p_title text, p_desired_outcome text, p_acceptance_criteria jsonb, p_doctrine_section_id uuid, p_doctrine_revision_id uuid, p_idempotency_key uuid) IS 'The sole carr_writer INSERT path for Work Requests. Validates and locks exact current shared doctrine evidence; actor attribution remains in the MCP tool_call/event envelope.';


--
-- Name: claim_calendar_prebrief_joe_live_job(text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_calendar_prebrief_joe_live_job(p_worker text, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(job_id uuid, lease uuid, scheduled_for timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v ops.job%rowtype;
begin
 if session_user<>'carr_jobs' or btrim(coalesce(p_worker,''))='' or p_lease_seconds not between 1 and 300 then raise exception 'Joe calendar runtime identity or lease refused'; end if;
 if not exists(
   select 1
     from ops.calendar_prebrief_allowed_calendar a
     join lateral (
       select r.allowlist_revision_id
         from ops.calendar_prebrief_runtime_activation_receipt r
        where r.sponsor='joe'
        order by r.activated_at desc,r.id desc limit 1
     ) latest on latest.allowlist_revision_id=a.active_revision_id
     join ops.calendar_prebrief_allowlist_receipt l
       on l.id=a.active_revision_id and l.sponsor='joe'
      and l.configuration_digest=a.configuration_digest
    where a.sponsor='joe'
 ) then raise exception 'Joe claim activation gate refused'; end if;
 perform ops.reap_expired_jobs();
 select j.* into v from ops.job j join ops.job_definition d on d.key=j.definition_key and d.version=j.definition_version where d.enabled and j.definition_key='calendar-prebrief-projection-joe-daily' and j.definition_version=1 and d.owner_actor='joe' and j.mode='live' and j.state in ('queued','retry_wait') and j.next_attempt_at<=now() order by j.scheduled_for,j.created_at for update of j,d skip locked limit 1;
 if not found then return; end if;
 update ops.job set state='running',attempt=v.attempt+1,lease_owner=p_worker,lease_token=gen_random_uuid(),leased_until=now()+make_interval(secs=>p_lease_seconds),started_at=coalesce(started_at,now()),updated_at=now() where id=v.id returning * into v;
 insert into ops.job_attempt(job_id,attempt,lease_owner,lease_token,state) values(v.id,v.attempt,v.lease_owner,v.lease_token,'running');
 return query select v.id,v.lease_token,v.scheduled_for;
end $$;


--
-- Name: claim_job(text, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_job(p_worker text, p_limit integer DEFAULT 1, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(job_id uuid, lease_token uuid, definition_key text, definition_version integer, payload jsonb, execution_kind text, execution_contract jsonb, attempt integer, timeout_seconds integer, mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if btrim(coalesce(p_worker,''))='' or p_limit<1 or p_lease_seconds<1 then
    raise exception 'worker, positive limit and positive lease are required';
  end if;
  perform ops.reap_expired_jobs();
  return query
  with candidate as (
    select j.id from ops.job j join ops.job_definition d
      on d.key=j.definition_key and d.version=j.definition_version
     where d.enabled and j.state in ('queued','retry_wait') and j.next_attempt_at<=now()
       and not (j.definition_key='calendar-prebrief-projection-joe-daily' and j.definition_version=1)
     order by j.scheduled_for,j.created_at for update of j,d skip locked limit p_limit
  ), claimed as (
    update ops.job j set state='running',attempt=j.attempt+1,lease_owner=p_worker,
      lease_token=gen_random_uuid(),leased_until=now()+make_interval(secs=>p_lease_seconds),
      started_at=coalesce(j.started_at,now()),updated_at=now()
      from candidate c where j.id=c.id returning j.*
  ), attempts(claimed_job_id) as (
    insert into ops.job_attempt(job_id,attempt,lease_owner,lease_token,state)
    select c.id,c.attempt,c.lease_owner,c.lease_token,'running' from claimed c
    returning ops.job_attempt.job_id
  )
  select c.id,c.lease_token,c.definition_key,c.definition_version,c.payload,
         d.execution_kind,d.execution_contract,c.attempt,c.timeout_seconds,c.mode
    from claimed c join ops.job_definition d
      on d.key=c.definition_key and d.version=c.definition_version
    join attempts a on a.claimed_job_id=c.id;
end $$;


--
-- Name: claim_job_mode(text, text, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_job_mode(p_worker text, p_mode text, p_limit integer DEFAULT 1, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(job_id uuid, lease_token uuid, definition_key text, definition_version integer, payload jsonb, execution_kind text, execution_contract jsonb, attempt integer, timeout_seconds integer, mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if btrim(coalesce(p_worker,''))='' or p_mode not in ('shadow','canary','live','replay')
     or p_limit<1 or p_lease_seconds<1 then
    raise exception 'worker, valid mode, positive limit and positive lease are required';
  end if;
  perform ops.reap_expired_jobs();
  return query
  with candidate as (
    select j.id from ops.job j join ops.job_definition d
      on d.key=j.definition_key and d.version=j.definition_version
     where d.enabled and j.state in ('queued','retry_wait') and j.next_attempt_at<=now()
       and j.mode=p_mode
       and not (j.definition_key='calendar-prebrief-projection-joe-daily' and j.definition_version=1)
     order by j.scheduled_for,j.created_at for update of j,d skip locked limit p_limit
  ), claimed as (
    update ops.job j set state='running',attempt=j.attempt+1,lease_owner=p_worker,
      lease_token=gen_random_uuid(),leased_until=now()+make_interval(secs=>p_lease_seconds),
      started_at=coalesce(j.started_at,now()),updated_at=now()
      from candidate c where j.id=c.id returning j.*
  ), attempts(claimed_job_id) as (
    insert into ops.job_attempt(job_id,attempt,lease_owner,lease_token,state)
    select c.id,c.attempt,c.lease_owner,c.lease_token,'running' from claimed c
    returning ops.job_attempt.job_id
  )
  select c.id,c.lease_token,c.definition_key,c.definition_version,c.payload,
         d.execution_kind,d.execution_contract,c.attempt,c.timeout_seconds,c.mode
    from claimed c join ops.job_definition d
      on d.key=c.definition_key and d.version=c.definition_version
    join attempts a on a.claimed_job_id=c.id;
end $$;


--
-- Name: claim_staging_deployment_attempt(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_staging_deployment_attempt(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare attempt ops.staging_deployment_attempt%rowtype; inserted_count integer;
begin
  if session_user<>'carr_jobs' then
    raise exception 'staging attempt claim requires the carr_jobs session';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_deployment_attempt
    where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging attempt must be prepared before claim'; end if;
  if exists(select 1 from ops.staging_release_readback_receipt
            where deployment_attempt_id=attempt.id) then
    return jsonb_build_object('attempt_id',attempt.id,'deploy_allowed',false,
      'replayed',true,'state','observed');
  end if;
  insert into ops.staging_deployment_claim(deployment_attempt_id,writer_session_user)
    values(attempt.id,session_user) on conflict do nothing;
  get diagnostics inserted_count=row_count;
  return jsonb_build_object('attempt_id',attempt.id,
    'deploy_allowed',inserted_count=1,'replayed',inserted_count=0,
    'state',case when inserted_count=1 then 'claimed' else 'claimed_pending_readback' end);
end $$;


--
-- Name: claim_staging_restore_only_attempt(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_staging_restore_only_attempt(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare attempt ops.staging_restore_only_attempt%rowtype; inserted_count integer; result_row ops.staging_restore_only_result%rowtype;
begin
  if session_user<>'carr_jobs' then raise exception 'restore-only claim requires the carr_jobs session'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_restore_only_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'restore-only attempt must be prepared before claim'; end if;
  select * into result_row from ops.staging_restore_only_result where restore_attempt_id=attempt.id;
  if found then return jsonb_build_object('restore_attempt_id',attempt.id,'mutation_allowed',false,'state',result_row.status,'replayed',true); end if;
  insert into ops.staging_restore_only_claim(restore_attempt_id,writer_session_user) values(attempt.id,session_user) on conflict do nothing;
  get diagnostics inserted_count=row_count;
  return jsonb_build_object('restore_attempt_id',attempt.id,'mutation_allowed',inserted_count=1,'state',case when inserted_count=1 then 'claimed' else 'claimed_pending_result' end,'replayed',inserted_count=0);
end $$;


--
-- Name: clear_recovered_incident(text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.clear_recovered_incident(p_ref text, p_required integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_id           uuid;
  v_state        text;
  v_severity     text;
  v_source_kind  text;
  v_signature    text;
  v_environment  text;
  v_service      text;
  v_env          text;
  v_run_key      text;
  v_required     int;
  v_total        int;
  v_green        int;
  v_latest       uuid;
begin
  -- THE FLOOR IS THE FUNCTION'S, NOT THE CALLER'S. A caller that asks for a
  -- shorter sequence than the system's definition of recovered gets the
  -- system's definition. Asking for a longer one is allowed: that is a caller
  -- being more careful, which never needs preventing.
  v_required := greatest(coalesce(p_required, 3), 3);

  select i.id, i.state, i.severity, i.source_kind, i.signature, i.environment
    into v_id, v_state, v_severity, v_source_kind, v_signature, v_environment
    from ops.incident i where i.ref = p_ref for update;
  if not found then return false; end if;

  -- Everything below is a REFUSAL, and each one is the reason a job role may
  -- hold EXECUTE on a function that writes resolved_at.
  if v_state in ('resolved', 'reviewed') then return false; end if;

  -- SEV-1 (and any SEV-0) NEVER CLOSES HERE. The council was explicit that the
  -- critical incidents are the work, not hygiene, and 0117 made human closure a
  -- grant rather than a convention. This keeps that true through the one door
  -- the grant no longer covers.
  if v_severity !~ '^SEV-[2-4]$' then return false; end if;

  -- Only what the machine opened. A human who writes an incident by hand is
  -- describing something the run ledger cannot see, so the run ledger has no
  -- standing to declare it over.
  if v_source_kind <> 'collector' then return false; end if;
  if v_signature is null then return false; end if;

  v_service := split_part(v_signature, '|', 1);
  v_env     := split_part(v_signature, '|', 2);
  v_run_key := split_part(v_signature, '|', 3);
  if v_service = '' or v_env = '' or v_run_key = '' then return false; end if;
  if v_env is distinct from v_environment then return false; end if;

  -- RE-DERIVED, NOT BELIEVED. The caller passes no evidence and no count; the
  -- sequence is read here, from the same ledger a human would read. skipped and
  -- cancelled runs are excluded rather than counted either way — a step that was
  -- gated out is not proof of health and not proof of breakage.
  with recent as (
    select r.id, r.state, r.observed_at
      from ops.run r join ops.service s on s.id = r.service_id
     where s.key = v_service
       and r.environment = v_env
       and r.run_key = v_run_key
       and r.state in ('succeeded', 'failed', 'timed_out')
     order by r.observed_at desc, r.id desc
     limit v_required)
  select count(*), count(*) filter (where recent.state = 'succeeded'),
         (select r2.id from recent r2 order by r2.observed_at desc, r2.id desc limit 1)
    into v_total, v_green, v_latest
    from recent;

  -- A job with fewer than v_required terminal runs on record has not yet
  -- demonstrated the sequence, however green the ones it has are.
  if v_total < v_required or v_green < v_required then return false; end if;

  update ops.incident i
     set state = 'resolved',
         resolved_at = now(),
         monitoring_until = coalesce(i.monitoring_until, now()),
         recovery_evidence_ref = 'ops.run:' || v_latest::text,
         root_cause = format(
           'recovered: %s has run green %s consecutive times in %s, which is the '
           'success sequence this system calls recovered. Closed automatically by '
           'ops.clear_recovered_incident with those runs as the evidence.',
           v_run_key, v_required, v_env),
         next_action = 'review and record a followup disposition',
         last_seen_at = i.last_seen_at,
         observed_at = now()
   where i.id = v_id;

  insert into ops.incident_fact (incident_id, text, source_ref)
  values (v_id,
          format('%s consecutive healthy runs of %s (%s); latest green run %s',
                 v_required, v_run_key, v_env, v_latest),
          'ops.clear_recovered_incident');

  return true;
end;
$_$;


--
-- Name: FUNCTION clear_recovered_incident(p_ref text, p_required integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.clear_recovered_incident(p_ref text, p_required integer) IS 'The only path by which a scheduled job may close an incident. SECURITY DEFINER because 0117 withholds resolved_at from carr_jobs and that grant stands: the role gains one function that re-derives the success sequence from ops.run and refuses SEV-1, refuses hand-opened incidents, and refuses anything whose evidence does not hold. Returns false rather than raising, so a refusal never costs the caller its run row.';


--
-- Name: compile_context_bundle(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.compile_context_bundle(p_work_request text, p_plan_ref text, p_tenant text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare work ops.work_request%rowtype; plan ops.sourced_work_request_plan%rowtype; body jsonb;
begin
  if coalesce(current_setting('carr.organization_tenant_id',true),'') <> p_tenant then
    raise exception 'context compilation tenant must match authenticated tenant context';
  end if;
  if p_tenant is null or p_tenant='' then raise exception 'context compiler requires authenticated tenant'; end if;
  select * into work from ops.work_request where ref=p_work_request and organization_tenant_id=p_tenant;
  select * into plan from ops.sourced_work_request_plan where work_request_id=work.id and plan_ref=p_plan_ref order by plan_version desc limit 1;
  if not found then raise exception 'context compiler plan not found'; end if;
  if work.id is null then raise exception 'context compiler Work Request not found'; end if;
  if jsonb_typeof(plan.preimage->'context_activation_items') <> 'array'
     or jsonb_array_length(plan.preimage->'context_activation_items') < 1 then
    raise exception 'context compiler accepted plan has no frozen canonical items';
  end if;
  body := ops.context_activation_bundle_from_items(
    p_tenant, work.ref, 'plan:runbook:' || plan.runbook_revision_id::text, 1,
    coalesce(plan.preimage->'context_activation'->>'base_plan_digest',plan.plan_hash),
    work.triaged_at, plan.preimage->'context_activation_items'
  );
  return body || jsonb_build_object('bundle_digest',ops.context_activation_bundle_digest(body));
end $$;


--
-- Name: complete_calendar_prebrief_joe_live_job(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.complete_calendar_prebrief_joe_live_job(p_job uuid, p_lease uuid, p_attestation uuid, p_receipt uuid) RETURNS TABLE(job_id uuid, attempt integer, state text, attestation_id uuid, receipt_id uuid, allowlist_revision_id uuid, allowlist_digest text, scheduled_for timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; r ops.calendar_prebrief_projection_receipt%rowtype; a ops.calendar_prebrief_source_attestation_receipt%rowtype;
begin
 if session_user<>'carr_jobs' then raise exception 'Joe completion identity refused'; end if;
 select * into j from ops.job where id=p_job for update;
 if not found or j.definition_key<>'calendar-prebrief-projection-joe-daily' or j.definition_version<>1 or j.mode<>'live' or j.state<>'running' or j.lease_token is distinct from p_lease then raise exception 'Joe completion lease refused'; end if;
 select * into r from ops.calendar_prebrief_projection_receipt where job_id=j.id and attempt=j.attempt and id=p_receipt;
 select * into a from ops.calendar_prebrief_source_attestation_receipt where job_id=j.id and attempt=j.attempt and id=p_attestation;
 if r.id is null or a.id is null or r.source_attestation_id<>a.id or r.sponsor<>'joe' or a.sponsor<>'joe' or a.lease_token<>p_lease then raise exception 'Joe completion evidence refused'; end if;
 perform ops.complete_job(j.id,p_lease,jsonb_build_object('sponsor','joe','mode','live','attestation_id',p_attestation,'receipt_id',p_receipt,'allowlist_revision_id',r.allowlist_revision_id,'allowlist_digest',r.allowlist_digest),'calendar-prebrief:joe:'||j.id::text||':'||j.attempt::text);
 return query select j.id,j.attempt,'succeeded'::text,a.id,r.id,r.allowlist_revision_id,r.allowlist_digest,j.scheduled_for;
end $$;


--
-- Name: complete_job(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.complete_job(p_job_id uuid, p_lease_token uuid, p_evidence jsonb, p_receipt_ref text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state <> 'running' or j.lease_token <> p_lease_token
     or j.leased_until < now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  update ops.job_attempt set state='succeeded',ended_at=now()
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token;
  update ops.job set state='succeeded',ended_at=now(),lease_owner=null,
         lease_token=null,leased_until=null,updated_at=now() where id=j.id;
  insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,'completion',p_receipt_ref,coalesce(p_evidence,'{}'::jsonb));
  return true;
end $$;


--
-- Name: completed_release_append_only(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.completed_release_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.state = 'complete' then
    raise exception 'completed release % is append-only history', old.release_key;
  end if;
  return new;
end
$$;


--
-- Name: FUNCTION completed_release_append_only(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.completed_release_append_only() IS 'A completed release is immutable history; derived schema mismatch evidence must not rewrite its declaration.';


--
-- Name: completed_release_delete_refused(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.completed_release_delete_refused() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.state = 'complete' then
    raise exception 'completed release % is append-only history', old.release_key;
  end if;
  return old;
end
$$;


--
-- Name: completion_capsule(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.completion_capsule(evidence jsonb) RETURNS TABLE(acceptance_predicates jsonb, change_ref text, user_facing boolean, user_journey_ref text, attestor text, decision_ref text)
    LANGUAGE sql IMMUTABLE
    AS $$
  select
    coalesce(
      case when jsonb_typeof(evidence #> '{candidate,acceptance_test_refs}') = 'array'
           then evidence #> '{candidate,acceptance_test_refs}' end,
      case when jsonb_typeof(evidence -> 'acceptance_predicates') = 'array'
           then evidence -> 'acceptance_predicates' end),
    coalesce(evidence #>> '{candidate,candidate_commit_sha}',
             evidence ->> 'change_ref'),
    coalesce((evidence #>> '{candidate,user_facing}')::boolean,
             (evidence ->> 'user_facing')::boolean),
    coalesce(evidence #>> '{candidate,user_journey_ref}',
             evidence ->> 'user_journey_ref'),
    coalesce(evidence #>> '{attestation,verifier_actor_id}',
             evidence ->> 'attested_by'),
    coalesce(evidence #>> '{candidate,decision_ref}',
             evidence ->> 'decision_ref')
$$;


--
-- Name: FUNCTION completion_capsule(evidence jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.completion_capsule(evidence jsonb) IS 'The tune-up council 2026-08-21 completion capsule, read from either the capability lane shape (candidate/attestation) or a plain one. ONE definition so the closing trigger and any reader cannot disagree about what done means. 0281 added decision_ref, which is what a DECLINED closure turns on instead of a change reference.';


--
-- Name: context_activation_brief_assignment(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.context_activation_brief_assignment(p_work_request text, p_binding_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare profile_key text;
begin
 select p.profile_key into profile_key from ops.context_activation_binding b join ops.work_request w on w.id=b.work_request_id
 join ops.sourced_work_request_plan plan on plan.id=b.plan_id
 join ops.sourced_work_request_plan_acceptance_receipt ar on ar.work_request_id=w.id and ar.plan_id=plan.id
 join ops.work_request_execution_assignment a on a.work_request_id=w.id join public.agent_profile p on p.id=a.profile_id
 join ops.execution_envelope_v1 e on e.activation_binding_id=b.id and e.expires_at>=now()
 where b.binding_id=p_binding_id and b.expires_at>=now() and w.ref=p_work_request and b.organization_tenant_id=current_setting('carr.organization_tenant_id',true)
   and w.version=b.work_request_version and plan.work_request_id=w.id and plan.plan_hash=b.plan_hash
   and ar.plan_hash=b.plan_hash and ar.result_version=w.version;
 if profile_key is null then raise exception 'context activation brief assignment is expired, stale, or no longer the exact accepted plan'; end if;
 return profile_key;
end $$;


--
-- Name: context_activation_bundle_body(text, text, text, integer, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.context_activation_bundle_body(p_tenant text, p_work_request_ref text, p_plan_revision_ref text, p_plan_revision integer, p_base_plan_digest text, p_issued_at timestamp with time zone, p_item_ref text, p_revision_ref text, p_item_digest text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
    'schema_version','context-bundle.v1',
    'header',jsonb_build_object(
      'tenant_id',p_tenant,
      'work_request_id',p_work_request_ref,
      'accepted_plan_revision_id',p_plan_revision_ref,
      'accepted_plan_revision',p_plan_revision,
      'accepted_plan_digest',p_base_plan_digest,
      'issued_at',to_char(p_issued_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'mode','shadow',
      'retrieval_policy','policy:bounded-doctrine-v1',
      'retrieval_policy_version','v1','compiler_id','compiler:context-activation-v1',
      'compiler_version','v1','compiler_digest','sha256:'||encode(digest('compiler:context-activation-v1','sha256'),'hex'),
      'query_basis_digest','sha256:'||encode(digest(p_tenant||':'||p_work_request_ref||':'||p_plan_revision_ref,'sha256'),'hex'),
      'grounding_plan',jsonb_build_object('inline_budget',64,'retrieval_policy','bounded-doctrine','cache_segment','plan-bound','modalities',jsonb_build_array('metadata_only'),'freshness_sla','accepted-plan-bound')
    ),
    'items',jsonb_build_array(jsonb_build_object(
      'kind','doctrine',
      'canonical_ref',p_item_ref,
      'revision',p_revision_ref,
      'digest',p_item_digest,
      'required',true,
      'trigger','work-request-admission',
      'consumer','hermes-profile-brief',
      'enforcement','must-apply',
      'redaction_class','metadata_only','artifact_kind','doctrine','scope_redaction','metadata_only',
      'trigger_ref','work-request-admission','consumer_ref','hermes-profile-brief','delivery_mode','inline','representation_kind','doctrine','freshness_sla','accepted-plan-bound','selection_reason','canonical-doctrine-binding','selection_rank',0,'requirement_class','required',
      'freshness','fresh'
    ))
  );
$$;


--
-- Name: context_activation_bundle_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.context_activation_bundle_digest(p_bundle jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select 'sha256:' || encode(digest(ops.guidance_import_canonical_json(
    jsonb_build_object(
      'schema_version', p_bundle->'schema_version',
      'header', coalesce(p_bundle->'header','{}'::jsonb)
                  - 'issued_at' - 'expires_at' - 'binding_id',
      'items', p_bundle->'items'
    )), 'sha256'), 'hex')
$$;


--
-- Name: context_activation_bundle_from_items(text, text, text, integer, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.context_activation_bundle_from_items(p_tenant text, p_work_request_ref text, p_plan_revision_ref text, p_plan_revision integer, p_base_plan_digest text, p_issued_at timestamp with time zone, p_items jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
    'schema_version','context-bundle.v1',
    'header',jsonb_build_object(
      'tenant_id',p_tenant, 'work_request_id',p_work_request_ref,
      'accepted_plan_revision_id',p_plan_revision_ref,
      'accepted_plan_revision',p_plan_revision,
      'accepted_plan_digest',p_base_plan_digest,
      'issued_at',to_char(p_issued_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'mode','shadow', 'retrieval_policy','policy:bounded-doctrine-v1',
      'retrieval_policy_version','v1','compiler_id','compiler:context-activation-v1','compiler_version','v1',
      'compiler_digest','sha256:'||encode(digest('compiler:context-activation-v1','sha256'),'hex'),
      'query_basis_digest','sha256:'||encode(digest(p_tenant||':'||p_work_request_ref||':'||p_plan_revision_ref,'sha256'),'hex'),
      'grounding_plan',jsonb_build_object('inline_budget',64,'retrieval_policy','bounded-doctrine','cache_segment','plan-bound','modalities',jsonb_build_array('metadata_only'),'freshness_sla','accepted-plan-bound')
    ), 'items',(select jsonb_agg(item || jsonb_build_object('artifact_kind',item->>'kind','scope_redaction',item->>'redaction_class','trigger_ref',item->>'trigger','consumer_ref',item->>'consumer','delivery_mode',case when (item->>'required')::boolean and item->>'kind' in ('doctrine','rule','decision') then 'inline' when item->>'kind'='memory' then 'on_demand_tool' else 'reference_only' end,'representation_kind',item->>'kind','freshness_sla','accepted-plan-bound','selection_reason',coalesce(item->>'selection_reason','canonical-compiler'),'selection_rank',coalesce((item->>'selection_rank')::int,ordinal),'requirement_class',case when (item->>'required')::boolean then 'required' else 'advisory' end) order by ordinal) from jsonb_array_elements(p_items) with ordinality x(item,ordinal))
  )
$$;


--
-- Name: context_activation_compiler_items(uuid, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.context_activation_compiler_items(p_work_request_id uuid, p_tenant text, p_dependency_refs jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare items jsonb;
begin
  select jsonb_agg(item order by ordinal) into items from (
    select 0 as ordinal, jsonb_build_object(
      'kind','doctrine', 'canonical_ref','doctrine:section:'||w.doctrine_section_id::text,
      'revision','revision:'||w.doctrine_revision_id::text,
      'digest','sha256:'||dr.content_hash, 'required',true,
      'trigger','work-request-admission', 'consumer','hermes-profile-brief',
      'enforcement','must-apply', 'redaction_class','metadata_only', 'freshness','fresh'
    ) as item
      from ops.work_request w
      join public.doctrine_revision dr on dr.id=w.doctrine_revision_id and dr.section_id=w.doctrine_section_id
     where w.id=p_work_request_id and w.organization_tenant_id=p_tenant
    union all
    select 100000 + row_number() over (order by r.id), jsonb_build_object(
      'kind','rule', 'canonical_ref','rule:'||r.id::text,
      'revision','revision:'||r.id::text,
      'digest','sha256:'||encode(public.digest(r.statement,'sha256'),'hex'), 'required',true,
      'trigger','standing-rule-delivery', 'consumer','execution-envelope',
      'enforcement',r.enforcement, 'redaction_class','metadata_only', 'freshness','fresh'
    )
      from ops.rule_delivery_plan(null, '{}'::text[]) delivery
      join public.rule r on r.id=delivery.rule_id
     where delivery.selected and delivery.scope='shared'
    union all
    select 150000 + row_number() over (order by d.decision_id), jsonb_build_object(
      'kind','decision', 'canonical_ref','decision:'||d.decision_id::text,
      'revision','revision:'||d.event_id::text,
      'digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object(
        'title',d.title, 'human_quote',d.human_quote, 'agent_rationale',d.agent_rationale,
        'provenance',d.provenance, 'entry_date',d.entry_date
      )),'sha256'),'hex'), 'required',true,
      'trigger','accepted-plan-dependency', 'consumer','execution-envelope',
      'enforcement','must-apply', 'redaction_class','metadata_only', 'freshness','fresh'
    )
      from public.v_decision_entry d
     where coalesce(p_dependency_refs,'[]'::jsonb) ? ('safe:decision:'||d.decision_id::text)
    union all
    select 200000 + row_number() over (order by m.id), jsonb_build_object(
      'kind','memory', 'canonical_ref','memory:'||m.id::text,
      'revision','revision:'||m.id::text||':v'||m.version::text,
      'digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object(
        'id',m.id,'version',m.version,'kind',m.kind,'statement',m.statement,'context',m.context,
        'scope',m.scope,'organization_tenant_id',m.organization_tenant_id,'work_request_id',m.work_request_id,
        'work_request_version',m.work_request_version,'plan_id',m.plan_id,'status',m.status,'confidence',m.confidence
      )),'sha256'),'hex'), 'required',false,
      'trigger','promoted-memory-retrieval', 'consumer','execution-envelope',
      'enforcement','advisory-only', 'redaction_class','metadata_only', 'freshness','fresh',
      'selection_reason',case when m.work_request_id=p_work_request_id then 'work-request-anchor'
        when coalesce(p_dependency_refs,'[]'::jsonb) ? ('safe:memory:'||m.id::text) then 'accepted-plan-dependency'
        else 'accepted-work-request-fts' end,
      'selection_rank',row_number() over (order by (m.work_request_id=p_work_request_id) desc,
        (coalesce(p_dependency_refs,'[]'::jsonb) ? ('safe:memory:'||m.id::text)) desc,
        m.confidence desc,m.id)
    )
      from (
        select m.* from public.memory_item m
        join ops.work_request candidate_work on candidate_work.id=p_work_request_id
         where m.organization_tenant_id=p_tenant and m.status='promoted' and m.scope='shared'
           and (
             m.work_request_id=candidate_work.id
             or coalesce(p_dependency_refs,'[]'::jsonb) ? ('safe:memory:'||m.id::text)
             or m.search_vector @@ websearch_to_tsquery('english', candidate_work.title || ' ' || candidate_work.desired_outcome)
           )
         order by (m.work_request_id=candidate_work.id) desc,
                  (coalesce(p_dependency_refs,'[]'::jsonb) ? ('safe:memory:'||m.id::text)) desc,
                  ts_rank(m.search_vector,websearch_to_tsquery('english', candidate_work.title || ' ' || candidate_work.desired_outcome)) desc,
                  m.confidence desc,m.id
         limit 16
      ) m
    union all
    select 250000 + row_number() over (order by d.occurred_on desc,d.id), jsonb_build_object(
      'kind','prior_failure','canonical_ref','defect:'||d.id::text,
      'revision','occurred:'||d.occurred_on::text,
      'digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object(
        'id',d.id,'occurred_on',d.occurred_on,'defect_class',d.defect_class,'claimed',d.claimed,
        'actual',d.actual,'source_unread',d.source_unread,'rule_violated',d.rule_violated,
        'detected_by',d.detected_by,'session_key',d.session_key,'cost_note',d.cost_note,'created_at',d.created_at,'created_by',d.created_by
      )),'sha256'),'hex'),
      'required',false,'trigger','accepted-plan-prior-failure','consumer','execution-envelope',
      'enforcement','advisory-only','redaction_class','metadata_only','freshness','fresh'
    ) from (
      select * from public.defect
       where coalesce(p_dependency_refs,'[]'::jsonb) ? ('safe:defect:'||id::text)
       order by occurred_on desc,id limit 16
    ) d
  ) compiled;
  if items is null or jsonb_array_length(items)=0 then
    raise exception 'context compiler has no canonical doctrine item';
  end if;
  if jsonb_array_length(items) > 64 then
    raise exception 'context compiler requires % items, exceeding the contract maximum; narrow the active delivery set', jsonb_array_length(items);
  end if;
  return items;
end $$;


--
-- Name: context_activation_receipt_binding(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.context_activation_receipt_binding(p_work_request text, p_binding_id text) RETURNS TABLE(binding_pk uuid, plan_hash text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'pg_temp'
    AS $$
  select b.id,b.plan_hash
    from ops.context_activation_binding b join ops.work_request w on w.id=b.work_request_id
    join ops.sourced_work_request_plan p on p.id=b.plan_id
    join ops.sourced_work_request_plan_acceptance_receipt ar on ar.work_request_id=w.id and ar.plan_id=p.id
   where b.binding_id=p_binding_id and w.ref=p_work_request
     and b.organization_tenant_id=current_setting('carr.organization_tenant_id',true)
     and w.organization_tenant_id=current_setting('carr.organization_tenant_id',true)
     and b.expires_at>=now() and w.version=b.work_request_version
     and p.work_request_id=w.id and p.plan_hash=b.plan_hash
     and ar.plan_hash=b.plan_hash and ar.result_version=w.version
$$;


--
-- Name: create_calendar_canary_source_snapshot(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_calendar_canary_source_snapshot(p_job_id uuid, p_lease uuid) RETURNS TABLE(id uuid, snapshot_digest text, contact_count integer, snapshot_text text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;s jsonb;r ops.calendar_canary_source_snapshot%rowtype;
begin
 j:=ops.calendar_canary_live_job(p_job_id,p_lease);
 select coalesce(jsonb_agg(x order by source_rank,x->>'email',x->>'ref'),'[]') into s from(
  select jsonb_build_object('email',lower(btrim("Email")),'ref',"Client ID",'name',"Name",'org',"Practice / Entity") x,1 source_rank from v_export_clients where "Email" is not null and position('@' in btrim("Email"))>1
  union all select jsonb_build_object('email',lower(btrim("Email")),'ref',"Lead ID",'name',"Contact Name",'org',"Practice"),2 from v_export_leads where "Email" is not null and position('@' in btrim("Email"))>1)q;
 if jsonb_array_length(s)=0 then raise exception using errcode='22023',message='calendar canary source snapshot is empty'; end if;
 insert into ops.calendar_canary_source_snapshot(job_id,attempt,workflow_version,snapshot,snapshot_digest,contact_count)
 values(j.id,j.attempt,5,s,encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex'),jsonb_array_length(s)) on conflict(job_id,attempt) do nothing returning * into r;
 if not found then
  select * into r from ops.calendar_canary_source_snapshot where job_id=j.id and attempt=j.attempt;
  if r.snapshot_digest<>encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex') or r.contact_count<>jsonb_array_length(s) then raise exception using errcode='23505',message='calendar canary source snapshot replay conflicts with canonical contacts'; end if;
 end if;
 return query select r.id,r.snapshot_digest,r.contact_count,r.snapshot::text;
end $$;


--
-- Name: create_nightly_availability_canary_source_snapshot(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_nightly_availability_canary_source_snapshot(p_job_id uuid, p_lease uuid) RETURNS TABLE(id uuid, snapshot_digest text, availability_count integer, open_search_count integer, snapshot_text text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;s jsonb;r ops.nightly_availability_canary_source_snapshot%rowtype;
begin
 j:=ops.nightly_availability_canary_live_job(p_job_id,p_lease);
 select jsonb_build_object(
   'availabilities',coalesce((select jsonb_agg(x order by x->>'id') from (
      select jsonb_build_object('id',av.id::text,'status',av.status,'rate_norm',av.rate_norm_sf_yr,
        'owed',av.norm_owed,'available_on',av.available_on,'observed',av.observed_at::date,
        'source',av.source,'area',sp.area_amount,'suite',sp.suite,'city',b.city,'state',b.state,
        'sub_type',b.sub_type,'address',b.address,'bname',b.name) x
        from (select distinct on (av.space_id) av.* from availability av
               order by av.space_id,av.observed_at desc,av.id desc) av
        join space sp on sp.id=av.space_id join building b on b.id=sp.building_id)q),'[]'::jsonb),
   'searches',coalesce((select jsonb_agg(x order by x->>'ref',x->>'id') from (
      select jsonb_build_object('id',s.id::text,'spec',s.spec,'ref',coalesce(c.roster_ref,''),'name',p.name) x
        from space_search s join client c on c.id=s.client_id join party p on p.id=c.party_id where s.status='open')q),'[]'::jsonb)) into s;
 if jsonb_array_length(s->'availabilities')=0 or jsonb_array_length(s->'searches')=0 then
   raise exception using errcode='22023',message='nightly availability canary source must contain availability and open-search evidence';
 end if;
 insert into ops.nightly_availability_canary_source_snapshot(job_id,attempt,workflow_version,snapshot,snapshot_digest,availability_count,open_search_count)
 values(j.id,j.attempt,3,s,encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex'),jsonb_array_length(s->'availabilities'),jsonb_array_length(s->'searches'))
 on conflict(job_id,attempt) do nothing returning * into r;
 if not found then
  select * into r from ops.nightly_availability_canary_source_snapshot where job_id=j.id and attempt=j.attempt;
  if r.snapshot_digest<>encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex') or r.availability_count<>jsonb_array_length(s->'availabilities') or r.open_search_count<>jsonb_array_length(s->'searches') then raise exception using errcode='23505',message='nightly availability canary source replay conflicts with canonical snapshot'; end if;
 end if;
 return query select r.id,r.snapshot_digest,r.availability_count,r.open_search_count,r.snapshot::text;
end $$;


--
-- Name: current_sourced_work_requests(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.current_sourced_work_requests(p_organization_tenant_id text) RETURNS TABLE(ref text, title text, state text, source_label text, source_freshness text, next_human_action text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select w.ref,
         w.title,
         w.state,
         coalesce(s.title, s.section_key) as source_label,
         'current'::text as source_freshness,
         case
           when w.state = 'captured' then 'Review and triage'
           when w.state = 'triaged' then 'Prepare or review bounded plan'
           when w.state = 'ready' then 'Record or review outcome evidence'
         end as next_human_action
    from ops.work_request w
    join public.doctrine_section s on s.id = w.doctrine_section_id
    join public.doctrine_document d on d.id = s.document_id
   where p_organization_tenant_id = 'carr-internal'
     and w.organization_tenant_id = p_organization_tenant_id
     and w.capture_idempotency_key is not null
     and w.state in ('captured', 'triaged', 'ready')
     and d.visibility = 'shared'
     and s.status = 'active'
     and s.current_revision_id = w.doctrine_revision_id
     and (
       w.state <> 'triaged'
       or (
         not exists (
           select 1
             from ops.sourced_work_request_plan existing_plan
            where existing_plan.work_request_id = w.id
         )
         and exists (
           select 1
             from public.doctrine_document runbook_document
             join public.doctrine_section runbook_section
               on runbook_section.document_id = runbook_document.id
             join public.doctrine_revision runbook_revision
               on runbook_revision.id = runbook_section.current_revision_id
              and runbook_revision.section_id = runbook_section.id
            where runbook_document.slug = 'runbook'
              and runbook_document.visibility = 'shared'
              and runbook_section.section_key = 'diagnosis-checklist-in-order-2-minutes'
              and runbook_section.status = 'active'
              and runbook_revision.content_hash ~ '^[0-9a-f]{64}$'
              and encode(public.digest(runbook_revision.plain_text, 'sha256'), 'hex') = runbook_revision.content_hash
              and runbook_revision.body = jsonb_build_object('text', runbook_revision.plain_text)
         )
       )
       or exists (
         select 1
           from ops.sourced_work_request_plan current_plan
           join public.doctrine_section planned_runbook_section
             on planned_runbook_section.id = current_plan.runbook_section_id
           join public.doctrine_document planned_runbook_document
             on planned_runbook_document.id = planned_runbook_section.document_id
           join public.doctrine_revision planned_runbook_revision
             on planned_runbook_revision.id = planned_runbook_section.current_revision_id
            and planned_runbook_revision.section_id = planned_runbook_section.id
          where current_plan.id = (
            select latest_plan.id
              from ops.sourced_work_request_plan latest_plan
             where latest_plan.work_request_id = w.id
             order by latest_plan.plan_version desc
             limit 1
          )
            and planned_runbook_document.slug = 'runbook'
            and planned_runbook_document.visibility = 'shared'
            and planned_runbook_section.status = 'active'
            and planned_runbook_revision.id = current_plan.runbook_revision_id
            and planned_runbook_revision.content_hash = current_plan.runbook_content_hash
            and ('doctrine:' || planned_runbook_document.slug || '#' || planned_runbook_section.section_key) = current_plan.runbook_ref
            and encode(public.digest(planned_runbook_revision.plain_text, 'sha256'), 'hex') = planned_runbook_revision.content_hash
            and planned_runbook_revision.body = jsonb_build_object('text', planned_runbook_revision.plain_text)
       )
     )
   order by w.captured_at asc, w.ref asc
   limit 20;
$_$;


--
-- Name: deactivate_guidance_registry(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.deactivate_guidance_registry(p_registry_id uuid, p_manifest_digest text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_authority_slug text;
  v_authority_actor uuid;
  v_registry_owner uuid;
  v_active_digest text;
  v_existing record;
  v_receipt_id uuid;
  v_event_id uuid;
begin
  v_authority_slug := ops.authority_actor_slug();
  select id into v_authority_actor from actor where slug=v_authority_slug and kind='human' and active;
  select created_by into v_registry_owner from ops.guidance_registry where id=p_registry_id;
  if v_authority_actor is null or v_registry_owner is null or v_authority_actor<>v_registry_owner then
    raise exception 'guidance registry deactivation requires its accountable human authority actor';
  end if;
  if p_manifest_digest !~ '^[0-9a-f]{64}$' or coalesce(btrim(p_idempotency_key),'')=''
     or coalesce(btrim(p_reason),'')='' then
    raise exception 'deactivation requires a sha256 manifest digest, idempotency key and reason';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('guidance-registry-deactivation:' || p_idempotency_key,0));
  select ar.id,ar.kind,ar.subject_type,ar.subject_id,ar.actor_id,ar.decision,
         ar.contract_hash,ge.id as event_id,ge.manifest_digest,ge.reason
    into v_existing from ops.authority_receipt ar
    left join ops.guidance_registry_event ge on ge.authority_receipt_id=ar.id
   where ar.idempotency_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.kind<>'rejection' or v_existing.subject_type<>'guidance'
       or v_existing.subject_id<>p_registry_id or v_existing.actor_id<>v_authority_actor
       or v_existing.decision<>'retired' or v_existing.contract_hash<>p_manifest_digest
       or v_existing.event_id is null or v_existing.manifest_digest<>p_manifest_digest
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different or incomplete guidance registry deactivation';
    end if;
    return v_existing.event_id;
  end if;
  select manifest_digest into v_active_digest from ops.v_guidance_registry_state
   where registry_id=p_registry_id and state='active';
  if v_active_digest is null or v_active_digest<>p_manifest_digest then
    raise exception 'guidance registry deactivation requires the exact currently active manifest digest';
  end if;
  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,contract_hash,evidence_refs)
  values (p_idempotency_key,'rejection','guidance',p_registry_id,v_authority_actor,
          'retired',p_manifest_digest,array[p_registry_id::text])
  returning id into v_receipt_id;
  insert into ops.guidance_registry_event
    (registry_id,state,authority_receipt_id,manifest_digest,reason)
  values (p_registry_id,'inactive',v_receipt_id,p_manifest_digest,p_reason)
  returning id into v_event_id;
  return v_event_id;
end $_$;


--
-- Name: decide_guidance_import_batch(uuid, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.decide_guidance_import_batch(p_batch_id uuid, p_manifest_digest text, p_state text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_batch ops.guidance_import_batch%rowtype;
  v_authority_slug text;
  v_authority_actor uuid;
  v_registry_owner uuid;
  v_existing record;
  v_decision_id uuid;
  v_entry ops.guidance_import_entry%rowtype;
  v_item_id uuid;
  v_revision_id uuid;
  v_lifecycle_id uuid;
  v_binding_id uuid;
  v_mapping ops.guidance_import_mapping_execution%rowtype;
  v_active_mapping_id uuid;
begin
  v_authority_slug := ops.authority_actor_slug();
  select id into v_authority_actor from actor where slug=v_authority_slug and kind='human' and active;
  select created_by into v_registry_owner from ops.guidance_registry where singleton;
  if v_authority_actor is null or v_authority_actor<>v_registry_owner then
    raise exception 'guidance import batch decision requires the accountable registry human authority';
  end if;
  if p_state <> 'active' or p_manifest_digest !~ '^[0-9a-f]{64}$'
     or coalesce(btrim(p_idempotency_key),'')='' or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance import decision requires state, digest, idempotency key and reason';
  end if;
  select * into v_batch from ops.guidance_import_batch where id=p_batch_id;
  if v_batch.id is null or v_batch.manifest_digest<>p_manifest_digest
     or not exists (select 1 from ops.guidance_import_apply_event where batch_id=p_batch_id) then
    raise exception 'guidance import batch must be staged, exact-digest matched and applied before a decision';
  end if;
  perform ops.assert_guidance_import_inventory(p_batch_id);
  select * into v_existing from ops.guidance_import_decision_event where idempotency_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.batch_id<>p_batch_id or v_existing.manifest_digest<>p_manifest_digest
       or v_existing.state<>p_state or v_existing.authority_actor_id<>v_authority_actor
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different guidance import decision';
    end if;
    return v_existing.id;
  end if;
  insert into ops.guidance_import_decision_event
    (batch_id,manifest_digest,state,idempotency_key,authority_actor_id,reason)
  values (p_batch_id,p_manifest_digest,p_state,p_idempotency_key,v_authority_actor,p_reason)
  returning id into v_decision_id;
  for v_entry in select * from ops.guidance_import_entry where batch_id=p_batch_id order by ordinal loop
    select i.id,r.id into v_item_id,v_revision_id from ops.guidance_item i
      join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
     where i.source_rule_id=v_entry.source_rule_id and i.source_clause=v_entry.source_clause;
    if v_revision_id is null then
      raise exception 'applied import entry % has no exact revision',v_entry.guidance_id;
    end if;
    v_lifecycle_id := ops.record_guidance_decision(
      v_revision_id,p_state,
      encode(digest(convert_to(p_idempotency_key || ':revision:' || v_revision_id::text,'UTF8'),'sha256'),'hex'),
      p_reason);
    if p_state='active' then
      select authority_binding_id into v_binding_id from ops.guidance_lifecycle_event where id=v_lifecycle_id;
      for v_mapping in select * from ops.guidance_import_mapping_execution
          where batch_id=p_batch_id and entry_id=v_entry.id
            and active_mapping_id is null order by ordinal loop
        if exists (select 1 from ops.guidance_import_mapping_execution prior
                    where prior.proposed_mapping_id=v_mapping.proposed_mapping_id
                      and prior.active_mapping_id is not null) then
          continue;
        end if;
        v_active_mapping_id := ops.activate_guidance_situation_mapping(
          v_mapping.proposed_mapping_id,v_binding_id,p_reason);
        -- Mapping execution is append-only; record the activated counterpart
        -- in a second immutable row rather than rewriting the proposal row.
        insert into ops.guidance_import_mapping_execution
          (batch_id,entry_id,ordinal,concept_id,doctrine_section_id,proposed_mapping_id,active_mapping_id)
        values (p_batch_id,v_entry.id,v_mapping.ordinal + 1000000,
                v_mapping.concept_id,v_mapping.doctrine_section_id,
                v_mapping.proposed_mapping_id,v_active_mapping_id);
      end loop;
    end if;
  end loop;
  return v_decision_id;
end $_$;


--
-- Name: deployment_provider_identity_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.deployment_provider_identity_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.environment = 'production'
     and old.state in ('deploying', 'verifying', 'complete')
     and (new.provider is distinct from old.provider
          or new.provider_version_id is distinct from old.provider_version_id) then
    raise exception 'Production deployment provider identity is immutable after promotion begins';
  end if;
  return new;
end $$;


--
-- Name: deployment_requires_a_live_approval(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.deployment_requires_a_live_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  r record;
begin
  if new.environment <> 'production' then
    return new;
  end if;
  if new.release_id is null then
    raise exception 'a production deployment must name its release (ops.release), '
                    'because a deploy nobody can trace to an approved plan is the '
                    'exact gap P0-1 closes';
  end if;
  select state, approval_expires_at, release_key, git_sha, environment,
         provider, provider_version_id into r
    from ops.release where id = new.release_id;
  if r.state not in ('approved','deploying','verifying','complete') then
    raise exception 'release % is %, not approved — promotion refused',
                    r.release_key, r.state;
  end if;
  if r.approval_expires_at is null or r.approval_expires_at <= now() then
    raise exception 'release % has an expired approval (%) — re-approve before '
                    'promoting', r.release_key, r.approval_expires_at;
  end if;
  if r.environment is distinct from new.environment then
    raise exception 'release % targets %, not deployment environment % — promotion refused',
                    r.release_key, r.environment, new.environment;
  end if;
  if r.git_sha is distinct from new.git_sha then
    raise exception 'release % binds git SHA %, not deployment SHA % — promotion refused',
                    r.release_key, r.git_sha, new.git_sha;
  end if;
  if r.provider is distinct from new.provider then
    raise exception 'release % binds provider %, not deployment provider % — promotion refused',
                    r.release_key, r.provider, new.provider;
  end if;
  if r.provider_version_id is distinct from new.provider_version_id then
    raise exception 'release % binds provider version %, not deployment provider version % — promotion refused',
                    r.release_key, r.provider_version_id, new.provider_version_id;
  end if;
  return new;
end $$;


--
-- Name: disable_legacy_schedule(text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.disable_legacy_schedule(p_workflow_key text, p_surface_id text, p_locator text, p_reason text, p_pre_observation_ref text, p_post_observation_ref text, p_sibling_surface_id text, p_sibling_locator text, p_sibling_pre_observation_ref text, p_sibling_post_observation_ref text, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  n integer; v integer; ref text; kind text; group_name text;
  sibling_kind text; sibling_group text;
  existing ops.legacy_schedule_disable_receipt%rowtype;
  pre ops.legacy_schedule_observation_receipt%rowtype;
  post ops.legacy_schedule_observation_receipt%rowtype;
  sibling_pre ops.legacy_schedule_observation_receipt%rowtype;
  sibling_post ops.legacy_schedule_observation_receipt%rowtype;
begin
  if ops.authority_actor_slug() <> 'joe' then
    raise exception 'legacy schedule retirement requires Joe authority session';
  end if;
  if btrim(coalesce(p_workflow_key,''))='' or btrim(coalesce(p_surface_id,''))=''
     or btrim(coalesce(p_locator,''))='' or btrim(coalesce(p_reason,''))=''
     or btrim(coalesce(p_pre_observation_ref,''))=''
     or btrim(coalesce(p_post_observation_ref,''))=''
     or btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'cutover subject, reason, native observations, and idempotency key are required';
  end if;
  if (p_sibling_surface_id is null) <> (p_sibling_locator is null)
     or (p_sibling_surface_id is null) <> (p_sibling_pre_observation_ref is null)
     or (p_sibling_surface_id is null) <> (p_sibling_post_observation_ref is null)
     or (p_sibling_surface_id is not null and (
       btrim(p_sibling_surface_id)='' or btrim(p_sibling_locator)=''
       or btrim(p_sibling_pre_observation_ref)='' or btrim(p_sibling_post_observation_ref)='')) then
    raise exception 'duplicate scheduler evidence fields must be supplied together';
  end if;

  select * into existing from ops.legacy_schedule_disable_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.workflow_key is distinct from p_workflow_key
       or existing.surface_id is distinct from p_surface_id
       or existing.locator is distinct from p_locator
       or existing.reason is distinct from p_reason
       or existing.pre_observation_ref is distinct from p_pre_observation_ref
       or existing.post_observation_ref is distinct from p_post_observation_ref
       or existing.sibling_surface_id is distinct from p_sibling_surface_id
       or existing.sibling_locator is distinct from p_sibling_locator
       or existing.sibling_pre_observation_ref is distinct from p_sibling_pre_observation_ref
       or existing.sibling_post_observation_ref is distinct from p_sibling_post_observation_ref then
      raise exception 'idempotency key is bound to different verified legacy disable evidence';
    end if;
    return existing.receipt_ref;
  end if;

  select version into v from ops.job_definition
   where key=p_workflow_key order by version desc limit 1;
  if v is null then raise exception 'unknown workflow %',p_workflow_key; end if;
  select scheduler_kind,duplicate_group into kind,group_name
    from ops.legacy_schedule_surface_registry
   where workflow_key=p_workflow_key and workflow_version=v
     and surface_id=p_surface_id and locator=p_locator;
  if kind is null then raise exception 'legacy schedule surface is not registered'; end if;

  if group_name is null then
    if p_sibling_surface_id is not null then
      raise exception 'single-surface cutover does not accept sibling evidence';
    end if;
  else
    if p_sibling_surface_id is null or p_surface_id >= p_sibling_surface_id then
      raise exception 'duplicate scheduler evidence must use canonical primary and sibling order';
    end if;
    select scheduler_kind,duplicate_group into sibling_kind,sibling_group
      from ops.legacy_schedule_surface_registry
     where workflow_key=p_workflow_key and workflow_version=v
       and surface_id=p_sibling_surface_id and locator=p_sibling_locator;
    if sibling_kind is null or sibling_group is distinct from group_name
       or (select count(*) from ops.legacy_schedule_surface_registry
            where workflow_key=p_workflow_key and workflow_version=v
              and duplicate_group=group_name) <> 2
       or array[kind,sibling_kind]::text[] @> array['claude-code','launchd']::text[] is not true then
      raise exception 'Notes duplicate retirement requires exact claude-code and launchd surfaces';
    end if;
  end if;

  if not exists (
    select 1 from ops.workflow_acceptance
     where workflow_key=p_workflow_key and workflow_version=v and mode='shadow' and status='accepted'
  ) or not exists (
    select 1 from ops.workflow_acceptance
     where workflow_key=p_workflow_key and workflow_version=v and mode='canary' and status='accepted'
  ) then
    raise exception 'legacy schedule retirement requires accepted shadow and canary evidence';
  end if;

  select r.* into pre from ops.legacy_schedule_observation_receipt r
   where r.receipt_ref=p_pre_observation_ref and r.scheduler_kind=kind
     and ((kind='claude-code' and exists (
       select 1 from ops.legacy_schedule_provider_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.cron_expression=r.cron_expression and c.timezone=r.timezone
          and c.definition_sha256=r.definition_sha256))
       or (kind='launchd' and exists (
       select 1 from ops.legacy_schedule_launchd_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
          and c.plist_sha256=r.definition_sha256)));
  select r.* into post from ops.legacy_schedule_observation_receipt r
   where r.receipt_ref=p_post_observation_ref and r.scheduler_kind=kind
     and ((kind='claude-code' and exists (
       select 1 from ops.legacy_schedule_provider_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.cron_expression=r.cron_expression and c.timezone=r.timezone
          and c.definition_sha256=r.definition_sha256))
       or (kind='launchd' and exists (
       select 1 from ops.legacy_schedule_launchd_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
          and c.plist_sha256=r.definition_sha256)));
  if pre.id is null or post.id is null
     or pre.workflow_key<>p_workflow_key or post.workflow_key<>p_workflow_key
     or pre.workflow_version<>v or post.workflow_version<>v
     or pre.surface_id<>p_surface_id or post.surface_id<>p_surface_id
     or pre.locator<>p_locator or post.locator<>p_locator
     or pre.scheduler_state<>'enabled' or post.scheduler_state<>'disabled'
     or pre.observed_at<now()-interval '15 minutes'
     or post.observed_at<now()-interval '15 minutes'
     or pre.observed_at>now()+interval '5 minutes'
     or post.observed_at>now()+interval '5 minutes'
     or post.observed_at<pre.observed_at
     or pre.source_fingerprint=post.source_fingerprint then
    raise exception 'native scheduler evidence is not a current enabled-to-disabled readback';
  end if;

  if p_sibling_surface_id is not null then
    select r.* into sibling_pre from ops.legacy_schedule_observation_receipt r
     where r.receipt_ref=p_sibling_pre_observation_ref and r.scheduler_kind=sibling_kind
       and ((sibling_kind='claude-code' and exists (
         select 1 from ops.legacy_schedule_provider_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.cron_expression=r.cron_expression and c.timezone=r.timezone
            and c.definition_sha256=r.definition_sha256))
         or (sibling_kind='launchd' and exists (
         select 1 from ops.legacy_schedule_launchd_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
            and c.plist_sha256=r.definition_sha256)));
    select r.* into sibling_post from ops.legacy_schedule_observation_receipt r
     where r.receipt_ref=p_sibling_post_observation_ref and r.scheduler_kind=sibling_kind
       and ((sibling_kind='claude-code' and exists (
         select 1 from ops.legacy_schedule_provider_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.cron_expression=r.cron_expression and c.timezone=r.timezone
            and c.definition_sha256=r.definition_sha256))
         or (sibling_kind='launchd' and exists (
         select 1 from ops.legacy_schedule_launchd_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
            and c.plist_sha256=r.definition_sha256)));
    if sibling_pre.id is null or sibling_post.id is null
       or sibling_pre.workflow_key<>p_workflow_key or sibling_post.workflow_key<>p_workflow_key
       or sibling_pre.workflow_version<>v or sibling_post.workflow_version<>v
       or sibling_pre.surface_id<>p_sibling_surface_id or sibling_post.surface_id<>p_sibling_surface_id
       or sibling_pre.locator<>p_sibling_locator or sibling_post.locator<>p_sibling_locator
       or sibling_pre.scheduler_state<>'enabled' or sibling_post.scheduler_state<>'disabled'
       or sibling_pre.observed_at<now()-interval '15 minutes'
       or sibling_post.observed_at<now()-interval '15 minutes'
       or sibling_pre.observed_at>now()+interval '5 minutes'
       or sibling_post.observed_at>now()+interval '5 minutes'
       or sibling_post.observed_at<sibling_pre.observed_at
       or sibling_pre.source_fingerprint=sibling_post.source_fingerprint then
      raise exception 'native duplicate scheduler evidence is not a current enabled-to-disabled readback';
    end if;
  end if;

  ref := 'legacy-disable:' || p_idempotency_key;
  update ops.job_definition set legacy_disabled_at=now(),legacy_disable_reason=p_reason,updated_at=now()
   where key=p_workflow_key and version=v and legacy_disabled_at is null;
  get diagnostics n=row_count;
  if n<>1 then raise exception 'legacy schedule was not disabled'; end if;
  insert into ops.legacy_schedule_disable_receipt
    (receipt_ref,idempotency_key,workflow_key,workflow_version,surface_id,locator,reason,
     approved_by,pre_observation_ref,post_observation_ref,sibling_observation_ref,
     sibling_surface_id,sibling_locator,sibling_pre_observation_ref,sibling_post_observation_ref)
  values
    (ref,p_idempotency_key,p_workflow_key,v,p_surface_id,p_locator,p_reason,'joe',
     p_pre_observation_ref,p_post_observation_ref,null,
     p_sibling_surface_id,p_sibling_locator,p_sibling_pre_observation_ref,p_sibling_post_observation_ref);
  return ref;
end $$;


--
-- Name: enforce_completion_capsule(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_completion_capsule() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  cap         record;
  implementer text;
  n_predicates int;
  declining   boolean;
begin
  if new.state <> 'confirmed_closed' then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.state = 'confirmed_closed' then
    return new;
  end if;

  if new.completion_evidence is null
     or jsonb_typeof(new.completion_evidence) <> 'object' then
    raise exception
      'closing %: done needs an evidence capsule, and completion_evidence is not an object.',
      new.ref using errcode = 'check_violation';
  end if;

  select * into cap from ops.completion_capsule(new.completion_evidence);

  -- KEYED ON THE DECLARED KIND, never on the capsule looking thin. If a missing
  -- change reference were itself the signal, "I have no change reference" would
  -- become the way to buy the cheaper close.
  declining := (new.completion_kind = 'declined');

  if declining then
    -- A DECLINE HAS NO CHANGE, NO ACCEPTANCE TESTS AND NO JOURNEY. What it has
    -- is a decision, and someone other than the implementer who checked it.
    if coalesce(btrim(cap.decision_ref),'') = '' then
      raise exception
        'closing %: a decline needs the DECISION that made it. Nothing else here is '
        'evidence — there is no change to point at and no test that passed.',
        new.ref using errcode = 'check_violation';
    end if;
  else
    select count(*) into n_predicates
      from jsonb_array_elements_text(coalesce(cap.acceptance_predicates,'[]'::jsonb)) p
     where btrim(p) <> '';
    if n_predicates = 0 then
      raise exception
        'closing %: the evidence capsule states no acceptance predicates. What would have '
        'made this done had to be sayable before it was done.', new.ref
        using errcode = 'check_violation';
    end if;

    if coalesce(btrim(cap.change_ref),'') = '' then
      raise exception
        'closing %: the evidence capsule names no change reference, so nothing ties this '
        'closure to what actually shipped.', new.ref
        using errcode = 'check_violation';
    end if;

    if cap.user_facing is null then
      raise exception
        'closing %: the evidence capsule does not say whether this is user-facing. Say so '
        'explicitly — silence here is how a capability gets reported live before a human '
        'has used it.', new.ref
        using errcode = 'check_violation';
    end if;

    if cap.user_facing and coalesce(btrim(cap.user_journey_ref),'') = '' then
      raise exception
        'closing %: this is declared user-facing, so the capsule must name an EXERCISED user '
        'journey. A user-facing thing nobody has used is not done.', new.ref
        using errcode = 'check_violation';
    end if;
  end if;

  -- IDENTICAL FOR BOTH KINDS, and that is the point. A decline waved through on
  -- the implementer's own say-so is exactly as unaccountable as a self-attested
  -- build. The uuid-or-slug resolution stays too: every capability-lane
  -- attestation records a uuid, so a slug-only comparison would pass every
  -- self-attestation ever made.
  if coalesce(btrim(cap.attestor),'') = '' then
    raise exception
      'closing %: no attestor. Done requires somebody who did not build it saying it is done.',
      new.ref using errcode = 'check_violation';
  end if;

  implementer := coalesce(new.executor_actor, new.owner_actor);
  if implementer is not null then
    if lower(btrim(cap.attestor)) = lower(btrim(implementer))
       or exists (select 1 from actor a
                   where a.id::text = cap.attestor
                     and lower(a.slug) = lower(btrim(implementer))) then
      raise exception
        'closing %: % attested their own work. The whole point of an independent attestor '
        'is that it is somebody else.', new.ref, implementer
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $$;


--
-- Name: FUNCTION enforce_completion_capsule(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.enforce_completion_capsule() IS 'Tune-up council 2026-08-21: a Work Request cannot reach confirmed_closed on a timestamp alone. Fires on the TRANSITION into confirmed_closed. A BUILT closure pays acceptance predicates, a change reference, an explicit user-facing boolean and a journey where that is true; a DECLINED closure pays the decision that made it, because there is no change and no test (0281). The independent-attestor test is identical for both.';


--
-- Name: enforce_work_in_progress_limit(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_work_in_progress_limit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  system_wide     int;
  per_executor    int;
  who             text;
  who_before      text;
  already_in_flight boolean;
  limit_system    constant int := 2;
  limit_each      constant int := 1;
begin
  if new.state not in ('claimed','in_progress') then
    return new;
  end if;

  already_in_flight := (tg_op = 'UPDATE' and old.state in ('claimed','in_progress'));

  -- SYSTEM-WIDE: entry only. A row already in flight is already counted, and
  -- re-checking here would make a full queue uneditable.
  if not already_in_flight then
    select count(*) into system_wide
      from ops.work_request
     where state in ('claimed','in_progress')
       and id <> new.id;

    if system_wide + 1 > limit_system then
      raise exception
        'work-in-progress limit: % already in flight system-wide and the limit is %. '
        'Move something to blocked, verification or confirmed_closed before claiming %.',
        system_wide, limit_system, new.ref
        using errcode = 'check_violation';
    end if;
  end if;

  who := coalesce(new.executor_actor, new.owner_actor);

  -- PER-EXECUTOR: on entry, and on any reassignment of a row already in flight.
  -- Reassignment does not move the system-wide total but it does move this one.
  if already_in_flight then
    who_before := coalesce(old.executor_actor, old.owner_actor);
    if who_before is not distinct from who then
      return new;
    end if;
  end if;

  if who is not null then
    select count(*) into per_executor
      from ops.work_request
     where state in ('claimed','in_progress')
       and coalesce(executor_actor, owner_actor) = who
       and id <> new.id;

    if per_executor + 1 > limit_each then
      raise exception
        'work-in-progress limit: % already has % in flight and the limit per executor is %. '
        'One thing at a time is the point; finish or park it before claiming %.',
        who, per_executor, limit_each, new.ref
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $$;


--
-- Name: FUNCTION enforce_work_in_progress_limit(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.enforce_work_in_progress_limit() IS 'Tune-up council 2026-08-21: work-in-progress limit of 2 system-wide and 1 per executor, enforced at the row transition because the claim path has more than one route. Counts claimed and in_progress only; held-but-not-active states are deliberately excluded so a blocked row cannot freeze the queue. The system-wide check runs on entry into flight only; the per-executor check ALSO runs when a row already in flight changes hands, because reassignment moves that count without moving the total (0277).';


--
-- Name: enqueue_job(text, integer, timestamp with time zone, jsonb, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enqueue_job(p_definition_key text, p_definition_version integer, p_scheduled_for timestamp with time zone, p_payload jsonb, p_idempotency_key text, p_mode text DEFAULT 'live'::text) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  d ops.job_definition%rowtype;
  j ops.job%rowtype;
begin
  select * into d from ops.job_definition
   where key=p_definition_key and version=p_definition_version and enabled;
  if not found then
    raise exception 'job definition % v% is not enabled',p_definition_key,p_definition_version;
  end if;
  if p_mode not in ('shadow','canary','live','replay') then
    raise exception 'invalid job mode %',p_mode;
  end if;
  insert into ops.job
    (definition_key,definition_version,idempotency_key,scheduled_for,mode,payload,
     max_attempts,timeout_seconds)
  values
    (d.key,d.version,p_idempotency_key,p_scheduled_for,p_mode,coalesce(p_payload,'{}'::jsonb),
     (d.retry_policy->>'max_attempts')::integer,
     (d.retry_policy->>'timeout_seconds')::integer)
  on conflict do nothing
  returning * into j;
  if j.id is null then
    select * into j from ops.job
     where idempotency_key=p_idempotency_key
        or (definition_key=p_definition_key
            and definition_version=p_definition_version
            and scheduled_for=p_scheduled_for)
     order by (idempotency_key=p_idempotency_key) desc
     limit 1;
    if j.id is null
       or j.definition_key <> p_definition_key
       or j.definition_version <> p_definition_version
       or j.scheduled_for <> p_scheduled_for
       or j.payload <> coalesce(p_payload,'{}'::jsonb)
       or j.mode <> p_mode then
      raise exception 'duplicate delivery conflicts with the canonical scheduled job';
    end if;
  end if;
  return j;
end $$;


--
-- Name: evidence_activation_append_only(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.evidence_activation_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'evidence activation projections are append-only';
end $$;


--
-- Name: fail_job(uuid, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fail_job(p_job_id uuid, p_lease_token uuid, p_failure_class text, p_detail text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; next_state text;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state <> 'running' or j.lease_token <> p_lease_token
     or j.leased_until < now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  next_state := case when j.attempt < j.max_attempts then 'retry_wait' else 'dead_lettered' end;
  update ops.job_attempt set state='failed',ended_at=now(),
         failure_class=p_failure_class,detail=p_detail
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token;
  update ops.job set state=next_state,
         next_attempt_at=case when next_state='retry_wait'
                              then now()+make_interval(secs=>ops.retry_delay_seconds(j))
                              else next_attempt_at end,
         ended_at=case when next_state='dead_lettered' then now() else null end,
         last_failure_class=p_failure_class,last_failure_detail=p_detail,
         lease_owner=null,lease_token=null,leased_until=null,updated_at=now()
   where id=j.id;
  insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,case when next_state='dead_lettered' then 'dead_letter' else 'failure' end,
           concat('failure:',j.id,':',j.attempt),
           jsonb_build_object('failure_class',p_failure_class,'detail',p_detail,'next_state',next_state));
  return next_state;
end $$;


--
-- Name: fence_definition_jobs(text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fence_definition_jobs(p_definition_key text, p_definition_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  with transitioned as (
    update ops.job j
       set state='cancelled',ended_at=now(),
           last_failure_class='definition_disabled',
           last_failure_detail='definition version disabled before dispatch',
           lease_owner=null,lease_token=null,leased_until=null,updated_at=now()
     where j.definition_key=p_definition_key
       and j.definition_version=p_definition_version
       and j.state in ('queued','retry_wait')
    returning j.id,j.attempt,j.definition_key,j.definition_version
  ), receipts as (
    insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    select t.id,t.attempt,'override',
           concat('definition-disabled:',t.id,':v',t.definition_version),
           jsonb_build_object(
             'failure_class','definition_disabled',
             'definition_key',t.definition_key,
             'definition_version',t.definition_version,
             'next_state','cancelled')
      from transitioned t
    returning id
  )
  select count(*) into n from receipts;
  return n;
end $$;


--
-- Name: fence_jobs_when_definition_disabled(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fence_jobs_when_definition_disabled() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if old.enabled and not new.enabled then
    perform ops.fence_definition_jobs(new.key,new.version);
  end if;
  return new;
end $$;


--
-- Name: freshness(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.freshness(observed_at timestamp with time zone, expires_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when observed_at is null then 'missing'
    when expires_at  is null then 'unknown'
    when now() > expires_at  then 'stale'
    else 'fresh'
  end
$$;


--
-- Name: FUNCTION freshness(observed_at timestamp with time zone, expires_at timestamp with time zone); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.freshness(observed_at timestamp with time zone, expires_at timestamp with time zone) IS 'The four freshness states from control-room/contracts/entity-schemas.v1.json. unknown is NOT stale: it means the observation carried no expiry, so nobody can say. Never collapse the two.';


--
-- Name: get_cognition_cache(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.get_cognition_cache(p_cache_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select proposal from ops.cognition_result_cache
   where cache_key=p_cache_key and invalidated_at is null and expires_at>now()
$$;


--
-- Name: get_cognition_cache_for_job(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.get_cognition_cache_for_job(p_job_id uuid, p_lease_token uuid, p_cache_key text) RETURNS TABLE(cache_state text, proposal jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; c ops.cognition_result_cache%rowtype; observed_kind text; execution_kind text;
        declared_cognition_key text; active_contract_count integer; contract ops.cognition_job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select d.execution_kind,d.execution_contract->>'cognition_job' into execution_kind,declared_cognition_key from ops.job_definition d
   where d.key=j.definition_key and d.version=j.definition_version;
  if execution_kind is distinct from 'cognition' then
    raise exception 'job % is not a cognition workflow',p_job_id;
  end if;
  select count(*) into active_contract_count from ops.cognition_job
   where key=declared_cognition_key and active;
  if active_contract_count <> 1 then raise exception 'job % lacks one active cognition contract',p_job_id; end if;
  select * into contract from ops.cognition_job where key=declared_cognition_key and active;
  if btrim(coalesce(p_cache_key,''))='' then raise exception 'cache key is required'; end if;
  select * into c from ops.cognition_result_cache where cache_key=p_cache_key;
  observed_kind := case when c.cache_key is null then 'miss'
                        when c.cognition_key<>contract.key or c.cognition_version<>contract.version
                          or c.output_schema_version<>contract.output_schema_version then 'miss'
                        when c.invalidated_at is not null then 'invalidated'
                        when c.expires_at<=now() then 'expired' else 'hit' end;
  insert into ops.cognition_cache_observation
    (job_id,attempt,workflow_key,workflow_version,mode,cache_key,observation_kind)
  values (j.id,j.attempt,j.definition_key,j.definition_version,j.mode,p_cache_key,observed_kind)
  on conflict (job_id,attempt,cache_key,observation_kind) do nothing;
  return query select observed_kind,case when observed_kind='hit' then c.proposal else null end;
end $$;


--
-- Name: guidance_import_canonical_json(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_import_canonical_json(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_kind text := jsonb_typeof(p_value);
  v_result text;
begin
  if v_kind='object' then
    select '{' || coalesce(string_agg(
             to_jsonb(entry.key)::text || ':' || ops.guidance_import_canonical_json(entry.value),
             ',' order by entry.key collate "C"), '') || '}'
      into v_result
      from jsonb_each(p_value) as entry(key,value);
    return v_result;
  elsif v_kind='array' then
    select '[' || coalesce(string_agg(
             ops.guidance_import_canonical_json(entry.value), ',' order by entry.ordinality), '') || ']'
      into v_result
      from jsonb_array_elements(p_value) with ordinality as entry(value,ordinality);
    return v_result;
  elsif v_kind='string' then
    return to_jsonb(p_value #>> '{}')::text;
  end if;
  -- The compiler emits only integral structural numbers; jsonb's scalar
  -- representation is identical for that admitted subset.  Booleans and null
  -- are likewise already the portable JSON spellings.
  return p_value::text;
end $$;


--
-- Name: guidance_import_manifest_digest(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_import_manifest_digest(p_manifest_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select encode(digest(convert_to(p_manifest_text,'UTF8'),'sha256'),'hex')
$$;


--
-- Name: guidance_import_split_group_id(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_import_split_group_id(p_key text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  select (substr(md5('guidance-import-split:' || p_key),1,8) || '-' ||
          substr(md5('guidance-import-split:' || p_key),9,4) || '-' ||
          substr(md5('guidance-import-split:' || p_key),13,4) || '-' ||
          substr(md5('guidance-import-split:' || p_key),17,4) || '-' ||
          substr(md5('guidance-import-split:' || p_key),21,12))::uuid
$$;


--
-- Name: guidance_revision_contract_hash(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_revision_contract_hash(p_revision_id uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select encode(digest(jsonb_build_object(
    'guidance_revision_id',r.id,
    'guidance_item_id',r.guidance_item_id,
    'version',r.version,
    'guidance_type',r.guidance_type,
    'scope',r.scope,
    'activation',r.activation,
    'consumer',r.consumer,
    'verification',r.verification,
    'provenance',r.provenance,
    'delivery',r.delivery,
    'is_constitution',r.is_constitution,
    'supersedes_revision_id',r.supersedes_revision_id,
    'reason',r.reason
  )::text,'sha256'),'hex')
    from ops.guidance_revision r where r.id=p_revision_id
$$;


--
-- Name: heartbeat_job(uuid, uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heartbeat_job(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  update ops.job set leased_until=now()+make_interval(secs=>p_lease_seconds),updated_at=now()
   where id=p_job_id and state='running' and lease_token=p_lease_token
     and leased_until >= now();
  get diagnostics n=row_count;
  return n=1;
end $$;


--
-- Name: hermes_runtime_admission_for_brief(text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.hermes_runtime_admission_for_brief(p_runtime_slug text, p_profile_key text, p_sponsor_slug text, p_work_request text, p_binding_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare
  tenant text := current_setting('carr.organization_tenant_id', true);
  runtime_actor actor%rowtype;
  sponsor actor%rowtype;
  envelope_row ops.execution_envelope_v1%rowtype;
  expected_state_version integer;
  expected_plan_hash text;
  expected_runtime text := 'runtime:' || p_profile_key;
  expected_agent text := 'agent:' || p_profile_key;
  actual_envelope_digest text;
begin
  -- The caller cannot choose any of these values in the tool payload: the
  -- Worker passes the authenticated actor and sponsor, while the rest is the
  -- exact Bot-Brief request. Unknown actors and missing tenant context refuse
  -- without revealing another tenant's registration.
  if p_runtime_slug is distinct from 'hermes-pilot' then
    return jsonb_build_object('status','not_registered','authorized',false,'reason','runtime_identity_not_registered');
  end if;
  select * into runtime_actor from actor
   where slug='hermes-pilot' and kind='automation' and active;
  if runtime_actor.id is null or coalesce(tenant,'')='' or p_work_request is null or p_binding_id is null then
    return jsonb_build_object('status','not_registered','authorized',false,'reason','runtime_or_activation_missing');
  end if;
  select * into sponsor from actor where slug=p_sponsor_slug and kind='human' and active;
  if sponsor.id is null then
    return jsonb_build_object('status','stale','authorized',false,'reason','sponsoring_human_unavailable');
  end if;

  select e.* into envelope_row
    from ops.execution_envelope_v1 e
    join ops.context_activation_binding b on b.id=e.activation_binding_id
    join ops.work_request w on w.id=b.work_request_id
    join ops.sourced_work_request_plan plan on plan.id=b.plan_id
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.plan_id=plan.id
    join ops.work_request_execution_assignment a on a.work_request_id=w.id
      and a.sponsoring_human_id=sponsor.id
    join agent_profile p on p.id=a.profile_id
   where e.organization_tenant_id=tenant and b.organization_tenant_id=tenant
     and w.organization_tenant_id=tenant and w.ref=p_work_request
     and b.binding_id=p_binding_id and e.activation_binding_id=b.id
     and b.expires_at > now() and e.expires_at > now()
     and w.version=b.work_request_version and plan.work_request_id=w.id
     and plan.plan_hash=b.plan_hash and ar.plan_hash=b.plan_hash
     and ar.result_version=w.version and p.profile_key=p_profile_key
     and e.work_request_id=w.id and e.plan_hash=b.plan_hash
     and p.status='active' and p.current_model is not null and p.current_desk is not null;
  if not found then
    return jsonb_build_object('status','stale','authorized',false,'reason','activation_or_envelope_not_exact');
  end if;

  select b.work_request_version, b.plan_hash
    into expected_state_version, expected_plan_hash
    from ops.context_activation_binding b
   where b.id=envelope_row.activation_binding_id;

  actual_envelope_digest := 'sha256:' || encode(
    public.digest(ops.guidance_import_canonical_json(envelope_row.envelope),'sha256'),'hex');

  if envelope_row.envelope->'server_binding'->'identity'->>'runtime_principal' is distinct from expected_runtime
     or envelope_row.envelope->'server_binding'->'identity'->>'agent_principal_id' is distinct from expected_agent
     or envelope_row.envelope->'server_binding'->'identity'->>'sponsoring_human_id' is distinct from ('human:' || p_sponsor_slug)
     or envelope_row.envelope->'server_binding'->'identity'->>'organization_tenant_id' is distinct from tenant
     or envelope_row.envelope->'server_binding'->'identity'->>'client_mutable' is distinct from 'false'
     or envelope_row.envelope->'server_binding'->'authority'->>'read_only' is distinct from 'true'
     or envelope_row.envelope->'server_binding'->'authority'->>'client_mutable' is distinct from 'false'
     or envelope_row.envelope->'server_binding'->'authority'->>'capability_profile' is distinct from 'capability:metadata-only'
     or envelope_row.envelope->'server_binding'->'adapter'->>'surface' is distinct from 'hermes_desktop'
     or envelope_row.envelope->'server_binding'->'adapter'->>'adapter_id' is distinct from 'adapter:hermes-desktop'
     or envelope_row.envelope->'server_binding'->'adapter'->>'adapter_version' is distinct from 'v1'
     or envelope_row.envelope->'server_binding'->'adapter'->>'native_session_ref' is distinct from ('native:profile-' || p_profile_key)
     or envelope_row.envelope->'server_binding'->'adapter'->>'configuration_fingerprint' is distinct from envelope_row.configuration_digest
     or envelope_row.runtime_profile->>'profile_key' is distinct from p_profile_key
     or envelope_row.runtime_profile->>'profile_version' is distinct from (
       select p.version::text from agent_profile p where p.profile_key=p_profile_key)
     or envelope_row.runtime_profile->>'model_id' is distinct from (
       select 'model:' || p.current_model from agent_profile p where p.profile_key=p_profile_key)
     or envelope_row.runtime_profile->>'desk' is distinct from (
       select p.current_desk from agent_profile p where p.profile_key=p_profile_key)
     or envelope_row.envelope->'server_binding'->'adapter'->>'provider_id' is distinct from envelope_row.runtime_profile->>'provider_id'
     or envelope_row.envelope->'server_binding'->'adapter'->>'model_id' is distinct from envelope_row.runtime_profile->>'model_id'
     or envelope_row.envelope->'state_binding'->>'state_version' is distinct from expected_state_version::text
     or envelope_row.envelope->'state_binding'->>'canonical_record_digest' is distinct from expected_plan_hash
     or envelope_row.envelope->>'work_request_id' is distinct from p_work_request
     or envelope_row.envelope->>'context_activation_ref' is distinct from p_binding_id
     or envelope_row.envelope_digest is distinct from actual_envelope_digest then
    return jsonb_build_object('status','stale','authorized',false,'reason','server_envelope_identity_mismatch');
  end if;

  return jsonb_build_object(
    'status','registered','authorized',true,'reason','exact_server_envelope',
    'registration_scope','execution_envelope','grants_authority',false,
    'runtime_registration_id','envelope:' || envelope_row.id::text,
    'runtime_principal',envelope_row.envelope->'server_binding'->'identity'->>'runtime_principal',
    'agent_principal_id',envelope_row.envelope->'server_binding'->'identity'->>'agent_principal_id',
    'organization_tenant_id',tenant,'sponsoring_human_slug',p_sponsor_slug,
    'work_request',p_work_request,
    'profile_version',(envelope_row.runtime_profile->>'profile_version')::integer,
    'native_session_ref',envelope_row.envelope->'server_binding'->'adapter'->>'native_session_ref',
    'surface',envelope_row.envelope->'server_binding'->'adapter'->>'surface',
    'adapter_id',envelope_row.envelope->'server_binding'->'adapter'->>'adapter_id',
    'adapter_version',envelope_row.envelope->'server_binding'->'adapter'->>'adapter_version',
    'provider_id',envelope_row.envelope->'server_binding'->'adapter'->>'provider_id',
    'model_id',envelope_row.envelope->'server_binding'->'adapter'->>'model_id',
    'configuration_fingerprint',envelope_row.envelope->'server_binding'->'adapter'->>'configuration_fingerprint',
    'capability_profile',envelope_row.envelope->'server_binding'->'authority'->>'capability_profile',
    'read_only',true,'envelope_digest',envelope_row.envelope_digest,
    'activation_binding_id',p_binding_id,'expires_at',envelope_row.expires_at,
    'device_binding_status','not_asserted',
    'operator_surface','job-passport:context-activation',
    'telemetry_ref','observatory:activation-reliability:' || p_binding_id
  );
end $$;


--
-- Name: calendar_prebrief_canary_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_canary_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    sponsor text NOT NULL,
    destination text NOT NULL,
    snapshot_at timestamp with time zone NOT NULL,
    allowlist_revision_id uuid NOT NULL,
    source_attestation_id uuid NOT NULL,
    canonical_event_digest text CONSTRAINT calendar_prebrief_canary_receip_canonical_event_digest_not_null NOT NULL,
    event_count integer NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT calendar_prebrief_canary_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT calendar_prebrief_canary_receipt_canonical_event_digest_check CHECK ((canonical_event_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_canary_receipt_destination_check CHECK ((destination = ANY (ARRAY['calendar-prebrief-canary-joe'::text, 'calendar-prebrief-canary-dell'::text]))),
    CONSTRAINT calendar_prebrief_canary_receipt_event_count_check CHECK ((event_count >= 0)),
    CONSTRAINT calendar_prebrief_canary_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: ingest_calendar_prebrief_canary_projection(uuid, uuid, text, text[], jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_calendar_prebrief_canary_projection(p_job_id uuid, p_lease uuid, p_destination text, p_observed_calendar_keys text[], p_events jsonb) RETURNS ops.calendar_prebrief_canary_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_job ops.job%rowtype; v_sponsor text; v_session_sponsor text; v_destination text;
  v_observed text[]; v_event_count integer; v_event_digest text; v_source ops.calendar_prebrief_source_attestation_receipt%rowtype;
  v_receipt ops.calendar_prebrief_canary_receipt%rowtype; v_event jsonb;
  v_current_revision uuid; v_current_digest text;
begin
  case session_user
    when 'carr_calendar_prebrief_canary_joe' then v_session_sponsor := 'joe';
    when 'carr_calendar_prebrief_canary_dell' then v_session_sponsor := 'dell';
    else raise exception using errcode='42501',message='calendar prebrief canary requires its named externally provisioned execution identity';
  end case;
  if not pg_has_role(session_user,'carr_calendar_prebrief_canary_jobs','member') then
    raise exception using errcode='42501',message='calendar prebrief canary execution identity lacks its capability bundle';
  end if;
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief canary requires current live job lease';
  end if;
  select owner_actor into v_sponsor from ops.job_definition
    where key=v_job.definition_key and version=v_job.definition_version for update;
  v_destination:=case v_job.definition_key
    when 'calendar-prebrief-canary-joe-daily' then 'calendar-prebrief-canary-joe'
    when 'calendar-prebrief-canary-dell-daily' then 'calendar-prebrief-canary-dell'
  end;
  if not found or v_job.mode<>'canary' or v_sponsor<>v_session_sponsor or p_destination is distinct from v_destination
     or (v_job.definition_key='calendar-prebrief-canary-joe-daily' and v_sponsor<>'joe')
     or (v_job.definition_key='calendar-prebrief-canary-dell-daily' and v_sponsor<>'dell')
     or v_job.definition_key not in ('calendar-prebrief-canary-joe-daily','calendar-prebrief-canary-dell-daily') then
    raise exception using errcode='42501',message='calendar prebrief canary mode or destination does not match the static job owner';
  end if;
  select array_agg(k order by k) into v_observed from unnest(coalesce(p_observed_calendar_keys,'{}'::text[])) keys(k);
  select event_count,canonical_event_digest into v_event_count,v_event_digest
    from ops.calendar_prebrief_canonical_event_digest(p_events);
  select * into v_source from ops.calendar_prebrief_source_attestation_receipt
   where job_id=v_job.id and attempt=v_job.attempt;
  if not found then
    raise exception using errcode='55000',message='calendar prebrief canary requires an exact immutable verified source envelope';
  end if;
  select active_revision_id,configuration_digest into v_current_revision,v_current_digest
    from ops.calendar_prebrief_allowed_calendar where sponsor=v_sponsor for update;
  if v_current_revision is null or v_current_digest is null or v_source.lease_token<>p_lease or v_source.sponsor<>v_sponsor or v_source.mode<>'canary'
     or v_source.destination<>v_destination or v_source.snapshot_at<>v_job.scheduled_for
     or v_source.allowlist_revision_id<>v_current_revision or v_source.allowlist_digest<>v_current_digest
     or v_source.observed_calendar_keys is distinct from v_observed or v_source.event_count<>v_event_count
     or v_source.canonical_event_digest<>v_event_digest then
    raise exception using errcode='55000',message='calendar prebrief canary requires an exact immutable verified source envelope';
  end if;
  select * into v_receipt from ops.calendar_prebrief_canary_receipt where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_receipt.source_attestation_id<>v_source.id or v_receipt.destination<>v_destination
       or v_receipt.canonical_event_digest<>v_event_digest then
      raise exception using errcode='23505',message='calendar prebrief canary replay conflicts with immutable attempt';
    end if;
    return v_receipt;
  end if;
  if exists(select 1 from ops.calendar_prebrief_canary_receipt where sponsor=v_sponsor and destination=v_destination and snapshot_at>v_job.scheduled_for) then
    raise exception using errcode='22023',message='calendar prebrief canary refuses stale snapshot';
  end if;
  if not exists(select 1 from ops.job where id=v_job.id and state='running' and lease_token=p_lease and leased_until>=now()) then
    raise exception using errcode='55000',message='calendar prebrief canary lease expired before isolated replacement';
  end if;
  if exists(select 1 from jsonb_array_elements(p_events) e(value)
      where coalesce(e.value->>'occurrence_key','') !~ '^[0-9a-f]{64}$')
     or v_event_count<>(select count(distinct e.value->>'occurrence_key') from jsonb_array_elements(p_events) e(value)) then
    raise exception using errcode='22023',message='calendar prebrief canary requires distinct opaque occurrence keys';
  end if;
  delete from ops.calendar_prebrief_canary_event where sponsor=v_sponsor and destination=v_destination;
  for v_event in select value from jsonb_array_elements(p_events) loop
    insert into ops.calendar_prebrief_canary_event(sponsor,destination,occurrence_key,snapshot_at,allowlist_revision_id,source_attestation_id)
    values(v_sponsor,v_destination,v_event->>'occurrence_key',v_job.scheduled_for,v_source.allowlist_revision_id,v_source.id);
  end loop;
  insert into ops.calendar_prebrief_canary_receipt(job_id,attempt,sponsor,destination,snapshot_at,allowlist_revision_id,source_attestation_id,canonical_event_digest,event_count)
  values(v_job.id,v_job.attempt,v_sponsor,v_destination,v_job.scheduled_for,v_source.allowlist_revision_id,v_source.id,v_event_digest,v_event_count)
  returning * into v_receipt;
  return v_receipt;
end $_$;


--
-- Name: calendar_prebrief_projection_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_projection_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    sponsor text NOT NULL,
    snapshot_at timestamp with time zone NOT NULL,
    allowlist_revision_id uuid CONSTRAINT calendar_prebrief_projection_rec_allowlist_revision_id_not_null NOT NULL,
    allowlist_digest text NOT NULL,
    snapshot_digest text NOT NULL,
    event_count integer NOT NULL,
    participant_count integer NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    source_attestation_id uuid CONSTRAINT calendar_prebrief_projection_rec_source_attestation_id_not_null NOT NULL,
    CONSTRAINT calendar_prebrief_projection_receipt_allowlist_digest_check CHECK ((allowlist_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_projection_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT calendar_prebrief_projection_receipt_event_count_check CHECK ((event_count >= 0)),
    CONSTRAINT calendar_prebrief_projection_receipt_participant_count_check CHECK ((participant_count >= 0)),
    CONSTRAINT calendar_prebrief_projection_receipt_snapshot_digest_check CHECK ((snapshot_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_projection_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: ingest_calendar_prebrief_projection(uuid, uuid, text[], jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_calendar_prebrief_projection(p_job_id uuid, p_lease uuid, p_observed_calendar_keys text[], p_events jsonb) RETURNS ops.calendar_prebrief_projection_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_job ops.job%rowtype;
  v_sponsor text;
  v_session_sponsor text;
  v_execution_kind text;
  v_allowed text[];
  v_allowlist_digest text;
  v_allowlist_revision_id uuid;
  v_observed text[];
  v_event jsonb;
  v_event_id uuid;
  v_calendar_key text;
  v_event_key text;
  v_occurrence_key text;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_title text;
  v_location text;
  v_participant_ref text;
  v_party_id uuid;
  v_subject_type text;
  v_subject_id uuid;
  v_match_count integer;
  v_event_participant_count integer;
  v_event_count integer := 0;
  v_participant_count integer := 0;
  v_canonical_events jsonb;
  v_event_digest text;
  v_snapshot_digest text;
  v_receipt ops.calendar_prebrief_projection_receipt%rowtype;
  v_source ops.calendar_prebrief_source_attestation_receipt%rowtype;
begin
  case session_user
    when 'carr_calendar_prebrief_joe' then v_session_sponsor := 'joe';
    when 'carr_calendar_prebrief_dell' then v_session_sponsor := 'dell';
    else raise exception using errcode='42501',message='calendar prebrief projection requires its named externally provisioned execution identity';
  end case;
  if not pg_has_role(session_user,'carr_calendar_prebrief_jobs','member') then
    raise exception using errcode='42501',message='calendar prebrief projection execution identity lacks its capability bundle';
  end if;
  if p_events is null or pg_column_size(p_events)>262144 or jsonb_typeof(p_events)<>'array' then
    raise exception using errcode='22023',message='calendar prebrief projection requires a bounded event array';
  end if;
  if jsonb_array_length(p_events)>128 then
    raise exception using errcode='22023',message='calendar prebrief projection event count exceeds its bound';
  end if;

  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief projection requires current live job lease';
  end if;
  if v_job.scheduled_for < now()-interval '30 minutes' or v_job.scheduled_for > now()+interval '5 minutes' then
    raise exception using errcode='22023',message='calendar prebrief projection refuses job scheduled outside its DB-clock window';
  end if;
  select owner_actor,execution_kind into v_sponsor,v_execution_kind
    from ops.job_definition where key=v_job.definition_key and version=v_job.definition_version for update;
  if not found or v_job.definition_key not in ('calendar-prebrief-projection-joe-daily','calendar-prebrief-projection-dell-daily')
     or v_job.definition_version<>1 or v_job.mode<>'live' or v_execution_kind<>'deterministic'
     or (v_job.definition_key='calendar-prebrief-projection-joe-daily' and v_sponsor<>'joe')
     or (v_job.definition_key='calendar-prebrief-projection-dell-daily' and v_sponsor<>'dell')
     or v_sponsor<>v_session_sponsor then
    raise exception using errcode='42501',message='calendar prebrief projection execution identity does not match the static job owner';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('calendar-prebrief-projection:' || v_sponsor,0));
  select calendar_keys,configuration_digest,active_revision_id into v_allowed,v_allowlist_digest,v_allowlist_revision_id from ops.calendar_prebrief_allowed_calendar
   where sponsor=v_sponsor for update;
  if not found or coalesce(cardinality(v_allowed),0)=0
     or array_position(v_allowed,null) is not null
     or v_allowlist_digest !~ '^[0-9a-f]{64}$' or v_allowlist_revision_id is null
     or exists(select 1 from unnest(v_allowed) keys(k) where k !~ '^[0-9a-f]{64}$')
     or cardinality(v_allowed)<>(select count(distinct k) from unnest(v_allowed) keys(k))
     or not exists(select 1 from ops.calendar_prebrief_allowlist_receipt ar
                   where ar.id=v_allowlist_revision_id and ar.sponsor=v_sponsor
                     and ar.configuration_digest=v_allowlist_digest and ar.calendar_keys=v_allowed) then
    raise exception using errcode='22023',message='calendar prebrief projection requires a valid DB-owned sponsor allowlist';
  end if;
  select array_agg(k order by k) into v_observed from unnest(coalesce(p_observed_calendar_keys,'{}'::text[])) keys(k);
  if coalesce(cardinality(v_observed),0)=0 or array_position(v_observed,null) is not null
     or exists(select 1 from unnest(v_observed) keys(k) where k !~ '^[0-9a-f]{64}$')
     or cardinality(v_observed)<>(select count(distinct k) from unnest(v_observed) keys(k))
     or v_observed is distinct from v_allowed then
    raise exception using errcode='22023',message='calendar prebrief observed calendars must have exact DB allowlist coverage';
  end if;

  -- Prevalidate every event and every participant before deleting a current
  -- projection.  A bad event cannot partially replace a good one.
  for v_event in select value from jsonb_array_elements(p_events) loop
    if pg_column_size(v_event)>4096 or jsonb_typeof(v_event)<>'object'
       or exists(select 1 from jsonb_object_keys(v_event) keys(key)
                 where key not in ('calendar_key','event_key','occurrence_key','starts_at','ends_at','title','location','participant_refs'))
       or exists(select key from unnest(array['calendar_key','event_key','occurrence_key','starts_at','ends_at','title','location','participant_refs']) required(key)
                 except select key from jsonb_object_keys(v_event) actual(key)) then
      raise exception using errcode='22023',message='calendar prebrief event has fields outside its bounded contract';
    end if;
    if jsonb_typeof(v_event->'calendar_key')<>'string' or jsonb_typeof(v_event->'event_key')<>'string'
       or jsonb_typeof(v_event->'occurrence_key')<>'string' or jsonb_typeof(v_event->'starts_at')<>'string'
       or jsonb_typeof(v_event->'ends_at')<>'string' or jsonb_typeof(v_event->'title')<>'string'
       or jsonb_typeof(v_event->'participant_refs')<>'array'
       or (v_event->'location' is not null and jsonb_typeof(v_event->'location') not in ('string','null')) then
      raise exception using errcode='22023',message='calendar prebrief event has invalid bounded fields';
    end if;
    v_event_participant_count:=jsonb_array_length(v_event->'participant_refs');
    if v_event_participant_count>16 or exists(select 1 from jsonb_array_elements(v_event->'participant_refs') refs(value) where jsonb_typeof(refs.value)<>'string')
       or v_event_participant_count<>(select count(distinct value#>>'{}') from jsonb_array_elements(v_event->'participant_refs') refs(value)) then
      raise exception using errcode='22023',message='calendar prebrief event has invalid or duplicate participant refs';
    end if;
    v_participant_count:=v_participant_count+v_event_participant_count;
    if v_participant_count>256 then
      raise exception using errcode='22023',message='calendar prebrief projection participant count exceeds its bound';
    end if;
    v_calendar_key:=v_event->>'calendar_key'; v_event_key:=v_event->>'event_key';
    v_occurrence_key:=v_event->>'occurrence_key'; v_title:=v_event->>'title'; v_location:=v_event->>'location';
    if v_calendar_key!~'^[0-9a-f]{64}$' or v_event_key!~'^[0-9a-f]{64}$' or v_occurrence_key!~'^[0-9a-f]{64}$'
       or length(v_title)>240 or coalesce(length(v_location),0)>240 or btrim(v_title)=''
       or v_title~'[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
       or coalesce(v_location,'')~'[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
       or v_title~*'(^|[^[:alnum:]])[a-z][a-z0-9+.-]*:[^[:space:]]' or coalesce(v_location,'')~*'(^|[^[:alnum:]])[a-z][a-z0-9+.-]*:[^[:space:]]'
       or v_title~*'www\.' or coalesce(v_location,'')~*'www\.'
       or v_title~*'\m(join|meeting|conference)[[:space:]]*(id|code|link)?[[:space:]]*[:#=]?[[:space:]]*[a-z0-9_-]{6,}\M'
       or coalesce(v_location,'')~*'\m(join|meeting|conference)[[:space:]]*(id|code|link)?[[:space:]]*[:#=]?[[:space:]]*[a-z0-9_-]{6,}\M' then
      raise exception using errcode='22023',message='calendar prebrief bounded fields must not contain email, URI, www, or join locator';
    end if;
    v_starts_at:=(v_event->>'starts_at')::timestamptz; v_ends_at:=(v_event->>'ends_at')::timestamptz;
    if v_ends_at<=v_starts_at or v_starts_at<v_job.scheduled_for-interval '7 days'
       or v_starts_at>v_job.scheduled_for+interval '45 days' or v_ends_at<v_job.scheduled_for-interval '7 days'
       or v_ends_at>v_job.scheduled_for+interval '45 days' then
      raise exception using errcode='22023',message='calendar prebrief event is outside its bounded snapshot window';
    end if;
    if not (v_calendar_key=any(v_allowed)) then
      raise exception using errcode='22023',message='calendar prebrief event calendar is outside the DB allowlist';
    end if;
    for v_participant_ref in select value from jsonb_array_elements_text(v_event->'participant_refs') loop
      if length(v_participant_ref)>128 or v_participant_ref!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' then
        raise exception using errcode='22023',message='calendar prebrief participant ref must be a bounded canonical ref';
      end if;
      select count(*) into v_match_count from v_ref_index r where r.ref=v_participant_ref and not r.merged and r.party_id is not null;
      if v_match_count<>1 then
        raise exception using errcode='22023',message='calendar prebrief participant ref does not resolve uniquely to one live unmerged party';
      end if;
    end loop;
  end loop;
  if (select count(*) from jsonb_array_elements(p_events) element(value))
     <> (select count(distinct value->>'occurrence_key') from jsonb_array_elements(p_events) element(value)) then
    raise exception using errcode='22023',message='calendar prebrief snapshot has duplicate occurrence keys';
  end if;

  select coalesce(jsonb_agg(event order by event->>'occurrence_key'),'[]'::jsonb) into v_canonical_events
  from (select jsonb_set(element.value,'{participant_refs}',coalesce((select jsonb_agg(ref order by ref)
          from jsonb_array_elements_text(element.value->'participant_refs') refs(ref)),'[]'::jsonb)) event
        from jsonb_array_elements(p_events) element(value)) normalized;
  v_event_digest:=encode(digest(convert_to(v_canonical_events::text,'UTF8'),'sha256'),'hex');
  v_snapshot_digest:=encode(digest(convert_to(jsonb_build_object(
    'allowlist_revision_id',v_allowlist_revision_id,'allowlist_digest',v_allowlist_digest,'observed_calendar_keys',to_jsonb(v_observed),
    'events',v_canonical_events,'snapshot_at',v_job.scheduled_for)::text,'UTF8'),'sha256'),'hex');
  select * into v_source from ops.calendar_prebrief_source_attestation_receipt
   where job_id=v_job.id and attempt=v_job.attempt;
  if not found or v_source.lease_token<>p_lease or v_source.sponsor<>v_sponsor
     or v_source.mode<>'live' or v_source.destination<>'live'
     or v_source.snapshot_at<>v_job.scheduled_for or v_source.allowlist_revision_id<>v_allowlist_revision_id
     or v_source.allowlist_digest<>v_allowlist_digest or v_source.observed_calendar_keys is distinct from v_observed
     or v_source.event_count<>jsonb_array_length(p_events) or v_source.canonical_event_digest<>v_event_digest then
    raise exception using errcode='55000',message='calendar prebrief projection requires an exact immutable verified source envelope';
  end if;
  select * into v_receipt from ops.calendar_prebrief_projection_receipt where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_receipt.snapshot_digest<>v_snapshot_digest then raise exception using errcode='23505',message='calendar prebrief job attempt conflicts with immutable snapshot'; end if;
    return v_receipt;
  end if;
  select * into v_receipt from ops.calendar_prebrief_projection_receipt where sponsor=v_sponsor and snapshot_at=v_job.scheduled_for;
  if found then
    if v_receipt.snapshot_digest<>v_snapshot_digest then raise exception using errcode='23505',message='calendar prebrief equal snapshot timestamp conflicts with immutable digest'; end if;
    return v_receipt;
  end if;
  if exists(select 1 from ops.calendar_prebrief_projection_receipt where sponsor=v_sponsor and snapshot_at>v_job.scheduled_for) then
    raise exception using errcode='22023',message='calendar prebrief projection refuses stale snapshot';
  end if;

  -- The second check is deliberately adjacent to the destructive replacement.
  if not exists(select 1 from ops.job where id=v_job.id and state='running' and lease_token=p_lease
                and leased_until is not null and leased_until>=now()) then
    raise exception using errcode='55000',message='calendar prebrief projection lease expired before current projection replacement';
  end if;
  delete from ops.calendar_prebrief_projection_event where sponsor=v_sponsor;
  v_participant_count:=0;
  for v_event in select value from jsonb_array_elements(p_events) loop
    insert into ops.calendar_prebrief_projection_event
      (sponsor,calendar_key,event_key,occurrence_key,starts_at,ends_at,title,location,snapshot_at,allowlist_revision_id)
    values(v_sponsor,v_event->>'calendar_key',v_event->>'event_key',v_event->>'occurrence_key',
      (v_event->>'starts_at')::timestamptz,(v_event->>'ends_at')::timestamptz,v_event->>'title',v_event->>'location',v_job.scheduled_for,v_allowlist_revision_id)
    returning id into v_event_id;
    v_event_count:=v_event_count+1;
    for v_participant_ref in select value from jsonb_array_elements_text(v_event->'participant_refs') loop
      select r.party_id,r.subject_type,r.subject_id into v_party_id,v_subject_type,v_subject_id from v_ref_index r
       where r.ref=v_participant_ref and not r.merged and r.party_id is not null;
      insert into ops.calendar_prebrief_projection_participant(event_id,party_id,subject_type,subject_id,participant_ref)
      values(v_event_id,v_party_id,v_subject_type,v_subject_id,v_participant_ref);
      v_participant_count:=v_participant_count+1;
    end loop;
  end loop;
  insert into ops.calendar_prebrief_projection_receipt(job_id,attempt,sponsor,snapshot_at,allowlist_revision_id,allowlist_digest,source_attestation_id,snapshot_digest,event_count,participant_count)
  values(v_job.id,v_job.attempt,v_sponsor,v_job.scheduled_for,v_allowlist_revision_id,v_allowlist_digest,v_source.id,v_snapshot_digest,v_event_count,v_participant_count)
  returning * into v_receipt;
  return v_receipt;
end $_$;


--
-- Name: ingest_renewal_signed_snapshot(uuid, uuid, uuid, text, text, timestamp with time zone, text, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_renewal_signed_snapshot(p_job_id uuid, p_lease uuid, p_snapshot_id uuid, p_provider text, p_key_fingerprint text, p_source_observed_at timestamp with time zone, p_payload_sha256 text, p_signature_sha256 text, p_rows jsonb) RETURNS TABLE(source_run_id uuid, row_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare v_job ops.job%rowtype; v_snapshot ops.renewal_source_snapshot%rowtype; v_row jsonb; v_candidate_id uuid; v_run ops.renewal_decision_source_run%rowtype; v_count integer; v_seq integer:=0; v_key text;
begin
 if session_user<>'carr_renewal_source_attestor' or not pg_has_role(session_user,'carr_renewal_source_attestors','member') then raise exception using errcode='42501',message='renewal signed ingress requires the exact renewal source attestor capability'; end if;
 if p_provider is null or btrim(p_provider)='' or octet_length(p_provider)>256 or p_key_fingerprint !~ '^[0-9a-f]{64}$' or p_payload_sha256 !~ '^[0-9a-f]{64}$' or p_signature_sha256 !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='renewal signed ingress provenance is malformed'; end if;
 if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>10000 or octet_length(p_rows::text)>8388608 then raise exception using errcode='22023',message='renewal signed ingress source rows are not bounded'; end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x(value) where jsonb_typeof(value)<>'object'
           or (select array_agg(key order by key) from jsonb_object_keys(value) key) is distinct from array['address','city','county','email','est_basis','est_lease_event','name','org_name','phone','segment','source_key','source_row','state','vertical']
           or nullif(btrim(value->>'source_key'),'') is null or nullif(btrim(value->>'name'),'') is null or octet_length(value->>'source_key')>512 or octet_length(value->>'name')>512 or octet_length((value->'source_row')::text)>65536 or octet_length(value::text)>131072 or jsonb_typeof(value->'source_row')<>'object') then
   raise exception using errcode='22023',message='renewal signed ingress source row shape is malformed'; end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x(value) group by value->>'source_key' having count(*)<>1) then raise exception using errcode='23505',message='renewal signed ingress source key is duplicated'; end if;
 select * into v_job from ops.job where id=p_job_id for update;
 if not found or v_job.definition_key<>'renewal-radar-source-daily' or v_job.definition_version<>1 or v_job.mode<>'live' or v_job.state<>'running' or v_job.lease_token is distinct from p_lease or v_job.leased_until is null or v_job.leased_until<now() then raise exception using errcode='55000',message='renewal signed ingress requires its exact current live job lease'; end if;
 if p_source_observed_at < now()-interval '36 hours' or p_source_observed_at > now()+interval '5 minutes' then raise exception using errcode='22023',message='renewal signed ingress source observation is outside its DB-clock window'; end if;
 insert into ops.renewal_source_snapshot(id,job_id,attempt,provider,key_fingerprint,source_observed_at,payload_sha256,signature_sha256,row_count)
 values(p_snapshot_id,v_job.id,v_job.attempt,p_provider,p_key_fingerprint,p_source_observed_at,p_payload_sha256,p_signature_sha256,jsonb_array_length(p_rows)) on conflict(id) do nothing;
 select * into v_snapshot from ops.renewal_source_snapshot where id=p_snapshot_id for update;
 if not found or v_snapshot.job_id<>v_job.id or v_snapshot.attempt<>v_job.attempt or v_snapshot.provider<>p_provider or v_snapshot.key_fingerprint<>p_key_fingerprint or v_snapshot.source_observed_at<>p_source_observed_at or v_snapshot.payload_sha256<>p_payload_sha256 or v_snapshot.signature_sha256<>p_signature_sha256 or v_snapshot.row_count<>jsonb_array_length(p_rows) then raise exception using errcode='23505',message='renewal signed ingress snapshot identity conflicts with immutable receipt'; end if;
 select count(*) into v_count from ops.renewal_source_snapshot_member where snapshot_id=p_snapshot_id;
 if v_count>0 then
   if v_count<>jsonb_array_length(p_rows) or exists((select value->>'source_key' from jsonb_array_elements(p_rows) x(value)) except (select source_key from ops.renewal_source_snapshot_member where snapshot_id=p_snapshot_id)) or exists((select source_key from ops.renewal_source_snapshot_member where snapshot_id=p_snapshot_id) except (select value->>'source_key' from jsonb_array_elements(p_rows) x(value))) then raise exception using errcode='23505',message='renewal signed ingress replay conflicts with immutable source membership'; end if;
 else
   for v_row in select value from jsonb_array_elements(p_rows) x(value) loop
     v_seq:=v_seq+1; v_key:=btrim(v_row->>'source_key');
     insert into ingest_inbox(source,external_id,payload,status,triage_note) values('renewal-radar-signed',p_snapshot_id::text||':'||v_key,jsonb_build_object('provider',p_provider,'snapshot_id',p_snapshot_id,'observed_at',p_source_observed_at,'row',v_row),'new','signed renewal source ingress; payload is untrusted source data') on conflict(source,external_id) do nothing;
     insert into candidate_pool(source,source_key,source_seq,source_row,name,org_name,vertical,address,city,county,state,email,phone,segment,score,score_basis,est_lease_event,est_basis,status,created_by,updated_by)
       select 'renewal-radar',v_key,v_seq,v_row->'source_row',btrim(v_row->>'name'),nullif(btrim(v_row->>'org_name'),''),nullif(btrim(v_row->>'vertical'),''),nullif(btrim(v_row->>'address'),''),nullif(btrim(v_row->>'city'),''),nullif(btrim(v_row->>'county'),''),nullif(btrim(v_row->>'state'),''),nullif(btrim(v_row->>'email'),''),nullif(btrim(v_row->>'phone'),''),nullif(btrim(v_row->>'segment'),''),null,'unscored signed renewal source snapshot',nullif(v_row->>'est_lease_event','')::date,nullif(btrim(v_row->>'est_basis'),''),'pool',a.id,a.id from actor a where a.slug='system'
       on conflict(source,source_key) do update set source_seq=excluded.source_seq,source_row=excluded.source_row,name=excluded.name,org_name=excluded.org_name,vertical=excluded.vertical,address=excluded.address,city=excluded.city,county=excluded.county,state=excluded.state,email=excluded.email,phone=excluded.phone,segment=excluded.segment,score=null,score_basis='unscored signed renewal source snapshot',est_lease_event=excluded.est_lease_event,est_basis=excluded.est_basis,updated_by=excluded.updated_by where candidate_pool.status='pool' returning id into v_candidate_id;
     if v_candidate_id is null then raise exception using errcode='23505',message='renewal signed ingress source key conflicts with a non-pool candidate'; end if;
     insert into ops.renewal_source_snapshot_member(snapshot_id,source_key,candidate_id) values(p_snapshot_id,v_key,v_candidate_id);
     update ingest_inbox set status='filed',filed_refs=jsonb_build_object('candidate_pool',v_candidate_id::text) where source='renewal-radar-signed' and external_id=p_snapshot_id::text||':'||v_key and status='new';
   end loop;
 end if;
 select * into v_run from ops.seal_renewal_decision_source_run(p_job_id,p_lease,p_snapshot_id);
 source_run_id:=v_run.id; row_count:=v_snapshot.row_count; return next;
end $_$;


--
-- Name: invalidate_cognition_cache(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.invalidate_cognition_cache(p_dependency_ref text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  update ops.cognition_result_cache set invalidated_at=now()
   where invalidated_at is null and p_dependency_ref=any(dependency_refs);
  get diagnostics n=row_count;
  return n;
end $$;


--
-- Name: invalidate_cognition_cache_for_job(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.invalidate_cognition_cache_for_job(p_job_id uuid, p_lease_token uuid, p_dependency_ref text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; n integer; execution_kind text;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select d.execution_kind into execution_kind from ops.job_definition d
   where d.key=j.definition_key and d.version=j.definition_version;
  if execution_kind is distinct from 'cognition' then
    raise exception 'job % is not a cognition workflow',p_job_id;
  end if;
  if btrim(coalesce(p_dependency_ref,''))='' then raise exception 'dependency ref is required'; end if;
  with changed as (
    update ops.cognition_result_cache set invalidated_at=now()
     where invalidated_at is null and p_dependency_ref=any(dependency_refs)
     returning cache_key
  ), evidence as (
    insert into ops.cognition_cache_observation
      (job_id,attempt,workflow_key,workflow_version,mode,cache_key,observation_kind,dependency_ref)
    select j.id,j.attempt,j.definition_key,j.definition_version,j.mode,cache_key,'invalidate',p_dependency_ref
      from changed
    on conflict (job_id,attempt,cache_key,observation_kind) do nothing
    returning 1
  ) select count(*) into n from evidence;
  return n;
end $$;


--
-- Name: issue_calendar_prebrief_capture_contract(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.issue_calendar_prebrief_capture_contract(p_job_id uuid, p_lease uuid) RETURNS TABLE(challenge_id uuid, sponsor text, job_id uuid, attempt integer, lease_token uuid, scheduled_for timestamp with time zone, window_starts_at timestamp with time zone, window_ends_at timestamp with time zone, mode text, destination text, allowlist_revision_id uuid, allowlist_digest text, calendar_keys text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v_job ops.job%rowtype; v_sponsor text; v_resolver_sponsor text; v_destination text;
  v_keys text[]; v_digest text; v_revision uuid; v_challenge ops.calendar_prebrief_capture_challenge%rowtype;
begin
  v_resolver_sponsor:=ops.calendar_prebrief_resolver_sponsor();
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief capture contract requires current live job lease';
  end if;
  if v_job.scheduled_for < now()-interval '30 minutes' or v_job.scheduled_for > now()+interval '5 minutes' then
    raise exception using errcode='22023',message='calendar prebrief capture contract refuses job scheduled outside its DB-clock window';
  end if;
  select owner_actor into v_sponsor from ops.job_definition where key=v_job.definition_key and version=v_job.definition_version for update;
  v_destination:=case v_job.definition_key
    when 'calendar-prebrief-projection-joe-daily' then 'live'
    when 'calendar-prebrief-projection-dell-daily' then 'live'
    when 'calendar-prebrief-canary-joe-daily' then 'calendar-prebrief-canary-joe'
    when 'calendar-prebrief-canary-dell-daily' then 'calendar-prebrief-canary-dell'
  end;
  if not found or v_sponsor<>v_resolver_sponsor or v_destination is null
     or (v_destination='live' and v_job.mode<>'live') or (v_destination<>'live' and v_job.mode<>'canary') then
    raise exception using errcode='42501',message='calendar prebrief capture contract identity, mode, or static job owner mismatch';
  end if;
  select a.calendar_keys,a.configuration_digest,a.active_revision_id into v_keys,v_digest,v_revision
    from ops.calendar_prebrief_allowed_calendar a where a.sponsor=v_sponsor for update;
  if not found or coalesce(cardinality(v_keys),0)=0 or v_revision is null then
    raise exception using errcode='22023',message='calendar prebrief capture contract requires current DB allowlist';
  end if;
  insert into ops.calendar_prebrief_capture_challenge
    (job_id,attempt,lease_token,sponsor,resolver_identity,mode,destination,scheduled_for,window_starts_at,window_ends_at,allowlist_revision_id,allowlist_digest,calendar_keys)
  values(v_job.id,v_job.attempt,p_lease,v_sponsor,session_user,v_job.mode,v_destination,v_job.scheduled_for,
         v_job.scheduled_for-interval '7 days',v_job.scheduled_for+interval '45 days',v_revision,v_digest,v_keys)
  returning * into v_challenge;
  return query select v_challenge.id,v_challenge.sponsor,v_challenge.job_id,v_challenge.attempt,v_challenge.lease_token,
    v_challenge.scheduled_for,v_challenge.window_starts_at,v_challenge.window_ends_at,v_challenge.mode,v_challenge.destination,
    v_challenge.allowlist_revision_id,v_challenge.allowlist_digest,v_challenge.calendar_keys;
end $$;


--
-- Name: issue_execution_envelope_v1(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.issue_execution_envelope_v1(p_work_request text, p_binding_id text, p_idempotency_key uuid) RETURNS TABLE(envelope_id uuid, envelope_digest text, envelope jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id', true); binding ops.context_activation_binding%rowtype;
  work ops.work_request%rowtype; plan ops.sourced_work_request_plan%rowtype; assignment ops.work_request_execution_assignment%rowtype; profile agent_profile%rowtype; sponsor actor%rowtype; existing ops.execution_envelope_v1%rowtype; issued timestamptz := now(); expires timestamptz;
  runtime jsonb; topology jsonb; evaluation jsonb; configuration text; body jsonb; digest_text text;
begin
  if coalesce(tenant,'')='' then raise exception 'execution envelope requires authenticated tenant context'; end if;
  select b.* into binding from ops.context_activation_binding b join ops.work_request w on w.id=b.work_request_id
   where b.binding_id=p_binding_id and b.organization_tenant_id=tenant and w.ref=p_work_request
     and b.expires_at>=now() and w.version=b.work_request_version for share;
  if not found then raise exception 'execution envelope binding is not visible to tenant'; end if;
  select * into work from ops.work_request where id=binding.work_request_id for share;
  select * into plan from ops.sourced_work_request_plan where id=binding.plan_id for share;
  if plan.id is null or plan.work_request_id<>work.id or plan.plan_hash<>binding.plan_hash
     or not exists (select 1 from ops.sourced_work_request_plan_acceptance_receipt ar where ar.work_request_id=work.id and ar.plan_id=plan.id and ar.plan_hash=binding.plan_hash and ar.result_version=work.version) then
    raise exception 'execution envelope binding is stale or no longer the exact accepted plan';
  end if;
  select * into assignment from ops.work_request_execution_assignment where work_request_id=work.id for share;
  if not found then raise exception 'execution envelope requires a preassigned server-owned profile lane'; end if;
  select * into profile from agent_profile where id=assignment.profile_id and status='active' and current_model is not null and current_desk is not null for share;
  select * into sponsor from actor where id=assignment.sponsoring_human_id and kind='human' and active for share;
  if profile.id is null or sponsor.id is null then raise exception 'execution envelope assignment has no active durable runtime profile/sponsor'; end if;
  select * into existing from ops.execution_envelope_v1 where organization_tenant_id=tenant and idempotency_key=p_idempotency_key for share;
  if found then
    if existing.work_request_id<>work.id or existing.activation_binding_id<>binding.id then raise exception 'execution envelope idempotency conflict'; end if;
    return query select existing.id,existing.envelope_digest,existing.envelope,true; return;
  end if;
  -- A binding has one server-issued envelope.  A later request cannot cause a
  -- timestamp/profile snapshot to fork the same governed attempt.
  select * into existing from ops.execution_envelope_v1
   where organization_tenant_id=tenant and activation_binding_id=binding.id for share;
  if found then
    return query select existing.id,existing.envelope_digest,existing.envelope,true; return;
  end if;
  -- These bounded versioned metadata refs are server-issued configuration,
  -- never caller authority/provider/model selections. They contain no secret
  -- values and are retained with the immutable envelope for audit.
  runtime := jsonb_build_object('ref','runtime-profile:'||profile.profile_key||':v'||profile.version::text,'profile_key',profile.profile_key,'profile_version',profile.version,'provider_id','provider:'||split_part(profile.current_model,'/',1),'model_id','model:'||profile.current_model,'desk',profile.current_desk,'policy_ref',assignment.policy_ref,'policy_digest',assignment.policy_digest,'modality','modality:text','reasoning_effort_ref','reasoning-effort:governed-default','sampling_profile_ref','sampling:governed-default','context_budget',8192,'cache_policy_ref','cache:governed-default','knowledge_cutoff_posture','knowledge-cutoff:provider-declared','tool_calling_mode','tool-calling:metadata-only');
  runtime := runtime || jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(runtime),'sha256'),'hex'));
  topology := jsonb_build_object('ref','execution-topology:single-governed-attempt-v1','kind','single_agent_loop','harness_digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object('harness','postgres-governed-attempt-v1')),'sha256'),'hex'),'parallelism','sequential','code_model_step_refs',jsonb_build_array('step:model-governed'),'fallback_policy_ref','fallback:stop-and-escalate','stop_condition_refs',jsonb_build_array('stop:capability-expired','stop:critical-failure'),'context_refresh_policy_ref','context-refresh:bound-revisions-only','memory_policy_ref','memory:context-never-authority','sandbox_ref','sandbox:metadata-only','guardrail_ref','guardrail:governed-default','threat_model_ref','threat-model:governed-default');
  topology := topology || jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(topology),'sha256'),'hex'));
  evaluation := jsonb_build_object('ref','evaluation-plan:independent-risk-v1','lane_ref','lane:governed-work','risk_class','R2','rubric_digest','sha256:'||encode(public.digest('rubric:independent-risk-v1','sha256'),'hex'),'case_set_digest',binding.bundle_digest,'evaluator_policy_digest','sha256:'||encode(public.digest('evaluator-policy:r2-v1','sha256'),'hex'),'evaluator_ref','evaluator:authority-independent-v1','rubric_ref','rubric:independent-risk-v1','evaluator_version','version:v1','evaluator_digest','sha256:'||encode(public.digest('evaluator:authority-independent-v1:version:v1','sha256'),'hex'),'required_rungs',jsonb_build_array('rung:smoke','rung:regression'),'required_deterministic_check_refs',jsonb_build_array('check:activation-binding','check:critical-security'),'critical_dimensions',jsonb_build_array('dimension:correctness','dimension:security'),'human_acceptance_required',true,'outcome_horizon_ref',case when assignment.environment='rehearsal' then 'outcome-horizon:synthetic-fixture-zero' else 'outcome-horizon:r2-seven-day' end,'outcome_horizon_not_before',to_char((issued + case when assignment.environment='rehearsal' then interval '0' else interval '7 days' end) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'requirements',jsonb_build_object('required_evaluator_kinds',jsonb_build_array('deterministic','judge','human_acceptance'),'minimum_held_out_case_count',1,'minimum_calibration_ref_count',1,'maximum_critical_failure_count',0,'maximum_critical_failure_rate',0,'confidence_posture','lower_bound_required','drift_tolerance','no_critical_regression','independent_review_required',true,'human_acceptance_required',true,'outcome_horizon_required',true));
  evaluation := evaluation || jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(evaluation),'sha256'),'hex'));
  configuration := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(runtime||topology||evaluation),'sha256'),'hex');
  expires := least(binding.expires_at, issued + interval '1 hour');
  body := jsonb_build_object(
    'schema_version','execution-envelope.v1','envelope_id','env:'||binding.binding_id,
    'work_request_id',work.ref,
    'plan_revision',jsonb_build_object('id','plan:'||binding.plan_id::text,'revision',plan.plan_version,'digest',binding.plan_hash),
    'agent_session',jsonb_build_object('id','session:'||binding.binding_id,'lease_expires_at',to_char(expires at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')),
    'issued_at',to_char(issued at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'expires_at',to_char(expires at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'state_binding',jsonb_build_object('state_version',work.version,'canonical_record_digest',binding.plan_hash,'accepted_resource_revisions','[]'::jsonb,'compare_and_swap_required',true),
    'phase_binding',jsonb_build_object('phase_id','phase:governed-execution','session_affinity','same_native_session_preferred','switch_conditions',jsonb_build_array('verified_checkpoint','phase_boundary'),'native_session_transfer','semantic_state_only'),
    'evaluation_context',jsonb_build_object('experiment_arm','same_pair_audited_state','auditor_mode','diverse_read_only_auditor','evaluation_kernel_ref',evaluation->>'ref','workflow_rubric_digest',evaluation->>'rubric_digest','case_set_digest',binding.bundle_digest),
    'request',jsonb_build_object('job_ref','job:'||work.ref,'input_digest',binding.bundle_digest,'data_class','metadata_only','allowed_actions','[]'::jsonb,'declared_expectations',jsonb_build_object('plan_step_refs','[]'::jsonb,'component_refs','[]'::jsonb,'component_dependencies','[]'::jsonb,'resource_refs','[]'::jsonb)),
    'server_binding',jsonb_build_object('identity',jsonb_build_object('organization_tenant_id',tenant,'sponsoring_human_id','human:'||sponsor.slug,'agent_principal_id','agent:'||profile.profile_key,'runtime_principal','runtime:'||profile.profile_key,'personal_brain_scope','none','personal_brain_version','none','personal_rule_count',0,'derived_by','server_identity_resolution','client_mutable',false),'authority',jsonb_build_object('environment',assignment.environment,'risk_class','R2','capability_profile','capability:metadata-only','capability_grant_ref','grant:'||assignment.id::text,'read_only',true,'derived_by','server_capability_resolution','client_mutable',false),'adapter',jsonb_build_object('surface','hermes_desktop','adapter_id','adapter:hermes-desktop','adapter_version','v1','harness_id','harness:postgres','harness_version','v1','provider_id','provider:'||split_part(profile.current_model,'/',1),'model_id','model:'||profile.current_model,'native_session_ref','native:profile-'||profile.profile_key,'configuration_fingerprint',configuration)),
    'handoff',jsonb_build_object('mode','original','replaces_agent_session_id',null,'capability_inherited',false,'checkpoint_ref',null,'native_session_transfer','semantic_state_only'),
    'activation_binding',jsonb_build_object('bundle_digest',binding.bundle_digest,'item_refs',(select coalesce(jsonb_agg(canonical_ref order by ordinal),'[]'::jsonb) from ops.context_activation_item where binding_id=binding.id),'mode',binding.mode,'retrieval_policy_version','v1'),
    'reliability_policy_binding',jsonb_build_object('policy_ref',assignment.policy_ref,'policy_digest',assignment.policy_digest,'risk_class','R2','mode',binding.mode),
    'context_activation_ref',binding.binding_id,'runtime_profile',runtime,'execution_topology',topology,'evaluation_plan',evaluation
  );
  digest_text := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(body),'sha256'),'hex');
  insert into ops.execution_envelope_v1(idempotency_key,organization_tenant_id,work_request_id,plan_hash,activation_binding_id,envelope_digest,envelope,runtime_profile,execution_topology,evaluation_plan,configuration_digest,issued_at,expires_at)
  values(p_idempotency_key,tenant,work.id,binding.plan_hash,binding.id,digest_text,body,runtime,topology,evaluation,configuration,issued,expires)
  returning id,ops.execution_envelope_v1.envelope_digest,ops.execution_envelope_v1.envelope into envelope_id,envelope_digest,envelope;
  return query select envelope_id,envelope_digest,envelope,false;
end $$;


--
-- Name: nightly_availability_canary_live_job(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.nightly_availability_canary_live_job(p_job_id uuid, p_lease uuid) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; k text;
begin
 if session_user<>'carr_jobs' then raise exception using errcode='42501',message='nightly availability canary requires carr_jobs identity'; end if;
 select * into j from ops.job where id=p_job_id for update;
 select execution_kind into k from ops.job_definition where key=j.definition_key and version=j.definition_version;
 if not found or j.state<>'running' or j.lease_token<>p_lease or j.leased_until<now() then raise exception using errcode='55000',message='nightly availability canary requires current live job lease'; end if;
 if j.definition_key<>'nightly-record-layer' or j.definition_version<>3 or j.mode<>'canary' or k<>'deterministic' then raise exception using errcode='22023',message='job is not nightly-record-layer v3 deterministic canary'; end if;
 return j;
end $$;


--
-- Name: pending_sourced_work_request_outcome_feedback(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.pending_sourced_work_request_outcome_feedback(p_work_request text, p_organization_tenant_id text) RETURNS TABLE(ref text, state text, version integer, plan_ref text, plan_hash text, feedback_ref text, feedback_hash text, outcome text, criterion_results jsonb, evidence_refs jsonb, blocker_code text, result_summary text, observed_minutes integer, interaction_surface text, heavy_session_used boolean, manual_context_transfers integer, proposed_at timestamp with time zone, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select w.ref,w.state,w.version,
         p.plan_ref,p.plan_hash,
         f.feedback_ref,f.feedback_hash,f.outcome,
         f.criterion_results,f.evidence_refs,f.blocker_code,
         f.result_summary,f.observed_minutes,f.interaction_surface,
         f.heavy_session_used,f.manual_context_transfers,
         f.created_at,'pending_human_acceptance'::text
    from ops.work_request w
    join public.doctrine_section s on s.id=w.doctrine_section_id
    join public.doctrine_document d on d.id=s.document_id
    join ops.sourced_work_request_outcome_feedback f
      on f.work_request_id=w.id
     and f.work_request_version=w.version
    join ops.sourced_work_request_plan p
      on p.id=f.plan_id
     and p.work_request_id=w.id
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.id=f.plan_acceptance_receipt_id
     and ar.work_request_id=w.id
     and ar.plan_id=p.id
     and ar.result_version=w.version
     and ar.plan_hash=p.plan_hash
    left join ops.sourced_work_request_outcome_feedback_acceptance_receipt accepted
      on accepted.feedback_id=f.id
   where p_organization_tenant_id='carr-internal'
     and w.organization_tenant_id='carr-internal'
     and w.ref=p_work_request
     and w.state='ready'
     and d.visibility='shared'
     and accepted.id is null
   order by f.feedback_version desc
   limit 1;
$$;


--
-- Name: FUNCTION pending_sourced_work_request_outcome_feedback(p_work_request text, p_organization_tenant_id text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.pending_sourced_work_request_outcome_feedback(p_work_request text, p_organization_tenant_id text) IS 'Safe readback of only the latest still-unaccepted Program 6 outcome-feedback proposal for one exact current ready Work Request and accepted plan. It is separate from accepted-only card history and never claims execution, completion, success, approval, release, or displacement.';


--
-- Name: performance_receipt_requires_read_back(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.performance_receipt_requires_read_back() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.run_key like 'performance.%'
     and not exists (
       select 1
         from ops.deployment d
        where d.release_id = new.release_id
          and d.service_id = new.service_id
          and d.environment = 'production'
          and d.correlation_id = new.correlation_id
          and d.state in ('verifying', 'complete')
          and d.read_back_at is not null
     ) then
    raise exception 'performance receipt % requires an already-read-back Production deployment for the same release and correlation',
      new.run_key;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION performance_receipt_requires_read_back(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.performance_receipt_requires_read_back() IS 'Program 5: a performance receipt must follow the same-correlation Production deployment identity read-back.';


--
-- Name: prepare_staging_deployment_attempt(uuid, uuid, text, text, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_staging_deployment_attempt(p_idempotency_key uuid, p_correlation_id uuid, p_release_key text, p_prior_release_key text, p_recovery_attempt_id uuid, p_recovery_step text, p_git_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_deployment_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  observed_release ops.release%rowtype;
  attempt_uuid uuid;
  expected_tag text;
  migration_hash text;
  migration_count integer;
  receipt ops.staging_release_readback_receipt%rowtype;
begin
  if session_user<>'carr_jobs' then
    raise exception 'staging attempt writer requires the carr_jobs session';
  end if;
  if p_idempotency_key is null or p_correlation_id is null
     or coalesce(p_release_key,'')='' or coalesce(p_git_sha,'') !~ '^[0-9a-f]{40}$'
     or p_recovery_step not in ('standalone','current_before','prior','current_after') then
    raise exception 'invalid typed staging attempt input';
  end if;
  if (p_recovery_step='standalone' and (p_recovery_attempt_id is not null or p_prior_release_key is not null))
     or (p_recovery_step<>'standalone' and
         (p_recovery_attempt_id is null or p_prior_release_key is null
          or p_correlation_id<>p_recovery_attempt_id)) then
    raise exception 'recovery fields do not match the requested staging step';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  if p_recovery_attempt_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_recovery_attempt_id::text,202));
  end if;
  select * into current_release from ops.release where release_key=p_release_key;
  if not found or current_release.service_id is null then
    raise exception 'staging attempt release does not exist';
  end if;
  if coalesce(cardinality(current_release.migration_set),0)<=0
     or coalesce(current_release.schema_highest_migration,'') !~ '^[0-9]{4}_[a-z0-9_.-]+\.sql$'
     or coalesce(current_release.schema_applied_count,0)<=0
     or coalesce(current_release.schema_ledger_sha256,'') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'release does not declare an exact migration/schema set';
  end if;
  migration_hash:=ops.program5_migration_set_sha256(current_release.migration_set);
  migration_count:=cardinality(current_release.migration_set);
  if p_recovery_step='standalone' then
    if current_release.environment not in ('staging','production')
       or current_release.state not in ('candidate','approved','deploying','verifying') then
      raise exception 'standalone staging attempt release is not deployable';
    end if;
    observed_release:=current_release;
  else
    if current_release.environment<>'production' or current_release.state<>'candidate'
       or current_release.recovery_strategy is distinct from 'rollback'
       or coalesce(current_release.rollback_plan_ref,'')=''
       or coalesce(current_release.plan_hash,'')='' then
      raise exception 'current release is not a rollback-ready Production candidate';
    end if;
    select * into prior_release from ops.release where release_key=p_prior_release_key;
    if not found or prior_release.id=current_release.id
       or prior_release.environment<>'production' or prior_release.state<>'complete'
       or prior_release.service_id<>current_release.service_id then
      raise exception 'prior release is not a distinct completed Production release';
    end if;
    if not exists (
      select 1 from ops.deployment d where d.release_id=prior_release.id
       and d.service_id=current_release.service_id and d.environment='production'
       and d.state='complete' and d.read_back_at is not null
       and d.git_sha=prior_release.git_sha and d.provider=prior_release.provider
       and d.provider_version_id=prior_release.provider_version_id) then
      raise exception 'prior release has no exact completed Production readback';
    end if;
    observed_release:=case when p_recovery_step='prior' then prior_release else current_release end;
  end if;
  if p_git_sha<>observed_release.git_sha then
    raise exception 'staging attempt SHA does not match the release required for this step';
  end if;
  expected_tag:='carr-staging-'||replace(p_idempotency_key::text,'-','');
  select * into existing from ops.staging_deployment_attempt where idempotency_key=p_idempotency_key;
  if found then
    if (existing.correlation_id,existing.recovery_attempt_id,existing.recovery_step,
        existing.rehearsal_release_id,existing.observed_release_id,existing.prior_release_id,
        existing.service_id,existing.git_sha,existing.expected_provider_tag,
        existing.declared_migration_set_sha256,existing.declared_migration_count,
        existing.declared_schema_highest_migration,
        existing.declared_schema_applied_count,existing.declared_schema_ledger_sha256) is distinct from
       (p_correlation_id,p_recovery_attempt_id,p_recovery_step,current_release.id,
        observed_release.id,case when p_recovery_step='standalone' then null else prior_release.id end,
        current_release.service_id,p_git_sha,expected_tag,migration_hash,migration_count,
        current_release.schema_highest_migration,current_release.schema_applied_count,
        current_release.schema_ledger_sha256) then
      raise exception 'staging attempt idempotency key was reused with changed input';
    end if;
    select * into receipt from ops.staging_release_readback_receipt
      where deployment_attempt_id=existing.id;
    return jsonb_build_object('attempt_id',existing.id,
      'expected_provider_tag',existing.expected_provider_tag,
      'state',case when receipt.id is null then 'prepared' else 'observed' end,
      'deploy_claimed',exists(select 1 from ops.staging_deployment_claim where deployment_attempt_id=existing.id),
      'provider_version_id',receipt.provider_version_id,'receipt_ref',receipt.evidence_ref,
      'replayed',true);
  end if;
  insert into ops.staging_deployment_attempt(
    idempotency_key,recovery_attempt_id,recovery_step,correlation_id,
    rehearsal_release_id,observed_release_id,prior_release_id,service_id,
    environment,git_sha,provider,expected_provider_tag,
    declared_migration_set_sha256,declared_migration_count,
    declared_schema_highest_migration,declared_schema_applied_count,
    declared_schema_ledger_sha256,writer_session_user)
  values(p_idempotency_key,p_recovery_attempt_id,p_recovery_step,p_correlation_id,
    current_release.id,observed_release.id,
    case when p_recovery_step='standalone' then null else prior_release.id end,
    current_release.service_id,'staging',p_git_sha,'cloudflare-workers',expected_tag,
    migration_hash,migration_count,current_release.schema_highest_migration,
    current_release.schema_applied_count,current_release.schema_ledger_sha256,session_user)
  returning id into attempt_uuid;
  return jsonb_build_object('attempt_id',attempt_uuid,'expected_provider_tag',expected_tag,
    'state','prepared','deploy_claimed',false,'provider_version_id',null,
    'receipt_ref',null,'replayed',false);
end $_$;


--
-- Name: prepare_staging_restore_only_attempt(uuid, uuid, text, text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_staging_restore_only_attempt(p_idempotency_key uuid, p_correlation_id uuid, p_release_key text, p_prior_release_key text, p_recovery_attempt_id uuid, p_git_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_restore_only_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  migration_hash text;
  migration_count integer;
  attempt_uuid uuid;
  target_provider_version uuid;
  expected_tag text;
  existing_result ops.staging_restore_only_result%rowtype;
begin
  if session_user<>'carr_jobs' then raise exception 'restore-only writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_correlation_id is null or p_recovery_attempt_id is null
     or coalesce(p_release_key,'')='' or coalesce(p_prior_release_key,'' )=''
     or coalesce(p_git_sha,'') !~ '^[0-9a-f]{40}$' or p_correlation_id<>p_recovery_attempt_id then
    raise exception 'invalid typed restore-only attempt input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  perform pg_advisory_xact_lock(hashtextextended(p_recovery_attempt_id::text,202));
  select * into current_release from ops.release where release_key=p_release_key;
  if not found or current_release.environment<>'production' or current_release.state<>'candidate'
     or current_release.recovery_strategy<>'rollback' or coalesce(current_release.rollback_plan_ref,'')=''
     or coalesce(current_release.plan_hash,'')='' or current_release.service_id is null
     or current_release.provider<>'cloudflare-workers' or current_release.provider_version_id is null then
    raise exception 'restore-only target is not an exact rollback-ready Production candidate';
  end if;
  if current_release.provider_version_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'restore-only target provider version is not a canonical UUID';
  end if;
  target_provider_version:=current_release.provider_version_id::uuid;
  select * into prior_release from ops.release where release_key=p_prior_release_key;
  if not found or prior_release.id=current_release.id or prior_release.environment<>'production'
     or prior_release.state<>'complete' or prior_release.service_id<>current_release.service_id then
    raise exception 'restore-only prior release is not a distinct completed Production release';
  end if;
  if not exists (select 1 from ops.deployment d where d.release_id=prior_release.id
      and d.service_id=current_release.service_id and d.environment='production'
      and d.state='complete' and d.read_back_at is not null and d.git_sha=prior_release.git_sha
      and d.provider=prior_release.provider and d.provider_version_id=prior_release.provider_version_id) then
    raise exception 'restore-only prior release has no exact completed Production readback';
  end if;
  if p_git_sha<>current_release.git_sha then raise exception 'restore-only SHA does not match the current target'; end if;
  if coalesce(cardinality(current_release.migration_set),0)<=0
     or coalesce(current_release.schema_highest_migration,'') !~ '^[0-9]{4}_[a-z0-9_.-]+\.sql$'
     or coalesce(current_release.schema_applied_count,0)<=0
     or coalesce(current_release.schema_ledger_sha256,'') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'restore-only target does not declare an exact migration/schema set';
  end if;
  migration_hash:=ops.program5_migration_set_sha256(current_release.migration_set);
  migration_count:=cardinality(current_release.migration_set);
  expected_tag:='carr-staging-'||replace(p_idempotency_key::text,'-','');
  select * into existing from ops.staging_restore_only_attempt where idempotency_key=p_idempotency_key;
  if found then
    if (existing.correlation_id,existing.recovery_attempt_id,existing.rehearsal_release_id,
        existing.prior_release_id,existing.service_id,existing.git_sha,existing.target_provider_version_id,
        existing.recovery_strategy,existing.rollback_plan_ref,existing.plan_hash,existing.expected_provider_tag,
        existing.declared_migration_set_sha256,existing.declared_migration_count,
        existing.declared_schema_highest_migration,existing.declared_schema_applied_count,
        existing.declared_schema_ledger_sha256) is distinct from
       (p_correlation_id,p_recovery_attempt_id,current_release.id,prior_release.id,current_release.service_id,
        p_git_sha,target_provider_version,current_release.recovery_strategy,
        current_release.rollback_plan_ref,current_release.plan_hash,expected_tag,migration_hash,migration_count,
        current_release.schema_highest_migration,current_release.schema_applied_count,
        current_release.schema_ledger_sha256) then
      raise exception 'restore-only idempotency key was reused with changed input';
    end if;
    select * into existing_result from ops.staging_restore_only_result where restore_attempt_id=existing.id;
    return jsonb_build_object('restore_attempt_id',existing.id,'expected_provider_tag',existing.expected_provider_tag,
      'state',coalesce(existing_result.status,'prepared'),'mutation_claimed',exists(select 1 from ops.staging_restore_only_claim where restore_attempt_id=existing.id),
      'result_ref',existing_result.evidence_ref,'replayed',true);
  end if;
  insert into ops.staging_restore_only_attempt(idempotency_key,recovery_attempt_id,correlation_id,
    rehearsal_release_id,prior_release_id,service_id,environment,git_sha,provider,target_provider_version_id,
    recovery_strategy,rollback_plan_ref,plan_hash,expected_provider_tag,declared_migration_set_sha256,
    declared_migration_count,declared_schema_highest_migration,declared_schema_applied_count,
    declared_schema_ledger_sha256,writer_session_user)
  values(p_idempotency_key,p_recovery_attempt_id,p_correlation_id,current_release.id,prior_release.id,
    current_release.service_id,'staging',p_git_sha,'cloudflare-workers',target_provider_version,
    current_release.recovery_strategy,current_release.rollback_plan_ref,current_release.plan_hash,expected_tag,
    migration_hash,migration_count,current_release.schema_highest_migration,current_release.schema_applied_count,
    current_release.schema_ledger_sha256,session_user) returning id into attempt_uuid;
  return jsonb_build_object('restore_attempt_id',attempt_uuid,'expected_provider_tag',expected_tag,
    'state','prepared','mutation_claimed',false,'result_ref',null,'replayed',false);
end $_$;


--
-- Name: program5_migration_set_sha256(text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_migration_set_sha256(p_migration_set text[]) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select 'sha256:'||encode(public.digest(to_jsonb(p_migration_set)::text,'sha256'),'hex')
$$;


--
-- Name: program5_release_approval_is_joe_owned(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_release_approval_is_joe_owned() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.environment='production'
     and new.state in ('approved','deploying','verifying','complete')
     and (tg_op='INSERT' or old.state not in ('approved','deploying','verifying','complete')) then
    if new.state<>'approved' or session_user<>'carr_authority_joe'
       or new.approved_by_actor<>'joe'
       or new.approval_receipt_id is null or not exists (
         select 1 from ops.release_approval_receipt a
          where a.id=new.approval_receipt_id and a.release_id=new.id
            and a.plan_hash=new.plan_hash and a.approved_by_actor='joe'
            and a.approved_at=new.approved_at
            and a.approval_expires_at=new.approval_expires_at) then
      raise exception 'Program 5 Production approval requires Joe authority and its typed receipt';
    end if;
  end if;
  if tg_op='UPDATE'
     and old.environment='production'
     and old.state in ('approved','deploying','verifying','complete')
     and new.state in ('approved','deploying','verifying','complete')
     and (new.approved_by_actor,new.approved_at,new.approval_expires_at,new.approval_receipt_id)
         is distinct from
         (old.approved_by_actor,old.approved_at,old.approval_expires_at,old.approval_receipt_id) then
    raise exception 'Program 5 approval projection is immutable across promoted states';
  end if;
  return new;
end $$;


--
-- Name: program5_release_verifier_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_release_verifier_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.verifier_actor,new.verifier_evidence_ref)
       is distinct from (old.verifier_actor,old.verifier_evidence_ref)
     and (old.approval_receipt_id is not null
          or old.state in ('approved','deploying','verifying','complete'))
     and new.plan_hash is not distinct from old.plan_hash then
    raise exception 'Program 5 verifier evidence is immutable after approval; revise the plan to invalidate approval first';
  end if;
  return new;
end $$;


--
-- Name: program6_browser_action_challenge_redemptions_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program6_browser_action_challenge_redemptions_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'Program 6 browser action challenge redemptions are append-only';
end;
$$;


--
-- Name: propose_eval_candidate(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_eval_candidate(p_attempt_id text, p_fact_event_ref text, p_idempotency_key uuid) RETURNS TABLE(candidate_id uuid, candidate_ref text, lifecycle text, promotion_state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare tenant text := current_setting('carr.organization_tenant_id', true); fact ops.attempt_receipt%rowtype;
  envelope_row ops.execution_envelope_v1%rowtype; fact_event jsonb; fact_count integer; fact_kind text;
  source_digest_value text; root_key text; candidate_ref_value text; case_ref_value text; target_set_ref text;
  lane_value text; risk_value text; split_value text; context_value jsonb; basis_value jsonb;
  row_out ops.proposed_eval_candidate%rowtype; previous_event ops.proposed_eval_candidate_event%rowtype;
begin
  if coalesce(tenant,'')='' or p_attempt_id !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_fact_event_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' then
    raise exception 'eval proposal requires tenant-scoped canonical attempt and fact references';
  end if;
  select * into fact from ops.attempt_receipt where organization_tenant_id=tenant and attempt_id=p_attempt_id for share;
  if not found then raise exception 'eval candidate attempt receipt is not visible to tenant'; end if;
  select * into envelope_row from ops.execution_envelope_v1 where id=fact.execution_envelope_id and organization_tenant_id=tenant for share;
  if not found then raise exception 'eval candidate requires its exact issued evaluation plan'; end if;
  select count(*), (array_agg(item))[1], min(kind) into fact_count,fact_event,fact_kind from (
    select e.value as item, 'correction'::text as kind from jsonb_array_elements(fact.receipt->'reliability'->'corrections') e where e.value->>'event_ref'=p_fact_event_ref
    union all select e.value, 'defect'::text from jsonb_array_elements(fact.receipt->'reliability'->'defects') e where e.value->>'event_ref'=p_fact_event_ref
    union all select e.value, 'incident'::text from jsonb_array_elements(fact.receipt->'reliability'->'incidents') e where e.value->>'event_ref'=p_fact_event_ref
  ) canonical_fact;
  if fact_count<>1 or fact_event->>'kind'<>fact_kind
     or jsonb_typeof(fact_event->'evidence_refs')<>'array'
     or jsonb_array_length(fact_event->'evidence_refs')=0
     or ops.attempt_receipt_contains_raw_content(fact_event) then
    raise exception 'eval proposal fact must be one redacted canonical correction, defect, or incident';
  end if;
  -- `summary` is metadata classification, not a copied client/executor body.
  if coalesce(fact_event->>'summary','') !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' then
    raise exception 'eval proposal fact summary must be a bounded classification ref';
  end if;
  source_digest_value := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(fact_event),'sha256'),'hex');
  -- The event ref identifies this occurrence; summary is the bounded canonical
  -- taxonomy/root-cause classification.  Dedupe therefore means same root
  -- cause *and* same exact source fact, never merely the same event label.
  root_key := 'root:'||fact_kind||':'||lower(regexp_replace(fact_event->>'summary','[^A-Za-z0-9]+','-','g'));
  lane_value := coalesce(envelope_row.evaluation_plan->>'lane_ref','lane:governed-work');
  risk_value := coalesce(envelope_row.evaluation_plan->>'risk_class','R2');
  -- Issued policy currently has a single safe default.  It is deliberately
  -- server-owned and never passed by the executor or human proposer.
  split_value := coalesce(envelope_row.evaluation_plan->>'learning_split_target','development');
  if lane_value !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or risk_value !~ '^R[0-6]$'
     or split_value not in ('development','held_out','canary') then
    raise exception 'issued evaluation plan has no valid learning lane/risk/split';
  end if;
  candidate_ref_value := 'eval-candidate:'||substr(replace(source_digest_value,'sha256:',''),1,24);
  case_ref_value := 'case:proposal:'||substr(replace(source_digest_value,'sha256:',''),1,24);
  target_set_ref := 'golden:'||lower(regexp_replace(lane_value,'[^A-Za-z0-9]+','-','g'))||':'||lower(risk_value)||':'||split_value;
  context_value := jsonb_build_object('work_request_id','wr:'||fact.work_request_id::text,'case_digest',source_digest_value);
  basis_value := fact_event->'evidence_refs';
  select * into previous_event from ops.proposed_eval_candidate_event where idempotency_key=p_idempotency_key for share;
  if found then
    select * into row_out from ops.proposed_eval_candidate where id=previous_event.candidate_id and organization_tenant_id=tenant;
    if row_out.id is null or previous_event.event_kind<>'proposed' or row_out.attempt_receipt_id<>fact.id
       or row_out.source_digest<>source_digest_value or row_out.normalized_root_cause_key<>root_key then
      raise exception 'eval candidate proposal idempotency conflict';
    end if;
    return query select row_out.id,row_out.candidate_ref,
      coalesce((select pe.event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=row_out.id order by pe.created_at desc,pe.id desc limit 1),'proposed'),
      row_out.promotion_state,true;
    return;
  end if;
  select * into row_out from ops.proposed_eval_candidate
    where organization_tenant_id=tenant and normalized_root_cause_key=root_key and source_digest=source_digest_value for share;
  if found then
    if row_out.attempt_receipt_id<>fact.id or row_out.case_ref<>case_ref_value or row_out.target_golden_set_ref<>target_set_ref
       or row_out.lane_ref<>lane_value or row_out.risk_class<>risk_value or row_out.split_target<>split_value
       or row_out.provenance<>fact_kind or row_out.context_binding is distinct from context_value or row_out.basis is distinct from basis_value then
      raise exception 'eval candidate source dedupe conflicts with immutable proposal';
    end if;
    return query select row_out.id,row_out.candidate_ref,
      coalesce((select pe.event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=row_out.id order by pe.created_at desc,pe.id desc limit 1),'proposed'),
      row_out.promotion_state,true;
    return;
  end if;
  insert into ops.proposed_eval_candidate(organization_tenant_id,attempt_receipt_id,candidate_ref,case_ref,target_golden_set_ref,normalized_root_cause_key,source_digest,lane_ref,risk_class,provenance,split_target,context_binding,basis)
  values(tenant,fact.id,candidate_ref_value,case_ref_value,target_set_ref,root_key,source_digest_value,lane_value,risk_value,fact_kind,split_value,context_value,basis_value)
  returning * into row_out;
  insert into ops.proposed_eval_candidate_event(candidate_id,event_kind,decision_basis,idempotency_key)
  values(row_out.id,'proposed',jsonb_build_object('source','attempt-receipt','fact_event_ref',p_fact_event_ref,'source_digest',source_digest_value),p_idempotency_key);
  return query select row_out.id,row_out.candidate_ref,'proposed',row_out.promotion_state,false;
end $_$;


--
-- Name: propose_guidance_situation_mapping(uuid, uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_guidance_situation_mapping(p_revision_id uuid, p_concept_id uuid, p_doctrine_section_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare mapping_id uuid;
begin
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'situation mapping proposal requires a reason';
  end if;
  if not exists (
    select 1 from ops.guidance_revision
     where id=p_revision_id and guidance_type='doctrine') then
    raise exception 'situation mappings may be proposed only for doctrine revisions';
  end if;
  insert into ops.guidance_situation_mapping
    (guidance_revision_id,concept_id,doctrine_section_id,state,reason)
  values (p_revision_id,p_concept_id,p_doctrine_section_id,'proposed',p_reason)
  returning id into mapping_id;
  return mapping_id;
end $$;


--
-- Name: propose_sourced_work_request_outcome_feedback(text, integer, text, jsonb, jsonb, text, text, integer, text, boolean, integer, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_sourced_work_request_outcome_feedback(p_work_request text, p_base_version integer, p_plan_hash text, p_criterion_results jsonb, p_evidence_refs jsonb, p_blocker_code text, p_result_summary text, p_observed_minutes integer, p_interaction_surface text, p_heavy_session_used boolean, p_manual_context_transfers integer, p_idempotency_key uuid) RETURNS TABLE(feedback_id uuid, feedback_ref text, feedback_hash text, work_request_id uuid, ref text, state text, version integer, plan_id uuid, plan_ref text, plan_hash text, outcome text, criterion_results jsonb, evidence_refs jsonb, blocker_code text, result_summary text, observed_minutes integer, interaction_surface text, heavy_session_used boolean, manual_context_transfers integer, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype; p ops.sourced_work_request_plan%rowtype;
  ar ops.sourced_work_request_plan_acceptance_receipt%rowtype;
  f ops.sourced_work_request_outcome_feedback%rowtype;
  normalized_summary text; derived_outcome text; next_feedback_version integer;
  canonical_preimage jsonb; canonical_hash text;
begin
  normalized_summary := btrim(p_result_summary);
  if coalesce(btrim(p_work_request),'') !~ '^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version < 1
     or coalesce(p_plan_hash,'') !~ '^sha256:[0-9a-f]{64}$'
     or p_idempotency_key is null
     or coalesce(normalized_summary,'')='' or char_length(normalized_summary)>500
     or p_observed_minutes is null or p_observed_minutes not between 1 and 1440
     or p_interaction_surface not in ('workspace','control_room','mcp','codex','claude_code','other')
     or p_heavy_session_used is null
     or p_manual_context_transfers is null or p_manual_context_transfers not between 0 and 100
     or p_blocker_code not in ('none','evidence_missing','criterion_not_met','external_dependency','system_error')
     or jsonb_typeof(p_criterion_results) is distinct from 'array'
     or jsonb_typeof(p_evidence_refs) is distinct from 'array'
     or jsonb_array_length(p_evidence_refs) not between 1 and 12
     or exists (select 1 from jsonb_array_elements(p_evidence_refs) v
                 where jsonb_typeof(v) <> 'string'
                    or v #>> '{}' !~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
                    or char_length(v #>> '{}') > 300)
     or exists (select v #>> '{}' from jsonb_array_elements(p_evidence_refs) v
                 group by v #>> '{}' having count(*) > 1)
     or exists (select 1 from jsonb_array_elements(p_criterion_results) v
                 where jsonb_typeof(v) <> 'object'
                    or (select array_agg(k order by k) from jsonb_object_keys(v) k)
                         is distinct from array['id','result']::text[]
                    or coalesce(v->>'id','') !~ '^[A-Z][A-Z0-9-]{1,63}$'
                    or v->>'result' not in ('met','not_met','not_observed'))
     or exists (select v->>'id' from jsonb_array_elements(p_criterion_results) v
                 group by v->>'id' having count(*) > 1) then
    raise exception 'outcome feedback requires exact ready plan/version, full criterion results, safe evidence references, bounded observed facts, blocker, summary, and UUID idempotency key';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-outcome-feedback-proposal:' || p_idempotency_key,0));
  select x.* into f from ops.sourced_work_request_outcome_feedback x
   where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into w from ops.work_request x where x.id=f.work_request_id for share;
    select x.* into p from ops.sourced_work_request_plan x where x.id=f.plan_id for share;
    if not found or w.ref is distinct from p_work_request
       or f.work_request_version is distinct from p_base_version
       or p.plan_hash is distinct from p_plan_hash or f.criterion_results is distinct from p_criterion_results
       or f.evidence_refs is distinct from p_evidence_refs or f.blocker_code is distinct from p_blocker_code
       or f.result_summary is distinct from normalized_summary or f.observed_minutes is distinct from p_observed_minutes
       or f.interaction_surface is distinct from p_interaction_surface or f.heavy_session_used is distinct from p_heavy_session_used
       or f.manual_context_transfers is distinct from p_manual_context_transfers then
      raise exception 'idempotency key already names different sourced outcome feedback proposal';
    end if;
    return query select f.id,f.feedback_ref,f.feedback_hash,w.id,w.ref,'ready'::text,f.work_request_version,
      p.id,p.plan_ref,p.plan_hash,f.outcome,f.criterion_results,f.evidence_refs,f.blocker_code,
      f.result_summary,f.observed_minutes,f.interaction_surface,f.heavy_session_used,
      f.manual_context_transfers,true;
    return;
  end if;

  select x.* into w from ops.work_request x where x.ref=p_work_request for update;
  if not found then raise exception 'exact sourced Work Request not found'; end if;
  select x.* into p from ops.sourced_work_request_plan x
   join ops.sourced_work_request_plan_acceptance_receipt ar0 on ar0.plan_id=x.id
   where x.work_request_id=w.id and x.plan_hash=p_plan_hash for share of x;
  select x.* into ar from ops.sourced_work_request_plan_acceptance_receipt x
   where x.work_request_id=w.id and x.plan_id=p.id for share;
  if not found or w.capture_idempotency_key is null
     or w.organization_tenant_id is distinct from 'carr-internal'
     or w.state is distinct from 'ready' or w.version is distinct from p_base_version
     or p.work_request_version >= w.version or ar.result_version is distinct from w.version
     or ar.plan_hash is distinct from p.plan_hash
     or w.shape_fixed_surface_ref is distinct from ar.shape_fixed_surface_ref then
    raise exception 'only an exact current ready sourced plan may receive outcome feedback';
  end if;
  if (select array_agg(v->>'id' order by v->>'id') from jsonb_array_elements(p_criterion_results) v)
       is distinct from
     (select array_agg(v->>'id' order by v->>'id') from jsonb_array_elements(w.acceptance_criteria) v) then
    raise exception 'outcome feedback criterion results must name the exact full Work Request acceptance-criteria ID set';
  end if;
  if exists (select 1 from jsonb_array_elements(p_criterion_results) v where v->>'result'='not_met') then
    derived_outcome := 'criteria_not_met';
  elsif exists (select 1 from jsonb_array_elements(p_criterion_results) v where v->>'result'='not_observed') then
    derived_outcome := 'inconclusive';
  else
    derived_outcome := 'criteria_met';
  end if;
  if (derived_outcome='criteria_met' and p_blocker_code <> 'none')
     or (derived_outcome='criteria_not_met' and p_blocker_code='none')
     or (derived_outcome='inconclusive' and p_blocker_code not in ('evidence_missing','external_dependency','system_error')) then
    raise exception 'outcome feedback blocker is inconsistent with its derived criterion outcome';
  end if;

  select coalesce(max(x.feedback_version),0)+1 into next_feedback_version
    from ops.sourced_work_request_outcome_feedback x where x.work_request_id=w.id;
  canonical_preimage := ops.sourced_work_request_outcome_feedback_preimage(
    w.id,p.id,ar.id,p_criterion_results,p_evidence_refs,derived_outcome,p_blocker_code,
    normalized_summary,p_observed_minutes,p_interaction_surface,p_heavy_session_used,
    p_manual_context_transfers);
  canonical_hash := ops.sourced_work_request_outcome_feedback_digest(canonical_preimage);
  if canonical_preimage is null or canonical_hash is null then
    raise exception 'exact ready-plan outcome-feedback preimage is unavailable';
  end if;
  if exists (select 1 from ops.sourced_work_request_outcome_feedback x
              where x.work_request_id=w.id and x.feedback_hash=canonical_hash) then
    raise exception 'the exact sourced outcome feedback already exists under a different idempotency key';
  end if;
  insert into ops.sourced_work_request_outcome_feedback
    (work_request_id,feedback_version,idempotency_key,work_request_version,plan_id,
     plan_acceptance_receipt_id,preimage,criterion_results,evidence_refs,outcome,
     blocker_code,result_summary,observed_minutes,interaction_surface,heavy_session_used,
     manual_context_transfers,feedback_hash,feedback_ref)
  values
    (w.id,next_feedback_version,p_idempotency_key,w.version,p.id,ar.id,canonical_preimage,
     p_criterion_results,p_evidence_refs,derived_outcome,p_blocker_code,normalized_summary,
     p_observed_minutes,p_interaction_surface,p_heavy_session_used,p_manual_context_transfers,
     canonical_hash,'OUTCOME-' || substr(canonical_hash,8,12) || '-v' || next_feedback_version)
  returning * into f;
  return query select f.id,f.feedback_ref,f.feedback_hash,w.id,w.ref,w.state,w.version,
    p.id,p.plan_ref,p.plan_hash,f.outcome,f.criterion_results,f.evidence_refs,f.blocker_code,
    f.result_summary,f.observed_minutes,f.interaction_surface,f.heavy_session_used,
    f.manual_context_transfers,false;
end;
$_$;


--
-- Name: propose_sourced_work_request_plan(text, integer, text, text, jsonb, text, text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_sourced_work_request_plan(p_work_request text, p_base_version integer, p_scope_summary text, p_runbook_ref text, p_dependency_refs jsonb, p_recovery_ref text, p_observability_ref text, p_caps jsonb, p_idempotency_key uuid) RETURNS TABLE(plan_id uuid, plan_ref text, plan_hash text, work_request_id uuid, ref text, state text, version integer, runbook_ref text, runbook_revision_id uuid, runbook_content_hash text, scope_summary text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype; p ops.sourced_work_request_plan%rowtype;
  rb_section_id uuid; rb_revision_id uuid; rb_content_hash text;
  normalized_scope text; normalized_runbook text; normalized_recovery text; normalized_observability text;
  next_plan_version integer; canonical_preimage jsonb; canonical_hash text;
begin
  normalized_scope := btrim(p_scope_summary); normalized_runbook := btrim(p_runbook_ref);
  normalized_recovery := btrim(p_recovery_ref); normalized_observability := btrim(p_observability_ref);
  if p_idempotency_key is null or p_base_version is null or p_base_version < 1
     or coalesce(normalized_scope,'') = '' or char_length(normalized_scope) > 1000
     or coalesce(normalized_runbook,'') !~ '^doctrine:runbook#[a-z0-9][a-z0-9-]*$'
     or coalesce(normalized_recovery,'') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(normalized_recovery) > 300
     or coalesce(normalized_observability,'') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(normalized_observability) > 300 then
    raise exception 'invalid bounded sourced plan';
  end if;
  if jsonb_typeof(p_dependency_refs) is distinct from 'array' or jsonb_array_length(p_dependency_refs) > 12
     or exists (select 1 from jsonb_array_elements(p_dependency_refs) v where jsonb_typeof(v) <> 'string' or v #>> '{}' !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(v #>> '{}') > 300)
     or exists (select v #>> '{}' from jsonb_array_elements(p_dependency_refs) v group by v #>> '{}' having count(*) > 1) then
    raise exception 'invalid bounded sourced plan dependency references';
  end if;
  if jsonb_typeof(p_caps) is distinct from 'object'
     or (select array_agg(k order by k) from jsonb_object_keys(p_caps) k) is distinct from array['max_duration_minutes','max_steps']::text[]
     or coalesce(p_caps->>'max_steps','') !~ '^[0-9]+$' or coalesce(p_caps->>'max_duration_minutes','') !~ '^[0-9]+$'
     or (p_caps->>'max_steps')::integer not between 1 and 20 or (p_caps->>'max_duration_minutes')::integer not between 1 and 120 then
    raise exception 'invalid bounded sourced plan caps';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-plan-proposal:' || p_idempotency_key, 0));
  select x.* into p from ops.sourced_work_request_plan x where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into w from ops.work_request x where x.id=p.work_request_id for share;
    if not found or w.ref is distinct from p_work_request or p.work_request_version is distinct from p_base_version
       or p.scope_summary is distinct from normalized_scope or p.runbook_ref is distinct from normalized_runbook
       or p.dependency_refs is distinct from p_dependency_refs or p.recovery_ref is distinct from normalized_recovery
       or p.observability_ref is distinct from normalized_observability or p.caps is distinct from p_caps then
      raise exception 'idempotency key already names a different sourced plan proposal';
    end if;
    return query select p.id,p.plan_ref,p.plan_hash,w.id,w.ref,'triaged'::text,p.work_request_version,
      p.runbook_ref,p.runbook_revision_id,'sha256:' || p.runbook_content_hash,p.scope_summary,true;
    return;
  end if;

  select x.* into w from ops.work_request x where x.ref=p_work_request for update;
  if not found or w.state is distinct from 'triaged' or w.version is distinct from p_base_version
     or w.capture_idempotency_key is null or w.organization_tenant_id is distinct from 'carr-internal' then
    raise exception 'exact current triaged sourced Work Request required';
  end if;
  if not (
    ((w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
       is not distinct from (null::text,null::text,null::text,null::uuid,null::timestamptz)
      and not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id=w.id))
    or
    (w.shape_disposition='required' and w.shape_fixed_surface_ref is null and w.shape_rationale is not null and btrim(w.shape_rationale) <> ''
      and exists (select 1 from ops.sourced_work_request_shape_disposition_receipt r where r.work_request_id=w.id and r.result_version=w.version
                    and (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
                        is not distinct from (r.disposition,r.fixed_surface_ref,r.rationale,r.decided_by_actor_id,r.decided_at))
      and (select sr.work_request_version from ops.work_shape_revision sr where sr.work_request_id=w.id order by sr.version desc limit 1)=w.version)
    or
    (w.shape_disposition='not_required' and w.shape_fixed_surface_ref is not null and btrim(w.shape_fixed_surface_ref) <> ''
      and w.shape_rationale is not null and btrim(w.shape_rationale) <> ''
      and exists (select 1 from ops.sourced_work_request_shape_disposition_receipt r where r.work_request_id=w.id and r.result_version=w.version
                    and (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
                        is not distinct from (r.disposition,r.fixed_surface_ref,r.rationale,r.decided_by_actor_id,r.decided_at))
      and not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id=w.id))
  ) then
    raise exception 'exact unshaped or current receipt-backed shaped triaged sourced Work Request required';
  end if;

  perform 1 from public.doctrine_document source_document join public.doctrine_section source_section on source_section.document_id=source_document.id
    join public.doctrine_revision source_revision on source_revision.id=source_section.current_revision_id and source_revision.section_id=source_section.id
   where source_document.visibility='shared' and source_section.status='active' and source_section.id=w.doctrine_section_id
     and source_revision.id=w.doctrine_revision_id and source_revision.content_hash ~ '^[0-9a-f]{64}$'
     and encode(public.digest(source_revision.plain_text,'sha256'),'hex')=source_revision.content_hash
     and source_revision.body=jsonb_build_object('text',source_revision.plain_text)
   for share of source_document,source_section,source_revision;
  if not found then raise exception 'sourced Work Request evidence is no longer exact, current, active, and shared'; end if;
  select s.id,r.id,r.content_hash into rb_section_id,rb_revision_id,rb_content_hash
    from public.doctrine_document d join public.doctrine_section s on s.document_id=d.id
    join public.doctrine_revision r on r.id=s.current_revision_id and r.section_id=s.id
   where d.slug='runbook' and d.visibility='shared' and s.status='active'
     and ('doctrine:' || d.slug || '#' || s.section_key)=normalized_runbook and r.content_hash ~ '^[0-9a-f]{64}$'
     and encode(public.digest(r.plain_text,'sha256'),'hex')=r.content_hash and r.body=jsonb_build_object('text',r.plain_text)
   for share of d,s,r;
  if not found then raise exception 'runbook must be an exact current active shared doctrine revision'; end if;
  select coalesce(max(x.plan_version),0)+1 into next_plan_version from ops.sourced_work_request_plan x where x.work_request_id=w.id;
  canonical_preimage := ops.sourced_work_request_plan_preimage(w.id,normalized_scope,normalized_runbook,rb_section_id,rb_revision_id,rb_content_hash,p_dependency_refs,normalized_recovery,normalized_observability,p_caps);
  canonical_hash := ops.sourced_work_request_plan_digest(canonical_preimage);
  if exists (select 1 from ops.sourced_work_request_plan x where x.work_request_id=w.id and x.plan_hash=canonical_hash) then
    raise exception 'the exact sourced plan already exists under a different idempotency key';
  end if;
  insert into ops.sourced_work_request_plan (work_request_id,plan_version,idempotency_key,work_request_version,preimage,scope_summary,runbook_ref,runbook_section_id,runbook_revision_id,runbook_content_hash,dependency_refs,recovery_ref,observability_ref,caps,plan_hash,plan_ref)
  values (w.id,next_plan_version,p_idempotency_key,w.version,canonical_preimage,normalized_scope,normalized_runbook,rb_section_id,rb_revision_id,rb_content_hash,p_dependency_refs,normalized_recovery,normalized_observability,p_caps,canonical_hash,'PLAN-' || substr(canonical_hash,8,12) || '-v' || next_plan_version)
  returning * into p;
  return query select p.id,p.plan_ref,p.plan_hash,w.id,w.ref,w.state,w.version,p.runbook_ref,p.runbook_revision_id,'sha256:' || p.runbook_content_hash,p.scope_summary,false;
end;
$_$;


--
-- Name: protect_staging_readback_deployment(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.protect_staging_readback_deployment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (select 1 from ops.staging_release_readback_receipt where deployment_id=old.id) then
    raise exception 'Program 5 evidence deployment is append-only';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


--
-- Name: put_cognition_cache(text, text, integer, integer, jsonb, text[], integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.put_cognition_cache(p_cache_key text, p_cognition_key text, p_cognition_version integer, p_output_schema_version integer, p_proposal jsonb, p_dependency_refs text[], p_ttl_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if p_ttl_seconds < 1 then raise exception 'positive cache TTL is required'; end if;
  insert into ops.cognition_result_cache
    (cache_key,cognition_key,cognition_version,output_schema_version,proposal,
     dependency_refs,validated_at,expires_at)
  values(p_cache_key,p_cognition_key,p_cognition_version,p_output_schema_version,p_proposal,
         coalesce(p_dependency_refs,'{}'),now(),now()+make_interval(secs=>p_ttl_seconds))
  on conflict(cache_key) do update set
    proposal=excluded.proposal,dependency_refs=excluded.dependency_refs,
    validated_at=excluded.validated_at,expires_at=excluded.expires_at,invalidated_at=null;
  return true;
end $$;


--
-- Name: put_cognition_cache_for_job(uuid, uuid, text, text, integer, integer, jsonb, text[], integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.put_cognition_cache_for_job(p_job_id uuid, p_lease_token uuid, p_cache_key text, p_cognition_key text, p_cognition_version integer, p_output_schema_version integer, p_proposal jsonb, p_dependency_refs text[], p_ttl_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; execution_kind text; declared_cognition_key text; active_contract_count integer; contract ops.cognition_job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select d.execution_kind,d.execution_contract->>'cognition_job'
    into execution_kind,declared_cognition_key from ops.job_definition d
   where d.key=j.definition_key and d.version=j.definition_version;
  if execution_kind is distinct from 'cognition'
     or declared_cognition_key is distinct from p_cognition_key then
    raise exception 'job % is not bound to cognition contract %',p_job_id,p_cognition_key;
  end if;
  select count(*) into active_contract_count from ops.cognition_job where key=declared_cognition_key and active;
  if active_contract_count <> 1 then raise exception 'job % lacks one active cognition contract',p_job_id; end if;
  select * into contract from ops.cognition_job where key=declared_cognition_key and active;
  if p_cognition_key<>contract.key or p_cognition_version<>contract.version
     or p_output_schema_version<>contract.output_schema_version then
    raise exception 'cache write does not match active cognition contract';
  end if;
  if btrim(coalesce(p_cache_key,''))='' or p_ttl_seconds<1 then
    raise exception 'cache key and positive cache TTL are required';
  end if;
  insert into ops.cognition_result_cache
    (cache_key,cognition_key,cognition_version,output_schema_version,proposal,
     dependency_refs,validated_at,expires_at)
  values (p_cache_key,p_cognition_key,p_cognition_version,p_output_schema_version,p_proposal,
          coalesce(p_dependency_refs,'{}'),now(),now()+make_interval(secs=>p_ttl_seconds))
  on conflict(cache_key) do update set proposal=excluded.proposal,
    dependency_refs=excluded.dependency_refs,validated_at=excluded.validated_at,
    expires_at=excluded.expires_at,invalidated_at=null;
  insert into ops.cognition_cache_observation
    (job_id,attempt,workflow_key,workflow_version,mode,cache_key,observation_kind)
  values (j.id,j.attempt,j.definition_key,j.definition_version,j.mode,p_cache_key,'store')
  on conflict (job_id,attempt,cache_key,observation_kind) do nothing;
  return true;
end $$;


--
-- Name: read_attempt_receipt_reliability(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_attempt_receipt_reliability(p_attempt_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id',true); receipt_row ops.attempt_receipt%rowtype; envelope_row ops.execution_envelope_v1%rowtype;
  expected jsonb; have jsonb; final_state text; reasons jsonb; binding ops.context_activation_binding%rowtype; candidate_refs jsonb; lifecycle_value text; telemetry jsonb; authority_fact_count integer; learning_event_count integer; outcome_horizon_mature boolean;
begin
  select * into receipt_row from ops.attempt_receipt where organization_tenant_id=tenant and attempt_id=p_attempt_id;
  select * into envelope_row from ops.execution_envelope_v1 where id=receipt_row.execution_envelope_id and organization_tenant_id=tenant;
  select * into binding from ops.context_activation_binding where id=receipt_row.activation_binding_id and organization_tenant_id=tenant;
  if receipt_row.id is null or envelope_row.id is null then raise exception 'attempt reliability is not visible to tenant'; end if;
  select coalesce(jsonb_agg(value order by value),'[]'::jsonb) into expected from jsonb_array_elements_text(envelope_row.evaluation_plan->'required_deterministic_check_refs') value;
  -- Projection ordering is server-derived, not room arrival order.  Each
  -- append-only authority fact/event can only raise its count; the horizon
  -- bit can only advance from immature to mature for the frozen issued plan.
  select count(*)::integer into authority_fact_count from ops.attempt_receipt_evaluation_attestation where attempt_receipt_id=receipt_row.id;
  select count(*)::integer into learning_event_count from ops.proposed_eval_candidate_event e join ops.proposed_eval_candidate p on p.id=e.candidate_id where p.attempt_receipt_id=receipt_row.id;
  outcome_horizon_mature := clock_timestamp() >= (envelope_row.evaluation_plan->>'outcome_horizon_not_before')::timestamptz;
  select coalesce(jsonb_agg(a.check_ref order by a.check_ref),'[]'::jsonb) into have from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='deterministic' and a.status='passed';
  if exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='deterministic' and a.status in ('failed','blocked')) then
    final_state := 'blocked'; reasons := jsonb_build_array('reason:critical_deterministic_or_evaluator_failure');
  elsif exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='judge' and a.independent and a.status in ('failed','blocked'))
     or exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='human_acceptance' and a.status in ('failed','blocked')) then
    final_state := 'blocked'; reasons := jsonb_build_array('reason:critical_authority_evaluator_or_human_rejection');
  elsif have is distinct from expected
     or not exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='judge' and a.status='passed' and a.independent and a.confidence in ('high','medium') and a.lower_bound_ref is not null and jsonb_array_length(a.calibration_refs) >= coalesce((envelope_row.evaluation_plan->'requirements'->>'minimum_calibration_ref_count')::integer,1) and a.held_out_case_count >= coalesce((envelope_row.evaluation_plan->'requirements'->>'minimum_held_out_case_count')::integer,1))
     or not exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='human_acceptance' and a.status='passed' and a.outcome_feedback_ref is not null and a.outcome_feedback_hash is not null)
     or not exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='outcome_horizon' and a.status='mature' and clock_timestamp() >= (envelope_row.evaluation_plan->>'outcome_horizon_not_before')::timestamptz) then
    final_state := 'insufficient_evidence'; reasons := jsonb_build_array('reason:canonical_evaluation_coverage_incomplete');
  else final_state := 'eligible_for_human_review'; reasons := '[]'::jsonb;
  end if;
  select coalesce(jsonb_agg('candidate:'||p.id::text order by p.created_at,p.id),'[]'::jsonb), coalesce((array_agg(e.event_kind order by e.created_at desc,e.id desc))[1],'none') into candidate_refs,lifecycle_value from ops.proposed_eval_candidate p left join lateral (select id,event_kind,created_at from ops.proposed_eval_candidate_event where candidate_id=p.id order by created_at desc,id desc limit 1) e on true where p.attempt_receipt_id=receipt_row.id;
  select coalesce(jsonb_agg(jsonb_build_object('signal_id',signal_id,'state',state,'trigger_ref',trigger_ref,'consumer_ref',consumer_ref,'enforcement',enforcement,'owner_ref',owner_ref,'remedy_ref',remedy_ref,'verification_ref',verification_ref,'auto_clear',auto_clear) order by signal_id),'[]'::jsonb) into telemetry from ops.activation_reliability_telemetry where attempt_receipt_id=receipt_row.id;
  return jsonb_build_object('canonical_binding',jsonb_build_object('work_request_id',(select ref from ops.work_request where id=receipt_row.work_request_id),'work_request_version',binding.work_request_version,'accepted_plan_digest',receipt_row.plan_hash,'envelope_digest',receipt_row.envelope_digest,'attempt_id',receipt_row.attempt_id,'activation_binding_ref',binding.binding_id),'canonical_revision',jsonb_build_object('authority_fact_count',authority_fact_count,'learning_event_count',learning_event_count,'outcome_horizon_mature',outcome_horizon_mature),'learning',jsonb_build_object('lifecycle',lifecycle_value,'candidate_refs',candidate_refs),'telemetry',telemetry,'reliability',jsonb_build_object('state',final_state,'reasons',reasons,'derived_by','canonical_authority_evaluation','outcome_horizon_state',case when outcome_horizon_mature then 'mature' else 'immature' end,'outcome_horizon_not_before',envelope_row.evaluation_plan->>'outcome_horizon_not_before'));
end $$;


--
-- Name: read_calendar_prebrief_joe_activation(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_calendar_prebrief_joe_activation(p_id uuid) RETURNS TABLE(id uuid, sponsor text, app_evidence_digest text, allowlist_revision_id uuid, activated_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$ select id,sponsor,app_evidence_digest,allowlist_revision_id,activated_at from ops.calendar_prebrief_runtime_activation_receipt where id=p_id and session_user='carr_authority_joe' $$;


--
-- Name: read_context_activation(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_context_activation(p_work_request text, p_binding_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  -- This is the source-linked read spine consumed by Job Passport, Model
  -- Room, Observatory, and Hermes.  It deliberately reports canary evidence
  -- as unavailable until a receipt/evaluation is recorded; it does not
  -- manufacture a production posture from the feature mode alone.
  select jsonb_build_object(
    'binding',to_jsonb(b),
    'items',coalesce(jsonb_agg(to_jsonb(i) order by i.ordinal),'[]'::jsonb),
    'execution_envelopes',(select coalesce(jsonb_agg(jsonb_build_object(
      'envelope_digest',e.envelope_digest,'runtime_profile',e.runtime_profile,
      'execution_topology',e.execution_topology,'evaluation_plan',e.evaluation_plan,
      'configuration_digest',e.configuration_digest,'issued_at',e.issued_at,'expires_at',e.expires_at
    ) order by e.issued_at),'[]'::jsonb) from ops.execution_envelope_v1 e where e.activation_binding_id=b.id),
    'attempt_receipts',(select coalesce(jsonb_agg(jsonb_build_object(
      'attempt_id',r.attempt_id,'envelope_digest',r.envelope_digest,
      'knowledge_activation',r.receipt->'knowledge_activation','reliability',r.receipt->'reliability','created_at',r.created_at
    ) order by r.created_at),'[]'::jsonb) from ops.attempt_receipt r where r.activation_binding_id=b.id),
    'learning',(select coalesce(jsonb_agg(jsonb_build_object(
      'candidate_ref',p.candidate_ref,'case_ref',p.case_ref,
      'lifecycle',coalesce((select event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=p.id order by pe.created_at desc,pe.id desc limit 1),p.lifecycle),
      'promotion_state',p.promotion_state,'provenance',p.provenance,
      'lane_ref',p.lane_ref,'risk_class',p.risk_class,'split_target',p.split_target,
      'source_digest',p.source_digest,'source_ref','attempt:'||r.attempt_id,
      'basis',p.basis,'created_at',p.created_at,
      'golden_membership',jsonb_build_object(
        'target_golden_set_ref',p.target_golden_set_ref,
        'ever_accepted',exists(select 1 from ops.accepted_eval_golden_membership gm where gm.candidate_id=p.id),
        'active',coalesce((select event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=p.id order by pe.created_at desc,pe.id desc limit 1),'proposed')='accepted'
      )
    ) order by p.created_at,p.id),'[]'::jsonb) from ops.proposed_eval_candidate p join ops.attempt_receipt r on r.id=p.attempt_receipt_id where r.activation_binding_id=b.id),
    'evidence_register',jsonb_build_object(
      'work_request_ref',p_work_request,
      'source_ref','plan:'||b.plan_id::text,
      'source_digest',b.plan_hash,
      'admission_ref','activation:'||b.binding_id,
      'retrieval_evidence_ref','context-bundle:'||b.bundle_digest,
      'operator_surface','job-passport:context-activation',
      'telemetry_ref','observatory:activation-reliability:'||b.binding_id,
      'canary',jsonb_build_object('posture',b.mode,
        'evidence_availability',case when exists(select 1 from ops.attempt_receipt r where r.activation_binding_id=b.id) then 'recorded_redacted' else 'not_recorded' end,
        'evidence_ref',case when exists(select 1 from ops.attempt_receipt r where r.activation_binding_id=b.id) then 'attempt-receipt:'||b.binding_id else null end),
      'rollback_ref',coalesce((select recovery_ref from ops.sourced_work_request_plan where id=b.plan_id), 'not_configured'),
      'freshness',jsonb_build_object('state',case when b.expires_at < now() then 'stale' else 'fresh' end,'expires_at',b.expires_at),
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'source_ref',i.canonical_ref,'source_digest',i.content_digest,
        'consumer',i.consumer_ref,'trigger',i.trigger_ref,
        'admission_ref','activation:'||b.binding_id,
        'retrieval_evidence_ref','context-bundle:'||b.bundle_digest,
        'enforcement',case when i.required then 'must-apply' else 'advisory-only' end,
        'operator_surface','job-passport:context-activation',
        'telemetry_ref','observatory:activation-reliability:'||b.binding_id,
        'canary_posture',b.mode,
        'rollback_ref',coalesce((select recovery_ref from ops.sourced_work_request_plan where id=b.plan_id), 'not_configured'),
        'freshness',i.freshness
      ) order by i.ordinal),'[]'::jsonb)
    )
  )
    from ops.context_activation_binding b left join ops.context_activation_item i on i.binding_id=b.id
   where b.organization_tenant_id=current_setting('carr.organization_tenant_id', true)
     and b.binding_id=p_binding_id and b.work_request_id=(select id from ops.work_request where ref=p_work_request and organization_tenant_id=current_setting('carr.organization_tenant_id', true))
   group by b.id;
$$;


--
-- Name: reap_expired_jobs(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reap_expired_jobs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  with expired as materialized (
    select j.id,j.attempt
      from ops.job j
     where j.state='running' and j.leased_until < now()
     for update skip locked
  ), attempts as (
    update ops.job_attempt a
       set state='timed_out',ended_at=now(),failure_class='lease_expired',detail='lease expired'
      from expired e
     where a.job_id=e.id and a.attempt=e.attempt and a.state='running'
    returning a.job_id
  ), transitioned as (
    update ops.job j
       set state=case when j.attempt < j.max_attempts then 'retry_wait' else 'dead_lettered' end,
           next_attempt_at=case when j.attempt < j.max_attempts
                                then now()+make_interval(secs=>ops.retry_delay_seconds(j))
                                else j.next_attempt_at end,
           ended_at=case when j.attempt < j.max_attempts then null else now() end,
           last_failure_class='lease_expired',last_failure_detail='lease expired',
           lease_owner=null,lease_token=null,leased_until=null,updated_at=now()
      from expired e
     where j.id=e.id
    returning j.id,j.attempt,j.state
  ), receipts as (
    insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    select t.id,t.attempt,
           case when t.state='dead_lettered' then 'dead_letter' else 'timeout' end,
           concat('lease-expired:',t.id,':',t.attempt),
           jsonb_build_object('failure_class','lease_expired','next_state',t.state)
      from transitioned t
    returning id
  )
  select count(*) into n from transitioned;
  return n;
end $$;


--
-- Name: record_attempt_receipt(text, text, text, uuid, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_attempt_receipt(p_work_request text, p_plan_hash text, p_envelope_digest text, p_activation_binding_id uuid, p_receipt jsonb, p_idempotency_key uuid) RETURNS TABLE(attempt_receipt_id uuid, attempt_id text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id', true); existing ops.attempt_receipt%rowtype; work_id uuid; envelope_id uuid;
begin
  if coalesce(tenant,'')='' then raise exception 'reliability record requires authenticated tenant context'; end if;
  select w.id into work_id from ops.work_request w
   join ops.context_activation_binding b on b.id=p_activation_binding_id and b.work_request_id=w.id
   join ops.sourced_work_request_plan p on p.id=b.plan_id
   join ops.sourced_work_request_plan_acceptance_receipt ar on ar.work_request_id=w.id and ar.plan_id=p.id
   where w.ref=p_work_request and w.organization_tenant_id=tenant and b.organization_tenant_id=tenant
     and b.expires_at>=now() and w.version=b.work_request_version and p.work_request_id=w.id
     and p.plan_hash=p_plan_hash and b.plan_hash=p_plan_hash
     and ar.plan_hash=p_plan_hash and ar.result_version=w.version;
  if work_id is null then raise exception 'reliability Work Request is not visible to tenant'; end if;
  if jsonb_typeof(p_receipt) <> 'object' or p_receipt->>'schema_version' <> 'attempt-receipt.v1'
     or p_receipt->>'envelope_digest' <> p_envelope_digest or coalesce(p_receipt->>'attempt_id','') = '' then
    raise exception 'exact attempt receipt v1/envelope binding is required';
  end if;
  select id into envelope_id from ops.execution_envelope_v1
   where organization_tenant_id=tenant and work_request_id=work_id and plan_hash=p_plan_hash
     and activation_binding_id=p_activation_binding_id and envelope_digest=p_envelope_digest;
  if envelope_id is null then raise exception 'attempt receipt requires exact server-issued execution envelope'; end if;
  select * into existing from ops.attempt_receipt where organization_tenant_id=tenant and idempotency_key=p_idempotency_key;
  if found then
    if existing.work_request_id<>work_id or existing.attempt_id<>p_receipt->>'attempt_id' or existing.envelope_digest<>p_envelope_digest or existing.receipt is distinct from p_receipt then raise exception 'attempt receipt idempotency conflict'; end if;
    return query select existing.id, existing.attempt_id, true; return;
  end if;
  insert into ops.attempt_receipt(idempotency_key,organization_tenant_id,work_request_id,plan_hash,envelope_digest,attempt_id,activation_binding_id,execution_envelope_id,receipt)
  values(p_idempotency_key,tenant,work_id,p_plan_hash,p_envelope_digest,p_receipt->>'attempt_id',p_activation_binding_id,envelope_id,p_receipt)
  returning id, ops.attempt_receipt.attempt_id into attempt_receipt_id, attempt_id;
  -- Observatory telemetry is generated from the admitted canonical receipt,
  -- never accepted from executor-supplied telemetry JSON.
  insert into ops.activation_reliability_telemetry(organization_tenant_id,attempt_receipt_id,signal_id,trigger_ref,consumer_ref,enforcement,owner_ref,remedy_ref,verification_ref,auto_clear,state)
  values(tenant,attempt_receipt_id,'telemetry:knowledge-activation','trigger:required-knowledge-closure','consumer:observatory','enforcement:block-reliability-closure','owner:execution-governance','remedy:resolve-required-activation','verification:canonical-receipt-binding',true,
    case when p_receipt->'knowledge_activation'->'closure'->>'state'='closed' then 'verified' else 'open' end);
  return query select attempt_receipt_id, attempt_id, false;
end $$;


--
-- Name: calendar_canary_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_canary_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    source_snapshot_id uuid NOT NULL,
    source_snapshot_digest text NOT NULL,
    source_contact_count integer NOT NULL,
    output_digest text NOT NULL,
    exact_count integer NOT NULL,
    domain_count integer NOT NULL,
    unknown_count integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT calendar_canary_receipt_domain_count_check CHECK ((domain_count >= 0)),
    CONSTRAINT calendar_canary_receipt_exact_count_check CHECK ((exact_count >= 0)),
    CONSTRAINT calendar_canary_receipt_output_digest_check CHECK ((output_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_canary_receipt_unknown_count_check CHECK ((unknown_count >= 0))
);


--
-- Name: record_calendar_canary_receipt(uuid, uuid, uuid, text, integer, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_calendar_canary_receipt(p_job_id uuid, p_lease uuid, p_source_snapshot_id uuid, p_output_digest text, p_exact integer, p_domain integer, p_unknown integer) RETURNS ops.calendar_canary_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare j ops.job%rowtype;s ops.calendar_canary_source_snapshot%rowtype;r ops.calendar_canary_receipt%rowtype;e ops.calendar_canary_receipt%rowtype;
begin
 j:=ops.calendar_canary_live_job(p_job_id,p_lease); select * into s from ops.calendar_canary_source_snapshot where id=p_source_snapshot_id and job_id=j.id and attempt=j.attempt;
 if not found then raise exception using errcode='22023',message='source snapshot is not bound to this job attempt'; end if;
 if p_output_digest!~'^[0-9a-f]{64}$' or p_exact<0 or p_domain<0 or p_unknown<0 then raise exception using errcode='22023',message='invalid calendar canary aggregate'; end if;
 insert into ops.calendar_canary_receipt(job_id,attempt,source_snapshot_id,source_snapshot_digest,source_contact_count,output_digest,exact_count,domain_count,unknown_count)
 values(j.id,j.attempt,s.id,s.snapshot_digest,s.contact_count,p_output_digest,p_exact,p_domain,p_unknown) on conflict(job_id,attempt) do nothing returning * into r;
 if found then return r; end if; select * into e from ops.calendar_canary_receipt where job_id=j.id and attempt=j.attempt;
 if e.source_snapshot_id<>s.id or e.output_digest<>p_output_digest or e.exact_count<>p_exact or e.domain_count<>p_domain or e.unknown_count<>p_unknown then raise exception using errcode='23505',message='calendar canary receipt replay conflicts with immutable attempt'; end if; return e;
end $_$;


--
-- Name: calendar_prebrief_source_attestation_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_source_attestation_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    lease_token uuid CONSTRAINT calendar_prebrief_source_attestation_recei_lease_token_not_null NOT NULL,
    sponsor text NOT NULL,
    attestor_identity text CONSTRAINT calendar_prebrief_source_attestation_attestor_identity_not_null NOT NULL,
    mode text NOT NULL,
    destination text CONSTRAINT calendar_prebrief_source_attestation_recei_destination_not_null NOT NULL,
    snapshot_at timestamp with time zone CONSTRAINT calendar_prebrief_source_attestation_recei_snapshot_at_not_null NOT NULL,
    allowlist_revision_id uuid CONSTRAINT calendar_prebrief_source_attesta_allowlist_revision_id_not_null NOT NULL,
    capture_challenge_id uuid CONSTRAINT calendar_prebrief_source_attestat_capture_challenge_id_not_null NOT NULL,
    allowlist_digest text CONSTRAINT calendar_prebrief_source_attestation__allowlist_digest_not_null NOT NULL,
    observed_calendar_keys text[] CONSTRAINT calendar_prebrief_source_attest_observed_calendar_keys_not_null NOT NULL,
    event_count integer CONSTRAINT calendar_prebrief_source_attestation_recei_event_count_not_null NOT NULL,
    canonical_event_digest text CONSTRAINT calendar_prebrief_source_attest_canonical_event_digest_not_null NOT NULL,
    collector_key_fingerprint text CONSTRAINT calendar_prebrief_source_att_collector_key_fingerprint_not_null NOT NULL,
    signature_sha256 text CONSTRAINT calendar_prebrief_source_attestation__signature_sha256_not_null NOT NULL,
    collector_version text CONSTRAINT calendar_prebrief_source_attestation_collector_version_not_null NOT NULL,
    attested_at timestamp with time zone DEFAULT now() CONSTRAINT calendar_prebrief_source_attestation_recei_attested_at_not_null NOT NULL,
    CONSTRAINT calendar_prebrief_source_attest_collector_key_fingerprint_check CHECK ((collector_key_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestati_canonical_event_digest_check CHECK ((canonical_event_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_re_attestor_identity_check CHECK ((attestor_identity = ANY (ARRAY['carr_calendar_prebrief_attestor_joe'::text, 'carr_calendar_prebrief_attestor_dell'::text]))),
    CONSTRAINT calendar_prebrief_source_attestation_re_collector_version_check CHECK ((collector_version ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_rec_allowlist_digest_check CHECK ((allowlist_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_rec_signature_sha256_check CHECK ((signature_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_destination_check CHECK ((destination = ANY (ARRAY['live'::text, 'calendar-prebrief-canary-joe'::text, 'calendar-prebrief-canary-dell'::text]))),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_event_count_check CHECK (((event_count >= 0) AND (event_count <= 128))),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_mode_check CHECK ((mode = ANY (ARRAY['live'::text, 'canary'::text]))),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: record_calendar_prebrief_verified_envelope(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, uuid, text, text[], text[], jsonb, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_calendar_prebrief_verified_envelope(p_job_id uuid, p_lease uuid, p_challenge_id uuid, p_scheduled_for timestamp with time zone, p_window_starts_at timestamp with time zone, p_window_ends_at timestamp with time zone, p_allowlist_revision_id uuid, p_allowlist_digest text, p_calendar_keys text[], p_observed_calendar_keys text[], p_events jsonb, p_destination text, p_collector_key_fingerprint text, p_signature_sha256 text, p_collector_version text) RETURNS ops.calendar_prebrief_source_attestation_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare v_job ops.job%rowtype; v_challenge ops.calendar_prebrief_capture_challenge%rowtype;
  v_existing ops.calendar_prebrief_source_attestation_receipt%rowtype; v_attestor_sponsor text;
  v_current_keys text[]; v_current_digest text; v_current_revision uuid; v_observed text[]; v_event_count integer; v_event_digest text;
begin
  v_attestor_sponsor:=ops.calendar_prebrief_attestor_sponsor();
  if p_challenge_id is null or p_signature_sha256 is null or p_signature_sha256 !~ '^[0-9a-f]{64}$'
     or p_collector_key_fingerprint is null or p_collector_key_fingerprint !~ '^[0-9a-f]{64}$'
     or p_collector_version is null or p_collector_version !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$' then
    raise exception using errcode='22023',message='calendar prebrief verified envelope requires bounded signed claim and collector evidence';
  end if;
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief verified envelope requires current live job lease';
  end if;
  select * into v_challenge from ops.calendar_prebrief_capture_challenge where id=p_challenge_id for update;
  if not found or v_challenge.job_id<>v_job.id or v_challenge.attempt<>v_job.attempt or v_challenge.lease_token<>p_lease
     or v_challenge.sponsor<>v_attestor_sponsor or v_challenge.scheduled_for<>p_scheduled_for
     or v_challenge.window_starts_at<>p_window_starts_at or v_challenge.window_ends_at<>p_window_ends_at
     or v_challenge.allowlist_revision_id<>p_allowlist_revision_id or v_challenge.allowlist_digest<>p_allowlist_digest
     or v_challenge.calendar_keys is distinct from p_calendar_keys or v_challenge.destination<>p_destination or v_challenge.mode<>v_job.mode then
    raise exception using errcode='42501',message='calendar prebrief verified envelope signed claim does not match its DB-issued capture contract';
  end if;
  select calendar_keys,configuration_digest,active_revision_id into v_current_keys,v_current_digest,v_current_revision
    from ops.calendar_prebrief_allowed_calendar where sponsor=v_challenge.sponsor for update;
  if not found or v_current_revision<>v_challenge.allowlist_revision_id or v_current_digest<>v_challenge.allowlist_digest
     or v_current_keys is distinct from v_challenge.calendar_keys then
    raise exception using errcode='22023',message='calendar prebrief verified envelope capture contract is stale against DB allowlist';
  end if;
  select array_agg(k order by k) into v_observed from unnest(coalesce(p_observed_calendar_keys,'{}'::text[])) keys(k);
  if v_observed is distinct from v_challenge.calendar_keys then
    raise exception using errcode='22023',message='calendar prebrief verified envelope requires exact signed allowlist coverage';
  end if;
  select event_count,canonical_event_digest into v_event_count,v_event_digest from ops.calendar_prebrief_canonical_event_digest(p_events);
  perform pg_advisory_xact_lock(hashtextextended('calendar-prebrief-source:' || v_job.id::text,0));
  select * into v_existing from ops.calendar_prebrief_source_attestation_receipt where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_existing.capture_challenge_id<>p_challenge_id or v_existing.lease_token<>p_lease or v_existing.sponsor<>v_challenge.sponsor
       or v_existing.attestor_identity<>session_user or v_existing.mode<>v_challenge.mode or v_existing.destination<>p_destination
       or v_existing.snapshot_at<>p_scheduled_for or v_existing.allowlist_revision_id<>p_allowlist_revision_id
       or v_existing.allowlist_digest<>p_allowlist_digest or v_existing.observed_calendar_keys is distinct from v_observed
       or v_existing.event_count<>v_event_count or v_existing.canonical_event_digest<>v_event_digest
       or v_existing.collector_key_fingerprint<>p_collector_key_fingerprint or v_existing.signature_sha256<>p_signature_sha256
       or v_existing.collector_version<>p_collector_version then
      raise exception using errcode='23505',message='calendar prebrief verified envelope replay conflicts with immutable attempt';
    end if;
    return v_existing;
  end if;
  if exists(select 1 from ops.calendar_prebrief_source_attestation_receipt where capture_challenge_id=p_challenge_id or signature_sha256=p_signature_sha256) then
    raise exception using errcode='23505',message='calendar prebrief verified envelope challenge or signature was already consumed';
  end if;
  insert into ops.calendar_prebrief_source_attestation_receipt
    (job_id,attempt,lease_token,sponsor,attestor_identity,mode,destination,snapshot_at,allowlist_revision_id,capture_challenge_id,allowlist_digest,observed_calendar_keys,event_count,canonical_event_digest,collector_key_fingerprint,signature_sha256,collector_version)
  values(v_job.id,v_job.attempt,p_lease,v_challenge.sponsor,session_user,v_challenge.mode,p_destination,p_scheduled_for,p_allowlist_revision_id,p_challenge_id,p_allowlist_digest,v_observed,v_event_count,v_event_digest,p_collector_key_fingerprint,p_signature_sha256,p_collector_version)
  returning * into v_existing;
  return v_existing;
end $_$;


--
-- Name: record_claude_scheduler_observation(text, text, text, text, boolean, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_claude_scheduler_observation(p_surface_id text, p_provider_task_id text, p_cron_expression text, p_timezone text, p_enabled boolean, p_definition_sha256 text, p_provider_revision text, p_source_fingerprint text, p_observed_at timestamp with time zone, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  principal ops.device_evidence_principal%rowtype;
  contract ops.legacy_schedule_provider_contract%rowtype;
  existing ops.legacy_schedule_observation_receipt%rowtype;
  state text;
  ref text;
begin
  select * into principal from ops.device_evidence_principal
   where login_role=session_user and active;
  if not found then
    raise exception 'scheduler observation session user is not an active provisioned device principal';
  end if;
  if btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'scheduler observation idempotency key is required';
  end if;
  if btrim(coalesce(p_surface_id,''))='' or btrim(coalesce(p_provider_task_id,''))=''
     or btrim(coalesce(p_cron_expression,''))='' or btrim(coalesce(p_timezone,''))=''
     or p_enabled is null then
    raise exception 'scheduler observation identity, recurrence, and state are required';
  end if;
  if p_observed_at > now() + interval '5 minutes'
     or p_observed_at < now() - interval '15 minutes' then
    raise exception 'scheduler observation is outside the freshness window';
  end if;
  if coalesce(p_definition_sha256,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source_fingerprint,'') !~ '^[0-9a-f]{64}$'
     or btrim(coalesce(p_provider_revision,''))='' then
    raise exception 'scheduler observation provenance is malformed';
  end if;

  select * into contract from ops.legacy_schedule_provider_contract
   where surface_id=p_surface_id for share;
  if not found then raise exception 'scheduler provider surface is not registered'; end if;
  if p_provider_task_id <> contract.locator
     or p_cron_expression <> contract.cron_expression
     or p_timezone <> contract.timezone
     or p_definition_sha256 <> contract.definition_sha256 then
    raise exception 'scheduler observation does not match the registered provider contract';
  end if;
  state := case when p_enabled then 'enabled' else 'disabled' end;

  select * into existing from ops.legacy_schedule_observation_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.surface_id<>p_surface_id or existing.locator<>p_provider_task_id
       or existing.scheduler_state<>state or existing.cron_expression<>p_cron_expression
       or existing.timezone<>p_timezone or existing.definition_sha256<>p_definition_sha256
       or existing.provider_revision<>p_provider_revision
       or existing.source_fingerprint<>p_source_fingerprint
       or existing.observed_at<>p_observed_at or existing.device_id<>principal.device_id then
      raise exception 'scheduler observation idempotency key was reused with different evidence';
    end if;
    return existing.receipt_ref;
  end if;

  ref := 'scheduler-observation:' || p_idempotency_key;
  insert into ops.legacy_schedule_observation_receipt
    (receipt_ref,idempotency_key,surface_id,workflow_key,workflow_version,locator,
     scheduler_state,cron_expression,timezone,definition_sha256,provider_revision,
     source_fingerprint,observed_at,device_id)
  values
    (ref,p_idempotency_key,contract.surface_id,contract.workflow_key,contract.workflow_version,
     contract.locator,state,contract.cron_expression,contract.timezone,contract.definition_sha256,
     p_provider_revision,p_source_fingerprint,p_observed_at,principal.device_id);
  return ref;
end $_$;


--
-- Name: record_device_evidence(uuid, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_device_evidence(p_job_id uuid, p_builder_key text, p_observed_at timestamp with time zone, p_values jsonb, p_idempotency_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  principal ops.device_evidence_principal%rowtype;
  j ops.job%rowtype;
  existing ops.device_evidence_receipt%rowtype;
  expected_workflow text;
  expected_platform text;
  posts jsonb;
  post jsonb;
  result_id uuid;
begin
  select * into principal from ops.device_evidence_principal
   where login_role=session_user and active;
  if not found then
    raise exception 'device evidence session user is not an active provisioned principal';
  end if;

  select * into j from ops.job where id=p_job_id for share;
  if not found then raise exception 'device evidence job does not exist'; end if;
  if j.state not in ('queued','retry_wait','running') then
    raise exception 'device evidence job is not open for collection';
  end if;

  case p_builder_key
    when 'linkedin.source-posts' then
      expected_workflow := 'linkedin-engagement-daily';
      expected_platform := 'linkedin';
    when 'x.source-posts' then
      expected_workflow := 'x-reply-run-daily';
      expected_platform := 'x';
    else raise exception 'device evidence builder is not registered';
  end case;
  if j.definition_key <> expected_workflow then
    raise exception 'device evidence builder does not match ledger workflow';
  end if;
  if p_observed_at > now() + interval '5 minutes'
     or p_observed_at < j.scheduled_for - interval '24 hours'
     or p_observed_at > j.scheduled_for + interval '24 hours' then
    raise exception 'device evidence is outside the registered job freshness window';
  end if;
  if jsonb_typeof(p_values) <> 'object'
     or (p_values - array['platform','collector_state','source_posts','voice_version']) <> '{}'::jsonb
     or p_values->>'platform' <> expected_platform
     or p_values->>'collector_state' <> 'available'
     or jsonb_typeof(p_values->'voice_version') <> 'number'
     or (p_values->>'voice_version')::integer <= 0
     or jsonb_typeof(p_values->'source_posts') <> 'array' then
    raise exception 'device evidence envelope does not match the registered schema';
  end if;
  posts := p_values->'source_posts';
  if (p_builder_key='linkedin.source-posts' and jsonb_array_length(posts) not between 3 and 5)
     or (p_builder_key='x.source-posts' and jsonb_array_length(posts) not between 1 and 20) then
    raise exception 'device evidence post count is outside the registered range';
  end if;
  for post in select value from jsonb_array_elements(posts) loop
    if jsonb_typeof(post) <> 'object'
       or btrim(coalesce(post->>'url',''))='' then
      raise exception 'device evidence post lacks its source URL';
    end if;
    if p_builder_key='linkedin.source-posts'
       and jsonb_typeof(post->'network_priority') <> 'boolean' then
      raise exception 'LinkedIn device evidence lacks network priority';
    end if;
    if p_builder_key='x.source-posts'
       and btrim(coalesce(post->>'read_at',''))='' then
      raise exception 'X device evidence lacks actual-read timestamp';
    end if;
  end loop;

  select * into existing from ops.device_evidence_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.job_id<>p_job_id or existing.builder_key<>p_builder_key
       or existing.device_id<>principal.device_id
       or existing.observed_at<>p_observed_at or existing.evidence<>p_values then
      raise exception 'device evidence idempotency key was reused with different evidence';
    end if;
    return existing.id;
  end if;

  insert into ops.device_evidence_receipt
    (job_id,builder_key,workflow_key,workflow_version,mode,scheduled_for,
     device_id,observed_at,evidence,idempotency_key)
  values
    (j.id,p_builder_key,j.definition_key,j.definition_version,j.mode,j.scheduled_for,
     principal.device_id,p_observed_at,p_values,p_idempotency_key)
  returning id into result_id;
  return result_id;
end $$;


--
-- Name: record_executed_lease(text, integer, date, date, date, integer, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_executed_lease(p_deal text, p_base_version integer, p_executed_on date, p_commencement_on date, p_expiration_on date, p_term_months integer, p_evidence_kind text, p_evidence_ref text, p_source text) RETURNS TABLE(lease_id uuid, version integer, superseded_lease_id uuid, deal_id uuid, client_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_actor_slug text;
  v_actor_id uuid;
  v_deal_ids uuid[];
  v_deal_id uuid;
  v_client_id uuid;
  v_owner_id uuid;
  v_current_id uuid;
  v_current_version integer;
  v_new_id uuid;
  v_new_version integer;
begin
  v_actor_slug:=ops.authority_actor_slug();
  select id into v_actor_id from actor where slug=v_actor_slug and active;
  if v_actor_id is null then raise exception 'lease authority actor is unavailable'; end if;
  if nullif(btrim(coalesce(p_deal,'')),'') is null then raise exception 'deal is required'; end if;
  if p_deal ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select array_agg(id) into v_deal_ids from deal where id=p_deal::uuid;
  else
    select array_agg(id order by id) into v_deal_ids from deal where lower(name)=lower(btrim(p_deal));
  end if;
  if coalesce(array_length(v_deal_ids,1),0)=0 then raise exception 'lease deal was not found'; end if;
  if array_length(v_deal_ids,1)<>1 then raise exception 'lease deal needs exact disambiguation'; end if;
  v_deal_id:=v_deal_ids[1];

  perform pg_advisory_xact_lock(hashtextextended('executed-lease:'||v_deal_id::text,0));
  select d.client_id,
         coalesce((select dp.actor_id from deal_participant dp
                    where dp.deal_id=d.id and dp.role='lead' and dp.to_at is null limit 1),
                  c.created_by)
    into v_client_id,v_owner_id
    from deal d join client c on c.id=d.client_id
   where d.id=v_deal_id;
  if v_owner_id is distinct from v_actor_id then
    raise exception 'lease authority does not own the current deal';
  end if;
  if p_executed_on is null or p_expiration_on is null then
    raise exception 'executed_on and expiration_on are required';
  end if;
  if p_commencement_on is not null and p_expiration_on<=p_commencement_on then
    raise exception 'lease expiration must follow commencement';
  end if;
  if p_term_months is not null and (p_term_months<1 or p_term_months>480) then
    raise exception 'lease term_months is outside 1..480';
  end if;
  if p_evidence_kind not in ('executed_lease','lease_amendment','lease_abstract') then
    raise exception 'lease evidence kind is not admitted';
  end if;
  if nullif(btrim(coalesce(p_evidence_ref,'')),'') is null or length(p_evidence_ref)>1000 then
    raise exception 'lease evidence reference is required and bounded';
  end if;
  if nullif(btrim(coalesce(p_source,'')),'') is null or length(p_source)>500 then
    raise exception 'lease source is required and bounded';
  end if;

  select l.id,l.version into v_current_id,v_current_version
    from lease l where l.deal_id=v_deal_id and l.status='current' for update;
  if v_current_id is not null and p_base_version is distinct from v_current_version then
    raise exception 'lease version conflict: expected %',v_current_version;
  end if;
  if v_current_id is null and p_base_version is not null then
    raise exception 'no current lease exists for supplied base version';
  end if;
  if v_current_id is not null then
    update lease as held set status='superseded',superseded_at=now(),updated_by=v_actor_id
     where held.id=v_current_id and held.version=v_current_version and held.status='current';
    if not found then raise exception 'lease version conflict during replacement'; end if;
  end if;
  insert into lease
    (deal_id,client_id,owner_id,executed_on,commencement_on,expiration_on,term_months,
     evidence_kind,evidence_ref,source,created_by,updated_by,status,supersedes_lease_id)
  values
    (v_deal_id,v_client_id,v_actor_id,p_executed_on,p_commencement_on,p_expiration_on,p_term_months,
     p_evidence_kind,btrim(p_evidence_ref),btrim(p_source),v_actor_id,v_actor_id,'current',v_current_id)
  returning id,lease.version into v_new_id,v_new_version;
  lease_id:=v_new_id; version:=v_new_version; superseded_lease_id:=v_current_id;
  deal_id:=v_deal_id; client_id:=v_client_id;
  return next;
end $_$;


--
-- Name: record_guidance_decision(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_guidance_decision(p_revision_id uuid, p_state text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  authority_slug text;
  authority_actor uuid;
  item_id uuid;
  revision_hash text;
  receipt_id uuid;
  binding_id uuid;
  event_id uuid;
  receipt_kind text;
  receipt_decision text;
  existing record;
begin
  authority_slug := ops.authority_actor_slug();
  select id into authority_actor from actor
   where slug=authority_slug and kind='human';
  if authority_actor is null then
    raise exception 'guidance decision requires an admitted human authority actor';
  end if;
  if p_state not in ('active','retired','superseded') then
    raise exception 'unsupported guidance lifecycle decision %',p_state;
  end if;
  if coalesce(btrim(p_idempotency_key),'')='' or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance decision requires idempotency key and reason';
  end if;
  select guidance_item_id,ops.guidance_revision_contract_hash(id)
    into item_id,revision_hash
    from ops.guidance_revision where id=p_revision_id;
  if item_id is null or revision_hash is null then
    raise exception 'unknown guidance revision %',p_revision_id;
  end if;
  receipt_kind := case p_state
    when 'active' then 'activation'
    when 'retired' then 'rejection'
    else 'amendment' end;
  receipt_decision := case p_state
    when 'active' then 'approved'
    when 'retired' then 'retired'
    else 'superseded' end;

  select ar.id,ar.kind,ar.subject_type,ar.subject_id,ar.actor_id,ar.decision,
         ar.contract_hash,le.id as event_id
    into existing
    from ops.authority_receipt ar
    left join ops.guidance_authority_binding b on b.authority_receipt_id=ar.id
    left join ops.guidance_lifecycle_event le
      on le.authority_binding_id=b.id and le.state=p_state
   where ar.idempotency_key=p_idempotency_key;
  if existing.id is not null then
    if existing.kind<>receipt_kind or existing.subject_type<>'guidance'
       or existing.subject_id<>item_id or existing.actor_id<>authority_actor
       or existing.decision<>receipt_decision
       or existing.contract_hash is distinct from revision_hash
       or existing.event_id is null then
      raise exception 'idempotency key already names a different or incomplete guidance decision';
    end if;
    return existing.event_id;
  end if;

  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,
     contract_hash,evidence_refs)
  values
    (p_idempotency_key,receipt_kind,'guidance',item_id,authority_actor,
     receipt_decision,revision_hash,array[p_revision_id::text])
  returning id into receipt_id;
  insert into ops.guidance_authority_binding
    (guidance_revision_id,authority_receipt_id,contract_hash)
  values (p_revision_id,receipt_id,revision_hash)
  returning id into binding_id;
  insert into ops.guidance_lifecycle_event
    (guidance_revision_id,state,authority_binding_id,reason)
  values (p_revision_id,p_state,binding_id,p_reason)
  returning id into event_id;
  return event_id;
end $$;


--
-- Name: record_launchd_scheduler_observation(text, text, text, boolean, text, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_launchd_scheduler_observation(p_surface_id text, p_label text, p_timezone text, p_enabled boolean, p_plist_sha256 text, p_schedule_sha256 text, p_launchctl_revision text, p_source_fingerprint text, p_observed_at timestamp with time zone, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  principal ops.device_evidence_principal%rowtype;
  contract ops.legacy_schedule_launchd_contract%rowtype;
  existing ops.legacy_schedule_observation_receipt%rowtype;
  state text;
  ref text;
begin
  select * into principal from ops.device_evidence_principal
   where login_role=session_user and active;
  if not found then
    raise exception 'launchd observation session user is not an active provisioned device principal';
  end if;
  if btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'launchd observation idempotency key is required';
  end if;
  if btrim(coalesce(p_surface_id,''))='' or btrim(coalesce(p_label,''))=''
     or btrim(coalesce(p_timezone,''))='' or p_enabled is null then
    raise exception 'launchd observation identity, timezone, and state are required';
  end if;
  if p_observed_at > now() + interval '5 minutes'
     or p_observed_at < now() - interval '15 minutes' then
    raise exception 'launchd observation is outside the freshness window';
  end if;
  if coalesce(p_plist_sha256,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_schedule_sha256,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_launchctl_revision,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source_fingerprint,'') !~ '^[0-9a-f]{64}$' then
    raise exception 'launchd observation provenance is malformed';
  end if;

  select * into contract from ops.legacy_schedule_launchd_contract
   where surface_id=p_surface_id for share;
  if not found then raise exception 'launchd scheduler surface is not registered'; end if;
  if p_label <> contract.locator or p_timezone <> contract.timezone
     or p_plist_sha256 <> contract.plist_sha256
     or p_schedule_sha256 <> contract.schedule_sha256 then
    raise exception 'launchd observation does not match the registered native contract';
  end if;
  state := case when p_enabled then 'enabled' else 'disabled' end;

  select * into existing from ops.legacy_schedule_observation_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.surface_id is distinct from p_surface_id
       or existing.locator is distinct from p_label
       or existing.scheduler_kind is distinct from 'launchd'
       or existing.scheduler_state is distinct from state
       or existing.cron_expression is distinct from p_schedule_sha256
       or existing.timezone is distinct from p_timezone
       or existing.definition_sha256 is distinct from p_plist_sha256
       or existing.provider_revision is distinct from p_launchctl_revision
       or existing.source_fingerprint is distinct from p_source_fingerprint
       or existing.observed_at is distinct from p_observed_at
       or existing.device_id is distinct from principal.device_id then
      raise exception 'launchd observation idempotency key was reused with different evidence';
    end if;
    return existing.receipt_ref;
  end if;

  ref := 'scheduler-observation:' || p_idempotency_key;
  insert into ops.legacy_schedule_observation_receipt
    (receipt_ref,idempotency_key,surface_id,workflow_key,workflow_version,locator,
     scheduler_kind,scheduler_state,cron_expression,timezone,definition_sha256,
     provider_revision,source_fingerprint,observed_at,device_id)
  values
    (ref,p_idempotency_key,contract.surface_id,contract.workflow_key,contract.workflow_version,
     contract.locator,'launchd',state,contract.schedule_sha256,contract.timezone,
     contract.plist_sha256,p_launchctl_revision,p_source_fingerprint,p_observed_at,
     principal.device_id);
  return ref;
end $_$;


--
-- Name: nightly_availability_canary_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.nightly_availability_canary_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    source_snapshot_id uuid NOT NULL,
    source_snapshot_digest text CONSTRAINT nightly_availability_canary_rec_source_snapshot_digest_not_null NOT NULL,
    availability_count integer NOT NULL,
    open_search_count integer NOT NULL,
    match_count integer NOT NULL,
    output_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT nightly_availability_canary_receipt_availability_count_check CHECK ((availability_count >= 0)),
    CONSTRAINT nightly_availability_canary_receipt_match_count_check CHECK ((match_count >= 0)),
    CONSTRAINT nightly_availability_canary_receipt_open_search_count_check CHECK ((open_search_count >= 0)),
    CONSTRAINT nightly_availability_canary_receipt_output_digest_check CHECK ((output_digest ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: record_nightly_availability_canary_receipt(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_nightly_availability_canary_receipt(p_job_id uuid, p_lease uuid, p_source_snapshot_id uuid, p_output_digest text, p_match_count integer) RETURNS ops.nightly_availability_canary_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare j ops.job%rowtype;s ops.nightly_availability_canary_source_snapshot%rowtype;r ops.nightly_availability_canary_receipt%rowtype;e ops.nightly_availability_canary_receipt%rowtype;
begin
 j:=ops.nightly_availability_canary_live_job(p_job_id,p_lease);
 select * into s from ops.nightly_availability_canary_source_snapshot where id=p_source_snapshot_id and job_id=j.id and attempt=j.attempt;
 if not found then raise exception using errcode='22023',message='nightly availability source snapshot is not bound to this job attempt'; end if;
 if p_output_digest!~'^[0-9a-f]{64}$' or p_match_count<0 then raise exception using errcode='22023',message='invalid nightly availability canary aggregate'; end if;
 insert into ops.nightly_availability_canary_receipt(job_id,attempt,source_snapshot_id,source_snapshot_digest,availability_count,open_search_count,match_count,output_digest)
 values(j.id,j.attempt,s.id,s.snapshot_digest,s.availability_count,s.open_search_count,p_match_count,p_output_digest)
 on conflict(job_id,attempt) do nothing returning * into r;
 if found then return r; end if;
 select * into e from ops.nightly_availability_canary_receipt where job_id=j.id and attempt=j.attempt;
 if e.source_snapshot_id<>s.id or e.output_digest<>p_output_digest or e.match_count<>p_match_count then raise exception using errcode='23505',message='nightly availability canary receipt replay conflicts with immutable attempt'; end if;
 return e;
end $_$;


--
-- Name: record_npi_device_evidence(uuid, timestamp with time zone, text, text, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_npi_device_evidence(p_job_id uuid, p_observed_at timestamp with time zone, p_source_release text, p_source_checksum text, p_results jsonb, p_idempotency_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare principal ops.device_evidence_principal%rowtype; j ops.job%rowtype;
        existing ops.npi_device_evidence_receipt%rowtype; result jsonb; item jsonb; rid uuid;
begin
  select * into principal from ops.device_evidence_principal where login_role=session_user and active;
  if not found then raise exception 'NPI evidence session user is not an active provisioned principal'; end if;
  select * into j from ops.job where id=p_job_id for share;
  if not found or j.definition_key<>'npi-sweep-weekly' or j.state not in ('queued','retry_wait','running') then
    raise exception 'NPI evidence must bind an open npi-sweep-weekly ledger job'; end if;
  if p_observed_at < j.scheduled_for-interval '24 hours' or p_observed_at > j.scheduled_for+interval '24 hours'
     or p_observed_at > now()+interval '5 minutes' then raise exception 'NPI evidence is outside its ledger freshness window'; end if;
  if btrim(coalesce(p_source_release,''))='' or coalesce(p_source_checksum,'') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_results)<>'array' or jsonb_array_length(p_results)=0 then
    raise exception 'NPI evidence requires release, SHA-256 checksum, and nonempty result array'; end if;
  for item in select value from jsonb_array_elements(p_results) loop
    if jsonb_typeof(item)<>'object' or (item - array['source_ref','npi','enumeration_type','last_updated','addresses','taxonomies'])<>'{}'::jsonb
       or btrim(coalesce(item->>'source_ref',''))='' or coalesce(item->>'npi','') !~ '^[0-9]{10}$'
       or btrim(coalesce(item->>'enumeration_type',''))='' or btrim(coalesce(item->>'last_updated',''))=''
       or jsonb_typeof(item->'addresses')<>'array' or jsonb_typeof(item->'taxonomies')<>'array'
       or jsonb_array_length(item->'taxonomies')=0
       or exists (select 1 from jsonb_array_elements(item->'taxonomies') code where jsonb_typeof(code)<>'string')
       or exists (select 1 from jsonb_array_elements(item->'addresses') address
                   where jsonb_typeof(address)<>'object' or jsonb_typeof(address->'postal_code')<>'string') then
      raise exception 'NPI result does not match the typed raw NPPES contract'; end if;
  end loop;
  select * into existing from ops.npi_device_evidence_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.job_id<>p_job_id or existing.device_id<>principal.device_id or existing.observed_at<>p_observed_at
       or existing.source_release<>p_source_release or existing.source_checksum<>p_source_checksum or existing.results<>p_results then
      raise exception 'NPI evidence idempotency key was reused with different evidence'; end if;
    return existing.id;
  end if;
  insert into ops.npi_device_evidence_receipt(job_id,builder_key,workflow_key,workflow_version,mode,scheduled_for,
      device_id,observed_at,source_release,source_checksum,results,idempotency_key)
    values(j.id,'npi.weekly-delta',j.definition_key,j.definition_version,j.mode,j.scheduled_for,
      principal.device_id,p_observed_at,p_source_release,p_source_checksum,p_results,p_idempotency_key)
    returning id into rid;
  return rid;
end $_$;


--
-- Name: record_provider_observation(text, text, integer, text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_provider_observation(p_route_key text, p_status text, p_latency_ms integer, p_error_class text, p_ttl_seconds integer, p_source_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare rid uuid;
begin
  if p_ttl_seconds < 1 or btrim(coalesce(p_source_ref,''))='' then
    raise exception 'positive observation TTL and source_ref are required';
  end if;
  insert into ops.provider_observation
    (route_key,status,latency_ms,error_class,expires_at,source_ref)
  values(p_route_key,p_status,p_latency_ms,p_error_class,
         now()+make_interval(secs=>p_ttl_seconds),p_source_ref)
  returning id into rid;
  return rid;
end $$;


--
-- Name: record_staging_release_readback(uuid, uuid, text, integer, text, integer, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_release_readback(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_release_readback_receipt%rowtype;
  attempt ops.staging_deployment_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  deployment_uuid uuid; receipt_uuid uuid; projection jsonb; projection_hash text;
  receipt_ref text; observed_time timestamptz := clock_timestamp();
begin
  if session_user <> 'carr_jobs' then raise exception 'staging readback writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_provider_version_id is null
     or coalesce(p_provider_tag,'') !~ '^carr-staging-[a-z0-9-]{8,50}$'
     or coalesce(p_verb_count,0)<=0
     or coalesce(p_schema_highest_migration,'') !~ '^[0-9]{4}_[a-z0-9_.-]+\.sql$'
     or coalesce(p_schema_applied_count,0)<=0 or coalesce(p_doctrine_generation,-1)<0 then
    raise exception 'invalid typed staging readback input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_deployment_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging readback has no prepared deployment attempt'; end if;
  if attempt.recovery_step <> 'prior' or attempt.recovery_attempt_id is null
     or attempt.prior_release_id is null or attempt.observed_release_id is distinct from attempt.prior_release_id then
    raise exception 'legacy staging readback is limited to the exact historical Production prior observation';
  end if;
  if not exists(select 1 from ops.legacy_prior_staging_readback_allowlist l
                where l.idempotency_key=p_idempotency_key and l.deployment_attempt_id=attempt.id) then
    raise exception 'legacy staging readback idempotency key was not captured at migration time';
  end if;
  if not exists(select 1 from ops.staging_deployment_claim where deployment_attempt_id=attempt.id) then
    raise exception 'staging readback deployment attempt was never claimed'; end if;
  perform pg_advisory_xact_lock(hashtextextended(attempt.recovery_attempt_id::text,202));
  select * into existing from ops.staging_release_readback_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.deployment_attempt_id<>attempt.id
       or (existing.git_sha,existing.provider_version_id,existing.provider_tag,existing.verb_count,
           existing.schema_highest_migration,existing.schema_applied_count,existing.doctrine_generation,
           existing.program6_actions_enabled) is distinct from
          (attempt.git_sha,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
           p_schema_applied_count,p_doctrine_generation,null::boolean) then
      raise exception 'staging readback idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('receipt_id',existing.id,'receipt_ref',existing.evidence_ref,'replayed',true,
      'bundle_id',(select id from ops.staging_recovery_rehearsal_bundle where recovery_attempt_id=attempt.recovery_attempt_id),
      'recovery_run_id',(select r.id from ops.run r join ops.staging_recovery_rehearsal_bundle b on b.id=r.recovery_rehearsal_bundle_id where b.recovery_attempt_id=attempt.recovery_attempt_id));
  end if;
  select * into strict current_release from ops.release where id=attempt.rehearsal_release_id;
  select * into strict prior_release from ops.release where id=attempt.prior_release_id;
  if prior_release.environment <> 'production' or prior_release.state <> 'complete' then
    raise exception 'legacy staging readback requires a completed historical Production prior release'; end if;
  if not exists(select 1 from ops.staging_release_readback_receipt before_receipt
                where before_receipt.recovery_attempt_id=attempt.recovery_attempt_id
                  and before_receipt.recovery_step='current_before'
                  and before_receipt.rehearsal_release_id=current_release.id
                  and before_receipt.observed_release_id=current_release.id
                  and before_receipt.prior_release_id=prior_release.id) then
    raise exception 'legacy staging readback prior requires its exact current_before receipt'; end if;
  if attempt.declared_migration_set_sha256<>ops.program5_migration_set_sha256(current_release.migration_set)
     or attempt.declared_migration_count<>cardinality(current_release.migration_set)
     or attempt.declared_schema_highest_migration<>current_release.schema_highest_migration
     or attempt.declared_schema_applied_count<>current_release.schema_applied_count
     or attempt.declared_schema_ledger_sha256<>current_release.schema_ledger_sha256
     or p_schema_highest_migration<>attempt.declared_schema_highest_migration
     or p_schema_applied_count<>attempt.declared_schema_applied_count then
    raise exception 'staging readback schema does not match the exact declared candidate migration set'; end if;
  if p_provider_tag<>attempt.expected_provider_tag then raise exception 'staging readback provider tag does not match its prepared attempt'; end if;
  projection:=jsonb_build_object(
    'deployment_attempt_id',attempt.id,'correlation_id',attempt.correlation_id,'recovery_attempt_id',attempt.recovery_attempt_id,
    'recovery_step',attempt.recovery_step,'rehearsal_release_id',current_release.id,'observed_release_id',prior_release.id,
    'prior_release_id',attempt.prior_release_id,'service_id',current_release.service_id,'environment','staging','git_sha',attempt.git_sha,
    'provider','cloudflare-workers','provider_version_id',p_provider_version_id,'provider_tag',p_provider_tag,
    'verb_count',p_verb_count,'schema_highest_migration',p_schema_highest_migration,'schema_applied_count',p_schema_applied_count,
    'declared_migration_set_sha256',attempt.declared_migration_set_sha256,'declared_migration_count',attempt.declared_migration_count,
    'declared_schema_applied_count',attempt.declared_schema_applied_count,'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256,
    'doctrine_generation',p_doctrine_generation);
  projection_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex'); receipt_ref:='ops.staging-release-readback:'||projection_hash;
  insert into ops.deployment(correlation_id,service_id,environment,state,git_sha,provider,provider_version_id,release_id,deployed_by_actor,verb_count,schema_highest_migration,doctrine_generation,started_at,ended_at,read_back_at,verification_evidence_ref,source_kind,source_ref,observed_at)
  values(attempt.correlation_id,current_release.service_id,'staging','complete',attempt.git_sha,'cloudflare-workers',p_provider_version_id::text,prior_release.id,session_user,p_verb_count,p_schema_highest_migration,p_doctrine_generation,observed_time,observed_time,observed_time,receipt_ref,'wrapper','bin/deploy-worker.sh',observed_time) returning id into deployment_uuid;
  insert into ops.staging_release_readback_receipt(idempotency_key,deployment_attempt_id,recovery_attempt_id,recovery_step,correlation_id,deployment_id,rehearsal_release_id,observed_release_id,prior_release_id,service_id,environment,git_sha,provider,provider_version_id,provider_tag,verb_count,schema_highest_migration,schema_applied_count,declared_migration_set_sha256,declared_migration_count,declared_schema_applied_count,declared_schema_ledger_sha256,doctrine_generation,program6_actions_enabled,projection_sha256,evidence_ref,observed_at,writer_session_user)
  values(p_idempotency_key,attempt.id,attempt.recovery_attempt_id,attempt.recovery_step,attempt.correlation_id,deployment_uuid,current_release.id,prior_release.id,attempt.prior_release_id,current_release.service_id,'staging',attempt.git_sha,'cloudflare-workers',p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,p_schema_applied_count,attempt.declared_migration_set_sha256,attempt.declared_migration_count,attempt.declared_schema_applied_count,attempt.declared_schema_ledger_sha256,p_doctrine_generation,null,projection_hash,receipt_ref,observed_time,session_user) returning id into receipt_uuid;
  return jsonb_build_object('receipt_id',receipt_uuid,'receipt_ref',receipt_ref,'replayed',false,'bundle_id',null,'recovery_run_id',null);
end $_$;


--
-- Name: record_staging_release_readback(uuid, uuid, text, integer, text, integer, bigint, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_release_readback(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint, p_program6_actions_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare legacy_posture boolean;
begin
  if session_user <> 'carr_jobs' then raise exception 'staging readback writer requires the carr_jobs session'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select program6_actions_enabled into legacy_posture
  from ops.staging_release_readback_receipt where idempotency_key=p_idempotency_key;
  if found and legacy_posture is null then
    raise exception 'Program 6 recorder cannot replay a legacy NULL-posture receipt';
  end if;
  return ops.record_staging_release_readback_program6(p_idempotency_key,p_provider_version_id,p_provider_tag,
    p_verb_count,p_schema_highest_migration,p_schema_applied_count,p_doctrine_generation,p_program6_actions_enabled);
end $$;


--
-- Name: record_staging_release_readback_program6(uuid, uuid, text, integer, text, integer, bigint, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_release_readback_program6(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint, p_program6_actions_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_release_readback_receipt%rowtype;
  attempt ops.staging_deployment_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  observed_release ops.release%rowtype;
  service_uuid uuid; deployment_uuid uuid; receipt_uuid uuid;
  before_receipt ops.staging_release_readback_receipt%rowtype;
  prior_receipt ops.staging_release_readback_receipt%rowtype;
  after_receipt ops.staging_release_readback_receipt%rowtype;
  bundle_uuid uuid; run_uuid uuid; projection jsonb; projection_hash text;
  receipt_ref text; bundle_projection jsonb; bundle_hash text; bundle_ref text;
  observed_time timestamptz := clock_timestamp();
begin
  if session_user <> 'carr_jobs' then raise exception 'staging readback writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_provider_version_id is null
     or coalesce(p_provider_tag,'') !~ '^carr-staging-[a-z0-9-]{8,50}$'
     or coalesce(p_verb_count,0)<=0
     or coalesce(p_schema_highest_migration,'') !~ '^[0-9]{4}_[a-z0-9_.-]+\.sql$'
     or coalesce(p_schema_applied_count,0)<=0 or coalesce(p_doctrine_generation,-1)<0
     or p_program6_actions_enabled is null then
    raise exception 'invalid typed staging readback input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_deployment_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging readback has no prepared deployment attempt'; end if;
  if not exists(select 1 from ops.staging_deployment_claim where deployment_attempt_id=attempt.id) then
    raise exception 'staging readback deployment attempt was never claimed'; end if;
  if attempt.recovery_attempt_id is not null then perform pg_advisory_xact_lock(hashtextextended(attempt.recovery_attempt_id::text,202)); end if;
  select * into existing from ops.staging_release_readback_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.deployment_attempt_id<>attempt.id
       or (existing.git_sha,existing.provider_version_id,existing.provider_tag,existing.verb_count,
           existing.schema_highest_migration,existing.schema_applied_count,existing.doctrine_generation) is distinct from
          (attempt.git_sha,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
           p_schema_applied_count,p_doctrine_generation)
       or (existing.program6_actions_enabled is not null
           and existing.program6_actions_enabled is distinct from p_program6_actions_enabled) then
      raise exception 'staging readback idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('receipt_id',existing.id,'receipt_ref',existing.evidence_ref,'replayed',true,
      'bundle_id',(select id from ops.staging_recovery_rehearsal_bundle where recovery_attempt_id=attempt.recovery_attempt_id),
      'recovery_run_id',(select r.id from ops.run r join ops.staging_recovery_rehearsal_bundle b on b.id=r.recovery_rehearsal_bundle_id where b.recovery_attempt_id=attempt.recovery_attempt_id));
  end if;
  select * into strict current_release from ops.release where id=attempt.rehearsal_release_id;
  if attempt.declared_migration_set_sha256<>ops.program5_migration_set_sha256(current_release.migration_set)
     or attempt.declared_migration_count<>cardinality(current_release.migration_set)
     or attempt.declared_schema_highest_migration<>current_release.schema_highest_migration
     or attempt.declared_schema_applied_count<>current_release.schema_applied_count
     or attempt.declared_schema_ledger_sha256<>current_release.schema_ledger_sha256
     or p_schema_highest_migration<>attempt.declared_schema_highest_migration
     or p_schema_applied_count<>attempt.declared_schema_applied_count then
    raise exception 'staging readback schema does not match the exact declared candidate migration set'; end if;
  if p_provider_tag<>attempt.expected_provider_tag then raise exception 'staging readback provider tag does not match its prepared attempt'; end if;
  service_uuid:=current_release.service_id;
  select * into strict observed_release from ops.release where id=attempt.observed_release_id;
  if attempt.prior_release_id is not null then select * into strict prior_release from ops.release where id=attempt.prior_release_id; end if;
  projection:=jsonb_build_object(
    'deployment_attempt_id',attempt.id,'correlation_id',attempt.correlation_id,'recovery_attempt_id',attempt.recovery_attempt_id,
    'recovery_step',attempt.recovery_step,'rehearsal_release_id',current_release.id,'observed_release_id',observed_release.id,
    'prior_release_id',attempt.prior_release_id,'service_id',service_uuid,'environment','staging','git_sha',attempt.git_sha,
    'provider','cloudflare-workers','provider_version_id',p_provider_version_id,'provider_tag',p_provider_tag,
    'verb_count',p_verb_count,'schema_highest_migration',p_schema_highest_migration,'schema_applied_count',p_schema_applied_count,
    'declared_migration_set_sha256',attempt.declared_migration_set_sha256,'declared_migration_count',attempt.declared_migration_count,
    'declared_schema_applied_count',attempt.declared_schema_applied_count,'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256,
    'doctrine_generation',p_doctrine_generation,'program6_actions_enabled',p_program6_actions_enabled);
  projection_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex'); receipt_ref:='ops.staging-release-readback:'||projection_hash;
  insert into ops.deployment(correlation_id,service_id,environment,state,git_sha,provider,provider_version_id,release_id,deployed_by_actor,verb_count,schema_highest_migration,doctrine_generation,started_at,ended_at,read_back_at,verification_evidence_ref,source_kind,source_ref,observed_at)
  values(attempt.correlation_id,service_uuid,'staging','complete',attempt.git_sha,'cloudflare-workers',p_provider_version_id::text,observed_release.id,session_user,p_verb_count,p_schema_highest_migration,p_doctrine_generation,observed_time,observed_time,observed_time,receipt_ref,'wrapper','bin/deploy-worker.sh',observed_time) returning id into deployment_uuid;
  insert into ops.staging_release_readback_receipt(idempotency_key,deployment_attempt_id,recovery_attempt_id,recovery_step,correlation_id,deployment_id,rehearsal_release_id,observed_release_id,prior_release_id,service_id,environment,git_sha,provider,provider_version_id,provider_tag,verb_count,schema_highest_migration,schema_applied_count,declared_migration_set_sha256,declared_migration_count,declared_schema_applied_count,declared_schema_ledger_sha256,doctrine_generation,program6_actions_enabled,projection_sha256,evidence_ref,observed_at,writer_session_user)
  values(p_idempotency_key,attempt.id,attempt.recovery_attempt_id,attempt.recovery_step,attempt.correlation_id,deployment_uuid,current_release.id,observed_release.id,attempt.prior_release_id,service_uuid,'staging',attempt.git_sha,'cloudflare-workers',p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,p_schema_applied_count,attempt.declared_migration_set_sha256,attempt.declared_migration_count,attempt.declared_schema_applied_count,attempt.declared_schema_ledger_sha256,p_doctrine_generation,p_program6_actions_enabled,projection_hash,receipt_ref,observed_time,session_user) returning id into receipt_uuid;
  if attempt.recovery_step='current_after' then
    select * into before_receipt from ops.staging_release_readback_receipt where recovery_attempt_id=attempt.recovery_attempt_id and recovery_step='current_before'; if not found then raise exception 'current_after requires current_before receipt'; end if;
    select * into prior_receipt from ops.staging_release_readback_receipt where recovery_attempt_id=attempt.recovery_attempt_id and recovery_step='prior'; if not found then raise exception 'current_after requires prior receipt'; end if;
    select * into strict after_receipt from ops.staging_release_readback_receipt where id=receipt_uuid;
    if before_receipt.rehearsal_release_id<>current_release.id or prior_receipt.rehearsal_release_id<>current_release.id
       or before_receipt.prior_release_id<>prior_release.id or prior_receipt.prior_release_id<>prior_release.id
       or before_receipt.observed_release_id<>current_release.id or prior_receipt.observed_release_id<>prior_release.id or after_receipt.observed_release_id<>current_release.id
       or before_receipt.service_id<>service_uuid or prior_receipt.service_id<>service_uuid
       or before_receipt.declared_migration_set_sha256<>attempt.declared_migration_set_sha256 or prior_receipt.declared_migration_set_sha256<>attempt.declared_migration_set_sha256 or after_receipt.declared_migration_set_sha256<>attempt.declared_migration_set_sha256
       or before_receipt.declared_migration_count<>attempt.declared_migration_count or prior_receipt.declared_migration_count<>attempt.declared_migration_count or after_receipt.declared_migration_count<>attempt.declared_migration_count
       or before_receipt.schema_highest_migration<>attempt.declared_schema_highest_migration or prior_receipt.schema_highest_migration<>attempt.declared_schema_highest_migration or after_receipt.schema_highest_migration<>attempt.declared_schema_highest_migration
       or before_receipt.schema_applied_count<>attempt.declared_schema_applied_count or prior_receipt.schema_applied_count<>attempt.declared_schema_applied_count or after_receipt.schema_applied_count<>attempt.declared_schema_applied_count
       or before_receipt.declared_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256 or prior_receipt.declared_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256 or after_receipt.declared_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256
       or not(before_receipt.observed_at<prior_receipt.observed_at and prior_receipt.observed_at<after_receipt.observed_at) or after_receipt.observed_at-before_receipt.observed_at>interval '1 hour' then
      raise exception 'recovery receipts do not form an ordered current-prior-current chain'; end if;
    bundle_projection:=jsonb_build_object('recovery_attempt_id',attempt.recovery_attempt_id,'current_release_id',current_release.id,'prior_release_id',prior_release.id,'service_id',service_uuid,'current_before_receipt_id',before_receipt.id,'prior_after_rollback_receipt_id',prior_receipt.id,'current_after_restore_receipt_id',after_receipt.id,'recovery_strategy',current_release.recovery_strategy,'recovery_plan_ref',current_release.rollback_plan_ref,'plan_hash',current_release.plan_hash,'declared_migration_set_sha256',attempt.declared_migration_set_sha256,'declared_migration_count',attempt.declared_migration_count,'declared_schema_highest_migration',attempt.declared_schema_highest_migration,'declared_schema_applied_count',attempt.declared_schema_applied_count,'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256);
    bundle_hash:='sha256:'||encode(public.digest(bundle_projection::text,'sha256'),'hex'); bundle_ref:='ops.staging-recovery-bundle:'||bundle_hash;
    insert into ops.staging_recovery_rehearsal_bundle(recovery_attempt_id,correlation_id,current_release_id,prior_release_id,service_id,environment,current_before_receipt_id,prior_after_rollback_receipt_id,current_after_restore_receipt_id,recovery_strategy,recovery_plan_ref,plan_hash,bundle_sha256,evidence_ref,declared_migration_set_sha256,declared_migration_count,declared_schema_highest_migration,declared_schema_applied_count,declared_schema_ledger_sha256,completed_at,writer_session_user)
    values(attempt.recovery_attempt_id,attempt.correlation_id,current_release.id,prior_release.id,service_uuid,'staging',before_receipt.id,prior_receipt.id,after_receipt.id,'rollback',current_release.rollback_plan_ref,current_release.plan_hash,bundle_hash,bundle_ref,attempt.declared_migration_set_sha256,attempt.declared_migration_count,attempt.declared_schema_highest_migration,attempt.declared_schema_applied_count,attempt.declared_schema_ledger_sha256,after_receipt.observed_at,session_user) returning id into bundle_uuid;
    insert into ops.run(correlation_id,kind,service_id,environment,run_key,state,started_at,ended_at,source_kind,source_ref,observed_at,evidence_ref,release_id,recovery_strategy,recovery_plan_ref,recovery_rehearsal_bundle_id)
    values(attempt.correlation_id,'check',service_uuid,'staging','recovery.rehearsal.worker','succeeded',before_receipt.observed_at,after_receipt.observed_at,'wrapper','bin/deploy-worker.sh',after_receipt.observed_at,bundle_ref,current_release.id,'rollback',current_release.rollback_plan_ref,bundle_uuid) returning id into run_uuid;
  end if;
  return jsonb_build_object('receipt_id',receipt_uuid,'receipt_ref',receipt_ref,'replayed',false,'bundle_id',bundle_uuid,'recovery_run_id',run_uuid);
end $_$;


--
-- Name: record_staging_restore_only_result(uuid, text, uuid, text, integer, text, integer, bigint, boolean, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_restore_only_result(p_idempotency_key uuid, p_status text, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint, p_program6_actions_enabled boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare attempt ops.staging_restore_only_attempt%rowtype; existing ops.staging_restore_only_result%rowtype;
  projection jsonb; result_hash text; result_ref text; result_uuid uuid;
begin
  if session_user<>'carr_jobs' then raise exception 'restore-only result requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_status not in ('succeeded','failed','unknown') then raise exception 'invalid restore-only result input'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_restore_only_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'restore-only result has no prepared attempt'; end if;
  if not exists(select 1 from ops.staging_restore_only_claim where restore_attempt_id=attempt.id) then raise exception 'restore-only result was never claimed'; end if;
  select * into existing from ops.staging_restore_only_result where restore_attempt_id=attempt.id;
  if found then
    if (existing.status,existing.provider_version_id,existing.provider_tag,existing.verb_count,
        existing.schema_highest_migration,existing.schema_applied_count,existing.doctrine_generation,
        existing.program6_actions_enabled,existing.reason) is distinct from
       (p_status,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
        p_schema_applied_count,p_doctrine_generation,p_program6_actions_enabled,p_reason) then
      raise exception 'restore-only result idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('restore_result_id',existing.id,'result_ref',existing.evidence_ref,'status',existing.status,'replayed',true);
  end if;
  if p_status='succeeded' then
    if p_provider_version_id is null or p_provider_tag<>attempt.expected_provider_tag or coalesce(p_verb_count,0)<=0
       or coalesce(p_schema_highest_migration,'')<>attempt.declared_schema_highest_migration
       or p_schema_applied_count<>attempt.declared_schema_applied_count or p_doctrine_generation is null
       or p_program6_actions_enabled is null or p_reason is not null then
      raise exception 'restore-only success lacks exact current-target readback';
    end if;
  elsif p_provider_version_id is not null or p_provider_tag is not null or p_verb_count is not null
     or p_schema_highest_migration is not null or p_schema_applied_count is not null
     or p_doctrine_generation is not null or p_program6_actions_enabled is not null
     or coalesce(p_reason,'') !~ '^[a-z0-9_.:-]{1,240}$' then
    raise exception 'restore-only non-success requires only a bounded reason';
  end if;
  projection:=jsonb_build_object('restore_attempt_id',attempt.id,'recovery_attempt_id',attempt.recovery_attempt_id,
    'target_release_id',attempt.rehearsal_release_id,'prior_release_id',attempt.prior_release_id,
    'target_provider_version_id',attempt.target_provider_version_id,'environment','staging','status',p_status,
    'provider_version_id',p_provider_version_id,'provider_tag',p_provider_tag,'verb_count',p_verb_count,
    'schema_highest_migration',p_schema_highest_migration,'schema_applied_count',p_schema_applied_count,
    'doctrine_generation',p_doctrine_generation,'program6_actions_enabled',p_program6_actions_enabled,'reason',p_reason);
  result_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  result_ref:='ops.staging-restore-only:'||result_hash;
  insert into ops.staging_restore_only_result(idempotency_key,restore_attempt_id,status,provider_version_id,
    provider_tag,verb_count,schema_highest_migration,schema_applied_count,doctrine_generation,
    program6_actions_enabled,reason,result_sha256,evidence_ref,writer_session_user)
  values(p_idempotency_key,attempt.id,p_status,p_provider_version_id,p_provider_tag,p_verb_count,
    p_schema_highest_migration,p_schema_applied_count,p_doctrine_generation,p_program6_actions_enabled,
    p_reason,result_hash,result_ref,session_user) returning id into result_uuid;
  return jsonb_build_object('restore_result_id',result_uuid,'result_ref',result_ref,'status',p_status,'replayed',false);
end $_$;


--
-- Name: record_workflow_acceptance(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v integer; rid uuid; authority_actor text;
begin
  authority_actor := ops.authority_actor_slug();
  if p_status='accepted' and p_mode='canary' and authority_actor <> 'joe' then
    raise exception 'accepted canary workflow evidence requires Joe authority session';
  end if;
  select version into v from ops.job_definition
   where key=p_workflow_key order by version desc limit 1;
  if v is null then raise exception 'unknown workflow %',p_workflow_key; end if;
  if p_status='accepted' and not exists (
    select 1 from ops.job j join ops.job_receipt r on r.job_id=j.id
     where j.definition_key=p_workflow_key and j.definition_version=v
       and j.mode=p_mode and r.kind='completion' and r.receipt_ref=p_receipt_ref
  ) then
    raise exception 'accepted workflow evidence must name a completion receipt from the matching workflow and mode';
  end if;
  insert into ops.workflow_acceptance
    (workflow_key,workflow_version,mode,status,receipt_ref,accepted_by)
  values(p_workflow_key,v,p_mode,p_status,p_receipt_ref,
         case when p_status='accepted' then authority_actor else null end)
  returning id into rid;
  return rid;
end $$;


--
-- Name: FUNCTION record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text) IS 'Control Plane: accepted canary evidence requires Joe; shadow acceptance remains available to admitted human authority sessions.';


--
-- Name: record_workflow_acceptance(text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text, p_actor text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v integer; rid uuid; human_actor actor%rowtype;
begin
  select version into v from ops.job_definition
   where key=p_workflow_key order by version desc limit 1;
  if v is null then raise exception 'unknown workflow %',p_workflow_key; end if;
  if p_status='accepted' then
    select * into human_actor from actor
     where slug=p_actor and kind='human' and active;
    if not found then
      raise exception 'accepted workflow evidence requires an active human actor';
    end if;
    if not exists (
      select 1
        from ops.job j join ops.job_receipt r on r.job_id=j.id
       where j.definition_key=p_workflow_key and j.definition_version=v
         and j.mode=p_mode and r.kind='completion' and r.receipt_ref=p_receipt_ref
    ) then
      raise exception 'accepted workflow evidence must name a completion receipt from the matching workflow and mode';
    end if;
  end if;
  insert into ops.workflow_acceptance
    (workflow_key,workflow_version,mode,status,receipt_ref,accepted_by)
  values(p_workflow_key,v,p_mode,p_status,p_receipt_ref,
         case when p_status='accepted' then human_actor.slug else null end)
  returning id into rid;
  return rid;
end $$;


--
-- Name: redeem_program6_browser_action_challenge(text, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.redeem_program6_browser_action_challenge(p_token_digest text, p_session_digest text, p_action text, p_material_digest text, p_idempotency_key uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  v_actor_slug text;
  v_actor public.actor%rowtype;
  v_inserted_id uuid;
begin
  if coalesce(p_token_digest, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_session_digest, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_material_digest, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_action, '') not in ('accept-ready-plan','accept-outcome-feedback')
     or p_idempotency_key is null then
    raise exception 'browser approval challenge requires lowercase SHA-256 token, session, and material digests, one approved action, and a UUID idempotency key';
  end if;

  v_actor_slug := ops.authority_actor_slug();
  select a.* into v_actor
    from public.actor a
   where a.slug = v_actor_slug
     and a.active
     and a.kind = 'human'
   for share;
  if not found then
    raise exception 'authority session user is not an active human actor';
  end if;

  -- The token's unique index makes concurrent redemption atomic.  A token
  -- that has already been consumed is an ordinary false result, never a
  -- second authority action and never a mutation of the first audit fact.
  insert into ops.program6_browser_action_challenge_redemption
    (token_digest,session_digest,action,material_digest,idempotency_key,redeemed_by_actor_id)
  values
    (p_token_digest,p_session_digest,p_action,p_material_digest,p_idempotency_key,v_actor.id)
  on conflict (token_digest) do nothing
  returning id into v_inserted_id;

  return v_inserted_id is not null;
end;
$_$;


--
-- Name: refuse_approved_rule_contract_rewrite(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.refuse_approved_rule_contract_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_rule_id uuid;
begin
  v_rule_id := case when tg_op='INSERT' then new.rule_id else old.rule_id end;
  if exists (select 1 from ops.rule_approval_receipt where rule_id=v_rule_id) then
    raise exception 'approved rule % contract is immutable; approve a replacement rule',v_rule_id;
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


