--
-- Name: assert_no_orphaned_edges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_no_orphaned_edges() RETURNS void
    LANGUAGE plpgsql
    AS $$
declare n int; worst text;
begin
  select count(*), min(edge || ' -> ' || coalesce(party_ref, '?') || ' ' || coalesce(name, ''))
    into n, worst from v_orphaned_edge;
  if n > 0 then
    raise exception 'v_orphaned_edge is not empty: % edge(s) point at a merged or deleted '
                    'party (e.g. %). Repoint or retire them before merging anything else — a '
                    'merge on top of a stale edge produces a graph that walks to a party which '
                    'no longer resolves.', n, worst;
  end if;
end
$$;


--
-- Name: FUNCTION assert_no_orphaned_edges(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.assert_no_orphaned_edges() IS 'Raises unless v_orphaned_edge is empty (0062). Call it from a migration guard alongside the v_orphaned_role check, and from any future merge path, so the survivorship rule''s mandatory sweep is enforced rather than remembered. Companion to assert_view_disjoint (0058): the same trade — a paragraph claiming an invariant becomes a call that fails.';


--
-- Name: assert_situation_retrieval_golden(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_situation_retrieval_golden(p_suite_digest text) RETURNS TABLE(case_id text, status text, target_rank integer)
    LANGUAGE plpgsql
    AS $$
declare c record; targets text[]; selected_policy text; required_ok boolean;
        forbidden_ok boolean; empty_ok boolean;
begin
  select rp.policy_id into selected_policy from retrieval_ranking_policy rp
   where rp.is_default and rp.status='active'
     and rp.golden_suite_digest=p_suite_digest;
  if selected_policy is null then
    raise exception 'golden suite digest mismatch';
  end if;
  for c in select * from (values
    ('RET-001','write acceptance tests first',array['carr-mature-software-end-state-bduf#s39-fresh-session-prompt']::text[],false,'{}'::text[],false),
    ('RET-002','record layer outage diagnosis runbook',array['runbook#diagnosis-checklist-in-order-2-minutes']::text[],false,'{}'::text[],false),
    ('RET-003','playbook self improvement review cycle',array['playbook-review#preamble']::text[],false,'{}'::text[],false),
    ('RET-004','document factory',array['document-factory-routing#preamble']::text[],false,'{}'::text[],false),
    ('RET-005','weekly new provider detection',array['npi-sweep-sop#preamble']::text[],false,'{}'::text[],false),
    ('RET-006','social publishing review approval',array['social-media-workflow#placement-the-entire-social-run-is-local-now-joe-july-18-2026']::text[],false,'{}'::text[],false),
    ('RET-007','space search multi source',array['space-search-sop#preamble']::text[],false,'{}'::text[],false),
    ('RET-008','lead system',array['lead-system-handoff#preamble']::text[],false,'{}'::text[],false),
    ('RET-009','restore backup rehearsal',array['carr-control-room-bduf#s30-test-and-verification-strategy']::text[],false,'{}'::text[],false),
    ('RET-010','single source of truth',array['deal-enrichment-sop#rules']::text[],false,'{}'::text[],false),
    ('RET-ARCH-001','agent systems validation',array['2026-07-30-agent-systems-explainer-takeaways#preamble']::text[],false,'{}'::text[],false),
    ('RET-TITLE-001','diagnosis checklist',array['runbook#diagnosis-checklist-in-order-2-minutes']::text[],false,'{}'::text[],false),
    ('RET-PHRASE-001','database service unavailable troubleshooting steps',array['runbook#diagnosis-checklist-in-order-2-minutes']::text[],false,'{}'::text[],false),
    ('RET-PHRASE-002','how the operating playbook learns from mistakes',array['playbook-review#preamble']::text[],false,'{}'::text[],false),
    ('RET-NEG-001','outage communication template','{}'::text[],false,array['runbook#diagnosis-checklist-in-order-2-minutes']::text[],false),
    -- The token zzqx can appear in no honest doctrine section, so this stays
    -- an every-word query that matches nothing — the drifted form ('retired
    -- retrieval lifecycle fixture') began matching a live end-state section
    -- and blocked every approval batch. Real retired-content leakage is
    -- proven fixture-based in ops/situation-retrieval-db-gate.py.
    ('RET-LIFE-001','retired zzqx retrieval lifecycle fixture','{}'::text[],false,'{}'::text[],true),
    ('RET-AMB-001','review cycle after a record layer outage',array['runbook#diagnosis-checklist-in-order-2-minutes','playbook-review#preamble']::text[],true,'{}'::text[],false)
  ) q(case_id,query,required_targets,require_all,forbidden_targets,expect_no_hits)
  loop
    select array_agg(x.doc_slug||'#'||x.section_key order by x.final_score desc,
                     x.concept_score desc,x.lexical_score desc,x.section_key)
      into targets from search_doctrine_situations(c.query,null,null,3,selected_policy) x;
    targets := coalesce(targets,'{}'); case_id := c.case_id;
    required_ok := case when cardinality(c.required_targets)=0 then true
                        when c.require_all then c.required_targets <@ targets
                        else c.required_targets && targets end;
    forbidden_ok := not (c.forbidden_targets && targets);
    empty_ok := not c.expect_no_hits or cardinality(targets)=0;
    target_rank := case when cardinality(c.required_targets)=0 then null
                        else array_position(targets,c.required_targets[1]) end;
    status := case when required_ok and forbidden_ok and empty_ok then 'pass' else 'fail' end;
    return next;
  end loop;
end $$;


--
-- Name: assert_view_disjoint(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_view_disjoint(source text, key_expr text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare
  dup_keys bigint;
  surplus  bigint;
  worst    text;
begin
  -- A bare identifier must resolve to a real relation. A parenthesised expression is taken
  -- as a caller-supplied subquery and must carry its own alias, which is a Postgres rule
  -- rather than one invented here.
  if source !~ '^\s*\(' and to_regclass(source) is null then
    raise exception 'assert_view_disjoint: no such relation %', source;
  end if;

  -- One pass: how many distinct key values repeat, how many surplus rows that is (the actual
  -- size of the inflation), and one sample to name in the error.
  execute format(
    $q$ select count(*), coalesce(sum(d.n - 1), 0), coalesce(min(d.k), '(null key)')
          from (select (%s)::text as k, count(*) as n
                  from %s
                 group by 1
                having count(*) > 1) d $q$,
    key_expr, source)
    into dup_keys, surplus, worst;

  if dup_keys > 0 then
    raise exception '% is NOT disjoint on %: % key(s) appear more than once, % surplus '
                    'row(s) (e.g. %). A union all branch overlaps another, so every consumer '
                    'of this view is counting something twice.',
                    source, key_expr, dup_keys, surplus, worst;
  end if;
end
$_$;


--
-- Name: FUNCTION assert_view_disjoint(source text, key_expr text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.assert_view_disjoint(source text, key_expr text) IS 'Raises unless every key value in `source` (a relation name, or a parenthesised subquery with an alias) appears exactly once — 0058. Call it from a migration''s guard block whenever you add or change a `union all` branch, INSTEAD of writing a paragraph arguing the branches cannot overlap. 0056 wrote the paragraph and the paragraph was right; the next one may not be, and an inflated denominator is invisible. Migration-time only: it does a full scan and belongs nowhere near a hot path. Null key values are grouped and reported like any other, never skipped, so key on something non-null in every branch.';


--
-- Name: campaign_channels_valid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_channels_valid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare bad text;
begin
  select string_agg(ch, ', ') into bad
    from unnest(new.channels) ch
   where ch not in (select slug from marketing_subject
                     where subject_type = 'platform' and retired_at is null);
  if bad is not null then
    raise exception 'campaign.channels holds unknown platform slug(s): %. Known live '
                    'platforms: %. Register a new platform in marketing_subject before '
                    'naming it here.', bad,
                    (select string_agg(slug, ', ' order by slug) from marketing_subject
                      where subject_type = 'platform' and retired_at is null);
  end if;
  return new;
end $$;


--
-- Name: capture_call_context(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_call_context(requested_deal_ids uuid[]) RETURNS TABLE(deal_id uuid, deal_name text, owner text, operating_state text, participant_party_id uuid, participant_party_ref text, participant_name text, participant_email text, participant_role text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select d.id, d.name, d.owner, d.operating_state, dp.party_id, p.ref, p.name, p.email, dp.role
    from public.deal d
    left join public.deal_participant dp on dp.deal_id=d.id and dp.to_at is null
    left join public.party p on p.id=dp.party_id
   where d.id = any(requested_deal_ids)
     and d.outcome is null
     and d.operating_state = 'active'
$$;


--
-- Name: carr_business_days(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.carr_business_days(a date, b date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when a is null or b is null then null
         else (case when b >= a then 1 else -1 end) * (
           select count(*)::int
             from generate_series(least(a,b), greatest(a,b) - 1, interval '1 day') d
            where extract(isodow from d) < 6)
         end;
$$;


--
-- Name: FUNCTION carr_business_days(a date, b date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.carr_business_days(a date, b date) IS 'Whole business days from a to b, negative when a is later than b. Weekends excluded per rule 236ca227; holidays deliberately not modelled, because CARR holds no holiday calendar and a guessed one would be a second source of truth. THE one business-day primitive: route human obligation aging, staleness and overdue display through this rather than raw date subtraction, and leave machine liveness cadences in elapsed time where a weekend is still a weekend.';


--
-- Name: current_retrievable_doctrine(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_retrievable_doctrine(p_actor_id uuid, p_content_classes text[] DEFAULT NULL::text[]) RETURNS TABLE(section_id uuid, section_key text, section_title text, doc_slug text, doc_title text, content_class text, plain_text text, body_search_vector tsvector, section_title_vector tsvector, document_title_vector tsvector)
    LANGUAGE sql STABLE
    AS $$
  select s.id, s.section_key, s.title, d.slug, d.title, d.content_class,
         r.plain_text, r.search_vector, s.title_search_vector, d.title_search_vector
    from doctrine_section s
    join doctrine_document d on d.id = s.document_id
    join doctrine_revision r on r.id = s.current_revision_id
   where s.status = 'active'
     and (d.visibility <> 'personal' or d.owner_actor_id = p_actor_id)
     and (p_content_classes is null or d.content_class = any(p_content_classes))
$$;


--
-- Name: log_retrieval_query(text, integer, uuid[], jsonb, text, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_retrieval_query(p_query text, p_result_count integer, p_section_ids uuid[], p_score_bands jsonb, p_policy_id text, p_policy_version bigint, p_explicit_hit boolean, p_scope_ref text DEFAULT 'carr-internal'::text) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into retrieval_query_log
    (normalized_hash, result_count, score_bands, selected_row_ids,
     policy_id, policy_version, explicit_hit, scope_ref)
  values (
    encode(digest(convert_to(normalize_retrieval_phrase(p_query), 'UTF8'), 'sha256'), 'hex'),
    greatest(coalesce(p_result_count, 0), 0),
    coalesce(p_score_bands, jsonb_build_object('high', 0, 'medium', 0, 'low', 0)),
    coalesce(p_section_ids, '{}'),
    p_policy_id, p_policy_version,
    coalesce(p_explicit_hit, false),
    coalesce(p_scope_ref, 'carr-internal'))
  returning id
$$;


--
-- Name: mark_retrieval_mappings_for_repair(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_retrieval_mappings_for_repair() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.status = 'active' and new.status <> 'active' then
    update doctrine_concept_mapping
       set status = 'needs_repair', repair_reason = 'target section is no longer active',
           version = version + 1, updated_at = now()
     where section_id = new.id and status = 'approved';
  end if;
  return new;
end $$;


--
-- Name: memory_item_immutable_core(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.memory_item_immutable_core() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.created_at is distinct from old.created_at then
    raise exception 'memory_item created_at is immutable';
  end if;
  if new.kind is distinct from old.kind
     or new.context is distinct from old.context
     or new.confidence is distinct from old.confidence
     or new.observed_by_actor_id is distinct from old.observed_by_actor_id
     or new.statement is distinct from old.statement
     or new.scope is distinct from old.scope
     or new.owner_actor_id is distinct from old.owner_actor_id
     or new.organization_tenant_id is distinct from old.organization_tenant_id
     or new.work_request_id is distinct from old.work_request_id
     or new.work_request_version is distinct from old.work_request_version
     or new.plan_id is distinct from old.plan_id
     or new.predecessor_id is distinct from old.predecessor_id
     or new.lineage_root_id is distinct from old.lineage_root_id then
    raise exception 'memory_item core is immutable; create a successor for corrections';
  end if;
  if new.version <> old.version + 1 then
    raise exception 'memory_item lifecycle updates must increment version exactly once';
  end if;
  if new.status is not distinct from old.status then
    raise exception 'memory_item status must make one allowed lifecycle transition';
  end if;
  if old.status='candidate' and new.status='promoted' then
    if old.promoted_by_actor_id is not null or old.promoted_at is not null
       or new.promoted_by_actor_id is null or new.promoted_at is null
       or new.corrected_by_actor_id is distinct from old.corrected_by_actor_id
       or new.correction_reason is distinct from old.correction_reason
       or new.corrected_at is distinct from old.corrected_at
       or new.forgotten_by_actor_id is distinct from old.forgotten_by_actor_id
       or new.forget_reason is distinct from old.forget_reason
       or new.forgotten_at is distinct from old.forgotten_at then
      raise exception 'candidate promotion requires actor and timestamp';
    end if;
  elsif old.status in ('candidate','promoted') and new.status='corrected' then
    if old.corrected_by_actor_id is not null or old.correction_reason is not null or old.corrected_at is not null
       or new.corrected_by_actor_id is null or new.correction_reason is null or new.corrected_at is null
       or new.promoted_by_actor_id is distinct from old.promoted_by_actor_id
       or new.promoted_at is distinct from old.promoted_at
       or new.forgotten_by_actor_id is distinct from old.forgotten_by_actor_id
       or new.forget_reason is distinct from old.forget_reason
       or new.forgotten_at is distinct from old.forgotten_at then
      raise exception 'memory correction requires actor, reason, and timestamp';
    end if;
  elsif old.status in ('candidate','promoted','corrected') and new.status='forgotten' then
    if old.forgotten_by_actor_id is not null or old.forget_reason is not null or old.forgotten_at is not null
       or new.forgotten_by_actor_id is null or new.forget_reason is null or new.forgotten_at is null
       or new.promoted_by_actor_id is distinct from old.promoted_by_actor_id
       or new.promoted_at is distinct from old.promoted_at
       or new.corrected_by_actor_id is distinct from old.corrected_by_actor_id
       or new.correction_reason is distinct from old.correction_reason
       or new.corrected_at is distinct from old.corrected_at then
      raise exception 'memory forgetting requires actor, reason, and timestamp';
    end if;
  else
    raise exception 'memory_item status transition is not an allowed lifecycle transition';
  end if;
  return new;
end $$;


--
-- Name: memory_item_insert_valid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.memory_item_insert_valid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior memory_item%rowtype; expected_root uuid;
begin
  -- Timestamps are server-owned; caller-supplied values are ignored.
  new.created_at := now();
  new.updated_at := new.created_at;
  if new.status <> 'candidate' or new.version <> 1
     or new.promoted_by_actor_id is not null or new.promoted_at is not null
     or new.corrected_by_actor_id is not null or new.correction_reason is not null or new.corrected_at is not null
     or new.forgotten_by_actor_id is not null or new.forget_reason is not null or new.forgotten_at is not null then
    raise exception 'new memory rows must start as clean candidate version 1';
  end if;
  if new.predecessor_id is null or new.lineage_root_id is null then
    if new.predecessor_id is not null or new.lineage_root_id is not null then
      raise exception 'new memory roots cannot carry partial lineage';
    end if;
    return new;
  end if;
  select * into prior from public.memory_item where id=new.predecessor_id;
  expected_root := coalesce(prior.lineage_root_id, prior.id);
  if not found or prior.status <> 'corrected'
     or prior.organization_tenant_id is distinct from new.organization_tenant_id
     or prior.scope is distinct from new.scope
     or prior.owner_actor_id is distinct from new.owner_actor_id
     or prior.kind is distinct from new.kind
     or prior.context is distinct from new.context
     or prior.confidence is distinct from new.confidence
     or prior.work_request_id is distinct from new.work_request_id
     or prior.work_request_version is distinct from new.work_request_version
     or prior.plan_id is distinct from new.plan_id
     or new.lineage_root_id is distinct from expected_root then
    raise exception 'memory successor lineage does not match corrected predecessor';
  end if;
  return new;
end $$;


--
-- Name: memory_item_plan_anchor_valid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.memory_item_plan_anchor_valid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare plan_row record;
begin
  if new.plan_id is null then return new; end if;
  select plan.work_request_id, plan.work_request_version, w.organization_tenant_id
    into plan_row
    from ops.sourced_work_request_plan plan
    join ops.work_request w on w.id=plan.work_request_id
   where plan.id=new.plan_id;
  if not found or plan_row.work_request_id is distinct from new.work_request_id
     or plan_row.work_request_version is distinct from new.work_request_version
     or plan_row.organization_tenant_id is distinct from new.organization_tenant_id then
    raise exception 'memory plan anchor is missing, cross-tenant, or mismatched';
  end if;
  return new;
end $$;


--
-- Name: normalize_retrieval_phrase(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_retrieval_phrase(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
  select regexp_replace(lower(btrim(value)), '\s+', ' ', 'g')
$$;


--
-- Name: org_identity_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_identity_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_name is null                then null
    when btrim(p_name) = ''            then null
    when btrim(p_name) like '(%'       then null   -- '(TBD)', '(new practice, relocating…)'
    when p_name ~* '\mtbd\M'
      or p_name ~* '\munknown\M'
      or p_name ~* '\mn/a\M'           then null   -- 'Startup dental practice (entity name TBD)'
    else lower(regexp_replace(btrim(p_name), '\s+', ' ', 'g'))
  end
$$;


--
-- Name: FUNCTION org_identity_key(p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.org_identity_key(p_name text) IS 'The identity of an ORGANISATION, normalised (0059): trim, collapse whitespace, lowercase, and NULL for a placeholder. Null means "this string names no organisation" — six rows are literally called "(TBD — enrich)" and collapsing them would assert that six unrelated people share an employer, which is a fabricated fact. Null keys are excluded from the merge and from party_org_identity_uniq, so placeholders stay separate and new ones stay legal. Deliberately does NOT strip legal suffixes or parentheticals: "Carr Riggs Ingram" and "Carr Riggs Ingram (advisory)" are different rows on purpose. The enrichment step that wants domain as an exact match key should EXTEND this function rather than invent a second normalisation rule.';


--
-- Name: org_party_id(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_party_id(p_name text, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare k text; found uuid;
begin
  k := org_identity_key(p_name);

  -- A placeholder has no identity, so it gets a fresh row exactly as today. Six unknowns are
  -- six unknowns, not one company.
  if k is null then
    insert into party (kind, name, created_by, updated_by)
         values ('org', p_name, p_actor, p_actor) returning id into found;
    return found;
  end if;

  select id into found from party
   where kind = 'org' and merged_into is null and deleted_at is null
     and org_identity_key(name) = k
   limit 1;
  if found is not null then return found; end if;

  begin
    insert into party (kind, name, created_by, updated_by)
         values ('org', btrim(p_name), p_actor, p_actor) returning id into found;
  exception when unique_violation then
    -- Two sessions created the same organisation at once. The index decided; re-read.
    select id into found from party
     where kind = 'org' and merged_into is null and deleted_at is null
       and org_identity_key(name) = k
     limit 1;
  end;
  return found;
end
$$;


--
-- Name: FUNCTION org_party_id(p_name text, p_actor uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.org_party_id(p_name text, p_actor uuid) IS 'Find-or-create an organisation party by normalised name, atomically (0059). Replaces the blind `insert into party ... values (''org'', $1, ...)` at mcp-server/src/tools.js:1156 (add-party) and :1281 (add-premises), which is what minted 17 Henry Schein rows. Race-safe against party_org_identity_uniq: the loser of a concurrent insert re-reads rather than failing. A placeholder name still mints a fresh row, on purpose.';


--
-- Name: promote_retrieval_proposal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_retrieval_proposal(p_proposal_id uuid, p_approver_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
declare p retrieval_proposal%rowtype; landed uuid; cid uuid; sid uuid;
begin
  if not exists (select 1 from actor where actor.id=p_approver_id and kind='human') then
    raise exception 'human_only';
  end if;
  select * into p from retrieval_proposal where id=p_proposal_id for update;
  if not found or p.status <> 'pending' then raise exception 'proposal is not pending'; end if;
  if p.proposal_type = 'concept' then
    insert into retrieval_concept
      (concept_key,label,definition,status,review_after,proposer_id,approver_id,approved_at)
    values (p.payload->>'concept_key',p.payload->>'label',p.payload->>'definition','approved',
            (p.payload->>'review_after')::timestamptz,p.proposer_id,p_approver_id,now()) returning id into landed;
  elsif p.proposal_type = 'phrase' then
    select id into cid from retrieval_concept
     where concept_key=p.payload->>'concept_key' and status='approved';
    if cid is null then raise exception 'approved concept not found'; end if;
    insert into retrieval_phrase
      (concept_id,display_phrase,match_mode,min_similarity,weight,status,source,source_ref,
       proposer_id,approver_id,approved_at)
    values (cid,p.payload->>'phrase',p.payload->>'match_mode',
            coalesce((p.payload->>'min_similarity')::numeric,.35),
            (p.payload->>'weight')::numeric,'approved',p.payload->>'source',p.payload->>'source_ref',
            p.proposer_id,p_approver_id,now()) returning id into landed;
  elsif p.proposal_type = 'mapping' then
    select id into cid from retrieval_concept
     where concept_key=p.payload->>'concept_key' and status='approved';
    select s.id into sid from doctrine_section s join doctrine_document d on d.id=s.document_id
     where d.slug=split_part(p.payload->>'section_address','#',1)
       and s.section_key=split_part(p.payload->>'section_address','#',2) and s.status='active';
    if cid is null or sid is null then raise exception 'approved concept or current section not found'; end if;
    insert into doctrine_concept_mapping
      (concept_id,section_id,role,weight,rationale,status,proposer_id,approver_id,approved_at)
    values (cid,sid,p.payload->>'role',(p.payload->>'weight')::numeric,p.payload->>'rationale',
            'approved',p.proposer_id,p_approver_id,now()) returning id into landed;
  elsif p.proposal_type = 'retire' then
    select r.id into landed from retire_retrieval_curation(
      p.payload->>'target_type',(p.payload->>'target_id')::uuid,
      (p.payload->>'base_version')::bigint,p_approver_id,p.reason) r;
    if landed is null then raise exception 'retirement version conflict'; end if;
  end if;
  update retrieval_proposal set status='approved', reviewer_id=p_approver_id,
         resulting_row_ids=array[landed], reviewed_at=now(), version=version+1
   where id=p.id;
  return landed;
end $$;


--
-- Name: resolve_memory_plan_anchor(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_memory_plan_anchor(p_plan_id uuid, p_tenant text) RETURNS TABLE(plan_id uuid, work_request_id uuid, work_request_version integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select p.id, p.work_request_id, p.work_request_version
    from ops.sourced_work_request_plan p
    join ops.work_request w on w.id=p.work_request_id
   where p.id=$1 and w.organization_tenant_id=$2;
$_$;


--
-- Name: retire_retrieval_curation(text, uuid, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retire_retrieval_curation(p_target_type text, p_target_id uuid, p_base_version bigint, p_actor_id uuid, p_reason text) RETURNS TABLE(id uuid, version bigint, status text)
    LANGUAGE plpgsql
    AS $$
begin
  if btrim(p_reason) = '' then raise exception 'retirement reason required'; end if;
  if not exists (select 1 from actor where actor.id=p_actor_id and kind='human') then
    raise exception 'human_only';
  end if;
  if p_target_type = 'concept' then
    update retrieval_concept set status='retired', retired_at=now(), version=version+1, updated_at=now()
     where retrieval_concept.id=p_target_id and retrieval_concept.version=p_base_version and status='approved'
     returning retrieval_concept.id, retrieval_concept.version, retrieval_concept.status into id, version, status;
    if id is not null then
      update retrieval_phrase set status='retired', retired_at=now(), version=version+1, updated_at=now()
       where concept_id=p_target_id and status='approved';
      update doctrine_concept_mapping set status='retired', retired_at=now(), version=version+1, updated_at=now()
       where concept_id=p_target_id and status in ('approved','needs_repair');
    end if;
  elsif p_target_type = 'phrase' then
    update retrieval_phrase set status='retired', retired_at=now(), version=version+1, updated_at=now()
     where retrieval_phrase.id=p_target_id and retrieval_phrase.version=p_base_version and status='approved'
     returning retrieval_phrase.id, retrieval_phrase.version, retrieval_phrase.status into id, version, status;
  elsif p_target_type = 'mapping' then
    update doctrine_concept_mapping set status='retired', retired_at=now(), version=version+1, updated_at=now()
     where doctrine_concept_mapping.id=p_target_id and doctrine_concept_mapping.version=p_base_version
       and status in ('approved','needs_repair')
     returning doctrine_concept_mapping.id, doctrine_concept_mapping.version,
               doctrine_concept_mapping.status into id, version, status;
  else raise exception 'unknown retrieval curation type %', p_target_type;
  end if;
  if id is not null then return next; end if;
end $$;


--
-- Name: retrieval_proposal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retrieval_proposal_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then raise exception 'retrieval proposals are append-only'; end if;
  if old.proposal_type is distinct from new.proposal_type
     or old.payload is distinct from new.payload
     or old.reason is distinct from new.reason
     or old.proposer_id is distinct from new.proposer_id
     or old.idempotency_key is distinct from new.idempotency_key
     or old.created_at is distinct from new.created_at then
    raise exception 'retrieval proposal evidence is immutable';
  end if;
  if old.status <> 'pending' or new.status not in ('approved','rejected','superseded') then
    raise exception 'retrieval proposal review transition invalid';
  end if;
  return new;
end $$;


--
-- Name: retrieval_visibility_actor_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retrieval_visibility_actor_id(p_sponsor_slug text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select id from actor
   where slug = p_sponsor_slug and kind = 'human' and active = true
$$;


--
-- Name: search_doctrine_situations(text, uuid, text[], integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_doctrine_situations(p_query text, p_actor_id uuid, p_content_classes text[] DEFAULT NULL::text[], p_limit integer DEFAULT 20, p_policy_id text DEFAULT NULL::text, p_allow_fallback boolean DEFAULT false) RETURNS TABLE(section_id uuid, section_key text, title text, doc_slug text, content_class text, rank double precision, snippet text, lexical_score double precision, concept_score double precision, final_score double precision, provenance jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with
  normalized as materialized (
    select normalize_retrieval_phrase(p_query) as q
  ),
  policy as materialized (
    select * from retrieval_ranking_policy
     where policy_id = coalesce(
       p_policy_id,
       (select policy_id from retrieval_ranking_policy where is_default and status='active'))
       and status in ('candidate','active')
  ),
  query_terms as materialized (
    select websearch_to_tsquery('english', q) as tsq from normalized
  ),
  current_set as materialized (
    select * from current_retrievable_doctrine(p_actor_id, p_content_classes)
  ),
  lexical_raw as (
    select c.section_id,
           ts_rank_cd(
             setweight(c.section_title_vector, 'A') ||
             setweight(c.document_title_vector, 'A') ||
             setweight(c.body_search_vector, 'B'), q.tsq) as raw_score,
           ts_headline('english', c.plain_text, q.tsq, 'MaxWords=25, MinWords=10') as snippet
      from current_set c cross join query_terms q
     where c.section_title_vector @@ q.tsq
        or c.document_title_vector @@ q.tsq
        or c.body_search_vector @@ q.tsq
  ),
  phrase_match as (
    select p.id as phrase_id, p.concept_id, p.weight as phrase_weight,
           case p.match_mode
             when 'exact' then case when p.normalized_phrase = n.q then 1.0 else 0.0 end
             when 'fts' then case
               when to_tsvector('english', p.normalized_phrase) @@ websearch_to_tsquery('english', n.q)
               then least(1.0, ts_rank_cd(to_tsvector('english', p.normalized_phrase),
                                         websearch_to_tsquery('english', n.q))::double precision)
               else 0.0 end
             when 'trgm' then case when similarity(p.normalized_phrase, n.q) >= p.min_similarity
               then similarity(p.normalized_phrase, n.q) else 0.0 end
           end::double precision as phrase_strength
      from retrieval_phrase p cross join normalized n
     where p.status = 'approved'
  ),
  concept_evidence as (
    select m.section_id, pm.phrase_id, pm.concept_id, m.id as mapping_id,
           pm.phrase_strength, pm.phrase_weight::double precision,
           m.weight::double precision as mapping_weight,
           (pm.phrase_strength * pm.phrase_weight * m.weight)::double precision as contribution
      from phrase_match pm
      join retrieval_concept c on c.id = pm.concept_id and c.status = 'approved'
      join doctrine_concept_mapping m on m.concept_id = c.id and m.status = 'approved'
      join current_set visible on visible.section_id = m.section_id
     where pm.phrase_strength > 0
  ),
  concept_by_section as (
    select section_id, max(contribution)::double precision as concept_score,
           array_agg(distinct phrase_id order by phrase_id) as phrase_ids,
           array_agg(distinct concept_id order by concept_id) as concept_ids,
           array_agg(distinct mapping_id order by mapping_id) as mapping_ids
      from concept_evidence group by section_id
  ),
  unioned as materialized (
    -- Coalesce FIRST, cap second: least(1.0, NULL) is 1.0 in PostgreSQL
    -- (nulls are ignored), which is the whole defect this migration removes.
    select c.*, least(1.0, coalesce(l.raw_score, 0))::double precision as lexical_score,
           least(1.0, coalesce(ce.concept_score, 0))::double precision as concept_score,
           l.snippet, coalesce(ce.phrase_ids, '{}') as phrase_ids,
           coalesce(ce.concept_ids, '{}') as concept_ids,
           coalesce(ce.mapping_ids, '{}') as mapping_ids,
           false as used_fallback
      from current_set c
      left join lexical_raw l on l.section_id = c.section_id
      left join concept_by_section ce on ce.section_id = c.section_id
     where l.section_id is not null or ce.section_id is not null
  ),
  fallback_terms as materialized (
    select websearch_to_tsquery('english', regexp_replace(q, ' ', ' OR ', 'g')) as tsq
      from normalized
  ),
  fallback_raw as (
    select c.section_id,
           ts_rank_cd(
             setweight(c.section_title_vector, 'A') ||
             setweight(c.document_title_vector, 'A') ||
             setweight(c.body_search_vector, 'B'), q.tsq) as raw_score,
           ts_headline('english', c.plain_text, q.tsq, 'MaxWords=25, MinWords=10') as snippet
      from current_set c cross join fallback_terms q
     where p_allow_fallback
       and not exists (select 1 from unioned)
       and (c.section_title_vector @@ q.tsq
         or c.document_title_vector @@ q.tsq
         or c.body_search_vector @@ q.tsq)
  ),
  fallback_unioned as (
    select c.*, least(1.0, coalesce(f.raw_score, 0))::double precision as lexical_score,
           0::double precision as concept_score,
           f.snippet, '{}'::uuid[] as phrase_ids,
           '{}'::uuid[] as concept_ids,
           '{}'::uuid[] as mapping_ids,
           true as used_fallback
      from current_set c
      join fallback_raw f on f.section_id = c.section_id
  ),
  combined as (
    select * from unioned
    union all
    select * from fallback_unioned
  ),
  maxima as (
    select greatest(max(lexical_score), 0) as max_lexical,
           greatest(max(concept_score), 0) as max_concept from combined
  ),
  scored as (
    select u.*,
           case p.formula
             when 'weighted_sum' then
               ((p.config->>'lexical_weight')::double precision * u.lexical_score +
                (p.config->>'concept_weight')::double precision *
                  case when coalesce((p.config->>'concept_enabled')::boolean,true)
                       then u.concept_score else 0 end)
             when 'coequal_normalized' then
               (case when x.max_lexical > 0 then u.lexical_score / x.max_lexical else 0 end) +
               (case when coalesce((p.config->>'concept_enabled')::boolean,true) and x.max_concept > 0
                     then u.concept_score / x.max_concept else 0 end) +
               (case when coalesce((p.config->>'concept_enabled')::boolean,true)
                           and u.lexical_score > 0 and u.concept_score > 0
                     then (p.config->>'dual_evidence_bonus')::double precision else 0 end)
           end::double precision as final_score,
           p.policy_id, p.version as policy_version
      from combined u cross join maxima x cross join policy p
  ),
  limited as materialized (
    select * from scored
     where final_score > 0
     order by final_score desc, concept_score desc, lexical_score desc, section_key asc
     limit greatest(1, least(coalesce(p_limit, 20), 100))
  )
select l.section_id, l.section_key, l.section_title, l.doc_slug, l.content_class,
       l.final_score as rank,
       coalesce(l.snippet, left(l.plain_text, 240)) as snippet,
       l.lexical_score, l.concept_score, l.final_score,
       jsonb_build_object(
         'complete', true, 'policy_id', l.policy_id, 'policy_version', l.policy_version,
         'lexical_score', l.lexical_score, 'concept_score', l.concept_score,
         'final_score', l.final_score, 'phrase_ids', to_jsonb(l.phrase_ids),
         'concept_ids', to_jsonb(l.concept_ids), 'mapping_ids', to_jsonb(l.mapping_ids))
       || case when l.used_fallback then jsonb_build_object('fallback', true)
               else '{}'::jsonb end
  from limited l
 order by l.final_score desc, l.concept_score desc, l.lexical_score desc, l.section_key asc
$$;


--
-- Name: state_as_of(text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.state_as_of(p_type text, p_id uuid, p_at timestamp with time zone) RETURNS TABLE(field text, value_at jsonb, changed_at timestamp with time zone, changed_by text, verb text, later_changes integer, current_value jsonb)
    LANGUAGE sql STABLE
    AS $$
  with hist as (
    select h.field, h.new_value, h.occurred_at, h.actor, h.verb
      from v_field_history h
     where h.subject_type = p_type and h.subject_id = p_id
  ), at_time as (
    select distinct on (field) field, new_value, occurred_at, actor, verb
      from hist where occurred_at <= p_at
     order by field, occurred_at desc
  ), now_val as (
    select distinct on (field) field, new_value
      from hist order by field, occurred_at desc
  )
  select a.field, a.new_value, a.occurred_at, a.actor, a.verb,
         -- THE COLUMN THAT MAKES THE ANSWER SAFE TO ACT ON. A value with later changes is a
         -- historical value; one with none is still current. Without this a caller cannot
         -- tell "this was true then and still is" from "this was true then and has moved",
         -- which is the entire question rule 3fa17fa0 makes a session stop and ask about.
         (select count(*)::int from hist h
           where h.field = a.field and h.occurred_at > p_at) as later_changes,
         n.new_value
    from at_time a left join now_val n on n.field = a.field
   order by a.field;
$$;


--
-- Name: FUNCTION state_as_of(p_type text, p_id uuid, p_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.state_as_of(p_type text, p_id uuid, p_at timestamp with time zone) IS 'What the record said about one subject at one instant (0106, loop #281). Returns the newest value of each field at or before the cutoff, plus later_changes and the current value beside it — because "this was true then and still is" and "this was true then and has since moved" are different answers and a caller must never have to guess which it holds.';


--
-- Name: trg_availability_norm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_availability_norm() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.rate_amount is not null
     and new.rate_basis in ('usd_mo_gross','usd_yr_gross')
     and new.rate_norm_gross_sf_yr is null then
    new.norm_owed := true;                       -- [A5] normalized-or-owed, enforced
  end if;
  return new;
end $$;


--
-- Name: trg_deal_participant_side(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_deal_participant_side() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare s text;
begin
  select side into s from participant_role where slug = new.role;

  if s = 'actor' then
    if new.actor_id is null then
      raise exception 'deal_participant.role=% is an ACTOR-side role (a CARR employee) and '
                      'needs actor_id. See participant_role.side.', new.role;
    end if;
    if new.party_id is not null then
      raise exception 'deal_participant.role=% is an ACTOR-side role and must NOT carry '
                      'party_id. role=''lead'' means the deal''s OWNING AGENT (joe or dell), '
                      'not the client — v_deal_board reads lead_owner off actor_id and never '
                      'looks at party_id. Writing the client''s party here makes one row '
                      'assert two different owners. If you want the client''s person on the '
                      'deal, that is role=''client_contact'', or just follow '
                      'deal -> client -> client.party_id, which is already exact and 1:1.',
                      new.role;
    end if;

  elsif s = 'party' then
    if new.party_id is null then
      raise exception 'deal_participant.role=% is a PARTY-side role (someone outside CARR) '
                      'and needs party_id. See participant_role.side.', new.role;
    end if;
    if new.actor_id is not null then
      raise exception 'deal_participant.role=% is a PARTY-side role and must NOT carry '
                      'actor_id — an actor is a CARR employee and this role is a '
                      'counterparty.', new.role;
    end if;
  end if;

  return new;
end
$$;


--
-- Name: FUNCTION trg_deal_participant_side(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_deal_participant_side() IS 'Enforces participant_role.side on deal_participant (0060): an actor-side role carries actor_id and never party_id, a party-side role the reverse, a role with a null side is left alone. Deliberately a trigger and not a CHECK: a CHECK cannot read participant_role, so it would have to hardcode the role names and would silently fail to cover any role added later. Here the vocabulary IS the rule, so declaring a new role''s side is all that is needed to constrain it.';


--
-- Name: trg_touch_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_touch_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  new.version    := old.version + 1;
  return new;
end $$;


