    expires_at timestamp with time zone,
    detail text,
    release_id uuid,
    provider text,
    provider_version_id text,
    CONSTRAINT a_failed_deployment_names_its_class CHECK (((state <> 'failed'::text) OR (failure_class IS NOT NULL))),
