    statement_hash text NOT NULL,
    anchored_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_approval_lifecycle_anchor_rule_version_after_check CHECK ((rule_version_after > 0)),
    CONSTRAINT rule_approval_lifecycle_anchor_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: rule_approval_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_approval_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    rule_id uuid NOT NULL,
    rule_version integer NOT NULL,
    statement_hash text NOT NULL,
    actor_id uuid NOT NULL,
    policy_kind text NOT NULL,
    enforcement_status text NOT NULL,
    requested_control_keys text[] NOT NULL,
    installed_control_keys text[] NOT NULL,
    reason text NOT NULL,
    normalized_contract jsonb NOT NULL,
    contract_hash text NOT NULL,
    evidence_refs text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approved_controls_are_exact CHECK ((requested_control_keys = installed_control_keys)),
    CONSTRAINT rule_approval_contract_hash_matches CHECK ((contract_hash = encode(public.digest((normalized_contract)::text, 'sha256'::text), 'hex'::text))),
    CONSTRAINT rule_approval_receipt_contract_hash_check CHECK ((contract_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_approval_receipt_enforcement_status_check CHECK ((enforcement_status = ANY (ARRAY['hard_enforced'::text, 'authority_enforced'::text]))),
    CONSTRAINT rule_approval_receipt_evidence_refs_check CHECK ((cardinality(evidence_refs) > 0)),
    CONSTRAINT rule_approval_receipt_installed_control_keys_check CHECK ((cardinality(installed_control_keys) > 0)),
    CONSTRAINT rule_approval_receipt_normalized_contract_check CHECK ((jsonb_typeof(normalized_contract) = 'object'::text)),
    CONSTRAINT rule_approval_receipt_policy_kind_check CHECK ((policy_kind = ANY (ARRAY['machine_enforceable'::text, 'human_only'::text]))),
    CONSTRAINT rule_approval_receipt_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT rule_approval_receipt_requested_control_keys_check CHECK ((cardinality(requested_control_keys) > 0)),
    CONSTRAINT rule_approval_receipt_rule_version_check CHECK ((rule_version > 0)),
    CONSTRAINT rule_approval_receipt_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: rule_control_binding; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_control_binding (
    rule_id uuid NOT NULL,
    control_key text NOT NULL,
    statement_hash text NOT NULL,
    binding_contract jsonb NOT NULL,
    bound_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_control_binding_binding_contract_check CHECK ((jsonb_typeof(binding_contract) = 'object'::text)),
    CONSTRAINT rule_control_binding_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE rule_control_binding; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_control_binding IS 'Owner/deployment-authored exact semantic binding. A globally installed gate cannot be claimed for an unrelated rule or changed statement.';


--
-- Name: rule_delivery_policy; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_delivery_policy (
    singleton boolean DEFAULT true NOT NULL,
    mode text DEFAULT 'shadow'::text NOT NULL,
    changed_by text,
    reason text,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_delivery_policy_mode CHECK ((mode = ANY (ARRAY['shadow'::text, 'enforced'::text]))),
    CONSTRAINT rule_delivery_policy_singleton CHECK (singleton)
);


--
-- Name: TABLE rule_delivery_policy; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_delivery_policy IS 'shadow = compute the scoped set, report it, recite everything anyway. enforced = deliver the scoped set. Both council chairs required a week of shadow at zero unexplained misses before this row may say enforced.';


--
-- Name: rule_enforcement_point; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_enforcement_point (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_id uuid NOT NULL,
    control_key text NOT NULL,
    implementation_ref text NOT NULL,
    test_ref text NOT NULL,
    enforcement_class text NOT NULL,
    installed boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    CONSTRAINT installed_control_has_verification CHECK (((NOT installed) OR (btrim(test_ref) <> ''::text))),
    CONSTRAINT rule_enforcement_point_enforcement_class_check CHECK ((enforcement_class = ANY (ARRAY['deny_gate'::text, 'stop_gate'::text, 'schema'::text, 'surfacing'::text, 'transactional_schema'::text, 'judgment_ambient'::text])))
);


--
-- Name: rule_load_layer; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_load_layer (
    rule_id uuid NOT NULL,
    short_id text NOT NULL,
    load_layer text NOT NULL,
    packs text[] DEFAULT '{}'::text[] NOT NULL,
    scope text NOT NULL,
    why text,
    source text NOT NULL,
    map_digest text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_load_layer_known CHECK ((load_layer = ANY (ARRAY['layer0'::text, 'control'::text, 'pack'::text]))),
    CONSTRAINT rule_load_layer_layer0_reasoned CHECK (((load_layer <> 'layer0'::text) OR (COALESCE(btrim(why), ''::text) <> ''::text))),
    CONSTRAINT rule_load_layer_layer0_unconditional CHECK (((load_layer <> 'layer0'::text) OR (cardinality(packs) = 0))),
    CONSTRAINT rule_load_layer_no_wildcard CHECK ((NOT ('*'::text = ANY (packs)))),
    CONSTRAINT rule_load_layer_pack_has_pack CHECK (((load_layer <> 'pack'::text) OR (cardinality(packs) >= 1))),
    CONSTRAINT rule_load_layer_scope CHECK ((scope = ANY (ARRAY['shared'::text, 'joe'::text, 'dell'::text])))
);


--
-- Name: TABLE rule_load_layer; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_load_layer IS 'WHEN each active rule''s text reaches a session. layer0 = every boot. control = an installed deny/stop/schema control prints it at the moment it binds. pack = when the observed work matches a pack trigger. ops/rule-load-layer-check.py holds the same contract statically, including the one this table cannot see: that `control` is only honest for a rule whose enforcement_class is actually built.';


--
-- Name: rule_pack; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_pack (
    pack text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    triggers text[] NOT NULL,
    source text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_pack_has_triggers CHECK ((cardinality(triggers) >= 1)),
    CONSTRAINT rule_pack_named CHECK (((btrim(pack) <> ''::text) AND (pack <> '*'::text) AND (btrim(title) <> ''::text) AND (btrim(description) <> ''::text))),
    CONSTRAINT rule_pack_no_wildcard_trigger CHECK ((NOT ('*'::text = ANY (triggers))))
);


--
-- Name: TABLE rule_pack; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_pack IS 'The task packs a session can load. Triggers are OBSERVED-WORK nouns and verbs, never session names: rule 347a9ca6 forbids predicting the work from the title.';


--
-- Name: rule_retirement_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_retirement_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    rule_id uuid NOT NULL,
    rule_version_before integer NOT NULL,
    rule_version_after integer NOT NULL,
    statement_hash text NOT NULL,
    previous_status text NOT NULL,
    actor_id uuid NOT NULL,
    reason text NOT NULL,
    superseded_by uuid,
    approval_receipt_id uuid,
    contract_hash text NOT NULL,
    retired_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT active_retirement_has_approval CHECK (((previous_status <> 'active'::text) OR (approval_receipt_id IS NOT NULL))),
    CONSTRAINT rule_retirement_receipt_check CHECK ((rule_version_after = (rule_version_before + 1))),
    CONSTRAINT rule_retirement_receipt_contract_hash_check CHECK ((contract_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_retirement_receipt_idempotency_key_check CHECK ((btrim(idempotency_key) <> ''::text)),
    CONSTRAINT rule_retirement_receipt_previous_status_check CHECK ((previous_status = ANY (ARRAY['proposed'::text, 'active'::text]))),
    CONSTRAINT rule_retirement_receipt_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT rule_retirement_receipt_rule_version_before_check CHECK ((rule_version_before > 0)),
    CONSTRAINT rule_retirement_receipt_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: run; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    service_id uuid NOT NULL,
    environment text NOT NULL,
    run_key text NOT NULL,
    state text NOT NULL,
    failure_class text,
    exit_code integer,
    attempt integer DEFAULT 1 NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    duration_ms integer GENERATED ALWAYS AS (
CASE
    WHEN ((started_at IS NOT NULL) AND (ended_at IS NOT NULL)) THEN ((EXTRACT(epoch FROM (ended_at - started_at)) * (1000)::numeric))::integer
    ELSE NULL::integer
END) STORED,
    source_kind text NOT NULL,
    source_ref text NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    evidence_ref text,
    detail text,
    release_id uuid,
    budget_ms integer,
    recovery_strategy text,
    recovery_plan_ref text,
    recovery_rehearsal_bundle_id uuid,
    CONSTRAINT a_failure_names_its_class CHECK (((state <> ALL (ARRAY['failed'::text, 'timed_out'::text])) OR (failure_class IS NOT NULL))),
    CONSTRAINT a_run_that_ended_also_started CHECK (((ended_at IS NULL) OR (started_at IS NOT NULL))),
    CONSTRAINT a_terminal_run_has_ended CHECK (((state <> ALL (ARRAY['succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'skipped'::text])) OR (ended_at IS NOT NULL))),
    CONSTRAINT run_attempt_check CHECK ((attempt >= 1)),
    CONSTRAINT run_environment_check CHECK ((environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text]))),
    CONSTRAINT run_kind_check CHECK ((kind = ANY (ARRAY['job'::text, 'check'::text]))),
    CONSTRAINT run_source_kind_check CHECK ((source_kind = ANY (ARRAY['collector'::text, 'registry'::text, 'wrapper'::text, 'operator'::text]))),
    CONSTRAINT run_state_check CHECK ((state = ANY (ARRAY['scheduled'::text, 'queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'skipped'::text, 'stale'::text, 'unknown'::text])))
);


--
-- Name: TABLE run; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.run IS 'The job-run ledger and the synthetic golden-workflow ledger, one shape, as the frozen Run contract defines them. Holds NO business payload: evidence_ref points, detail is one redacted line.';


--
-- Name: service; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.service (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key text NOT NULL,
    name text NOT NULL,
    purpose text,
    family text,
    criticality text DEFAULT 'medium'::text NOT NULL,
    owner_actor text NOT NULL,
    repo_path text,
    runtime text,
    runbook_ref text,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT service_criticality_check CHECK ((criticality = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))
);


--
-- Name: TABLE service; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.service IS 'The service catalog as ROWS. It existed as prose in the Program 0 inventory and as frozen JSON contracts; a catalog nothing can query is a document.';


--
-- Name: service_dependency; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.service_dependency (
    service_id uuid NOT NULL,
    depends_on_id uuid NOT NULL,
    note text,
    CONSTRAINT a_service_does_not_depend_on_itself CHECK ((service_id <> depends_on_id))
);


--
-- Name: TABLE service_dependency; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.service_dependency IS 'Upstream/downstream blast radius. The BDUF requires every dependency graphic to have an accessible list equivalent; this table IS that list, and the graphic is derived from it rather than the other way round.';


--
-- Name: service_environment; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.service_environment (
    service_id uuid NOT NULL,
    environment text NOT NULL,
    endpoint text,
    deploy_mechanism text,
    expected_cadence_seconds integer,
    cadence_grace_seconds integer DEFAULT 0 NOT NULL,
    notes text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT service_environment_cadence_grace_seconds_check CHECK ((cadence_grace_seconds >= 0)),
    CONSTRAINT service_environment_environment_check CHECK ((environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text]))),
    CONSTRAINT service_environment_expected_cadence_seconds_check CHECK (((expected_cadence_seconds IS NULL) OR (expected_cadence_seconds > 0)))
);


--
-- Name: COLUMN service_environment.expected_cadence_seconds; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.service_environment.expected_cadence_seconds IS 'How long an observation of this service in this environment stays believable when the run does not declare its own expiry. NULL means unscheduled, which makes every observation unknown rather than fresh — deliberately.';


--
-- Name: settings_change; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.settings_change (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text NOT NULL,
    target text NOT NULL,
    reason text NOT NULL,
    outcome text NOT NULL,
    session_id text NOT NULL,
    actor text,
    command text,
    environment text,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT a_reason_has_to_say_something CHECK ((length(btrim(reason)) >= 8)),
    CONSTRAINT settings_change_environment_check CHECK (((environment IS NULL) OR (environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text])))),
    CONSTRAINT settings_change_outcome_check CHECK ((outcome = ANY (ARRAY['applied'::text, 'failed'::text])))
);


--
-- Name: TABLE settings_change; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.settings_change IS 'Every change to a control plane this system does not own — GitHub rulesets, Actions variables and secrets, branch protection, launchd jobs, git config, Worker secrets. Written by hooks/settings-change-gate.py AT THE MOMENT OF THE CHANGE, because a record that waits for the session to finish dies with it.';


--
-- Name: COLUMN settings_change.reason; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.settings_change.reason IS 'Why the change was made, in the words of whoever made it. The 2026-08-14 ruleset incident was not a missing change log — it was a missing REASON: the change itself was discoverable from GitHub''s own version history within minutes, and still nobody could tell an authorised change from tampering.';


--
-- Name: sourced_work_request_outcome_feedback; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_outcome_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    feedback_version integer NOT NULL,
    idempotency_key uuid NOT NULL,
    work_request_version integer CONSTRAINT sourced_work_request_outcome_feed_work_request_version_not_null NOT NULL,
    plan_id uuid NOT NULL,
    plan_acceptance_receipt_id uuid CONSTRAINT sourced_work_request_outcom_plan_acceptance_receipt_id_not_null NOT NULL,
    preimage jsonb NOT NULL,
    criterion_results jsonb CONSTRAINT sourced_work_request_outcome_feedbac_criterion_results_not_null NOT NULL,
    evidence_refs jsonb NOT NULL,
    outcome text NOT NULL,
    blocker_code text NOT NULL,
    result_summary text NOT NULL,
    observed_minutes integer NOT NULL,
    interaction_surface text CONSTRAINT sourced_work_request_outcome_feedb_interaction_surface_not_null NOT NULL,
    heavy_session_used boolean CONSTRAINT sourced_work_request_outcome_feedba_heavy_session_used_not_null NOT NULL,
    manual_context_transfers integer CONSTRAINT sourced_work_request_outcome__manual_context_transfers_not_null NOT NULL,
    feedback_hash text NOT NULL,
    feedback_ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sourced_work_request_outcome_fee_manual_context_transfers_check CHECK (((manual_context_transfers >= 0) AND (manual_context_transfers <= 100))),
    CONSTRAINT sourced_work_request_outcome_feedbac_work_request_version_check CHECK ((work_request_version > 0)),
    CONSTRAINT sourced_work_request_outcome_feedback_blocker_code_check CHECK ((blocker_code = ANY (ARRAY['none'::text, 'evidence_missing'::text, 'criterion_not_met'::text, 'external_dependency'::text, 'system_error'::text]))),
    CONSTRAINT sourced_work_request_outcome_feedback_criterion_results_check CHECK ((jsonb_typeof(criterion_results) = 'array'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_evidence_refs_check CHECK ((jsonb_typeof(evidence_refs) = 'array'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_feedback_hash_check CHECK ((feedback_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_feedback_ref_check CHECK ((feedback_ref ~ '^OUTCOME-[0-9a-f]{12}-v[1-9][0-9]*$'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_feedback_version_check CHECK ((feedback_version > 0)),
    CONSTRAINT sourced_work_request_outcome_feedback_interaction_surface_check CHECK ((interaction_surface = ANY (ARRAY['workspace'::text, 'control_room'::text, 'mcp'::text, 'codex'::text, 'claude_code'::text, 'other'::text]))),
    CONSTRAINT sourced_work_request_outcome_feedback_observed_minutes_check CHECK (((observed_minutes >= 1) AND (observed_minutes <= 1440))),
    CONSTRAINT sourced_work_request_outcome_feedback_outcome_check CHECK ((outcome = ANY (ARRAY['criteria_met'::text, 'criteria_not_met'::text, 'inconclusive'::text]))),
    CONSTRAINT sourced_work_request_outcome_feedback_preimage_check CHECK ((jsonb_typeof(preimage) = 'object'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_result_summary_check CHECK (((btrim(result_summary) <> ''::text) AND (char_length(result_summary) <= 500)))
);


--
-- Name: TABLE sourced_work_request_outcome_feedback; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.sourced_work_request_outcome_feedback IS 'Append-only bounded Program 6 outcome-feedback proposal. It binds every criterion result, evidence reference, blocker and measured operating fact to one accepted ready plan; it is not a claim of execution.';


--
-- Name: sourced_work_request_outcome_feedback_acceptance_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_outcome_feedback_acceptance_receipt (
    id uuid DEFAULT gen_random_uuid() CONSTRAINT sourced_work_request_outcome_feedback_acceptance_re_id_not_null NOT NULL,
    work_request_id uuid CONSTRAINT sourced_work_request_outcome_feedback__work_request_id_not_null NOT NULL,
    feedback_id uuid CONSTRAINT sourced_work_request_outcome_feedback_acce_feedback_id_not_null NOT NULL,
    idempotency_key uuid CONSTRAINT sourced_work_request_outcome_feedback__idempotency_key_not_null NOT NULL,
    base_version integer CONSTRAINT sourced_work_request_outcome_feedback_acc_base_version_not_null NOT NULL,
    feedback_hash text CONSTRAINT sourced_work_request_outcome_feedback_ac_feedback_hash_not_null NOT NULL,
    accepted_by_actor_id uuid CONSTRAINT sourced_work_request_outcome_feed_accepted_by_actor_id_not_null NOT NULL,
    accepted_at timestamp with time zone DEFAULT clock_timestamp() CONSTRAINT sourced_work_request_outcome_feedback_acce_accepted_at_not_null NOT NULL,
    result_version integer CONSTRAINT sourced_work_request_outcome_feedback_a_result_version_not_null NOT NULL,
    CONSTRAINT sourced_work_request_outcome_feedback_acce_result_version_check CHECK ((result_version > 0)),
    CONSTRAINT sourced_work_request_outcome_feedback_accep_feedback_hash_check CHECK ((feedback_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_accept_base_version_check CHECK ((base_version > 0))
);


--
-- Name: TABLE sourced_work_request_outcome_feedback_acceptance_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.sourced_work_request_outcome_feedback_acceptance_receipt IS 'Private append-only human-authority receipt for an outcome-feedback proposal. Independence is the routine-writer proposal versus human acceptance; acceptance leaves the Work Request ready and grants no execution authority.';


--
-- Name: sourced_work_request_plan; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_plan (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    plan_version integer NOT NULL,
    idempotency_key uuid NOT NULL,
    work_request_version integer NOT NULL,
    preimage jsonb NOT NULL,
    scope_summary text NOT NULL,
    runbook_ref text NOT NULL,
    runbook_section_id uuid NOT NULL,
    runbook_revision_id uuid NOT NULL,
    runbook_content_hash text NOT NULL,
    dependency_refs jsonb NOT NULL,
    recovery_ref text NOT NULL,
    observability_ref text NOT NULL,
    caps jsonb NOT NULL,
    plan_hash text NOT NULL,
    plan_ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sourced_work_request_plan_caps_check CHECK ((jsonb_typeof(caps) = 'object'::text)),
    CONSTRAINT sourced_work_request_plan_dependency_refs_check CHECK ((jsonb_typeof(dependency_refs) = 'array'::text)),
    CONSTRAINT sourced_work_request_plan_observability_ref_check CHECK (((observability_ref ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'::text) AND (char_length(observability_ref) <= 300))),
    CONSTRAINT sourced_work_request_plan_plan_hash_check CHECK ((plan_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT sourced_work_request_plan_plan_ref_check CHECK ((plan_ref ~ '^PLAN-[0-9a-f]{12}-v[1-9][0-9]*$'::text)),
    CONSTRAINT sourced_work_request_plan_plan_version_check CHECK ((plan_version > 0)),
    CONSTRAINT sourced_work_request_plan_preimage_check CHECK ((jsonb_typeof(preimage) = 'object'::text)),
    CONSTRAINT sourced_work_request_plan_recovery_ref_check CHECK (((recovery_ref ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'::text) AND (char_length(recovery_ref) <= 300))),
    CONSTRAINT sourced_work_request_plan_runbook_content_hash_check CHECK ((runbook_content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT sourced_work_request_plan_runbook_ref_check CHECK ((runbook_ref ~ '^doctrine:runbook#[a-z0-9][a-z0-9-]*$'::text)),
    CONSTRAINT sourced_work_request_plan_scope_summary_check CHECK (((btrim(scope_summary) <> ''::text) AND (char_length(scope_summary) <= 1000))),
    CONSTRAINT sourced_work_request_plan_work_request_version_check CHECK ((work_request_version > 0))
);


--
-- Name: TABLE sourced_work_request_plan; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.sourced_work_request_plan IS 'Append-only Program 6 plan preimage. It binds a triaged sourced Work Request to one current shared pre-authored runbook and bounded metadata; it is not executable.';


--
-- Name: sourced_work_request_plan_acceptance_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_plan_acceptance_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid CONSTRAINT sourced_work_request_plan_acceptance_r_work_request_id_not_null NOT NULL,
    plan_id uuid NOT NULL,
    idempotency_key uuid CONSTRAINT sourced_work_request_plan_acceptance_r_idempotency_key_not_null NOT NULL,
    base_version integer CONSTRAINT sourced_work_request_plan_acceptance_rece_base_version_not_null NOT NULL,
    plan_hash text NOT NULL,
    accepted_by_actor_id uuid CONSTRAINT sourced_work_request_plan_accepta_accepted_by_actor_id_not_null NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() CONSTRAINT sourced_work_request_plan_acceptance_recei_accepted_at_not_null NOT NULL,
    result_version integer CONSTRAINT sourced_work_request_plan_acceptance_re_result_version_not_null NOT NULL,
    shape_fixed_surface_ref text CONSTRAINT sourced_work_request_plan_acce_shape_fixed_surface_ref_not_null NOT NULL,
    shape_rationale text CONSTRAINT sourced_work_request_plan_acceptance_r_shape_rationale_not_null NOT NULL,
    CONSTRAINT sourced_work_request_plan_acceptance_recei_result_version_check CHECK ((result_version > 0)),
    CONSTRAINT sourced_work_request_plan_acceptance_receipt_base_version_check CHECK ((base_version > 0)),
    CONSTRAINT sourced_work_request_plan_acceptance_receipt_plan_hash_check CHECK ((plan_hash ~ '^sha256:[0-9a-f]{64}$'::text))
