);


--
-- Name: work_request; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.work_request (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ref text NOT NULL,
    state text DEFAULT 'captured'::text NOT NULL,
    title text NOT NULL,
    desired_outcome text,
    acceptance_criteria jsonb DEFAULT '[]'::jsonb NOT NULL,
    origin_ref text,
    requester_actor text NOT NULL,
    owner_actor text,
    executor_actor text,
    blocker_code text,
    blocker_detail text,
    verification_accepted_at timestamp with time zone,
    verification_evidence_ref text,
    exit_reason text,
    superseded_by uuid,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    started_at timestamp with time zone,
    closed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    correlation_id uuid,
    program_key text,
    program_ordinal smallint,
    disposition text,
    existing_status text,
    project_context jsonb DEFAULT '{}'::jsonb NOT NULL,
    completion_kind text,
    completion_evidence jsonb,
    version integer DEFAULT 1 NOT NULL,
    shape_disposition text,
    shape_fixed_surface_ref text,
    shape_rationale text,
    shape_decided_by_actor_id uuid,
    shape_decided_at timestamp with time zone,
    organization_tenant_id text,
    doctrine_section_id uuid,
    doctrine_revision_id uuid,
    capture_idempotency_key uuid,
    sourced_capture_sequence bigint,
    triage_classification text,
    triaged_by_actor_id uuid,
    triaged_at timestamp with time zone,
    CONSTRAINT blocked_needs_a_named_blocker CHECK (((state <> 'blocked'::text) OR ((blocker_code IS NOT NULL) AND (blocker_detail IS NOT NULL)))),
    CONSTRAINT confirmed_close_needs_accepted_verification CHECK (((state <> 'confirmed_closed'::text) OR (verification_accepted_at IS NOT NULL))),
    CONSTRAINT side_exits_record_a_reason CHECK (((state <> ALL (ARRAY['declined'::text, 'superseded'::text, 'failed'::text])) OR (exit_reason IS NOT NULL))),
    CONSTRAINT superseded_names_its_successor CHECK (((state <> 'superseded'::text) OR (superseded_by IS NOT NULL))),
    CONSTRAINT terminal_rows_are_closed CHECK (((state = ANY (ARRAY['confirmed_closed'::text, 'declined'::text, 'superseded'::text])) = (closed_at IS NOT NULL))),
    CONSTRAINT work_request_program_close_has_bundle CHECK (((program_key IS NULL) OR (state <> 'confirmed_closed'::text) OR ((completion_kind IS NOT NULL) AND (completion_evidence IS NOT NULL)))),
    CONSTRAINT work_request_program_completion_kind CHECK (((completion_kind IS NULL) OR (completion_kind = ANY (ARRAY['built'::text, 'extended'::text, 'adopted'::text, 'declined'::text])))),
    CONSTRAINT work_request_program_disposition CHECK (((disposition IS NULL) OR (disposition = ANY (ARRAY['build'::text, 'extend'::text, 'adopt'::text, 'decline'::text])))),
    CONSTRAINT work_request_program_fields_travel_together CHECK (((program_key IS NULL) = (program_ordinal IS NULL))),
    CONSTRAINT work_request_program_ordinal_positive CHECK (((program_ordinal IS NULL) OR (program_ordinal > 0))),
    CONSTRAINT work_request_shape_disposition_complete CHECK ((((shape_disposition IS NULL) AND (shape_fixed_surface_ref IS NULL) AND (shape_rationale IS NULL) AND (shape_decided_by_actor_id IS NULL) AND (shape_decided_at IS NULL)) OR ((shape_disposition = 'required'::text) AND (shape_fixed_surface_ref IS NULL) AND (shape_rationale IS NOT NULL) AND (btrim(shape_rationale) <> ''::text) AND (shape_decided_by_actor_id IS NOT NULL) AND (shape_decided_at IS NOT NULL)) OR ((shape_disposition = 'not_required'::text) AND (shape_fixed_surface_ref IS NOT NULL) AND (btrim(shape_fixed_surface_ref) <> ''::text) AND (shape_rationale IS NOT NULL) AND (btrim(shape_rationale) <> ''::text) AND (shape_decided_by_actor_id IS NOT NULL) AND (shape_decided_at IS NOT NULL)))),
    CONSTRAINT work_request_shape_disposition_valid CHECK (((shape_disposition IS NULL) OR (shape_disposition = ANY (ARRAY['required'::text, 'not_required'::text])))),
    CONSTRAINT work_request_state_check CHECK ((state = ANY (ARRAY['captured'::text, 'triaged'::text, 'ready'::text, 'claimed'::text, 'in_progress'::text, 'verification'::text, 'awaiting_release'::text, 'released'::text, 'confirmed_closed'::text, 'needs_joe'::text, 'blocked'::text, 'declined'::text, 'superseded'::text, 'failed'::text])))
);


--
-- Name: TABLE work_request; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.work_request IS 'The canonical Work Request. States come from control-room/contracts/state-machines.v1.json; the Workspace projection is defined by control-room/contracts/work-request-projection.v1.json and is derived, never stored. TRANSITIONS ARE SERVER-ENFORCED, not enforced here: doctrine requires it and the guards need evidence a CHECK cannot see. This table guarantees only that a row is never in an undefined state and never violates an invariant the machine declares about states.';


--
-- Name: COLUMN work_request.correlation_id; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.correlation_id IS 'Nullable on purpose: rows predate correlation, and a work request captured by hand has no journey behind it. Present when the request came out of a traced failure.';


--
-- Name: COLUMN work_request.project_context; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.project_context IS 'Session-complete context for one governed portfolio item: scope, non-goals, prerequisites, first deliverable, acceptance, rollback, data risk, effort, evidence and completion meaning. Operational metadata only; never client payload or secrets.';


--
-- Name: COLUMN work_request.shape_disposition; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.shape_disposition IS 'Mandatory before a request enters implementation: required runs the evidence-backed shape method; not_required cites the already-fixed implementation surface. Null is permitted while work is captured or triaged and on pre-0130 ready rows, which the implementation-entry gate still refuses until classified.';


--
-- Name: COLUMN work_request.organization_tenant_id; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.organization_tenant_id IS 'Server-derived CARR organization tenant for sourced Program 6 capture. Historical rows remain null.';


--
-- Name: COLUMN work_request.doctrine_revision_id; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.doctrine_revision_id IS 'Exact current doctrine revision that grounded a sourced capture; a stale or invented revision is refused.';


--
-- Name: v_capability_program_next; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_capability_program_next AS
 SELECT id,
    ref,
    state,
    title,
    desired_outcome,
    acceptance_criteria,
    origin_ref,
    requester_actor,
    owner_actor,
    executor_actor,
    blocker_code,
    blocker_detail,
    verification_accepted_at,
    verification_evidence_ref,
    exit_reason,
    superseded_by,
    captured_at,
    claimed_at,
    started_at,
    closed_at,
    updated_at,
    correlation_id,
    program_key,
    program_ordinal,
    disposition,
    existing_status,
    project_context,
    completion_kind,
    completion_evidence,
    version
   FROM ops.work_request w
  WHERE ((program_key IS NOT NULL) AND (state <> 'confirmed_closed'::text) AND (NOT (EXISTS ( SELECT 1
           FROM ops.work_request p
          WHERE ((p.program_key = w.program_key) AND (p.program_ordinal < w.program_ordinal) AND (p.state <> 'confirmed_closed'::text))))));


--
-- Name: VIEW v_capability_program_next; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_capability_program_next IS 'Exactly the first not-yet-verified Work Request in each ordered capability program. Blocked, failed, needs-Joe and verification rows remain current; later rows never skip them.';


--
-- Name: v_check_run; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_check_run AS
 SELECT id,
    correlation_id,
    kind,
    service_id,
    environment,
    run_key,
    state,
    failure_class,
    exit_code,
    attempt,
    started_at,
    ended_at,
    duration_ms,
    source_kind,
    source_ref,
    observed_at,
    expires_at,
    evidence_ref,
    detail
   FROM ops.run
  WHERE (kind = 'check'::text);


--
-- Name: actor; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.actor (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    kind text NOT NULL,
    display_name text NOT NULL,
    email text,
    active boolean DEFAULT true NOT NULL,
    phone text,
    CONSTRAINT actor_kind_check CHECK ((kind = ANY (ARRAY['human'::text, 'automation'::text, 'system'::text])))
);


--
-- Name: loop_block; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loop_block (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rel_path text NOT NULL,
    kind text NOT NULL,
    seq integer NOT NULL,
    block_key text,
    prose_md text DEFAULT ''::text NOT NULL,
    header_cols text[],
    col_order text[],
    renders_closed boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT loop_block_header_needs_columns CHECK (((header_cols IS NULL) OR (col_order IS NOT NULL))),
    CONSTRAINT loop_block_kind_check CHECK ((kind = ANY (ARRAY['open_loop'::text, 'team_loop'::text, 'action_required'::text, 'idea'::text]))),
    CONSTRAINT loop_block_prose_has_no_columns CHECK (((block_key IS NULL) = (col_order IS NULL)))
);


--
-- Name: TABLE loop_block; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.loop_block IS 'File scaffolding for the generated loop renders: the prose, the section order and the table headers of open-loops.md, open-loops-backlog.md, action-required.md and team-loops.md, stored as data so the render reproduces the file and the doctrine prose stays editable by the human rather than by a code change.';


--
-- Name: COLUMN loop_block.col_order; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_block.col_order IS 'Positional semantic column names. Vocabulary: number, owner, title, body, since_text, unblocks, source_note, closed_text, outcome, and extra:<key> for a cell the canonical set has no home for. A row may override this with its own col_order when the source row''s width disagrees with the header.';


--
-- Name: loop_item; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loop_item (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    number text NOT NULL,
    block_id uuid NOT NULL,
    render_seq integer NOT NULL,
    col_order text[],
    title text,
    body text,
    owner text,
    since_text text,
    unblocks text,
    source_note text,
    closed_text text,
    outcome text,
    extra_cells jsonb DEFAULT '{}'::jsonb NOT NULL,
    marker text DEFAULT 'none'::text NOT NULL,
    marker_literal text,
    due_on date,
    drift_critical boolean DEFAULT false NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    close_outcome text,
    closed_by uuid,
    closed_at timestamp with time zone,
    tier text NOT NULL,
    personal_to uuid,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid NOT NULL,
    domain text,
    blocker_class text,
    blocker_detail text,
    CONSTRAINT loop_item_blocker_class_known CHECK (((blocker_class IS NULL) OR (blocker_class = ANY (ARRAY['human_only'::text, 'counterparty'::text, 'ruling'::text, 'external_event'::text, 'other_lane'::text, 'capability'::text])))),
    CONSTRAINT loop_item_blocker_detail_present CHECK (((blocker_class IS NULL) OR ((blocker_detail IS NOT NULL) AND (length(btrim(blocker_detail)) >= 12)))),
    CONSTRAINT loop_item_closed_has_outcome CHECK (((status = 'open'::text) OR (close_outcome IS NOT NULL))),
    CONSTRAINT loop_item_closed_stamped CHECK (((status = 'open'::text) = (closed_at IS NULL))),
    CONSTRAINT loop_item_kind_check CHECK ((kind = ANY (ARRAY['open_loop'::text, 'team_loop'::text, 'action_required'::text, 'idea'::text]))),
    CONSTRAINT loop_item_marker_check CHECK ((marker = ANY (ARRAY['bell'::text, 'dated'::text, 'decision'::text, 'none'::text]))),
    CONSTRAINT loop_item_owner_known CHECK (((owner IS NULL) OR (owner = ANY (ARRAY['joe'::text, 'dell'::text, 'claude'::text, 'joint'::text])))),
    CONSTRAINT loop_item_personal_tier CHECK (((tier = 'personal'::text) = (personal_to IS NOT NULL))),
    CONSTRAINT loop_item_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'dropped'::text]))),
    CONSTRAINT loop_item_tier_check CHECK ((tier = ANY (ARRAY['personal'::text, 'shared'::text])))
);


--
-- Name: TABLE loop_item; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.loop_item IS 'The three markdown accumulators as records (one-writer Phase A). One row per item in open-loops.md, open-loops-backlog.md, action-required.md and team-loops.md. Items change via the loop verbs (add-loop, update-loop, close-loop); the four files are rendered views of this table. NO SESSION HAND-EDITS THOSE FOUR FILES after the live flip.';


--
-- Name: COLUMN loop_item.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.kind IS 'open_loop / team_loop / action_required (0024) plus idea (0031, ORDER 40): a candidate idea awaiting a decision to act, rendered into 00_Context/idea-bank.md. An idea is deliberately NOT an open_loop — the bank holds what has no owner and no commitment yet, which is the distinction the file was created to preserve.';


--
-- Name: COLUMN loop_item.number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.number IS 'The visible ref, verbatim and NOT unique — the source files contain real collisions (#111 twice in open-loops.md; #103/#95/#88/#108 across hot and backlog; T34 across Open and Done). Renumbering is a content change nobody ruled, so the collisions are reported, not resolved here.';


--
-- Name: COLUMN loop_item.owner; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.owner IS 'An ownership LABEL as the file states it (Joe/Claude, Joe→Dell, Dell''s brain→Joe), not a foreign key. Resolving it to actor rows would drop what the label says.';


--
-- Name: COLUMN loop_item.close_outcome; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.close_outcome IS 'Required to leave open. A closed row with no outcome is how the asker stops finding out, which is the failure team-loops was built to end.';


--
-- Name: COLUMN loop_item.domain; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.domain IS 'deals | prospecting | networking | marketing | business | system (loop_domain, Joe''s vocabulary 2026-08-02). NULL = not yet classified, and that renders as its own unsorted section rather than defaulting into a domain — a guessed classification would bury exactly what this column exists to surface. BOUNDARY RULE: classify by WHAT THE WORK IS, not who appears in it. A vendor introducing a PROSPECT normally means real intent and goes straight to DEALS; it is PROSPECTING only while no deal has formed and it is still conversion work (the Renalus C-125 case). A vendor introducing a VENDOR is networking. Connecting a prospect to a vendor is networking (reciprocity). Connecting a client to a vendor on a LIVE deal is deals. Prospecting is drawn narrowly on purpose: it carries the most volume, so anything adjacent that lands there drowns the lead work it exists to hold.';


--
-- Name: COLUMN loop_item.blocker_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.blocker_class IS 'Why the session that opened this loop could not do the work itself, from a closed list of states of the world OUTSIDE the session: human_only, counterparty, ruling, external_event, other_lane, capability. NULL on rows opened before migration 0081 (2026-08-09) and on kinds the gate does not cover (team_loop, action_required, idea). There is deliberately no value meaning "later" — a session that cannot name one of these can do the work.';


--
-- Name: COLUMN loop_item.blocker_detail; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loop_item.blocker_detail IS 'The specific thing named: which person, which ruling, which date, which credential. "the landlord" is not a counterparty; "Sanders, the listing broker on C-112" is. Required by add-loop whenever blocker_class is set.';


--
-- Name: CONSTRAINT loop_item_owner_known ON loop_item; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT loop_item_owner_known ON public.loop_item IS 'One spelling per owner. Added 0089 after Joe 31 / joe 22 and Claude 4 / claude 92 meant every owner filter returned a fraction of the pile — including the autonomous drain queue, which selects on owner=claude and had been silently omitting four rows it was entitled to work. NOT VALID on purpose: it binds every future write without failing the migration on any historical row a human still needs to look at.';


--
-- Name: v_loops; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_loops AS
 SELECT li.id AS loop_id,
    li.kind,
    li.number,
    lb.rel_path AS renders_into,
    lb.block_key AS section,
    li.render_seq,
    li.title,
    li.body,
    li.owner,
    li.since_text,
    li.unblocks,
    li.source_note,
    li.closed_text,
    li.outcome,
    li.marker,
    li.marker_literal,
    li.due_on,
    li.drift_critical,
    li.status,
    li.close_outcome,
    li.closed_at,
    li.tier,
    a.slug AS personal_to,
    li.created_at,
    li.updated_at,
    li.version
   FROM ((public.loop_item li
     JOIN public.loop_block lb ON ((lb.id = li.block_id)))
     LEFT JOIN public.actor a ON ((a.id = li.personal_to)));


--
-- Name: VIEW v_loops; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_loops IS 'Reader surface for the loop accumulators. SAFE COLUMNS ONLY (v_ref_index precedent): no block internals, no extra_cells, no actor uuids. tier and personal_to are carried BECAUSE the boundary that matters here is the personal/shared split — open-loops.md is Joe-personal, action-required.md and team-loops.md are shared. The consumer filters; the reader never sees the base table. This column list is a security boundary.';


--
-- Name: v_control_plane_actionable_loops; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_control_plane_actionable_loops AS
 SELECT loop_id AS id,
    owner,
    'actionable'::text AS state,
    NULL::text AS counterparty_ref,
    NULL::text AS event_blocker_ref
   FROM public.v_loops l
  WHERE ((status = 'open'::text) AND (lower(COALESCE(owner, ''::text)) = 'system'::text) AND (personal_to IS NULL) AND (due_on IS NULL));


--
-- Name: v_control_plane_capability_candidate; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_control_plane_capability_candidate AS
 SELECT w.id,
    w.state,
    w.project_context,
    s.id AS session_id,
    s.state AS session_state,
    w.program_ordinal
   FROM (ops.v_capability_program_next w
     JOIN LATERAL ( SELECT x.id,
            x.state
           FROM ops.capability_agent_session x
          WHERE ((x.work_request_id = w.id) AND (x.state = 'verification'::text))
          ORDER BY x.updated_at DESC
         LIMIT 1) s ON (true));


--
-- Name: doctrine_document; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.doctrine_document (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    title text NOT NULL,
    content_class text NOT NULL,
    visibility text DEFAULT 'shared'::text NOT NULL,
    owner_actor_id uuid,
    review_policy_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    title_search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((COALESCE(title, ''::text) || ' '::text) || replace(slug, '-'::text, ' '::text)))) STORED,
    CONSTRAINT doctrine_document_content_class_check CHECK ((content_class = ANY (ARRAY['playbook'::text, 'sop'::text, 'index'::text, 'reference'::text, 'dossier_narrative'::text, 'distillation'::text, 'rule'::text]))),
    CONSTRAINT doctrine_document_visibility_check CHECK ((visibility = ANY (ARRAY['shared'::text, 'personal'::text])))
);


--
-- Name: TABLE doctrine_document; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.doctrine_document IS 'A prose document migrated out of vault markdown (0075, doctrine-store P1). content_class ''rule'' is RESERVED for the P7 rule-store study — nothing writes it before that ruling.';


--
-- Name: doctrine_section; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.doctrine_section (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid NOT NULL,
    section_key text NOT NULL,
    title text,
    ordinal integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    current_revision_id uuid,
    current_version bigint DEFAULT 0 NOT NULL,
    body_hash text,
    review_after timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    title_search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((COALESCE(title, ''::text) || ' '::text) || replace(section_key, '-'::text, ' '::text)))) STORED,
    CONSTRAINT doctrine_section_status_check CHECK ((status = ANY (ARRAY['active'::text, 'retired'::text])))
);


--
-- Name: TABLE doctrine_section; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.doctrine_section IS 'Stable-address unit of doctrine. section_key never changes; reordering changes ordinal only. current_version is the optimistic-concurrency token every write verb must present (base_version), the same contract as the rest of the record layer.';


--
-- Name: v_control_plane_doctrine_due; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_control_plane_doctrine_due AS
 SELECT s.id,
    d.slug,
    s.review_after
   FROM (public.doctrine_section s
     JOIN public.doctrine_document d ON ((d.id = s.document_id)))
  WHERE ((s.status = 'active'::text) AND (s.review_after <= now()));


--
-- Name: doctrine_gate_finding; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.doctrine_gate_finding (
    run_id uuid NOT NULL,
    check_key text NOT NULL,
    severity text NOT NULL,
    passed boolean NOT NULL,
    message text NOT NULL,
    path text DEFAULT ''::text NOT NULL
);


--
-- Name: doctrine_gate_run; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.doctrine_gate_run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    change_set_id uuid,
    dry_run boolean DEFAULT false NOT NULL,
    actor_id uuid NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    result text,
    report jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT doctrine_gate_run_result_check CHECK ((result = ANY (ARRAY['pass'::text, 'fail'::text])))
);


--
-- Name: v_control_plane_doctrine_failures; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_control_plane_doctrine_failures AS
 SELECT ((('doctrine-gate:'::text || (f.run_id)::text) || ':'::text) || f.check_key) AS source_ref,
    r.started_at AS observed_at
   FROM (public.doctrine_gate_finding f
     JOIN public.doctrine_gate_run r ON ((r.id = f.run_id)))
  WHERE ((NOT f.passed) AND (r.started_at >= date_trunc('month'::text, now())));


--
-- Name: v_service_environment_health; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_service_environment_health AS
 WITH latest_run AS (
         SELECT DISTINCT ON (r.service_id, r.environment) r.service_id,
            r.environment,
            r.state,
            r.observed_at,
            r.expires_at,
            r.run_key,
            r.failure_class,
            r.source_kind,
            r.source_ref,
            r.correlation_id
           FROM ops.run r
          WHERE (r.state = ANY (ARRAY['succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'skipped'::text]))
          ORDER BY r.service_id, r.environment, r.observed_at DESC
        ), joe_terminal_job AS MATERIALIZED (
         SELECT j.id,
            j.definition_key,
            j.definition_version,
            j.correlation_id,
            j.idempotency_key,
            j.scheduled_for,
            j.mode,
            j.state,
            j.payload,
            j.attempt,
            j.max_attempts,
            j.next_attempt_at,
            j.lease_owner,
            j.lease_token,
            j.leased_until,
            j.timeout_seconds,
            j.last_failure_class,
            j.last_failure_detail,
            j.created_at,
            j.started_at,
            j.ended_at,
            j.updated_at
           FROM ops.job j
          WHERE ((j.definition_key = 'calendar-prebrief-projection-joe-daily'::text) AND (j.definition_version = 1) AND (j.mode = 'live'::text) AND (j.state = ANY (ARRAY['succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'dead_lettered'::text])))
          ORDER BY COALESCE(j.ended_at, j.updated_at) DESC, j.scheduled_for DESC, j.created_at DESC, j.id DESC
         LIMIT 1
        ), joe_job_evidence AS (
         SELECT j.id,
            j.definition_key,
            j.definition_version,
            j.correlation_id,
            j.idempotency_key,
            j.scheduled_for,
            j.mode,
            j.state,
            j.payload,
            j.attempt,
            j.max_attempts,
            j.next_attempt_at,
            j.lease_owner,
            j.lease_token,
            j.leased_until,
            j.timeout_seconds,
            j.last_failure_class,
            j.last_failure_detail,
            j.created_at,
            j.started_at,
            j.ended_at,
            j.updated_at,
            p.id AS projection_receipt_id,
            a.id AS attestation_receipt_id,
            c.id AS capture_challenge_id,
            completion.id AS completion_receipt_id,
            terminal.id AS terminal_receipt_id,
            ((p.id IS NOT NULL) AND (a.id IS NOT NULL) AND (c.id IS NOT NULL) AND (completion.id IS NOT NULL)) AS success_evidence_valid
           FROM (((((joe_terminal_job j
             LEFT JOIN ops.calendar_prebrief_projection_receipt p ON (((p.job_id = j.id) AND (p.attempt = j.attempt) AND (p.sponsor = 'joe'::text))))
             LEFT JOIN ops.calendar_prebrief_source_attestation_receipt a ON (((a.id = p.source_attestation_id) AND (a.job_id = j.id) AND (a.attempt = j.attempt) AND (a.sponsor = 'joe'::text) AND (a.mode = 'live'::text) AND (a.destination = 'live'::text) AND (a.snapshot_at = p.snapshot_at) AND (a.allowlist_revision_id = p.allowlist_revision_id) AND (a.allowlist_digest = p.allowlist_digest))))
             LEFT JOIN ops.calendar_prebrief_capture_challenge c ON (((c.id = a.capture_challenge_id) AND (c.job_id = j.id) AND (c.attempt = j.attempt) AND (c.sponsor = 'joe'::text) AND (c.mode = 'live'::text) AND (c.destination = 'live'::text) AND (c.lease_token = a.lease_token) AND (c.scheduled_for = j.scheduled_for) AND (c.allowlist_revision_id = p.allowlist_revision_id) AND (c.allowlist_digest = p.allowlist_digest))))
             LEFT JOIN LATERAL ( SELECT r.id
                   FROM ops.job_receipt r
                  WHERE ((r.job_id = j.id) AND (r.attempt = j.attempt) AND (r.kind = 'completion'::text) AND (r.receipt_ref = ((('calendar-prebrief:joe:'::text || (j.id)::text) || ':'::text) || (j.attempt)::text)) AND (r.evidence = jsonb_build_object('sponsor', 'joe', 'mode', 'live', 'attestation_id', a.id, 'receipt_id', p.id, 'allowlist_revision_id', p.allowlist_revision_id, 'allowlist_digest', p.allowlist_digest)))
                  ORDER BY r.created_at DESC, r.id DESC
                 LIMIT 1) completion ON (true))
             LEFT JOIN LATERAL ( SELECT r.id
                   FROM ops.job_receipt r
                  WHERE ((r.job_id = j.id) AND (r.attempt = j.attempt) AND (((j.state = 'failed'::text) AND (r.kind = 'failure'::text)) OR ((j.state = 'timed_out'::text) AND (r.kind = ANY (ARRAY['timeout'::text, 'failure'::text]))) OR ((j.state = 'cancelled'::text) AND (r.kind = 'override'::text)) OR ((j.state = 'dead_lettered'::text) AND (r.kind = 'dead_letter'::text))))
                  ORDER BY r.created_at DESC, r.id DESC
                 LIMIT 1) terminal ON (true))
        ), joe_observation AS (
         SELECT 'calendar-prebrief-projection-joe-daily'::text AS run_key,
                CASE
                    WHEN ((j.state = 'succeeded'::text) AND j.success_evidence_valid) THEN 'succeeded'::text
                    WHEN (j.state = 'succeeded'::text) THEN 'failed'::text
                    ELSE j.state
                END AS state,
                CASE
                    WHEN ((j.state = 'succeeded'::text) AND (NOT j.success_evidence_valid)) THEN 'calendar_prebrief_completion_evidence_missing'::text
                    WHEN ((j.state <> 'succeeded'::text) AND (j.terminal_receipt_id IS NULL)) THEN COALESCE(j.last_failure_class, 'calendar_prebrief_terminal_evidence_missing'::text)
                    ELSE j.last_failure_class
                END AS failure_class,
            j.correlation_id,
            COALESCE(j.ended_at, j.updated_at) AS observed_at,
            NULL::timestamp with time zone AS expires_at,
                CASE
                    WHEN ((j.state = 'succeeded'::text) AND j.success_evidence_valid) THEN 'calendar_prebrief_projection_receipt'::text
                    WHEN (j.terminal_receipt_id IS NOT NULL) THEN 'job_receipt'::text
                    ELSE 'job'::text
                END AS source_kind,
                CASE
                    WHEN ((j.state = 'succeeded'::text) AND j.success_evidence_valid) THEN ('ops.calendar_prebrief_projection_receipt:'::text || (j.projection_receipt_id)::text)
                    WHEN (j.terminal_receipt_id IS NOT NULL) THEN ('ops.job_receipt:'::text || (j.terminal_receipt_id)::text)
                    ELSE ('ops.job:'::text || (j.id)::text)
                END AS source_ref
           FROM joe_job_evidence j
        ), observation AS (
         SELECT se_1.service_id,
            se_1.environment,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.state
                    ELSE lr.state
                END AS state,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.observed_at
                    ELSE lr.observed_at
                END AS observed_at,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.expires_at
                    ELSE lr.expires_at
                END AS expires_at,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.run_key
                    ELSE lr.run_key
                END AS run_key,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.failure_class
                    ELSE lr.failure_class
                END AS failure_class,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.source_kind
                    ELSE lr.source_kind
                END AS source_kind,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.source_ref
                    ELSE lr.source_ref
                END AS source_ref,
                CASE
                    WHEN (s_1.key = 'calendar-prebrief-joe'::text) THEN jo.correlation_id
                    ELSE lr.correlation_id
                END AS correlation_id
           FROM (((ops.service_environment se_1
             JOIN ops.service s_1 ON ((s_1.id = se_1.service_id)))
             LEFT JOIN latest_run lr ON (((lr.service_id = se_1.service_id) AND (lr.environment = se_1.environment))))
             LEFT JOIN joe_observation jo ON ((s_1.key = 'calendar-prebrief-joe'::text)))
          WHERE (s_1.retired_at IS NULL)
        )
 SELECT se.service_id,
    s.key AS service_key,
    s.name AS service_name,
    s.criticality,
    se.environment,
    o.run_key AS last_run_key,
    o.state AS last_run_state,
    o.failure_class AS last_failure_class,
    o.correlation_id AS last_correlation_id,
    o.observed_at,
    COALESCE(o.expires_at, (o.observed_at + make_interval(secs => ((se.expected_cadence_seconds + se.cadence_grace_seconds))::double precision))) AS expires_at,
    ops.freshness(o.observed_at, COALESCE(o.expires_at, (o.observed_at + make_interval(secs => ((se.expected_cadence_seconds + se.cadence_grace_seconds))::double precision)))) AS freshness_state,
    COALESCE(o.source_kind, 'registry'::text) AS source_kind,
    COALESCE(o.source_ref, 'ops.service_environment'::text) AS source_ref,
        CASE
            WHEN (o.state IS NULL) THEN 'unknown'::text
            WHEN (ops.freshness(o.observed_at, COALESCE(o.expires_at, (o.observed_at + make_interval(secs => ((se.expected_cadence_seconds + se.cadence_grace_seconds))::double precision)))) <> 'fresh'::text) THEN 'unknown'::text
            WHEN (o.state = ANY (ARRAY['failed'::text, 'timed_out'::text, 'dead_lettered'::text])) THEN 'unavailable'::text
            WHEN (o.state = ANY (ARRAY['skipped'::text, 'cancelled'::text])) THEN 'degraded'::text
            WHEN (o.state = 'succeeded'::text) THEN 'healthy'::text
            ELSE 'unknown'::text
        END AS health
   FROM ((ops.service_environment se
     JOIN ops.service s ON ((s.id = se.service_id)))
     JOIN observation o ON (((o.service_id = se.service_id) AND (o.environment = se.environment))))
  WHERE (s.retired_at IS NULL);


--
-- Name: VIEW v_service_environment_health; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_service_environment_health IS 'The only place service health is expressed. Ordinary services derive from ops.run. calendar-prebrief-joe derives read-only from its exact Joe v1 live ops.job and typed projection/attestation/completion receipts, so its narrow runtime does not need broad ops.run write authority. Missing or stale evidence is never green, and unrelated workflows or modes cannot count.';


--
-- Name: v_control_plane_health_evidence; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_control_plane_health_evidence AS
 SELECT 'live'::text AS evidence_class,
    ((('health:'::text || h.service_key) || ':'::text) || h.environment) AS source_ref,
    h.observed_at
   FROM ops.v_service_environment_health h
  WHERE (h.health = 'healthy'::text)
UNION ALL
 SELECT 'registry'::text AS evidence_class,
    ('service:'::text || s.key) AS source_ref,
    s.updated_at AS observed_at
   FROM ops.service s
  WHERE (s.retired_at IS NULL)
UNION ALL
 SELECT 'artifact'::text AS evidence_class,
    ((('release:'::text || r.release_key) || ':'::text) || r.artifact_digest) AS source_ref,
    r.observed_at
   FROM ops.release r
  WHERE ((r.state = 'complete'::text) AND (r.artifact_digest IS NOT NULL));


--
-- Name: deprecation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.deprecation (
    object_name text NOT NULL,
    object_kind text NOT NULL,
    replaced_by text,
    reason text NOT NULL,
    deprecated_at date DEFAULT CURRENT_DATE NOT NULL,
    safe_to_drop_after date,
    dropped_at date
);


--
-- Name: TABLE deprecation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.deprecation IS 'Things kept alive only for compatibility. A row here is a debt with a payoff date. `run.sh health` reads it, greps the repo, and reports whether anything still references each object — so deleting is a decision made on evidence rather than nerve. Nothing here is dropped automatically: dropping is irreversible, detecting is free.';


--
-- Name: v_control_plane_system_prune_candidates; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_control_plane_system_prune_candidates AS
 SELECT ((object_kind || ':'::text) || object_name) AS subject_ref,
    'stale'::text AS measurement
   FROM public.deprecation d
  WHERE ((dropped_at IS NULL) AND (safe_to_drop_after IS NOT NULL) AND (safe_to_drop_after <= CURRENT_DATE));


--
-- Name: v_cost_refusal_metric; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_cost_refusal_metric AS
 SELECT date_trunc('month'::text, refused_at) AS month,
    route_key,
    reason,
    count(*) AS refusal_count,
    sum(estimated_cost_usd) AS refused_estimated_cost_usd,
    max(refused_at) AS last_refused_at
   FROM ops.cost_refusal
  GROUP BY (date_trunc('month'::text, refused_at)), route_key, reason;


--
-- Name: v_guidance_revision_state; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_revision_state AS
 SELECT r.id,
    r.guidance_item_id,
    r.version,
    r.guidance_type,
    r.scope,
    r.activation,
    r.consumer,
    r.verification,
    r.provenance,
    r.delivery,
    r.is_constitution,
    r.supersedes_revision_id,
    r.classified_by,
    r.reason,
    r.created_at,
    COALESCE(e.state, 'proposed'::text) AS lifecycle_status,
    e.id AS lifecycle_event_id,
    e.authority_binding_id,
    e.created_at AS lifecycle_at
   FROM (ops.guidance_revision r
     LEFT JOIN LATERAL ( SELECT le.id,
            le.event_seq,
            le.guidance_revision_id,
            le.state,
            le.authority_binding_id,
            le.supersedes_event_id,
            le.reason,
            le.created_at
           FROM ops.guidance_lifecycle_event le
          WHERE (le.guidance_revision_id = r.id)
          ORDER BY le.event_seq DESC
         LIMIT 1) e ON (true));


--
-- Name: v_guidance_materialized_current; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_materialized_current AS
 SELECT DISTINCT ON (i.id) i.id AS guidance_item_id,
    i.source_rule_id,
    i.guidance_intake_id,
    i.source_clause,
    i.is_primary,
    i.split_group_id,
    r.id AS guidance_revision_id,
    r.version,
    r.guidance_type,
    r.scope,
    r.activation,
    r.consumer,
    r.verification,
    r.provenance,
    r.delivery,
    r.is_constitution,
    r.classified_by,
    r.reason,
    r.lifecycle_at
   FROM (ops.guidance_item i
     JOIN ops.v_guidance_revision_state r ON ((r.guidance_item_id = i.id)))
  WHERE (r.lifecycle_status = 'active'::text)
  ORDER BY i.id, r.version DESC, r.lifecycle_at DESC, r.id DESC;


--
-- Name: v_guidance_registry_state; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_registry_state AS
 SELECT r.id AS registry_id,
    COALESCE(e.state, 'inactive'::text) AS state,
    e.authority_receipt_id,
    e.manifest_digest,
    e.created_at AS changed_at
   FROM (ops.guidance_registry r
     LEFT JOIN LATERAL ( SELECT ge.id,
            ge.event_seq,
            ge.registry_id,
            ge.state,
            ge.authority_receipt_id,
            ge.manifest_digest,
            ge.reason,
            ge.created_at
           FROM ops.guidance_registry_event ge
          WHERE (ge.registry_id = r.id)
          ORDER BY ge.event_seq DESC
         LIMIT 1) e ON (true));


--
-- Name: v_guidance_current; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_current AS
 SELECT guidance_item_id,
    source_rule_id,
    guidance_intake_id,
    source_clause,
    is_primary,
    split_group_id,
    guidance_revision_id,
    version,
    guidance_type,
    scope,
    activation,
    consumer,
    verification,
    provenance,
    delivery,
    is_constitution,
    classified_by,
    reason,
    lifecycle_at
   FROM ops.v_guidance_materialized_current g
  WHERE (EXISTS ( SELECT 1
           FROM (ops.v_guidance_registry_state s
             JOIN ops.guidance_registry registry ON (((registry.id = s.registry_id) AND registry.singleton)))
          WHERE (s.state = 'active'::text)));


--
-- Name: v_guidance_constraint; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_constraint AS
 SELECT g.guidance_item_id,
    g.source_rule_id,
    g.guidance_intake_id,
    g.source_clause,
    g.is_primary,
    g.split_group_id,
    g.guidance_revision_id,
    g.version,
    g.guidance_type,
    g.scope,
    g.activation,
    g.consumer,
    g.verification,
    g.provenance,
    g.delivery,
    g.is_constitution,
    g.classified_by,
    g.reason,
    g.lifecycle_at,
    a.enforcement_class,
    a.binding_moment,
    a.applicability,
    ep.control_key,
    ep.implementation_ref,
    ep.test_ref,
    ep.verified_at
   FROM ((ops.v_guidance_current g
     JOIN ops.rule_admission a ON (((a.rule_id = g.source_rule_id) AND (a.state = 'admitted'::text))))
     JOIN ops.rule_enforcement_point ep ON (((ep.rule_id = g.source_rule_id) AND ep.installed)))
  WHERE (g.guidance_type = 'constraint'::text);


--
-- Name: v_guidance_materialized_situation_mapping_current; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_materialized_situation_mapping_current AS
 SELECT DISTINCT ON (guidance_revision_id, concept_id, doctrine_section_id) id,
    mapping_seq,
    guidance_revision_id,
    concept_id,
    doctrine_section_id,
    state,
    authority_binding_id,
    supersedes_mapping_id,
    reason,
    created_at
   FROM ops.guidance_situation_mapping m
  ORDER BY guidance_revision_id, concept_id, doctrine_section_id, mapping_seq DESC;


--
-- Name: v_guidance_situation_mapping_current; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_situation_mapping_current AS
 SELECT id,
    mapping_seq,
    guidance_revision_id,
    concept_id,
    doctrine_section_id,
    state,
    authority_binding_id,
    supersedes_mapping_id,
    reason,
    created_at
   FROM ops.v_guidance_materialized_situation_mapping_current m
  WHERE (EXISTS ( SELECT 1
           FROM (ops.v_guidance_registry_state s
             JOIN ops.guidance_registry registry ON (((registry.id = s.registry_id) AND registry.singleton)))
          WHERE (s.state = 'active'::text)));


--
-- Name: doctrine_concept_mapping; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.doctrine_concept_mapping (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    concept_id uuid NOT NULL,
    section_id uuid NOT NULL,
    role text NOT NULL,
    weight numeric(5,4) DEFAULT 1 NOT NULL,
    rationale text NOT NULL,
    status text DEFAULT 'proposed'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    review_after timestamp with time zone,
    proposer_id uuid NOT NULL,
    approver_id uuid,
    approved_at timestamp with time zone,
    retired_at timestamp with time zone,
    repair_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT doctrine_concept_mapping_check CHECK ((((status = 'approved'::text) = ((approver_id IS NOT NULL) AND (approved_at IS NOT NULL))) OR (status = ANY (ARRAY['retired'::text, 'needs_repair'::text])))),
    CONSTRAINT doctrine_concept_mapping_rationale_check CHECK ((btrim(rationale) <> ''::text)),
    CONSTRAINT doctrine_concept_mapping_role_check CHECK ((role = ANY (ARRAY['governs'::text, 'supports'::text]))),
    CONSTRAINT doctrine_concept_mapping_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'approved'::text, 'retired'::text, 'needs_repair'::text]))),
    CONSTRAINT doctrine_concept_mapping_weight_check CHECK (((weight > (0)::numeric) AND (weight <= (1)::numeric)))
);


--
-- Name: retrieval_concept; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.retrieval_concept (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    concept_key text NOT NULL,
    label text NOT NULL,
    definition text NOT NULL,
    status text DEFAULT 'proposed'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    review_after timestamp with time zone,
    proposer_id uuid NOT NULL,
    approver_id uuid,
    approved_at timestamp with time zone,
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT retrieval_concept_check CHECK ((((status = 'approved'::text) = ((approver_id IS NOT NULL) AND (approved_at IS NOT NULL))) OR (status = 'retired'::text))),
    CONSTRAINT retrieval_concept_concept_key_check CHECK ((concept_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
    CONSTRAINT retrieval_concept_definition_check CHECK ((btrim(definition) <> ''::text)),
    CONSTRAINT retrieval_concept_label_check CHECK ((btrim(label) <> ''::text)),
    CONSTRAINT retrieval_concept_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'approved'::text, 'retired'::text])))
);


--
-- Name: v_guidance_doctrine_retrieval; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_doctrine_retrieval AS
 SELECT g.guidance_item_id,
    g.source_rule_id,
    g.guidance_intake_id,
    g.source_clause,
    g.is_primary,
    g.split_group_id,
    g.guidance_revision_id,
    g.version,
    g.guidance_type,
    g.scope,
    g.activation,
    g.consumer,
    g.verification,
    g.provenance,
    g.delivery,
    g.is_constitution,
    g.classified_by,
    g.reason,
    g.lifecycle_at,
    c.concept_key,
    s.document_id,
    s.section_key,
    m.id AS guidance_mapping_id,
    dcm.id AS retrieval_mapping_id
   FROM ((((ops.v_guidance_current g
     JOIN ops.v_guidance_situation_mapping_current m ON (((m.guidance_revision_id = g.guidance_revision_id) AND (m.state = 'active'::text))))
     JOIN public.retrieval_concept c ON (((c.id = m.concept_id) AND (c.status = 'approved'::text))))
     JOIN public.doctrine_section s ON (((s.id = m.doctrine_section_id) AND (s.status = 'active'::text))))
     JOIN public.doctrine_concept_mapping dcm ON (((dcm.concept_id = m.concept_id) AND (dcm.section_id = m.doctrine_section_id) AND (dcm.status = 'approved'::text))))
  WHERE (g.guidance_type = 'doctrine'::text);


--
-- Name: v_guidance_example; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_example AS
 SELECT guidance_item_id,
    source_rule_id,
    guidance_intake_id,
    source_clause,
    is_primary,
    split_group_id,
    guidance_revision_id,
    version,
    guidance_type,
    scope,
    activation,
    consumer,
    verification,
    provenance,
    delivery,
    is_constitution,
    classified_by,
    reason,
    lifecycle_at
   FROM ops.v_guidance_current
  WHERE (guidance_type = 'example'::text);


--
-- Name: rule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rule (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    statement text NOT NULL,
    human_quote text,
    taught_by uuid NOT NULL,
    scope jsonb DEFAULT '{}'::jsonb NOT NULL,
    personal_to uuid,
    status text DEFAULT 'proposed'::text NOT NULL,
    activated_by uuid,
    activated_at timestamp with time zone,
    enforcement text DEFAULT 'prose'::text NOT NULL,
    supersedes uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_by uuid,
    retired_at timestamp with time zone,
    CONSTRAINT rule_check CHECK (((status <> 'active'::text) OR (activated_by IS NOT NULL))),
    CONSTRAINT rule_enforcement_check CHECK ((enforcement = ANY (ARRAY['prose'::text, 'checklist'::text, 'gate'::text, 'constraint'::text, 'code'::text]))),
    CONSTRAINT rule_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'active'::text, 'retired'::text, 'superseded'::text])))
);


--
-- Name: COLUMN rule.human_quote; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule.human_quote IS 'verbatim words of the teacher. IMMUTABLE once non-empty — amend-rule may fill a NULL, never overwrite. NULL means imported doctrine, not a paraphrase passed off as a quote.';


--
-- Name: COLUMN rule.version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule.version IS '[A2] optimistic-concurrency token for amend-rule; bumped by trg_touch_row on every update';


--
-- Name: v_guidance_precedent; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_precedent AS
 SELECT g.guidance_item_id AS decision_id,
    (COALESCE(r.activated_at, r.created_at))::date AS entry_date,
    "left"(r.statement, 240) AS title,
    r.human_quote,
    g.reason AS agent_rationale,
    a.slug AS author,
    jsonb_build_object('source', 'typed-guidance', 'source_rule_id', g.source_rule_id, 'guidance_revision_id', g.guidance_revision_id) AS provenance,
    ((((COALESCE(r.statement, ''::text) || ' '::text) || COALESCE(r.human_quote, ''::text)) || ' '::text) || g.reason) AS haystack
   FROM ((ops.v_guidance_current g
     JOIN public.rule r ON ((r.id = g.source_rule_id)))
     LEFT JOIN public.actor a ON ((a.id = r.taught_by)))
  WHERE (g.guidance_type = 'precedent'::text);


--
-- Name: v_guidance_preference; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_preference AS
 SELECT guidance_item_id,
    source_rule_id,
    guidance_intake_id,
    source_clause,
    is_primary,
    split_group_id,
    guidance_revision_id,
    version,
    guidance_type,
    scope,
    activation,
    consumer,
    verification,
    provenance,
    delivery,
    is_constitution,
    classified_by,
    reason,
    lifecycle_at
   FROM ops.v_guidance_current
  WHERE (guidance_type = 'preference'::text);


--
-- Name: v_guidance_procedure; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_procedure AS
 SELECT guidance_item_id,
    source_rule_id,
    guidance_intake_id,
    source_clause,
    is_primary,
    split_group_id,
    guidance_revision_id,
    version,
    guidance_type,
    scope,
    activation,
    consumer,
    verification,
    provenance,
    delivery,
    is_constitution,
    classified_by,
    reason,
    lifecycle_at
   FROM ops.v_guidance_current
  WHERE (guidance_type = 'procedure'::text);


--
-- Name: v_guidance_projection_summary; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_projection_summary AS
 SELECT guidance_type,
    count(*) AS active_items,
    encode(public.digest(string_agg((guidance_revision_id)::text, ','::text ORDER BY guidance_revision_id), 'sha256'::text), 'hex'::text) AS projection_digest
   FROM ops.v_guidance_current
  GROUP BY guidance_type;


--
-- Name: v_guidance_rubric; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_guidance_rubric AS
 SELECT guidance_item_id,
    source_rule_id,
    guidance_intake_id,
    source_clause,
    is_primary,
    split_group_id,
    guidance_revision_id,
    version,
    guidance_type,
    scope,
    activation,
    consumer,
    verification,
    provenance,
    delivery,
    is_constitution,
    classified_by,
    reason,
    lifecycle_at
   FROM ops.v_guidance_current
  WHERE (guidance_type = 'rubric'::text);


--
-- Name: v_job_control; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_job_control AS
 SELECT j.id,
    j.definition_key,
    j.definition_version,
    j.correlation_id,
    j.state,
    j.mode,
    j.attempt,
    j.max_attempts,
    j.scheduled_for,
    j.next_attempt_at,
    j.lease_owner,
    j.leased_until,
    j.last_failure_class,
    j.created_at,
    j.started_at,
    j.ended_at,
    d.risk,
    d.execution_kind,
    d.owner_actor,
    ( SELECT count(*) AS count
           FROM ops.job_receipt r
          WHERE (r.job_id = j.id)) AS receipt_count
   FROM (ops.job j
     JOIN ops.job_definition d ON (((d.key = j.definition_key) AND (d.version = j.definition_version))));


--
-- Name: v_job_cost; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_job_cost AS
 SELECT date_trunc('month'::text, a.started_at) AS month,
    j.definition_key,
    a.provider_route,
    sum(COALESCE(a.input_tokens, 0)) AS input_tokens,
    sum(COALESCE(a.output_tokens, 0)) AS output_tokens,
    sum(COALESCE(a.cost_usd, (0)::numeric)) AS cost_usd,
    count(*) AS attempts
   FROM (ops.job_attempt a
     JOIN ops.job j ON ((j.id = a.job_id)))
  GROUP BY (date_trunc('month'::text, a.started_at)), j.definition_key, a.provider_route;


--
-- Name: v_job_run; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_job_run AS
 SELECT id,
    correlation_id,
    kind,
    service_id,
    environment,
    run_key,
    state,
    failure_class,
    exit_code,
    attempt,
    started_at,
    ended_at,
    duration_ms,
    source_kind,
    source_ref,
    observed_at,
    expires_at,
    evidence_ref,
    detail
   FROM ops.run
  WHERE (kind = 'job'::text);


--
-- Name: v_provider_route; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_provider_route AS
 WITH latest AS (
         SELECT DISTINCT ON (provider_observation.route_key) provider_observation.route_key,
            provider_observation.status,
            provider_observation.latency_ms,
            provider_observation.error_class,
            provider_observation.observed_at,
            provider_observation.expires_at
           FROM ops.provider_observation
          ORDER BY provider_observation.route_key, provider_observation.observed_at DESC
        )
 SELECT r.route_key,
    r.priority,
    r.enabled,
    r.endpoint_ref,
    r.capability_tags,
    r.max_concurrency,
    r.monthly_budget_usd,
    r.created_at,
    r.updated_at,
        CASE
            WHEN (NOT r.enabled) THEN 'disabled'::text
            WHEN (l.route_key IS NULL) THEN 'unknown'::text
            WHEN (l.expires_at < now()) THEN 'stale'::text
            ELSE l.status
        END AS health,
    l.latency_ms,
    l.error_class,
    l.observed_at
   FROM (ops.provider_route r
     LEFT JOIN latest l USING (route_key))
  ORDER BY r.priority;


--
-- Name: v_release_manifest; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_release_manifest AS
 SELECT r.id AS release_id,
    r.release_key,
    r.correlation_id,
    s.key AS service_key,
    r.environment,
    r.state,
    r.git_sha AS code_git_sha,
    r.artifact_digest AS code_artifact_digest,
    r.dependency_lock_digest AS code_dependency_lock_digest,
    r.sbom_ref AS code_sbom_ref,
    r.schema_highest_migration,
    r.migration_set,
    r.config_fingerprint,
    r.declared_env_differences,
    r.asset_versions,
    r.test_evidence_ref,
    r.security_evidence_ref,
    r.maker_actor,
    r.maker_verification_ref,
    r.plan_hash AS approval_plan_hash,
    r.approved_by_actor,
    r.approved_at,
    r.approval_expires_at,
        CASE
            WHEN (r.approved_at IS NULL) THEN 'unapproved'::text
            WHEN (r.approval_expires_at <= now()) THEN 'expired'::text
            ELSE 'live'::text
        END AS approval_status,
    d.id AS deployment_id,
    d.state AS deploy_state,
    d.read_back_at AS deploy_read_back_at,
    d.verification_evidence_ref AS deploy_verification_evidence_ref,
    r.verifier_actor,
    r.verifier_evidence_ref,
    r.rollback_ready,
    r.rollback_plan_ref,
    r.work_request_ref,
    r.source_kind,
    r.source_ref,
    r.observed_at,
    r.expires_at,
    ops.freshness(r.observed_at, r.expires_at) AS freshness,
    r.performance_budget_ref,
    r.performance_budget_ms,
    r.recovery_strategy
   FROM ((ops.release r
     JOIN ops.service s ON ((s.id = r.service_id)))
     LEFT JOIN LATERAL ( SELECT d2.id,
            d2.correlation_id,
            d2.service_id,
            d2.environment,
            d2.state,
            d2.git_sha,
            d2.release_ref,
            d2.deployed_by_actor,
            d2.verb_count,
            d2.schema_highest_migration,
            d2.doctrine_generation,
            d2.started_at,
            d2.ended_at,
            d2.read_back_at,
            d2.verification_evidence_ref,
            d2.failure_class,
            d2.rollback_of,
            d2.source_kind,
            d2.source_ref,
            d2.observed_at,
            d2.expires_at,
            d2.detail,
            d2.release_id,
            d2.provider,
            d2.provider_version_id
           FROM ops.deployment d2
          WHERE (d2.release_id = r.id)
          ORDER BY d2.observed_at DESC
         LIMIT 1) d ON (true));


--
-- Name: VIEW v_release_manifest; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_release_manifest IS 'P0-1 assertion 1: ONE query returns code, schema, config, tests, approval, deploy and verification for one release. Seven lookups was the fragmentation this replaces.';


--
-- Name: schema_migrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schema_migrations (
    filename text NOT NULL,
    sha256 text NOT NULL,
    applied_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: v_release_schema_provenance; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_release_schema_provenance AS
 WITH live AS (
         SELECT (count(*))::integer AS applied_count,
            (max((schema_migrations.filename COLLATE "C")) COLLATE "default") AS highest_applied_migration,
            ('sha256:'::text || encode(public.digest(COALESCE(string_agg((((convert_to(schema_migrations.filename, 'UTF8'::name) || decode('00'::text, 'hex'::text)) || convert_to(schema_migrations.sha256, 'UTF8'::name)) || decode('0a'::text, 'hex'::text)), '\x'::bytea ORDER BY (schema_migrations.filename COLLATE "C")), '\x'::bytea), 'sha256'::text), 'hex'::text)) AS ledger_sha256
           FROM public.schema_migrations
        )
 SELECT r.id AS release_id,
    r.release_key,
    r.environment,
    r.state,
    r.schema_highest_migration AS declared_schema_highest_migration,
    r.schema_applied_count AS declared_schema_applied_count,
    live.highest_applied_migration AS live_schema_highest_migration,
    live.applied_count AS live_schema_applied_count,
    live.ledger_sha256 AS live_schema_ledger_sha256,
    ((r.schema_highest_migration IS NOT NULL) AND (r.schema_applied_count IS NOT NULL) AND (r.schema_ledger_sha256 IS NOT NULL) AND (r.schema_highest_migration = live.highest_applied_migration) AND (r.schema_applied_count = live.applied_count) AND (r.schema_ledger_sha256 = live.ledger_sha256)) AS schema_declaration_matches_live,
        CASE
            WHEN ((r.schema_highest_migration IS NULL) OR (r.schema_applied_count IS NULL) OR (r.schema_ledger_sha256 IS NULL) OR (live.highest_applied_migration IS NULL) OR (live.ledger_sha256 IS NULL)) THEN 'unknown'::text
            WHEN ((r.schema_highest_migration = live.highest_applied_migration) AND (r.schema_applied_count = live.applied_count) AND (r.schema_ledger_sha256 = live.ledger_sha256)) THEN 'match'::text
            ELSE 'mismatch'::text
        END AS schema_status,
    jsonb_build_object('source', 'public.schema_migrations', 'declared', jsonb_build_object('highest_applied_migration', r.schema_highest_migration, 'applied_count', r.schema_applied_count, 'ledger_sha256', r.schema_ledger_sha256), 'live', jsonb_build_object('highest_applied_migration', live.highest_applied_migration, 'applied_count', live.applied_count, 'ledger_sha256', live.ledger_sha256)) AS schema_evidence
   FROM (ops.release r
     CROSS JOIN live);


--
-- Name: VIEW v_release_schema_provenance; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_release_schema_provenance IS 'Derived release schema status using a locale-stable exact ledger digest. Declarations remain historical; live evidence reads schema_migrations.';


--
-- Name: v_rule_applicability; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_rule_applicability AS
 SELECT r.id AS rule_id,
    r.status,
    a.enforcement_class,
    a.binding_moment,
    a.applicability,
    a.projection,
    a.reachability,
    a.version AS admission_version,
    a.state AS admission_state,
    COALESCE(( SELECT count(*) AS count
           FROM ops.rule_enforcement_point ep
          WHERE ((ep.rule_id = r.id) AND ep.installed)), (0)::bigint) AS installed_controls
   FROM (public.rule r
     JOIN ops.rule_admission a ON ((a.rule_id = r.id)));


--
-- Name: v_rule_enforcement_status; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_rule_enforcement_status AS
 SELECT r.id AS rule_id,
    r.status AS policy_status,
    a.enforcement_class,
    a.enforcement_status,
    a.binding_moment,
    a.coverage_detail,
    COALESCE(array_agg(ep.control_key ORDER BY ep.control_key) FILTER (WHERE ep.installed), '{}'::text[]) AS installed_controls,
    ar.id AS approval_receipt_id,
    ar.created_at AS approved_and_activated_at
   FROM (((public.rule r
     JOIN ops.rule_admission a ON ((a.rule_id = r.id)))
     LEFT JOIN ops.rule_enforcement_point ep ON ((ep.rule_id = r.id)))
     LEFT JOIN ops.rule_approval_receipt ar ON ((ar.rule_id = r.id)))
  GROUP BY r.id, r.status, a.enforcement_class, a.enforcement_status, a.binding_moment, a.coverage_detail, ar.id, ar.created_at;


--
-- Name: v_trace; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_trace AS
 SELECT d.correlation_id,
    'deployment'::text AS kind,
    COALESCE(d.release_ref, "left"(d.git_sha, 12), (d.id)::text) AS ref,
    d.state,
    COALESCE(d.ended_at, d.started_at, d.observed_at) AS occurred_at,
    d.environment,
    s.key AS service_key,
    d.failure_class,
    d.detail,
    d.source_kind,
    d.source_ref,
    d.observed_at,
    d.expires_at,
    ops.freshness(d.observed_at, d.expires_at) AS freshness_state,
    d.id AS row_id
   FROM (ops.deployment d
     JOIN ops.service s ON ((s.id = d.service_id)))
UNION ALL
 SELECT r.correlation_id,
    r.kind,
    r.run_key AS ref,
    r.state,
    COALESCE(r.ended_at, r.started_at, r.observed_at) AS occurred_at,
    r.environment,
    s.key AS service_key,
    r.failure_class,
    r.detail,
    r.source_kind,
    r.source_ref,
    r.observed_at,
    r.expires_at,
    ops.freshness(r.observed_at, r.expires_at) AS freshness_state,
    r.id AS row_id
   FROM (ops.run r
     JOIN ops.service s ON ((s.id = r.service_id)))
UNION ALL
 SELECT i.correlation_id,
    'incident'::text AS kind,
    i.ref,
    i.state,
    i.detected_at AS occurred_at,
    i.environment,
    NULL::text AS service_key,
    NULL::text AS failure_class,
    i.title AS detail,
    i.source_kind,
    i.source_ref,
    i.observed_at,
    i.expires_at,
    ops.freshness(i.observed_at, i.expires_at) AS freshness_state,
    i.id AS row_id
   FROM ops.incident i
UNION ALL
 SELECT f.correlation_id,
    'incident_fact'::text AS kind,
    i.ref,
    i.state,
    f.recorded_at AS occurred_at,
    i.environment,
    NULL::text AS service_key,
    NULL::text AS failure_class,
    f.text AS detail,
    i.source_kind,
    i.source_ref,
    f.recorded_at AS observed_at,
    i.expires_at,
    ops.freshness(f.recorded_at, i.expires_at) AS freshness_state,
    f.id AS row_id
   FROM (( SELECT incident_fact.id,
            incident_fact.incident_id,
            incident_fact.text,
            incident_fact.recorded_at,
            ("substring"(incident_fact.source_ref, '^correlation:([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$'::text))::uuid AS correlation_id
           FROM ops.incident_fact) f
     JOIN ops.incident i ON ((i.id = f.incident_id)))
  WHERE ((f.correlation_id IS NOT NULL) AND (f.correlation_id IS DISTINCT FROM i.correlation_id))
UNION ALL
 SELECT w.correlation_id,
    'work_request'::text AS kind,
    w.ref,
    w.state,
    w.captured_at AS occurred_at,
    NULL::text AS environment,
    NULL::text AS service_key,
    w.blocker_code AS failure_class,
    w.title AS detail,
    'registry'::text AS source_kind,
    'ops.work_request'::text AS source_ref,
    w.updated_at AS observed_at,
    NULL::timestamp with time zone AS expires_at,
    ops.freshness(w.updated_at, NULL::timestamp with time zone) AS freshness_state,
    w.id AS row_id
   FROM ops.work_request w
  WHERE (w.correlation_id IS NOT NULL);


--
-- Name: VIEW v_trace; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_trace IS 'THE PROGRAM 3 GATE. One correlation id returns the whole journey — deploy, golden-workflow check, job run, incident, RECURRENCE of an already-open incident, work request — in time order, every link carrying its own source and freshness. Read-only by construction: a view over the ops tables with no insert rule. The recurrence arm (0123) reads ops.incident_fact.source_ref, where mcp-server/src/trace.js stores the correlation id of every failure after the first one that opened the incident.';


--
-- Name: work_shape_revision; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.work_shape_revision (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    work_request_version integer NOT NULL,
    version integer NOT NULL,
    trinity jsonb NOT NULL,
    hidden_assumption text NOT NULL,
    repo_searches jsonb NOT NULL,
    maintained_repos jsonb NOT NULL,
    archetypes jsonb NOT NULL,
    chosen_key text NOT NULL,
    mind_changing_fact text NOT NULL,
    builder_brief jsonb NOT NULL,
    source_url text,
    created_by_actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_shape_revision_archetypes_check CHECK ((jsonb_typeof(archetypes) = 'array'::text)),
    CONSTRAINT work_shape_revision_builder_brief_check CHECK ((jsonb_typeof(builder_brief) = 'object'::text)),
    CONSTRAINT work_shape_revision_chosen_key_check CHECK ((btrim(chosen_key) <> ''::text)),
    CONSTRAINT work_shape_revision_hidden_assumption_check CHECK ((btrim(hidden_assumption) <> ''::text)),
    CONSTRAINT work_shape_revision_maintained_repos_check CHECK ((jsonb_typeof(maintained_repos) = 'array'::text)),
    CONSTRAINT work_shape_revision_mind_changing_fact_check CHECK ((btrim(mind_changing_fact) <> ''::text)),
    CONSTRAINT work_shape_revision_repo_searches_check CHECK ((jsonb_typeof(repo_searches) = 'array'::text)),
    CONSTRAINT work_shape_revision_trinity_check CHECK ((jsonb_typeof(trinity) = 'object'::text)),
    CONSTRAINT work_shape_revision_version_check CHECK ((version > 0)),
    CONSTRAINT work_shape_revision_work_request_version_check CHECK ((work_request_version > 0))
);


--
-- Name: TABLE work_shape_revision; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.work_shape_revision IS 'Append-only implementation-shape reasoning for one canonical Work Request. The Worker enforces the trinity, recon, three archetypes, scores, falsifier and builder-brief contract; the database preserves every accepted revision.';


--
-- Name: v_work_shape_current; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_work_shape_current WITH (security_invoker='true') AS
 SELECT DISTINCT ON (work_request_id) id,
    work_request_id,
    work_request_version,
    version,
    trinity,
    hidden_assumption,
    repo_searches,
    maintained_repos,
    archetypes,
    chosen_key,
    mind_changing_fact,
    builder_brief,
    source_url,
    created_by_actor_id,
    created_at
   FROM ops.work_shape_revision
  ORDER BY work_request_id, version DESC;


--
-- Name: work_request_execution_assignment; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.work_request_execution_assignment (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    sponsoring_human_id uuid NOT NULL,
    environment text NOT NULL,
    policy_ref text NOT NULL,
    policy_digest text NOT NULL,
    idempotency_key uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_request_execution_assignment_environment_check CHECK ((environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text]))),
    CONSTRAINT work_request_execution_assignment_policy_digest_check CHECK ((policy_digest ~ '^sha256:[0-9a-f]{64}$'::text))
);


--
-- Name: work_request_ref_seq; Type: SEQUENCE; Schema: ops; Owner: -
--

CREATE SEQUENCE ops.work_request_ref_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: work_request_triage_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.work_request_triage_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    base_version integer NOT NULL,
    classification text NOT NULL,
    triaged_by_actor_id uuid NOT NULL,
    result_version integer NOT NULL,
    triaged_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_request_triage_receipt_base_version_check CHECK ((base_version > 0)),
    CONSTRAINT work_request_triage_receipt_classification_check CHECK ((classification = ANY (ARRAY['operational'::text, 'needs_judgment'::text, 'safety_review'::text]))),
    CONSTRAINT work_request_triage_receipt_result_version_check CHECK ((result_version > 0))
);


--
-- Name: TABLE work_request_triage_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.work_request_triage_receipt IS 'Private, append-only receipt that authorizes the sole Program 6 captured-to-triaged transition. It is not a dispatch or execution record.';


--
-- Name: workflow_acceptance; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.workflow_acceptance (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_key text NOT NULL,
    workflow_version integer NOT NULL,
    mode text NOT NULL,
    status text NOT NULL,
    receipt_ref text NOT NULL,
    accepted_by text,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT accepted_evidence_names_actor CHECK (((status <> 'accepted'::text) OR (accepted_by IS NOT NULL))),
    CONSTRAINT workflow_acceptance_mode_check CHECK ((mode = ANY (ARRAY['shadow'::text, 'canary'::text]))),
    CONSTRAINT workflow_acceptance_status_check CHECK ((status = ANY (ARRAY['observed'::text, 'accepted'::text, 'rejected'::text])))
);


--
-- Name: activity; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.activity (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id uuid NOT NULL,
    kind text NOT NULL,
    summary text NOT NULL,
    detail text,
    owed text,
    deal_id uuid,
    client_id uuid,
    lead_id uuid,
    vendor_id uuid,
    source text DEFAULT 'stated'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    connected boolean
);


--
-- Name: COLUMN activity.connected; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.activity.connected IS 'Did this contact actually reach the person? TRUE = spoke/replied, FALSE = attempt only (voicemail, no answer, unanswered text), NULL = not recorded. Only meaningful for kinds whose direction is ambiguous — call and text. meeting/tour/loi/lease_signed are two-way by definition; email_in and counter_received prove a reply by existing. Stored because only the person who made the call knows, and NULL is honestly unknown rather than no.';


--
-- Name: activity_kind; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.activity_kind (
    slug text NOT NULL,
    label text NOT NULL,
    is_contact boolean NOT NULL
);


--
-- Name: TABLE activity_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.activity_kind IS 'Activity vocabulary. is_contact answers ONE question: does a row of this kind count as having TOUCHED the subject? v_last_touch aggregates only these. note and task are deliberately false — an internal annotation is not a touch (the 2026-07-30 freeze shipped 13 rulings as activity rows and stamped cold records warm; that is the defect this flag closes).';


--
-- Name: actor_profile; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.actor_profile (
    actor_id uuid NOT NULL,
    key text NOT NULL,
    value jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: agent_profile; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_profile (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_key text NOT NULL,
    display_name text NOT NULL,
    charter jsonb DEFAULT '[]'::jsonb NOT NULL,
    current_model text,
    current_desk text,
    sponsor_scope text DEFAULT 'shared'::text NOT NULL,
    status text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
