    CONSTRAINT capture_post_call_action_description_check CHECK ((btrim(description) <> ''::text)),
    CONSTRAINT capture_post_call_action_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'dropped'::text])))
);


