    CONSTRAINT comp_rate_norm_sf_yr_check CHECK (((rate_norm_sf_yr IS NULL) OR ((rate_norm_sf_yr >= (2)::numeric) AND (rate_norm_sf_yr <= (250)::numeric)))),
