    CONSTRAINT content_piece_status_check CHECK ((status = ANY (ARRAY['idea'::text, 'drafted'::text, 'in_review'::text, 'approved'::text, 'edited_approved'::text, 'rejected'::text, 'scheduled'::text, 'live'::text, 'measured'::text, 'retired'::text])))
);


