--
-- Name: COLUMN event.personal_scope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event.personal_scope IS 'Rule brain loaded for this event: joe-personal, dell-personal, none, or null before 0095.';


