   FROM ((public.deal_participant dp
     LEFT JOIN public.actor a ON ((a.id = dp.actor_id)))
     LEFT JOIN public.party p ON ((p.id = dp.party_id)))
  WHERE (dp.to_at IS NULL);


--
-- Name: v_deal_room_premises; Type: VIEW; Schema: public; Owner: -
